window.MH_TR["ch00"]={"t": "\u05e4\u05ea\u05d9\u05d7\u05d4", "l": [[3.0, "\u05ea\u05e1\u05ea\u05db\u05dc\u05d5 \u05e1\u05d1\u05d9\u05d1\u05db\u05dd: \u05d2\u05e9\u05e8\u05d9\u05dd, \u05d0\u05d5\u05e0\u05d9\u05d5\u05ea, \u05e6\u05e0\u05e8\u05ea \u05d2\u05d6, \u05de\u05e8\u05db\u05d1 \u05e9\u05dc \u05de\u05db\u05d5\u05e0\u05d9\u05ea, \u05de\u05d9\u05db\u05dc \u05dc\u05d7\u05e5 \u05d5\u05de\u05e1\u05d2\u05e8\u05ea \u05e9\u05dc \u05de\u05db\u05d5\u05e0\u05d4."], [11.7, "\u05d1\u05db\u05dc \u05d0\u05d7\u05d3 \u05de\u05d4\u05dd \u05d9\u05e9 \u05de\u05d0\u05d5\u05ea \u05d5\u05d0\u05e4\u05d9\u05dc\u05d5 \u05d0\u05dc\u05e4\u05d9 \u05de\u05d8\u05e8\u05d9\u05dd \u05e9\u05dc \u05e8\u05d9\u05ea\u05d5\u05da."], [16.2, "\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d5\u05d0 \u05d0\u05d7\u05ea \u05de\u05e9\u05d9\u05d8\u05d5\u05ea \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d4\u05d7\u05e9\u05d5\u05d1\u05d5\u05ea \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4, \u05d5\u05d1\u05dc\u05e2\u05d3\u05d9\u05d5 \u05e8\u05d5\u05d1 \u05d4\u05de\u05d1\u05e0\u05d9\u05dd \u05d4\u05de\u05ea\u05db\u05ea\u05d9\u05d9\u05dd \u05e4\u05e9\u05d5\u05d8 \u05dc\u05d0 \u05d4\u05d9\u05d5 \u05e7\u05d9\u05d9\u05de\u05d9\u05dd."], [24.7, "\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d5\u05d0 \u05d7\u05d9\u05d1\u05d5\u05e8 \u05e7\u05d1\u05d5\u05e2 \u05e9\u05dc \u05e9\u05e0\u05d9 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05d5 \u05d9\u05d5\u05ea\u05e8, \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05d7\u05d5\u05dd, \u05dc\u05d7\u05e5, \u05d0\u05d5 \u05e9\u05e0\u05d9\u05d4\u05dd."], [31.6, "\u05d1\u05e8\u05d5\u05d1 \u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd, \u05e9\u05d5\u05dc\u05d9 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e0\u05de\u05e1\u05d9\u05dd, \u05de\u05ea\u05e2\u05e8\u05d1\u05d1\u05d9\u05dd \u05d1\u05d0\u05de\u05d1\u05d8 \u05de\u05e9\u05d5\u05ea\u05e3, \u05d5\u05de\u05ea\u05de\u05e6\u05e7\u05d9\u05dd \u05dc\u05d2\u05d5\u05e3 \u05d0\u05d7\u05d3 \u05e8\u05e6\u05d9\u05e3."], [39.3, "\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05de\u05ea\u05db\u05ea \u05de\u05d9\u05dc\u05d5\u05d9, \u05db\u05de\u05d5 \u05d7\u05d5\u05d8 \u05d0\u05d5 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4, \u05db\u05d3\u05d9 \u05dc\u05de\u05dc\u05d0 \u05d0\u05ea \u05d4\u05e8\u05d5\u05d5\u05d7 \u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd."], [46.3, "\u05db\u05d0\u05df \u05d4\u05d4\u05d1\u05d3\u05dc \u05de\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d1\u05d1\u05d5\u05e8\u05d2 \u05d0\u05d5 \u05d1\u05de\u05e1\u05de\u05e8\u05ea: \u05e9\u05dd \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05e0\u05e4\u05e8\u05d3\u05d9\u05dd \u05d5\u05e0\u05e6\u05de\u05d3\u05d9\u05dd \u05de\u05db\u05e0\u05d9\u05ea, \u05d5\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05dd \u05d4\u05d5\u05e4\u05db\u05d9\u05dd \u05dc\u05d2\u05d5\u05e3 \u05d0\u05d7\u05d3."], [56.0, "\u05d5\u05d6\u05d4 \u05d2\u05dd \u05d4\u05d4\u05d1\u05d3\u05dc \u05de\u05d4\u05dc\u05d7\u05de\u05d4: \u05d1\u05d4\u05dc\u05d7\u05de\u05d4 \u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1 \u05dc\u05d0 \u05e0\u05de\u05e1\u05d4 \u05d1\u05db\u05dc\u05dc, \u05d5\u05e8\u05e7 \u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05e0\u05de\u05e1\u05d4 \u05d5\u05e0\u05db\u05e0\u05e1\u05ea \u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd."], [66.0, "\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d7\u05d9\u05e9\u05d5\u05dc \u05de\u05d5\u05db\u05e8 \u05db\u05d1\u05e8 \u05d0\u05dc\u05e4\u05d9 \u05e9\u05e0\u05d9\u05dd: \u05e0\u05e4\u05d7\u05d9\u05dd \u05d7\u05d9\u05de\u05de\u05d5 \u05d1\u05e8\u05d6\u05dc \u05d1\u05d0\u05e9 \u05d5\u05d4\u05dc\u05de\u05d5 \u05d1\u05e4\u05d8\u05d9\u05e9, \u05e2\u05d3 \u05e9\u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d4\u05ea\u05d0\u05d7\u05d5."], [74.8, "\u05d1\u05e1\u05d5\u05e3 \u05d4\u05de\u05d0\u05d4 \u05d4\u05ea\u05e9\u05e2 \u05e2\u05e9\u05e8\u05d4 \u05d4\u05d5\u05e4\u05d9\u05e2\u05d4 \u05d4\u05e7\u05e9\u05ea \u05d4\u05d7\u05e9\u05de\u05dc\u05d9\u05ea, \u05d5\u05d1\u05ea\u05d7\u05d9\u05dc\u05ea \u05d4\u05de\u05d0\u05d4 \u05d4\u05e2\u05e9\u05e8\u05d9\u05dd \u05e4\u05d5\u05ea\u05d7\u05d4 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d4\u05de\u05e6\u05d5\u05e4\u05d4."], [82.3, "\u05d1\u05de\u05dc\u05d7\u05de\u05ea \u05d4\u05e2\u05d5\u05dc\u05dd \u05d4\u05e9\u05e0\u05d9\u05d9\u05d4 \u05d4\u05d7\u05dc\u05d9\u05e3 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05ea \u05d4\u05de\u05e1\u05de\u05e8\u05d5\u05ea \u05d1\u05d1\u05e0\u05d9\u05d9\u05ea \u05d0\u05d5\u05e0\u05d9\u05d5\u05ea, \u05d5\u05e7\u05d9\u05e6\u05e8 \u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u05d6\u05de\u05df \u05d4\u05d1\u05e0\u05d9\u05d9\u05d4."], [89.2, "\u05d1\u05e9\u05e0\u05d5\u05ea \u05d4\u05d0\u05e8\u05d1\u05e2\u05d9\u05dd \u05e4\u05d5\u05ea\u05d7\u05d5 TIG \u05d5-MIG, \u05d1\u05d4\u05de\u05e9\u05da \u05d4\u05d2\u05d9\u05e2\u05d5 \u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05d5\u05dc\u05d9\u05d9\u05d6\u05e8, \u05d5\u05d1\u05e9\u05e0\u05ea 1991 \u05d2\u05dd Friction Stir Welding (FSW)."], [100.3, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea \u05d1\u05e8\u05d5\u05e8\u05d9\u05dd: \u05d7\u05d9\u05d1\u05d5\u05e8 \u05d7\u05d6\u05e7, \u05d5\u05d1\u05ea\u05db\u05e0\u05d5\u05df \u05e0\u05db\u05d5\u05df \u05d7\u05d6\u05e7 \u05db\u05de\u05d5 \u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1, \u05e9\u05d0\u05d9\u05e0\u05d5 \u05d3\u05d5\u05dc\u05e3, \u05d5\u05e7\u05dc \u05d9\u05d5\u05ea\u05e8 \u05de\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d1\u05d1\u05e8\u05d2\u05d9\u05dd."], [109.9, "\u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d2\u05dd \u05e0\u05d5\u05ea\u05df \u05d7\u05d5\u05e4\u05e9 \u05ea\u05db\u05e0\u05d5\u05df: \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d1\u05e0\u05d5\u05ea \u05de\u05d1\u05e0\u05d4 \u05de\u05dc\u05d5\u05d7\u05d5\u05ea \u05d5\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc\u05d9\u05dd \u05d1\u05de\u05e7\u05d5\u05dd \u05dc\u05e2\u05d1\u05d3 \u05d0\u05d5\u05ea\u05d5 \u05de\u05d2\u05d5\u05e9 \u05d0\u05d7\u05d3."], [117.3, "\u05d0\u05d1\u05dc \u05d9\u05e9 \u05de\u05d7\u05d9\u05e8: \u05d4\u05d7\u05d5\u05dd \u05d2\u05d5\u05e8\u05dd \u05dc\u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05d5\u05dc\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e9\u05d9\u05d5\u05e8\u05d9\u05d9\u05dd, \u05d5\u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05de\u05d1\u05e0\u05d4 \u05d4\u05d7\u05d5\u05de\u05e8 \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [125.1, "\u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d0\u05d9\u05e0\u05d5 \u05e4\u05e8\u05d9\u05e7, \u05d5\u05d0\u05d9\u05db\u05d5\u05ea\u05d5 \u05ea\u05dc\u05d5\u05d9\u05d4 \u05d1\u05e8\u05ea\u05da, \u05d1\u05e0\u05d5\u05d4\u05dc \u05d5\u05d1\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea."], [130.9, "\u05dc\u05db\u05df \u05e8\u05d9\u05ea\u05d5\u05da \u05d8\u05d5\u05d1 \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05e8\u05e7 \u05e2\u05e0\u05d9\u05d9\u05df \u05e9\u05dc \u05d9\u05d3 \u05d9\u05e6\u05d9\u05d1\u05d4, \u05d0\u05dc\u05d0 \u05e9\u05dc \u05ea\u05db\u05e0\u05d5\u05df, \u05d7\u05d5\u05de\u05e8, \u05ea\u05d4\u05dc\u05d9\u05da \u05d5\u05d1\u05e7\u05e8\u05d4."], [138.8, "\u05dc\u05db\u05dc \u05ea\u05d4\u05dc\u05d9\u05da \u05e8\u05d9\u05ea\u05d5\u05da \u05d9\u05e9 \u05de\u05e1\u05e4\u05e8 \u05dc\u05e4\u05d9 \u05ea\u05e7\u05df ISO 4063, \u05d5\u05d0\u05d5\u05ea\u05d5 \u05de\u05e1\u05e4\u05e8 \u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05d5\u05d1\u05e0\u05d4\u05dc\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da."], [147.7, "\u05dc\u05de\u05e9\u05dc: 111 \u05d4\u05d5\u05d0 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4, 135 \u05d4\u05d5\u05d0 MAG, 141 \u05d4\u05d5\u05d0 TIG, \u05d5-21 \u05d4\u05d5\u05d0 \u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e7\u05d5\u05d3\u05ea\u05d9."], [158.9, "\u05d1\u05db\u05dc \u05e4\u05e8\u05e7 \u05e0\u05e6\u05d9\u05d2 \u05d0\u05ea \u05d4\u05de\u05e1\u05e4\u05e8 \u05e9\u05dc \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05db\u05d1\u05e8 \u05d1\u05d4\u05ea\u05d7\u05dc\u05d4, \u05db\u05d3\u05d9 \u05e9\u05ea\u05d6\u05d4\u05d5 \u05d0\u05d5\u05ea\u05d5 \u05d2\u05dd \u05e2\u05dc \u05d4\u05e0\u05d9\u05d9\u05e8."], [165.6, "\u05d4\u05e7\u05d5\u05e8\u05e1 \u05d1\u05e0\u05d5\u05d9 \u05de\u05d7\u05de\u05e9 \u05e7\u05d1\u05d5\u05e6\u05d5\u05ea."], [168.0, "\u05d1\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05e0\u05dc\u05de\u05d3 \u05d0\u05ea \u05d4\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea: \u05d0\u05d9\u05da \u05e0\u05d5\u05e6\u05e8 \u05e8\u05d9\u05ea\u05d5\u05da, \u05d4\u05e7\u05e9\u05ea \u05d4\u05d7\u05e9\u05de\u05dc\u05d9\u05ea, \u05e1\u05d5\u05d2\u05d9 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd \u05d5\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [175.9, "\u05d1\u05e9\u05e0\u05d9\u05d9\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05ea\u05d4\u05dc\u05d9\u05db\u05d9 \u05d4\u05e7\u05e9\u05ea: \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4, MIG \u05d5-MAG, \u05d7\u05d5\u05d8 \u05de\u05dc\u05d9\u05ea, TIG, \u05e4\u05dc\u05d6\u05de\u05d4 \u05d5\u05e8\u05d9\u05ea\u05d5\u05da \u05ea\u05ea \u05d0\u05d1\u05e7\u05ea\u05d9."], [186.1, "\u05d1\u05e9\u05dc\u05d9\u05e9\u05d9\u05ea \u05e0\u05e2\u05d1\u05d5\u05e8 \u05dc\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d4\u05de\u05ea\u05e7\u05d3\u05de\u05d9\u05dd: \u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea, \u05dc\u05d9\u05d9\u05d6\u05e8, \u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd, \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d7\u05d9\u05db\u05d5\u05da, \u05d4\u05dc\u05d7\u05de\u05d4 \u05d5\u05e8\u05d5\u05d1\u05d5\u05d8\u05d9\u05e7\u05d4."], [196.5, "\u05d1\u05e8\u05d1\u05d9\u05e2\u05d9\u05ea \u05e0\u05e6\u05dc\u05d5\u05dc \u05dc\u05de\u05d8\u05dc\u05d5\u05e8\u05d2\u05d9\u05d4: \u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05dc\u05d7\u05d5\u05de\u05e8 \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d0\u05d9\u05da \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05e4\u05dc\u05d3\u05d5\u05ea, \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd, \u05d5\u05d0\u05d9\u05da \u05e9\u05d5\u05dc\u05d8\u05d9\u05dd \u05d1\u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd."], [206.6, "\u05d5\u05d1\u05d7\u05de\u05d9\u05e9\u05d9\u05ea \u05e0\u05e2\u05e1\u05d5\u05e7 \u05d1\u05ea\u05db\u05df \u05d5\u05d1\u05d0\u05d9\u05db\u05d5\u05ea: \u05e1\u05d9\u05de\u05d5\u05e0\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d7\u05d9\u05e9\u05d5\u05d1 \u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd, \u05e4\u05d2\u05de\u05d9\u05dd, \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea, \u05e0\u05d4\u05dc\u05d9\u05dd \u05d5\u05d4\u05e1\u05de\u05db\u05d5\u05ea, \u05d5\u05dc\u05d1\u05e1\u05d5\u05e3 \u05e2\u05dc\u05d5\u05d9\u05d5\u05ea."], [219.1, "\u05db\u05dc \u05e4\u05e8\u05e7 \u05ea\u05d4\u05dc\u05d9\u05da \u05d1\u05e0\u05d5\u05d9 \u05d1\u05d0\u05d5\u05ea\u05d4 \u05e6\u05d5\u05e8\u05d4: \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df, \u05d4\u05e6\u05d9\u05d5\u05d3, \u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd, \u05d0\u05d9\u05e4\u05d4 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d5, \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d4\u05d8\u05d9\u05e4\u05d5\u05e1\u05d9\u05d9\u05dd, \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."], [229.3, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05ea\u05d7\u05d9\u05dc \u05de\u05d4\u05d1\u05e1\u05d9\u05e1: \u05de\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05e7\u05d5\u05e8\u05d4 \u05db\u05e9\u05de\u05ea\u05db\u05ea \u05e0\u05de\u05e1\u05d4 \u05d5\u05de\u05ea\u05de\u05e6\u05e7\u05ea, \u05d5\u05de\u05d4 \u05d6\u05d4 \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05de\u05d5\u05e9\u05e4\u05e2 \u05de\u05d7\u05d5\u05dd."]]};
window.MH_TR["ch01"]={"t": "\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da", "l": [[3.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d1\u05d9\u05df \u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05d1\u05ea\u05d5\u05da \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e2\u05e6\u05de\u05d5, \u05de\u05d4\u05e8\u05d2\u05e2 \u05e9\u05d4\u05d7\u05d5\u05dd \u05de\u05d2\u05d9\u05e2 \u05d5\u05e2\u05d3 \u05e9\u05d4\u05de\u05ea\u05db\u05ea \u05de\u05ea\u05de\u05e6\u05e7\u05ea."], [10.5, "\u05e8\u05d5\u05d1 \u05ea\u05d4\u05dc\u05d9\u05db\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4 \u05d4\u05dd \u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d9\u05ea\u05d5\u05da: \u05de\u05e7\u05d5\u05e8 \u05d7\u05d5\u05dd \u05de\u05e8\u05d5\u05db\u05d6 \u05de\u05de\u05d9\u05e1 \u05d0\u05ea \u05e9\u05d5\u05dc\u05d9 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05d5\u05d4\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d5\u05ea\u05db\u05ea \u05de\u05ea\u05de\u05e6\u05e7\u05ea \u05dc\u05ea\u05e4\u05e8 \u05d0\u05d7\u05d3."], [21.0, "\u05d1\u05db\u05dc \u05e8\u05d9\u05ea\u05d5\u05da \u05db\u05d6\u05d4 \u05d9\u05e9 \u05d0\u05e8\u05d1\u05e2\u05d4 \u05de\u05e8\u05db\u05d9\u05d1\u05d9\u05dd: \u05de\u05e7\u05d5\u05e8 \u05d7\u05d5\u05dd, \u05d0\u05de\u05d1\u05d8 \u05de\u05d5\u05ea\u05da, \u05d4\u05d2\u05e0\u05d4 \u05e2\u05dc \u05d4\u05d0\u05de\u05d1\u05d8, \u05d5\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05de\u05ea\u05db\u05ea \u05de\u05d9\u05dc\u05d5\u05d9."], [31.0, "\u05de\u05e7\u05d5\u05e8 \u05d4\u05d7\u05d5\u05dd \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05dc\u05d4\u05d1\u05ea \u05d2\u05d6, \u05e7\u05e9\u05ea \u05d7\u05e9\u05de\u05dc\u05d9\u05ea, \u05e7\u05e8\u05df \u05dc\u05d9\u05d9\u05d6\u05e8 \u05d0\u05d5 \u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd."], [37.7, "\u05d4\u05d4\u05d1\u05d3\u05dc \u05d4\u05d7\u05e9\u05d5\u05d1 \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd \u05d4\u05d5\u05d0 \u05db\u05de\u05d4 \u05de\u05e8\u05d5\u05db\u05d6 \u05d4\u05d7\u05d5\u05dd, \u05db\u05dc\u05d5\u05de\u05e8 \u05db\u05de\u05d4 \u05d4\u05e1\u05e4\u05e7 \u05e0\u05db\u05e0\u05e1 \u05dc\u05db\u05dc \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e8\u05d1\u05d5\u05e2 \u05e9\u05dc \u05e9\u05d8\u05d7."], [45.8, "\u05dc\u05d4\u05d1\u05d4 \u05de\u05e4\u05d6\u05e8\u05ea \u05d0\u05ea \u05d4\u05d7\u05d5\u05dd \u05e2\u05dc \u05e9\u05d8\u05d7 \u05d2\u05d3\u05d5\u05dc: \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e8\u05d7\u05d1 \u05d5\u05e8\u05d3\u05d5\u05d3, \u05d5\u05d4\u05e8\u05d1\u05d4 \u05d7\u05d5\u05dd \u05d1\u05d5\u05e8\u05d7 \u05dc\u05d7\u05d5\u05de\u05e8 \u05e9\u05de\u05e1\u05d1\u05d9\u05d1."], [53.7, "\u05e7\u05e9\u05ea \u05d7\u05e9\u05de\u05dc\u05d9\u05ea \u05de\u05e8\u05d5\u05db\u05d6\u05ea \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05dc\u05db\u05df \u05d4\u05d9\u05d0 \u05de\u05de\u05d9\u05e1\u05d4 \u05de\u05d4\u05e8 \u05d5\u05d9\u05d5\u05e6\u05e8\u05ea \u05e8\u05d9\u05ea\u05d5\u05da \u05e6\u05e8 \u05d5\u05e2\u05de\u05d5\u05e7 \u05d9\u05d5\u05ea\u05e8."], [61.1, "\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d5\u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05de\u05e8\u05d5\u05db\u05d6\u05d9\u05dd \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8: \u05d4\u05dd \u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05ea\u05e2\u05dc\u05d4 \u05e6\u05e8\u05d4 \u05e9\u05dc \u05d0\u05d3\u05d9 \u05de\u05ea\u05db\u05ea, keyhole, \u05d5\u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05dc\u05e2\u05d5\u05de\u05e7 \u05e8\u05d1 \u05d1\u05ea\u05e4\u05e8 \u05e6\u05e8 \u05de\u05d0\u05d5\u05d3."], [71.5, "\u05db\u05db\u05dc \u05e9\u05d4\u05d7\u05d5\u05dd \u05de\u05e8\u05d5\u05db\u05d6 \u05d9\u05d5\u05ea\u05e8, \u05e0\u05db\u05e0\u05e1 \u05e4\u05d7\u05d5\u05ea \u05d7\u05d5\u05dd \u05dc\u05d7\u05dc\u05e7, \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05de\u05d5\u05e9\u05e4\u05e2 \u05e7\u05d8\u05df \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d4\u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."], [80.1, "\u05de\u05ea\u05d7\u05ea \u05dc\u05de\u05e7\u05d5\u05e8 \u05d4\u05d7\u05d5\u05dd \u05e0\u05d5\u05e6\u05e8 \u05d0\u05de\u05d1\u05d8 \u05e8\u05d9\u05ea\u05d5\u05da: \u05db\u05de\u05d5\u05ea \u05e7\u05d8\u05e0\u05d4 \u05e9\u05dc \u05de\u05ea\u05db\u05ea \u05e0\u05d5\u05d6\u05dc\u05d9\u05ea, \u05e9\u05d1\u05e4\u05dc\u05d3\u05d4 \u05d7\u05de\u05d4 \u05de-1,500 \u05de\u05e2\u05dc\u05d5\u05ea."], [89.0, "\u05d4\u05d0\u05de\u05d1\u05d8 \u05e0\u05e2 \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d9\u05d7\u05d3 \u05e2\u05dd \u05de\u05e7\u05d5\u05e8 \u05d4\u05d7\u05d5\u05dd."], [92.6, "\u05d1\u05d7\u05d6\u05d9\u05ea \u05d4\u05d0\u05de\u05d1\u05d8 \u05d4\u05de\u05ea\u05db\u05ea \u05e0\u05de\u05e1\u05d4, \u05d5\u05d1\u05d7\u05dc\u05e7\u05d5 \u05d4\u05d0\u05d7\u05d5\u05e8\u05d9 \u05d4\u05d9\u05d0 \u05de\u05ea\u05de\u05e6\u05e7\u05ea \u05d5\u05d9\u05d5\u05e6\u05e8\u05ea \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8."], [99.6, "\u05d1\u05ea\u05d5\u05da \u05d4\u05d0\u05de\u05d1\u05d8 \u05d4\u05de\u05ea\u05db\u05ea \u05d6\u05d5\u05e8\u05de\u05ea \u05d5\u05de\u05ea\u05e2\u05e8\u05d1\u05d1\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05ea\u05db\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05d7\u05d9\u05d3\u05d4 \u05d9\u05d7\u05e1\u05d9\u05ea \u05d1\u05d4\u05e8\u05db\u05d1\u05d4."], [107.0, "\u05d4\u05d4\u05ea\u05de\u05e6\u05e7\u05d5\u05ea \u05de\u05ea\u05d7\u05d9\u05dc\u05d4 \u05de\u05d3\u05e4\u05e0\u05d5\u05ea \u05d4\u05d0\u05de\u05d1\u05d8: \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05e6\u05d5\u05de\u05d7\u05d9\u05dd \u05de\u05e7\u05d5 \u05d4\u05d4\u05d9\u05ea\u05d5\u05da \u05e4\u05e0\u05d9\u05de\u05d4, \u05d0\u05dc \u05de\u05e8\u05db\u05d6 \u05d4\u05ea\u05e4\u05e8."], [114.0, "\u05d1\u05d2\u05dc\u05dc \u05d6\u05d4 \u05de\u05e8\u05db\u05d6 \u05d4\u05ea\u05e4\u05e8 \u05d4\u05d5\u05d0 \u05d4\u05de\u05e7\u05d5\u05dd \u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05e9\u05de\u05ea\u05de\u05e6\u05e7, \u05d5\u05e9\u05dd \u05e0\u05d5\u05d8\u05d9\u05dd \u05dc\u05d4\u05e6\u05d8\u05d1\u05e8 \u05d6\u05d9\u05d4\u05d5\u05de\u05d9\u05dd \u05d5\u05dc\u05d4\u05d5\u05e4\u05d9\u05e2 \u05e1\u05d3\u05e7\u05d9 \u05d4\u05ea\u05de\u05e6\u05e7\u05d5\u05ea."], [123.0, "\u05de\u05ea\u05db\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d9\u05d0 \u05ea\u05e2\u05e8\u05d5\u05d1\u05ea: \u05d7\u05dc\u05e7 \u05de\u05de\u05e0\u05d4 \u05d4\u05d2\u05d9\u05e2 \u05de\u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1 \u05e9\u05e0\u05de\u05e1\u05d4, \u05d5\u05d7\u05dc\u05e7 \u05de\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9."], [130.8, "\u05d4\u05d7\u05dc\u05e7 \u05e9\u05dc \u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1 \u05d1\u05ea\u05d5\u05da \u05de\u05ea\u05db\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e7\u05e8\u05d0 \u05d3\u05d9\u05dc\u05d5\u05dc."], [135.6, "\u05dc\u05de\u05e9\u05dc, \u05d0\u05dd \u05e9\u05dc\u05d9\u05e9 \u05de\u05e9\u05d8\u05d7 \u05d4\u05d7\u05ea\u05da \u05e9\u05dc \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d2\u05d9\u05e2 \u05de\u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1, \u05d4\u05d3\u05d9\u05dc\u05d5\u05dc \u05d4\u05d5\u05d0 \u05db-33%."], [143.5, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05dc\u05d9 \u05de\u05ea\u05db\u05ea \u05de\u05d9\u05dc\u05d5\u05d9, \u05dc\u05de\u05e9\u05dc TIG \u05d1\u05dc\u05d9 \u05d7\u05d5\u05d8, \u05d4\u05d3\u05d9\u05dc\u05d5\u05dc \u05d4\u05d5\u05d0 100%."], [149.7, "\u05d4\u05d3\u05d9\u05dc\u05d5\u05dc \u05e7\u05d5\u05d1\u05e2 \u05d0\u05ea \u05d4\u05d4\u05e8\u05db\u05d1 \u05d4\u05db\u05d9\u05de\u05d9 \u05e9\u05dc \u05d4\u05ea\u05e4\u05e8, \u05d5\u05dc\u05db\u05df \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d7\u05d5\u05d8 \u05e9\u05de\u05ea\u05d0\u05d9\u05dd \u05d2\u05dd \u05dc\u05ea\u05e2\u05e8\u05d5\u05d1\u05ea, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05dc\u05d7\u05d5\u05de\u05e8 \u05d4\u05d1\u05e1\u05d9\u05e1."], [157.8, "\u05d6\u05d4 \u05e7\u05e8\u05d9\u05d8\u05d9 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e9\u05dc \u05e9\u05ea\u05d9 \u05de\u05ea\u05db\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea, \u05db\u05de\u05d5 \u05e4\u05dc\u05d3\u05ea \u05d0\u05dc-\u05d7\u05dc\u05d3 \u05dc\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df."], [164.8, "\u05d0\u05dd \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05e8\u05d9\u05ea\u05d5\u05da, \u05de\u05dc\u05d8\u05e9\u05d9\u05dd \u05d5\u05e6\u05d5\u05e8\u05d1\u05d9\u05dd \u05d1\u05d7\u05d5\u05de\u05e6\u05d4, \u05e8\u05d5\u05d0\u05d9\u05dd \u05d1\u05e2\u05d9\u05df \u05db\u05de\u05d4 \u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd."], [170.8, "\u05d1\u05de\u05e8\u05db\u05d6 \u05e0\u05de\u05e6\u05d0\u05ea \u05de\u05ea\u05db\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da: \u05d4\u05d0\u05d6\u05d5\u05e8 \u05e9\u05d4\u05d9\u05d4 \u05e0\u05d5\u05d6\u05dc\u05d9 \u05d5\u05d4\u05ea\u05de\u05e6\u05e7."], [176.0, "\u05d4\u05d2\u05d1\u05d5\u05dc \u05e9\u05dc\u05d4 \u05e2\u05dd \u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1 \u05e0\u05e7\u05e8\u05d0 \u05e7\u05d5 \u05d4\u05d4\u05d9\u05ea\u05d5\u05da."], [180.0, "\u05de\u05e1\u05d1\u05d9\u05d1 \u05dc\u05d5 \u05d9\u05e9 \u05d0\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05de\u05d5\u05e9\u05e4\u05e2 \u05de\u05d7\u05d5\u05dd, HAZ: \u05de\u05ea\u05db\u05ea \u05e9\u05dc\u05d0 \u05e0\u05de\u05e1\u05d4, \u05d0\u05d1\u05dc \u05d4\u05ea\u05d7\u05de\u05de\u05d4 \u05de\u05e1\u05e4\u05d9\u05e7 \u05db\u05d3\u05d9 \u05e9\u05d4\u05de\u05d1\u05e0\u05d4 \u05e9\u05dc\u05d4 \u05d9\u05e9\u05ea\u05e0\u05d4."], [189.4, "\u05d5\u05de\u05e2\u05d1\u05e8 \u05dc\u05d5 \u05e0\u05de\u05e6\u05d0\u05ea \u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1, \u05e9\u05dc\u05d0 \u05d4\u05d5\u05e9\u05e4\u05e2\u05d4."], [193.7, "\u05d1\u05db\u05dc \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d1-HAZ \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e2\u05d5\u05dc\u05d4 \u05dc\u05e9\u05d9\u05d0 \u05d5\u05d9\u05d5\u05e8\u05d3\u05ea, \u05d5\u05db\u05db\u05dc \u05e9\u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05e7\u05e8\u05d5\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05e7\u05d5 \u05d4\u05d4\u05d9\u05ea\u05d5\u05da, \u05d4\u05e9\u05d9\u05d0 \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8."], [203.0, "\u05d1\u05e4\u05dc\u05d3\u05d4, \u05d4\u05d0\u05d6\u05d5\u05e8 \u05e9\u05d4\u05ea\u05d7\u05de\u05dd \u05de\u05e2\u05dc 727 \u05de\u05e2\u05dc\u05d5\u05ea \u05e2\u05d5\u05d1\u05e8 \u05e9\u05d9\u05e0\u05d5\u05d9 \u05de\u05d1\u05e0\u05d9."], [209.1, "\u05dc\u05d9\u05d3 \u05e7\u05d5 \u05d4\u05d4\u05d9\u05ea\u05d5\u05da \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d2\u05d3\u05dc\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05d5\u05d0\u05dd \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8, \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d6\u05d4 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05e7\u05e9\u05d4 \u05d5\u05e9\u05d1\u05d9\u05e8."], [216.6, "\u05e7\u05e6\u05ea \u05d9\u05d5\u05ea\u05e8 \u05e8\u05d7\u05d5\u05e7 \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d3\u05d5\u05d5\u05e7\u05d0 \u05de\u05ea\u05e2\u05d3\u05e0\u05d9\u05dd, \u05d5\u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d8\u05d5\u05d1\u05d5\u05ea \u05d9\u05d7\u05e1\u05d9\u05ea."], [221.9, "\u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05d5\u05e7\u05e9\u05d4, \u05db\u05de\u05d5 6061 \u05d1\u05de\u05e6\u05d1 T6, \u05d4-HAZ \u05de\u05ea\u05e8\u05db\u05da \u05d5\u05de\u05d0\u05d1\u05d3 \u05d7\u05dc\u05e7 \u05e0\u05d9\u05db\u05e8 \u05de\u05d4\u05d7\u05d5\u05d6\u05e7."], [230.9, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05de\u05d8\u05dc\u05d5\u05e8\u05d2\u05d9\u05d4 \u05e0\u05e8\u05d7\u05d9\u05d1 \u05e2\u05dc \u05d6\u05d4. \u05db\u05e8\u05d2\u05e2 \u05d7\u05e9\u05d5\u05d1 \u05dc\u05d6\u05db\u05d5\u05e8 \u05e9\u05d4-HAZ \u05d4\u05d5\u05d0 \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d4\u05d7\u05d5\u05dc\u05d9\u05d4 \u05d4\u05d7\u05dc\u05e9\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8."], [239.9, "\u05de\u05ea\u05db\u05ea \u05e0\u05d5\u05d6\u05dc\u05d9\u05ea \u05de\u05d2\u05d9\u05d1\u05d4 \u05de\u05d4\u05e8 \u05de\u05d0\u05d5\u05d3 \u05e2\u05dd \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8: \u05d7\u05de\u05e6\u05df, \u05d7\u05e0\u05e7\u05df \u05d5\u05de\u05d9\u05de\u05df \u05e0\u05db\u05e0\u05e1\u05d9\u05dd \u05dc\u05d0\u05de\u05d1\u05d8."], [247.1, "\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05d4\u05d9\u05d0 \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea, \u05ea\u05d7\u05de\u05d5\u05e6\u05d5\u05ea \u05d5\u05ea\u05e4\u05e8 \u05e9\u05d1\u05d9\u05e8, \u05d5\u05dc\u05db\u05df \u05db\u05dc \u05ea\u05d4\u05dc\u05d9\u05da \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05d2\u05df \u05e2\u05dc \u05d4\u05d0\u05de\u05d1\u05d8 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05e9\u05d4\u05d9."], [255.5, "\u05d4\u05d3\u05e8\u05da \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05d4\u05d9\u05d0 \u05d2\u05d6 \u05de\u05d2\u05df, \u05db\u05de\u05d5 \u05d0\u05e8\u05d2\u05d5\u05df, \u05d4\u05dc\u05d9\u05d5\u05dd \u05d0\u05d5 CO\u2082 \u05d5\u05ea\u05e2\u05e8\u05d5\u05d1\u05d5\u05ea \u05e9\u05dc\u05d4\u05dd, \u05e9\u05d3\u05d5\u05d7\u05e7 \u05d0\u05ea \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8 \u05de\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [264.9, "\u05d4\u05d3\u05e8\u05da \u05d4\u05e9\u05e0\u05d9\u05d9\u05d4 \u05d4\u05d9\u05d0 flux: \u05d7\u05d5\u05de\u05e8 \u05e9\u05e0\u05de\u05e1 \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e9\u05db\u05d1\u05ea slag \u05e9\u05de\u05db\u05e1\u05d4 \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8, \u05d5\u05d2\u05dd \u05de\u05e9\u05d7\u05e8\u05e8 \u05d2\u05d6\u05d9\u05dd \u05de\u05d2\u05d9\u05e0\u05d9\u05dd."], [273.9, "\u05db\u05da \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d4\u05de\u05e6\u05d5\u05e4\u05d4, \u05d4\u05d7\u05d5\u05d8 \u05d4\u05de\u05dc\u05d9\u05ea \u05d5\u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05ea\u05ea-\u05d0\u05d1\u05e7\u05ea\u05d9."], [279.2, "\u05d5\u05d4\u05d3\u05e8\u05da \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9\u05ea \u05d4\u05d9\u05d0 \u05d5\u05d0\u05e7\u05d5\u05dd: \u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05d4\u05d7\u05dc\u05e7 \u05e0\u05de\u05e6\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05ea\u05d0 \u05e8\u05d9\u05e7 \u05de\u05d0\u05d5\u05d5\u05d9\u05e8."], [287.3, "\u05d2\u05d5\u05d3\u05dc \u05d7\u05e9\u05d5\u05d1 \u05e9\u05de\u05d7\u05d1\u05e8 \u05d0\u05ea \u05db\u05dc \u05d6\u05d4 \u05d4\u05d5\u05d0 heat input: \u05db\u05de\u05d4 \u05d7\u05d5\u05dd \u05e0\u05db\u05e0\u05e1 \u05dc\u05db\u05dc \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e9\u05dc \u05ea\u05e4\u05e8."], [294.4, "\u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05de\u05d4\u05de\u05ea\u05d7, \u05de\u05d4\u05d6\u05e8\u05dd \u05d5\u05de\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05de\u05db\u05e4\u05d9\u05dc\u05d9\u05dd \u05d1\u05de\u05e7\u05d3\u05dd \u05d4\u05d9\u05e2\u05d9\u05dc\u05d5\u05ea \u05e9\u05dc \u05d4\u05ea\u05d4\u05dc\u05d9\u05da."], [301.6, "\u05dc\u05de\u05e9\u05dc, \u05d1\u05e8\u05d9\u05ea\u05d5\u05da MAG \u05d1\u05de\u05ea\u05d7 \u05e9\u05dc 25 \u05d5\u05d5\u05dc\u05d8, \u05d6\u05e8\u05dd \u05e9\u05dc 200 \u05d0\u05de\u05e4\u05e8 \u05d5\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e9\u05dc 5 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d1\u05e9\u05e0\u05d9\u05d9\u05d4, \u05d0\u05e0\u05e8\u05d2\u05d9\u05d9\u05ea \u05d4\u05e7\u05e9\u05ea \u05d4\u05d9\u05d0 \u05e7\u05d9\u05dc\u05d5\u05d2'\u05d0\u05d5\u05dc \u05d0\u05d7\u05d3 \u05dc\u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."], [313.7, "\u05de\u05e7\u05d3\u05dd \u05d4\u05d9\u05e2\u05d9\u05dc\u05d5\u05ea \u05e9\u05dc MAG \u05d4\u05d5\u05d0 0.8, \u05d5\u05dc\u05db\u05df \u05d4-heat input \u05d4\u05d5\u05d0 0.8 \u05e7\u05d9\u05dc\u05d5\u05d2'\u05d0\u05d5\u05dc \u05dc\u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."], [322.0, "Heat input \u05d2\u05d1\u05d5\u05d4 \u05de\u05e8\u05d7\u05d9\u05d1 \u05d0\u05ea \u05d4-HAZ, \u05de\u05d0\u05d8 \u05d0\u05ea \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d5\u05de\u05d2\u05d3\u05d9\u05dc \u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd."], [327.9, "Heat input \u05e0\u05de\u05d5\u05da \u05de\u05d3\u05d9 \u05d2\u05d5\u05e8\u05dd \u05dc\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8, \u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05e1\u05d5\u05d9\u05de\u05d5\u05ea \u05dc\u05e1\u05db\u05e0\u05ea \u05d4\u05ea\u05e7\u05e9\u05d5\u05ea \u05d5\u05e1\u05d3\u05e7\u05d9\u05dd."], [334.6, "\u05dc\u05db\u05df \u05d1\u05e0\u05d4\u05dc\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da \u05e8\u05d1\u05d9\u05dd \u05de\u05d2\u05d1\u05d9\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4-heat input \u05dc\u05d8\u05d5\u05d5\u05d7 \u05de\u05d5\u05d2\u05d3\u05e8."], [340.3, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05de\u05e7\u05d5\u05e8 \u05d7\u05d5\u05dd \u05de\u05e8\u05d5\u05db\u05d6 \u05d9\u05d5\u05e6\u05e8 \u05d0\u05de\u05d1\u05d8 \u05de\u05d5\u05ea\u05da, \u05d4\u05d0\u05de\u05d1\u05d8 \u05de\u05d5\u05d2\u05df \u05de\u05d4\u05d0\u05d5\u05d5\u05d9\u05e8, \u05d5\u05de\u05ea\u05de\u05e6\u05e7 \u05de\u05d4\u05d3\u05e4\u05e0\u05d5\u05ea \u05dc\u05de\u05e8\u05db\u05d6."], [349.0, "\u05e1\u05d1\u05d9\u05d1\u05d5 \u05e0\u05d5\u05e6\u05e8 HAZ, \u05e9\u05ea\u05db\u05d5\u05e0\u05d5\u05ea\u05d9\u05d5 \u05ea\u05dc\u05d5\u05d9\u05d5\u05ea \u05d1\u05d7\u05d5\u05de\u05e8 \u05d5\u05d1-heat input."], [354.7, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05de\u05e7\u05d5\u05e8 \u05d4\u05d7\u05d5\u05dd \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d4\u05e7\u05e9\u05ea \u05d4\u05d7\u05e9\u05de\u05dc\u05d9\u05ea, \u05d5\u05d0\u05ea \u05de\u05e7\u05d5\u05e8\u05d5\u05ea \u05d4\u05d4\u05e1\u05e4\u05e7 \u05e9\u05de\u05d6\u05d9\u05e0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4."]]};
window.MH_TR["ch02"]={"t": "\u05d4\u05e7\u05e9\u05ea \u05d4\u05d7\u05e9\u05de\u05dc\u05d9\u05ea \u05d5\u05de\u05e7\u05d5\u05e8\u05d5\u05ea \u05d4\u05d4\u05e1\u05e4\u05e7", "l": [[3.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd \u05e8\u05d0\u05d9\u05e0\u05d5 \u05e9\u05e8\u05d9\u05ea\u05d5\u05da \u05e6\u05e8\u05d9\u05da \u05de\u05e7\u05d5\u05e8 \u05d7\u05d5\u05dd \u05de\u05e8\u05d5\u05db\u05d6. \u05d1\u05e8\u05d5\u05d1 \u05d4\u05e8\u05d9\u05ea\u05d5\u05db\u05d9\u05dd \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4 \u05d4\u05de\u05e7\u05d5\u05e8 \u05d4\u05d6\u05d4 \u05d4\u05d5\u05d0 \u05e7\u05e9\u05ea \u05d7\u05e9\u05de\u05dc\u05d9\u05ea."], [11.8, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d1\u05d9\u05df \u05de\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05e7\u05e9\u05ea, \u05d0\u05d9\u05da \u05e9\u05d5\u05dc\u05d8\u05d9\u05dd \u05d1\u05d4, \u05d5\u05d0\u05d9\u05da \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d5\u05de\u05e4\u05e2\u05d9\u05dc\u05d9\u05dd \u05d0\u05ea \u05de\u05e7\u05d5\u05e8 \u05d4\u05d4\u05e1\u05e4\u05e7 \u05e9\u05de\u05d6\u05d9\u05df \u05d0\u05d5\u05ea\u05d4."], [20.5, "\u05e7\u05e9\u05ea \u05d7\u05e9\u05de\u05dc\u05d9\u05ea \u05d4\u05d9\u05d0 \u05d6\u05e8\u05dd \u05d7\u05e9\u05de\u05dc\u05d9 \u05e9\u05e2\u05d5\u05d1\u05e8 \u05d3\u05e8\u05da \u05d2\u05d6, \u05d1\u05d9\u05df \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05dc\u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7."], [26.6, "\u05d4\u05d7\u05d5\u05dd \u05d4\u05d2\u05d1\u05d5\u05d4 \u05d4\u05d5\u05e4\u05da \u05d0\u05ea \u05d4\u05d2\u05d6 \u05dc\u05e4\u05dc\u05d6\u05de\u05d4: \u05d2\u05d6 \u05de\u05d9\u05d5\u05e0\u05df \u05e9\u05de\u05d5\u05dc\u05d9\u05da \u05d7\u05e9\u05de\u05dc."], [32.1, "\u05d1\u05ea\u05d5\u05da \u05d4\u05e7\u05e9\u05ea \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05d0\u05dc\u05e4\u05d9 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d4\u05e8\u05d1\u05d4 \u05de\u05e2\u05dc \u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05d4\u05d9\u05ea\u05d5\u05da \u05e9\u05dc \u05db\u05dc \u05de\u05ea\u05db\u05ea."], [38.8, "\u05d4\u05de\u05e2\u05d2\u05dc \u05d4\u05d7\u05e9\u05de\u05dc\u05d9 \u05db\u05d5\u05dc\u05dc \u05d0\u05ea \u05de\u05e7\u05d5\u05e8 \u05d4\u05d4\u05e1\u05e4\u05e7, \u05db\u05d1\u05dc \u05d0\u05dc \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4, \u05d4\u05e7\u05e9\u05ea, \u05d4\u05d7\u05dc\u05e7, \u05d5\u05db\u05d1\u05dc \u05d7\u05d6\u05e8\u05d4 \u05d0\u05dc \u05d4\u05de\u05db\u05d5\u05e0\u05d4."], [47.5, "\u05d1\u05e9\u05d8\u05d7 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05db\u05d1\u05dc \u05d4\u05d7\u05d6\u05e8\u05d4 \"\u05d4\u05d0\u05e8\u05e7\u05d4\", \u05d0\u05d1\u05dc \u05d1\u05e4\u05d5\u05e2\u05dc \u05d4\u05d5\u05d0 \u05d7\u05dc\u05e7 \u05de\u05de\u05e2\u05d2\u05dc \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05dc\u05d0 \u05d4\u05d0\u05e8\u05e7\u05ea \u05d1\u05d8\u05d9\u05d7\u05d5\u05ea."], [55.7, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05de\u05ea\u05d7 \u05e0\u05de\u05d5\u05da \u05d9\u05d7\u05e1\u05d9\u05ea \u05d5\u05d1\u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4: \u05de\u05ea\u05d7 \u05d4\u05e7\u05e9\u05ea \u05d4\u05d5\u05d0 \u05d1\u05e2\u05e8\u05da 10 \u05e2\u05d3 40 \u05d5\u05d5\u05dc\u05d8, \u05d5\u05d4\u05d6\u05e8\u05dd \u05e2\u05e9\u05e8\u05d5\u05ea \u05e2\u05d3 \u05de\u05d0\u05d5\u05ea \u05d0\u05de\u05e4\u05e8."], [66.3, "\u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05e7\u05e9\u05ea \u05e0\u05d3\u05dc\u05e7\u05ea, \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05e1\u05e4\u05e7\u05ea \u05de\u05ea\u05d7 \u05e8\u05d9\u05e7\u05dd \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05db\u05d3\u05d9 \u05e9\u05d9\u05d4\u05d9\u05d4 \u05e7\u05dc \u05dc\u05d4\u05e6\u05d9\u05ea \u05d0\u05d5\u05ea\u05d4."], [73.3, "\u05de\u05ea\u05d7 \u05d4\u05e7\u05e9\u05ea \u05ea\u05dc\u05d5\u05d9 \u05d1\u05d0\u05d5\u05e8\u05da \u05e9\u05dc\u05d4: \u05e7\u05e9\u05ea \u05d0\u05e8\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d3\u05d5\u05e8\u05e9\u05ea \u05de\u05ea\u05d7 \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05de\u05e4\u05d6\u05e8\u05ea \u05d0\u05ea \u05d4\u05d7\u05d5\u05dd \u05e2\u05dc \u05e9\u05d8\u05d7 \u05e8\u05d7\u05d1 \u05d9\u05d5\u05ea\u05e8."], [82.1, "\u05d4\u05d6\u05e8\u05dd \u05e7\u05d5\u05d1\u05e2 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05db\u05de\u05d4 \u05de\u05ea\u05db\u05ea \u05e0\u05de\u05e1\u05d4 \u05d5\u05db\u05de\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4."], [87.2, "\u05de\u05e6\u05d9\u05ea\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea \u05d1\u05e0\u05d2\u05d9\u05e2\u05d4 \u05e7\u05e6\u05e8\u05d4 \u05e9\u05dc \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d1\u05d7\u05dc\u05e7, \u05d0\u05d5 \u05d1\u05dc\u05d9 \u05de\u05d2\u05e2, \u05d1\u05e2\u05d6\u05e8\u05ea \u05de\u05ea\u05d7 \u05d1\u05ea\u05d3\u05e8 \u05d2\u05d1\u05d5\u05d4, \u05e9\u05e0\u05e4\u05d5\u05e5 \u05d1-TIG."], [96.2, "\u05de\u05e7\u05d5\u05e8 \u05d4\u05d4\u05e1\u05e4\u05e7 \u05d9\u05db\u05d5\u05dc \u05dc\u05e1\u05e4\u05e7 \u05d6\u05e8\u05dd \u05d9\u05e9\u05e8, DC, \u05d0\u05d5 \u05d6\u05e8\u05dd \u05d7\u05d9\u05dc\u05d5\u05e4\u05d9\u05df, AC."], [103.0, "\u05d1\u05d6\u05e8\u05dd \u05d9\u05e9\u05e8 \u05d9\u05e9 \u05de\u05e9\u05de\u05e2\u05d5\u05ea \u05dc\u05e7\u05d5\u05d8\u05d1\u05d9\u05d5\u05ea: \u05dc\u05d0\u05d9\u05d6\u05d4 \u05e7\u05d5\u05d8\u05d1 \u05de\u05d7\u05d5\u05d1\u05e8\u05ea \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4."], [108.7, "\u05db\u05e9\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05d7\u05d5\u05d1\u05e8\u05ea \u05dc\u05de\u05d9\u05e0\u05d5\u05e1, DCEN, \u05d1-TIG \u05e8\u05d5\u05d1 \u05d4\u05d7\u05d5\u05dd \u05e0\u05db\u05e0\u05e1 \u05dc\u05d7\u05dc\u05e7: \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05d5\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05e0\u05e9\u05d0\u05e8\u05ea \u05e7\u05e8\u05d4 \u05d9\u05d7\u05e1\u05d9\u05ea."], [119.2, "\u05db\u05e9\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05d7\u05d5\u05d1\u05e8\u05ea \u05dc\u05e4\u05dc\u05d5\u05e1, DCEP, \u05d9\u05d5\u05ea\u05e8 \u05d7\u05d5\u05dd \u05e2\u05d5\u05d1\u05e8 \u05dc\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4, \u05d5\u05d1-TIG \u05d4\u05d9\u05d0 \u05de\u05ea\u05d7\u05de\u05de\u05ea \u05de\u05d0\u05d5\u05d3."], [127.4, "\u05d1-MIG \u05d5-MAG, \u05dc\u05e2\u05d5\u05de\u05ea \u05d6\u05d0\u05ea, \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05db\u05de\u05e2\u05d8 \u05ea\u05de\u05d9\u05d3 \u05d1-DCEP, \u05db\u05d9 \u05db\u05da \u05d4\u05e7\u05e9\u05ea \u05d9\u05e6\u05d9\u05d1\u05d4 \u05d5\u05d4\u05de\u05e2\u05d1\u05e8 \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8 \u05d7\u05dc\u05e7."], [136.0, "\u05d1\u05d6\u05e8\u05dd \u05d7\u05d9\u05dc\u05d5\u05e4\u05d9\u05df \u05d4\u05e7\u05d5\u05d8\u05d1\u05d9\u05d5\u05ea \u05de\u05ea\u05d7\u05dc\u05e4\u05ea \u05e4\u05e2\u05de\u05d9\u05dd \u05e8\u05d1\u05d5\u05ea \u05d1\u05e9\u05e0\u05d9\u05d9\u05d4, \u05d5\u05d1\u05d7\u05e6\u05d9 \u05d4\u05de\u05d7\u05d6\u05d5\u05e8 \u05e9\u05d1\u05d5 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d7\u05d9\u05d5\u05d1\u05d9\u05ea, \u05d4\u05e7\u05e9\u05ea \u05de\u05e0\u05e7\u05d4 \u05d0\u05ea \u05e9\u05db\u05d1\u05ea \u05d4\u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [146.7, "\u05dc\u05db\u05df \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d1-TIG \u05d1\u05d6\u05e8\u05dd \u05d7\u05d9\u05dc\u05d5\u05e4\u05d9\u05df: \u05d4\u05e0\u05d9\u05e7\u05d5\u05d9 \u05de\u05e1\u05d9\u05e8 \u05d0\u05ea \u05d4\u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05d4\u05e7\u05e9\u05d4 \u05e9\u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd."], [155.1, "\u05dc\u05de\u05e7\u05d5\u05e8\u05d5\u05ea \u05d4\u05e1\u05e4\u05e7 \u05d9\u05e9 \u05e9\u05e0\u05d9 \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05dd \u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd: \u05d6\u05e8\u05dd \u05e7\u05d1\u05d5\u05e2, CC, \u05d5\u05de\u05ea\u05d7 \u05e7\u05d1\u05d5\u05e2, CV."], [163.5, "\u05d1\u05de\u05e7\u05d5\u05e8 \u05d6\u05e8\u05dd \u05e7\u05d1\u05d5\u05e2, \u05db\u05e9\u05d0\u05d5\u05e8\u05da \u05d4\u05e7\u05e9\u05ea \u05de\u05e9\u05ea\u05e0\u05d4, \u05d4\u05de\u05ea\u05d7 \u05de\u05e9\u05ea\u05e0\u05d4, \u05d0\u05d1\u05dc \u05d4\u05d6\u05e8\u05dd \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05d6\u05d6."], [171.2, "\u05d6\u05d4 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4 \u05d5\u05dc-TIG, \u05e9\u05d1\u05d4\u05dd \u05d4\u05d9\u05d3 \u05e9\u05dc \u05d4\u05e8\u05ea\u05da \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05ea \u05d0\u05d5\u05e8\u05da \u05d4\u05e7\u05e9\u05ea, \u05d5\u05d4\u05d5\u05d0 \u05de\u05e9\u05ea\u05e0\u05d4 \u05db\u05dc \u05d4\u05d6\u05de\u05df."], [179.3, "\u05d1\u05de\u05e7\u05d5\u05e8 \u05de\u05ea\u05d7 \u05e7\u05d1\u05d5\u05e2 \u05d4\u05de\u05ea\u05d7 \u05e0\u05e9\u05d0\u05e8 \u05db\u05de\u05e2\u05d8 \u05e7\u05d1\u05d5\u05e2, \u05d5\u05db\u05dc \u05e9\u05d9\u05e0\u05d5\u05d9 \u05e7\u05d8\u05df \u05d1\u05d0\u05d5\u05e8\u05da \u05d4\u05e7\u05e9\u05ea \u05d2\u05d5\u05e8\u05dd \u05dc\u05e9\u05d9\u05e0\u05d5\u05d9 \u05d2\u05d3\u05d5\u05dc \u05d1\u05d6\u05e8\u05dd."], [188.3, "\u05d6\u05d4 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc-MIG \u05d5-MAG, \u05e9\u05d1\u05d4\u05dd \u05d4\u05d7\u05d5\u05d8 \u05de\u05d5\u05d6\u05df \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e7\u05d1\u05d5\u05e2\u05d4."], [192.7, "\u05d0\u05dd \u05d4\u05e7\u05e9\u05ea \u05de\u05ea\u05e7\u05e6\u05e8\u05ea, \u05d4\u05d6\u05e8\u05dd \u05e2\u05d5\u05dc\u05d4, \u05d4\u05d7\u05d5\u05d8 \u05e0\u05de\u05e1 \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05d5\u05d4\u05e7\u05e9\u05ea \u05d7\u05d5\u05d6\u05e8\u05ea \u05dc\u05d0\u05d5\u05e8\u05db\u05d4. \u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 \u05d5\u05d9\u05e1\u05d5\u05ea \u05e2\u05e6\u05de\u05d9."], [201.7, "\u05dc\u05db\u05df \u05d1-MIG \u05d5-MAG, \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d6\u05e0\u05ea \u05d4\u05d7\u05d5\u05d8 \u05d4\u05d9\u05d0 \u05e9\u05e7\u05d5\u05d1\u05e2\u05ea \u05d1\u05e4\u05d5\u05e2\u05dc \u05d0\u05ea \u05d4\u05d6\u05e8\u05dd."], [208.1, "\u05de\u05e7\u05d5\u05e8\u05d5\u05ea \u05d4\u05d4\u05e1\u05e4\u05e7 \u05d4\u05d5\u05d5\u05ea\u05d9\u05e7\u05d9\u05dd \u05d4\u05dd \u05e9\u05e0\u05d0\u05d9\u05dd \u05d5\u05de\u05d9\u05d9\u05e9\u05e8\u05d9\u05dd \u05db\u05d1\u05d3\u05d9\u05dd, \u05e9\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05ea\u05d3\u05e8 \u05d4\u05e8\u05e9\u05ea."], [214.1, "\u05d2\u05e0\u05e8\u05d8\u05d5\u05e8 \u05e9\u05de\u05d5\u05e0\u05e2 \u05d1\u05de\u05e0\u05d5\u05e2 \u05de\u05e9\u05de\u05e9 \u05d1\u05e9\u05d8\u05d7, \u05d1\u05de\u05e7\u05d5\u05dd \u05e9\u05d0\u05d9\u05df \u05d1\u05d5 \u05d7\u05e9\u05de\u05dc."], [219.2, "\u05d4\u05d9\u05d5\u05dd \u05e8\u05d5\u05d1 \u05d4\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05df \u05d0\u05d9\u05e0\u05d5\u05d5\u05e8\u05d8\u05e8: \u05d4\u05df \u05de\u05de\u05d9\u05e8\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05e9\u05de\u05dc \u05dc\u05ea\u05d3\u05e8 \u05d2\u05d1\u05d5\u05d4, \u05d5\u05dc\u05db\u05df \u05d4\u05e9\u05e0\u05d0\u05d9 \u05e9\u05d1\u05ea\u05d5\u05db\u05df \u05e7\u05d8\u05df \u05d5\u05e7\u05dc \u05d1\u05d4\u05e8\u05d1\u05d4."], [228.3, "\u05d0\u05d9\u05e0\u05d5\u05d5\u05e8\u05d8\u05e8 \u05e9\u05d5\u05dc\u05d8 \u05d1\u05d6\u05e8\u05dd \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e8\u05d1\u05d4, \u05d5\u05d6\u05d4 \u05de\u05d0\u05e4\u05e9\u05e8 \u05ea\u05d5\u05db\u05e0\u05d9\u05d5\u05ea \u05e1\u05d9\u05e0\u05e8\u05d2\u05d9\u05d5\u05ea, \u05e4\u05d5\u05dc\u05e1\u05d9\u05dd \u05d5\u05e9\u05dc\u05d9\u05d8\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d1\u05e7\u05e9\u05ea."], [236.7, "\u05db\u05dc \u05de\u05e7\u05d5\u05e8 \u05d4\u05e1\u05e4\u05e7 \u05de\u05ea\u05d7\u05de\u05dd \u05db\u05e9\u05d4\u05d5\u05d0 \u05e2\u05d5\u05d1\u05d3, \u05d5\u05dc\u05db\u05df \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05dc\u05d5 \u05de\u05d7\u05d6\u05d5\u05e8 \u05e2\u05d1\u05d5\u05d3\u05d4, duty cycle."], [243.4, "\u05de\u05d7\u05d6\u05d5\u05e8 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d4\u05d5\u05d0 \u05d4\u05d0\u05d7\u05d5\u05d6 \u05de\u05ea\u05d5\u05da \u05e2\u05e9\u05e8 \u05d3\u05e7\u05d5\u05ea \u05e9\u05d1\u05d5 \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05e8\u05ea\u05da \u05d1\u05d6\u05e8\u05dd \u05de\u05e1\u05d5\u05d9\u05dd, \u05d1\u05dc\u05d9 \u05dc\u05d4\u05ea\u05d7\u05de\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05d3\u05d9."], [251.5, "\u05dc\u05de\u05e9\u05dc, 60% \u05d1-300 \u05d0\u05de\u05e4\u05e8 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e9\u05e9 \u05d3\u05e7\u05d5\u05ea \u05e8\u05d9\u05ea\u05d5\u05da \u05d5\u05d0\u05e8\u05d1\u05e2 \u05d3\u05e7\u05d5\u05ea \u05de\u05e0\u05d5\u05d7\u05d4, \u05d1\u05db\u05dc \u05e2\u05e9\u05e8 \u05d3\u05e7\u05d5\u05ea."], [259.7, "\u05d1\u05d6\u05e8\u05dd \u05e0\u05de\u05d5\u05da \u05d9\u05d5\u05ea\u05e8, \u05de\u05d7\u05d6\u05d5\u05e8 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d2\u05d3\u05dc: 100%, \u05db\u05dc\u05d5\u05de\u05e8 \u05e2\u05d1\u05d5\u05d3\u05d4 \u05e8\u05e6\u05d9\u05e4\u05d4, \u05de\u05ea\u05e7\u05d1\u05dc \u05d1\u05e2\u05e8\u05da \u05d1-232 \u05d0\u05de\u05e4\u05e8."], [269.9, "\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05de\u05db\u05d5\u05e0\u05d4 \u05dc\u05e4\u05d9 \u05d4\u05d6\u05e8\u05dd \u05d5\u05de\u05e9\u05da \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05e4\u05d5\u05e2\u05dc, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9 \u05d5\u05e8\u05d5\u05d1\u05d5\u05d8\u05d9."], [277.3, "\u05d4\u05e7\u05e9\u05ea \u05de\u05e1\u05d5\u05db\u05e0\u05ea \u05d1\u05e9\u05dc\u05d5\u05e9 \u05d3\u05e8\u05db\u05d9\u05dd \u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea: \u05e7\u05e8\u05d9\u05e0\u05d4, \u05d0\u05d3\u05d9\u05dd \u05d5\u05d7\u05e9\u05de\u05dc."], [283.1, "\u05d4\u05e7\u05e9\u05ea \u05e4\u05d5\u05dc\u05d8\u05ea \u05e7\u05e8\u05d9\u05e0\u05d4 \u05d0\u05d5\u05dc\u05d8\u05e8\u05d4-\u05e1\u05d2\u05d5\u05dc\u05d4 \u05d5\u05d0\u05d9\u05e0\u05e4\u05e8\u05d0-\u05d0\u05d3\u05d5\u05de\u05d4 \u05d7\u05d6\u05e7\u05d4, \u05e9\u05d2\u05d5\u05e8\u05de\u05ea \u05dc\u05db\u05d5\u05d5\u05d9\u05d5\u05ea \u05d1\u05e2\u05d5\u05e8 \u05d5\u05dc\u05d3\u05dc\u05e7\u05ea \u05d1\u05e7\u05e8\u05e0\u05d9\u05ea \u05d4\u05e2\u05d9\u05df."], [291.2, "\u05dc\u05db\u05df \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05e2\u05dd \u05de\u05e1\u05db\u05d4 \u05d5\u05de\u05e1\u05e0\u05df \u05d1\u05d3\u05e8\u05d2\u05ea \u05d4\u05e6\u05dc\u05dc\u05d4 \u05de\u05ea\u05d0\u05d9\u05de\u05d4, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05df 9 \u05dc-13 \u05dc\u05e4\u05d9 \u05d4\u05d6\u05e8\u05dd, \u05d5\u05de\u05d2\u05d9\u05e0\u05d9\u05dd \u05d2\u05dd \u05e2\u05dc \u05d0\u05e0\u05e9\u05d9\u05dd \u05e9\u05e2\u05d5\u05de\u05d3\u05d9\u05dd \u05d1\u05e1\u05d1\u05d9\u05d1\u05d4."], [301.9, "\u05d0\u05d3\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05db\u05d9\u05dc\u05d9\u05dd \u05ea\u05d7\u05de\u05d5\u05e6\u05d5\u05ea \u05de\u05ea\u05db\u05ea, \u05d5\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e4\u05dc\u05d3\u05ea \u05d0\u05dc-\u05d7\u05dc\u05d3 \u05d2\u05dd \u05db\u05e8\u05d5\u05dd \u05e9\u05e9-\u05e2\u05e8\u05db\u05d9."], [308.7, "\u05d0\u05d3\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05e1\u05d5\u05d5\u05d2\u05d9\u05dd \u05db\u05de\u05e1\u05e8\u05d8\u05e0\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d7\u05d5\u05d1\u05d4 \u05d9\u05e0\u05d9\u05e7\u05d4 \u05de\u05e7\u05d5\u05de\u05d9\u05ea \u05d5\u05d0\u05d5\u05d5\u05e8\u05d5\u05e8, \u05d5\u05d1\u05de\u05e7\u05e8\u05d4 \u05d4\u05e6\u05d5\u05e8\u05da \u05d2\u05dd \u05de\u05e1\u05db\u05ea \u05e0\u05e9\u05d9\u05de\u05d4."], [316.8, "\u05de\u05ea\u05d7 \u05d4\u05e8\u05d9\u05e7\u05dd \u05e9\u05dc \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d9\u05db\u05d5\u05dc \u05dc\u05d2\u05e8\u05d5\u05dd \u05dc\u05d4\u05ea\u05d7\u05e9\u05de\u05dc\u05d5\u05ea, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d4 \u05e8\u05d8\u05d5\u05d1\u05d4 \u05d0\u05d5 \u05d1\u05ea\u05d5\u05da \u05de\u05d9\u05db\u05dc \u05e1\u05d2\u05d5\u05e8."], [324.1, "\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05e2\u05dd \u05db\u05e4\u05e4\u05d5\u05ea \u05d9\u05d1\u05e9\u05d5\u05ea \u05d5\u05d1\u05d9\u05d3\u05d5\u05d3 \u05ea\u05e7\u05d9\u05df, \u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05d0\u05ea \u05db\u05d1\u05dc \u05d4\u05d7\u05d6\u05e8\u05d4 \u05e7\u05e8\u05d5\u05d1 \u05dc\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05db\u05d1\u05dc\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4."], [332.6, "\u05d5\u05dc\u05d0 \u05dc\u05e9\u05db\u05d5\u05d7 \u05d0\u05ea \u05e1\u05db\u05e0\u05ea \u05d4\u05e9\u05e8\u05d9\u05e4\u05d4: \u05e0\u05d9\u05e6\u05d5\u05e6\u05d5\u05ea \u05d7\u05de\u05d9\u05dd \u05e2\u05e4\u05d9\u05dd \u05dc\u05de\u05e8\u05d7\u05e7 \u05e9\u05dc \u05de\u05d8\u05e8\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05de\u05e8\u05d7\u05d9\u05e7\u05d9\u05dd \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d3\u05dc\u05d9\u05e7\u05d9\u05dd."], [341.4, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d4\u05e7\u05e9\u05ea \u05d4\u05d9\u05d0 \u05d6\u05e8\u05dd \u05e9\u05e2\u05d5\u05d1\u05e8 \u05d3\u05e8\u05da \u05d2\u05d6 \u05de\u05d9\u05d5\u05e0\u05df, \u05d1\u05de\u05ea\u05d7 \u05e0\u05de\u05d5\u05da \u05d5\u05d1\u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4."], [348.4, "\u05d4\u05e7\u05d5\u05d8\u05d1\u05d9\u05d5\u05ea \u05d5\u05e1\u05d5\u05d2 \u05d4\u05d6\u05e8\u05dd \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05d0\u05d9\u05e4\u05d4 \u05de\u05ea\u05e8\u05db\u05d6 \u05d4\u05d7\u05d5\u05dd, \u05d5\u05d0\u05d5\u05e4\u05d9\u05d9\u05df \u05d4\u05de\u05db\u05d5\u05e0\u05d4, \u05d6\u05e8\u05dd \u05e7\u05d1\u05d5\u05e2 \u05d0\u05d5 \u05de\u05ea\u05d7 \u05e7\u05d1\u05d5\u05e2, \u05de\u05d5\u05ea\u05d0\u05dd \u05dc\u05ea\u05d4\u05dc\u05d9\u05da."], [357.9, "\u05de\u05d7\u05d6\u05d5\u05e8 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05e7\u05d5\u05d1\u05e2 \u05db\u05de\u05d4 \u05d6\u05de\u05df \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05ea\u05da \u05d1\u05e8\u05e6\u05e3, \u05d5\u05d4\u05d1\u05d8\u05d9\u05d7\u05d5\u05ea \u05de\u05ea\u05d7\u05d9\u05dc\u05d4 \u05d1\u05d4\u05d2\u05e0\u05d4 \u05de\u05e7\u05e8\u05d9\u05e0\u05d4, \u05de\u05d0\u05d3\u05d9\u05dd \u05d5\u05de\u05d7\u05e9\u05de\u05dc."], [366.2, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e2\u05e1\u05d5\u05e7 \u05d1\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd: \u05e1\u05d5\u05d2\u05d9 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd, \u05d4\u05db\u05e0\u05ea \u05d4\u05e7\u05e6\u05d5\u05d5\u05ea \u05d5\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."]]};
window.MH_TR["ch03"]={"t": "\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd, \u05d4\u05db\u05e0\u05ea \u05e7\u05e6\u05d5\u05d5\u05ea \u05d5\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea", "l": [[3.0, "\u05dc\u05e4\u05e0\u05d9 \u05e9\u05de\u05e8\u05ea\u05db\u05d9\u05dd, \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d7\u05dc\u05d9\u05d8 \u05d0\u05d9\u05da \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e0\u05e4\u05d2\u05e9\u05d9\u05dd, \u05d0\u05d9\u05da \u05de\u05db\u05d9\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e6\u05d5\u05d5\u05ea, \u05d5\u05d1\u05d0\u05d9\u05d6\u05d5 \u05ea\u05e0\u05d5\u05d7\u05d4 \u05d9\u05e8\u05ea\u05db\u05d5."], [10.6, "\u05d4\u05d4\u05d7\u05dc\u05d8\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05e7\u05d5\u05d1\u05e2\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7, \u05d0\u05ea \u05db\u05de\u05d5\u05ea \u05d4\u05d7\u05d5\u05de\u05e8, \u05d0\u05ea \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05d5\u05d0\u05ea \u05d4\u05de\u05d7\u05d9\u05e8 \u05e9\u05dc \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [17.9, "\u05d9\u05e9 \u05d7\u05de\u05d9\u05e9\u05d4 \u05e1\u05d5\u05d2\u05d9 \u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd \u05d1\u05e1\u05d9\u05e1\u05d9\u05d9\u05dd."], [20.6, "\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e7\u05ea, butt: \u05e9\u05e0\u05d9 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05d0\u05d5\u05ea\u05d5 \u05de\u05d9\u05e9\u05d5\u05e8, \u05e7\u05e6\u05d4 \u05de\u05d5\u05dc \u05e7\u05e6\u05d4."], [26.7, "\u05d7\u05d9\u05d1\u05d5\u05e8 T: \u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3 \u05e0\u05d9\u05e6\u05d1 \u05dc\u05d0\u05de\u05e6\u05e2 \u05e9\u05dc \u05d4\u05e9\u05e0\u05d9."], [31.0, "\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e4\u05d9\u05e0\u05ea\u05d9, corner: \u05e9\u05e0\u05d9 \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e0\u05e4\u05d2\u05e9\u05d9\u05dd \u05d1\u05e7\u05e6\u05d5\u05d5\u05ea \u05e9\u05dc\u05d4\u05dd \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea, \u05db\u05de\u05d5 \u05d1\u05e4\u05d9\u05e0\u05d4 \u05e9\u05dc \u05e7\u05d5\u05e4\u05e1\u05d4."], [38.6, "\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d7\u05e4\u05d9\u05e4\u05d4, lap: \u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3 \u05de\u05d5\u05e0\u05d7 \u05e2\u05dc \u05d4\u05e9\u05e0\u05d9."], [43.1, "\u05d5\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e9\u05d5\u05dc\u05d9\u05d9\u05dd, edge: \u05e9\u05e0\u05d9 \u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e7\u05d1\u05d9\u05dc\u05d9\u05dd \u05e9\u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e6\u05d5\u05d5\u05ea \u05e9\u05dc\u05d4\u05dd \u05d9\u05d7\u05d3, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05e4\u05d7 \u05d3\u05e7."], [51.7, "\u05e1\u05d5\u05d2 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d4\u05d5\u05d0 \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4. \u05e1\u05d5\u05d2 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d5\u05d0 \u05d4\u05d0\u05d5\u05e4\u05df \u05e9\u05d1\u05d5 \u05de\u05de\u05dc\u05d0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5."], [57.5, "\u05e9\u05e0\u05d9 \u05e1\u05d5\u05d2\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd \u05d4\u05dd \u05e8\u05d9\u05ea\u05d5\u05da \u05e7\u05ea, \u05e9\u05de\u05de\u05dc\u05d0 \u05d7\u05e8\u05d9\u05e5 \u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05d5\u05e8\u05d9\u05ea\u05d5\u05da fillet, \u05e9\u05de\u05d5\u05e0\u05d7 \u05d1\u05e4\u05d9\u05e0\u05d4 \u05e9\u05e0\u05d5\u05e6\u05e8\u05ea \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd."], [67.2, "\u05e8\u05d9\u05ea\u05d5\u05da \u05e7\u05ea \u05e2\u05dd \u05d7\u05d3\u05d9\u05e8\u05d4 \u05de\u05dc\u05d0\u05d4 \u05de\u05e2\u05d1\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e1 \u05d3\u05e8\u05da \u05db\u05dc \u05e2\u05d5\u05d1\u05d9 \u05d4\u05d7\u05dc\u05e7, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d7\u05d6\u05e7 \u05db\u05de\u05d5 \u05d4\u05d7\u05d5\u05de\u05e8, \u05d0\u05d1\u05dc \u05d4\u05d5\u05d0 \u05d3\u05d5\u05e8\u05e9 \u05d4\u05db\u05e0\u05d4 \u05d5\u05d3\u05d9\u05d5\u05e7."], [77.8, "\u05e8\u05d9\u05ea\u05d5\u05da fillet \u05e7\u05dc \u05d5\u05de\u05d4\u05d9\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05d4\u05db\u05e0\u05d4, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05de\u05d1\u05e0\u05d9\u05dd: \u05d1\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9 T, \u05d7\u05e4\u05d9\u05e4\u05d4 \u05d5\u05e4\u05d9\u05e0\u05d4."], [86.2, "\u05d0\u05ea \u05d4\u05d2\u05d5\u05d3\u05dc \u05e9\u05dc \u05e8\u05d9\u05ea\u05d5\u05da fillet \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05d1\u05e9\u05ea\u05d9 \u05d3\u05e8\u05db\u05d9\u05dd: \u05d0\u05d5\u05e8\u05da \u05d4\u05e8\u05d2\u05dc z, \u05d0\u05d5 \u05e2\u05d5\u05d1\u05d9 \u05d4\u05e6\u05d5\u05d5\u05d0\u05e8 a, \u05d4\u05de\u05e8\u05d7\u05e7 \u05d4\u05e7\u05e6\u05e8 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05e9\u05d5\u05e8\u05e9 \u05d0\u05dc \u05e4\u05e0\u05d9 \u05d4\u05de\u05e9\u05d5\u05dc\u05e9."], [97.6, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da fillet \u05e9\u05d5\u05d5\u05d4-\u05e8\u05d2\u05dc\u05d9\u05d9\u05dd, \u05d4\u05e6\u05d5\u05d5\u05d0\u05e8 \u05e9\u05d5\u05d5\u05d4 \u05d1\u05e2\u05e8\u05da \u05dc\u05e9\u05d1\u05e2 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05de\u05d4\u05e8\u05d2\u05dc: \u05e8\u05d2\u05dc \u05e9\u05dc 7 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e0\u05d5\u05ea\u05e0\u05ea \u05e6\u05d5\u05d5\u05d0\u05e8 \u05e9\u05dc \u05db-5."], [107.4, "\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05dc\u05e4\u05d9 ISO \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d0\u05ea a, \u05d5\u05dc\u05e4\u05d9 AWS \u05d0\u05ea \u05d2\u05d5\u05d3\u05dc \u05d4\u05e8\u05d2\u05dc, \u05d5\u05dc\u05db\u05df \u05d7\u05e9\u05d5\u05d1 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05de\u05d4 \u05db\u05ea\u05d5\u05d1."], [117.6, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e7\u05ea, \u05d7\u05dc\u05e7 \u05d3\u05e7 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05ea\u05da \u05e2\u05dd \u05e7\u05e6\u05d5\u05d5\u05ea \u05d9\u05e9\u05e8\u05d9\u05dd, \u05d1\u05dc\u05d9 \u05d4\u05db\u05e0\u05d4."], [123.4, "\u05d1\u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4 \u05d4\u05e7\u05e9\u05ea \u05dc\u05d0 \u05ea\u05d7\u05d3\u05d5\u05e8 \u05dc\u05db\u05dc \u05d4\u05e2\u05d5\u05d1\u05d9, \u05d5\u05dc\u05db\u05df \u05de\u05db\u05d9\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e6\u05d5\u05d5\u05ea \u05d1\u05e9\u05d9\u05e4\u05d5\u05e2, \u05d5\u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05d7\u05e8\u05d9\u05e5."], [131.1, "\u05d4\u05d4\u05db\u05e0\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 V, \u05e2\u05dd \u05d6\u05d5\u05d5\u05d9\u05ea \u05db\u05d5\u05dc\u05dc\u05ea \u05e9\u05dc \u05db\u05e9\u05d9\u05e9\u05d9\u05dd \u05de\u05e2\u05dc\u05d5\u05ea."], [136.1, "\u05d1\u05ea\u05d7\u05ea\u05d9\u05ea \u05d4\u05d7\u05e8\u05d9\u05e5 \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05e4\u05ea\u05d7 \u05e9\u05d5\u05e8\u05e9, \u05d5\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d2\u05dd \u05d7\u05dc\u05e7 \u05d9\u05e9\u05e8 \u05e7\u05d8\u05df, root face, \u05e9\u05ea\u05d5\u05de\u05da \u05d1\u05d0\u05de\u05d1\u05d8 \u05d5\u05de\u05d5\u05e0\u05e2 \u05de\u05d4\u05d7\u05d5\u05de\u05e8 \u05dc\u05d9\u05e4\u05d5\u05dc."], [145.1, "\u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05dc\u05d4\u05db\u05e0\u05ea X, \u05e2\u05dd \u05e9\u05d9\u05e4\u05d5\u05e2 \u05de\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd."], [150.3, "\u05dc\u05de\u05e9\u05dc, \u05d1\u05dc\u05d5\u05d7 \u05e9\u05dc 20 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05d4\u05db\u05e0\u05ea X \u05d3\u05d5\u05e8\u05e9\u05ea \u05d1\u05e2\u05e8\u05da \u05d7\u05e6\u05d9 \u05de\u05db\u05de\u05d5\u05ea \u05d7\u05d5\u05de\u05e8 \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05e9\u05dc \u05d4\u05db\u05e0\u05ea V, \u05d5\u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05de\u05d0\u05d5\u05d6\u05df \u05d9\u05d5\u05ea\u05e8."], [160.2, "\u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd \u05de\u05d0\u05d5\u05d3 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4\u05db\u05e0\u05d5\u05ea U \u05d5-J, \u05e9\u05d1\u05d4\u05df \u05d4\u05d3\u05e4\u05e0\u05d5\u05ea \u05db\u05de\u05e2\u05d8 \u05d9\u05e9\u05e8\u05d5\u05ea \u05d5\u05e0\u05e4\u05d7 \u05d4\u05d7\u05e8\u05d9\u05e5 \u05e7\u05d8\u05df \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8."], [168.6, "\u05db\u05e9\u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05de\u05e6\u05d3 \u05d0\u05d7\u05d3, \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05d2\u05d9\u05d1\u05d5\u05d9, backing: \u05e4\u05e1 \u05de\u05ea\u05db\u05ea \u05d0\u05d5 \u05e7\u05e8\u05de\u05d9\u05e7\u05d4 \u05de\u05ea\u05d7\u05ea \u05dc\u05e9\u05d5\u05e8\u05e9."], [176.1, "\u05d5\u05db\u05e9\u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05de\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd, \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05de\u05e0\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05e9\u05d5\u05e8\u05e9 \u05d1\u05d7\u05e8\u05d9\u05e6\u05d4 \u05de\u05d4\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9, back gouging, \u05dc\u05e4\u05e0\u05d9 \u05e9\u05de\u05de\u05e9\u05d9\u05db\u05d9\u05dd."], [184.7, "\u05d0\u05ea \u05d4\u05d4\u05db\u05e0\u05d4 \u05e2\u05d5\u05e9\u05d9\u05dd \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9 \u05d0\u05d5 \u05d1\u05d7\u05d9\u05ea\u05d5\u05da \u05e4\u05dc\u05d6\u05de\u05d4 \u05d0\u05d5 \u05dc\u05d4\u05d1\u05d4, \u05d5\u05d0\u05d7\u05e8\u05d9\u05d4 \u05de\u05e0\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e6\u05d5\u05d5\u05ea \u05de\u05e9\u05de\u05df, \u05e6\u05d1\u05e2 \u05d5\u05ea\u05d7\u05de\u05d5\u05e6\u05d5\u05ea."], [194.3, "\u05dc\u05e4\u05e0\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e2\u05e6\u05de\u05d5 \u05d9\u05e9 \u05e9\u05dc\u05d1 \u05e9\u05e7\u05d5\u05d1\u05e2 \u05d4\u05e8\u05d1\u05d4 \u05de\u05d4\u05d0\u05d9\u05db\u05d5\u05ea: \u05d4\u05d4\u05ea\u05d0\u05de\u05d4, fit-up."], [200.5, "\u05d1\u05e9\u05dc\u05d1 \u05d4\u05d6\u05d4 \u05de\u05de\u05e7\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05de\u05d9\u05d9\u05e9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e6\u05d5\u05d5\u05ea, \u05d5\u05de\u05d5\u05d5\u05d3\u05d0\u05d9\u05dd \u05e9\u05e4\u05ea\u05d7 \u05d4\u05e9\u05d5\u05e8\u05e9 \u05d0\u05d7\u05d9\u05d3 \u05dc\u05db\u05dc \u05d4\u05d0\u05d5\u05e8\u05da."], [208.1, "\u05e4\u05ea\u05d7 \u05e9\u05d5\u05e8\u05e9 \u05e6\u05e8 \u05de\u05d3\u05d9 \u05d2\u05d5\u05e8\u05dd \u05dc\u05d7\u05d5\u05e1\u05e8 \u05d7\u05d3\u05d9\u05e8\u05d4, \u05d5\u05e4\u05ea\u05d7 \u05e8\u05d7\u05d1 \u05de\u05d3\u05d9 \u05d2\u05d5\u05e8\u05dd \u05dc\u05e9\u05e8\u05d9\u05e4\u05d4 \u05de\u05d4\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9 \u05d5\u05dc\u05e6\u05e8\u05d9\u05db\u05ea \u05d7\u05d5\u05de\u05e8 \u05d2\u05d1\u05d5\u05d4\u05d4."], [216.8, "\u05d2\u05dd \u05d4\u05e1\u05d8\u05d4 \u05d1\u05d9\u05df \u05d2\u05d5\u05d1\u05d4 \u05d4\u05dc\u05d5\u05d7\u05d5\u05ea \u05e4\u05d5\u05d2\u05e2\u05ea \u05d1\u05e9\u05d5\u05e8\u05e9 \u05d5\u05de\u05e8\u05db\u05d6\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd."], [221.7, "\u05db\u05d3\u05d9 \u05dc\u05e9\u05de\u05d5\u05e8 \u05e2\u05dc \u05d4\u05d4\u05ea\u05d0\u05de\u05d4 \u05d1\u05d6\u05de\u05df \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05de\u05e6\u05de\u05d9\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05e8\u05d9\u05ea\u05d5\u05db\u05d9 \u05d4\u05e6\u05de\u05d3\u05d4 \u05e7\u05e6\u05e8\u05d9\u05dd, tack welds."], [228.6, "\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05e6\u05de\u05d3\u05d4 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05d0\u05d5\u05ea\u05d4 \u05d0\u05d9\u05db\u05d5\u05ea \u05db\u05de\u05d5 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e2\u05e6\u05de\u05d5, \u05db\u05d9 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d4\u05d5\u05d0 \u05e0\u05d1\u05dc\u05e2 \u05d1\u05ea\u05d5\u05db\u05d5."], [235.1, "\u05de\u05e7\u05d5\u05d1\u05dc \u05dc\u05e9\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d1\u05de\u05e8\u05d5\u05d5\u05d7\u05d9\u05dd \u05e7\u05d1\u05d5\u05e2\u05d9\u05dd, \u05d5\u05dc\u05d4\u05ea\u05d7\u05d9\u05dc \u05de\u05d4\u05de\u05e8\u05db\u05d6 \u05d0\u05d5 \u05dc\u05e1\u05d9\u05e8\u05d5\u05d2\u05d9\u05df \u05de\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd, \u05db\u05d3\u05d9 \u05e9\u05d4\u05e4\u05ea\u05d7 \u05dc\u05d0 \u05d9\u05d9\u05e1\u05d2\u05e8."], [242.9, "\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e9\u05de\u05d5\u05e8 \u05e2\u05dc \u05d4\u05d4\u05ea\u05d0\u05de\u05d4 \u05d2\u05dd \u05d1\u05e2\u05d6\u05e8\u05ea \u05de\u05ea\u05e7\u05e0\u05d9 \u05d3\u05e4\u05d9\u05e0\u05d4, \u05de\u05dc\u05d7\u05e6\u05d9\u05d9\u05dd \u05d5\u05e4\u05e1\u05d9 \u05d7\u05d9\u05d6\u05d5\u05e7 \u05d6\u05de\u05e0\u05d9\u05d9\u05dd."], [249.3, "\u05e2\u05db\u05e9\u05d9\u05d5 \u05e0\u05d7\u05d6\u05d5\u05e8 \u05dc\u05d7\u05d3\u05d9\u05e8\u05d4: \u05dc\u05d0 \u05db\u05dc \u05e8\u05d9\u05ea\u05d5\u05da \u05e7\u05ea \u05e6\u05e8\u05d9\u05da \u05d7\u05d3\u05d9\u05e8\u05d4 \u05de\u05dc\u05d0\u05d4."], [254.4, "\u05d1\u05d7\u05d3\u05d9\u05e8\u05d4 \u05d7\u05dc\u05e7\u05d9\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05de\u05dc\u05d0 \u05e8\u05e7 \u05d7\u05dc\u05e7 \u05de\u05d4\u05e2\u05d5\u05d1\u05d9, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05e9\u05dc\u05d0 \u05e8\u05d5\u05ea\u05da \u05e0\u05e9\u05d0\u05e8 \u05db\u05de\u05d5 \u05e1\u05d3\u05e7 \u05e4\u05e0\u05d9\u05de\u05d9 \u05de\u05d5\u05d1\u05e0\u05d4."], [262.0, "\u05d6\u05d4 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05e2\u05d5\u05de\u05e1 \u05e1\u05d8\u05d8\u05d9 \u05e0\u05de\u05d5\u05da \u05d5\u05dc\u05d7\u05d9\u05e1\u05db\u05d5\u05df \u05d1\u05d7\u05d5\u05de\u05e8, \u05d0\u05d1\u05dc \u05e4\u05d7\u05d5\u05ea \u05d8\u05d5\u05d1 \u05d1\u05e2\u05d5\u05de\u05e1\u05d9 \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea, \u05db\u05d9 \u05d4\u05e9\u05d5\u05e8\u05e9 \u05e9\u05dc\u05d0 \u05e8\u05d5\u05ea\u05da \u05de\u05e8\u05db\u05d6 \u05de\u05d0\u05de\u05e6\u05d9\u05dd."], [270.8, "\u05d2\u05dd \u05e8\u05d9\u05ea\u05d5\u05da fillet \u05dc\u05d0 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05e8\u05e6\u05d9\u05e3: \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05e7\u05d5\u05d8\u05e2 \u05de\u05d5\u05e8\u05db\u05d1 \u05de\u05e7\u05d8\u05e2\u05d9\u05dd \u05e7\u05e6\u05e8\u05d9\u05dd, \u05e2\u05dd \u05e8\u05d5\u05d5\u05d7\u05d9\u05dd \u05e7\u05d1\u05d5\u05e2\u05d9\u05dd \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd."], [278.6, "\u05d4\u05d5\u05d0 \u05d7\u05d5\u05e1\u05da \u05d7\u05d5\u05de\u05e8 \u05d5\u05d6\u05de\u05df, \u05d5\u05de\u05e7\u05d8\u05d9\u05df \u05d0\u05ea \u05d4\u05d7\u05d5\u05dd \u05d5\u05d0\u05ea \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05e0\u05e4\u05d5\u05e5 \u05d1\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9 \u05e6\u05dc\u05e2\u05d5\u05ea \u05d5\u05e4\u05d7\u05d9\u05dd \u05d1\u05de\u05d1\u05e0\u05d9\u05dd \u05e7\u05dc\u05d9\u05dd."], [286.9, "\u05d0\u05d1\u05dc \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05e7\u05d5\u05d8\u05e2 \u05dc\u05d0 \u05d0\u05d5\u05d8\u05dd, \u05d5\u05d4\u05e8\u05d5\u05d5\u05d7\u05d9\u05dd \u05d1\u05d9\u05df \u05d4\u05e7\u05d8\u05e2\u05d9\u05dd \u05e2\u05dc\u05d5\u05dc\u05d9\u05dd \u05dc\u05e6\u05d1\u05d5\u05e8 \u05dc\u05d7\u05d5\u05ea \u05d5\u05dc\u05d4\u05d7\u05dc\u05d9\u05d3."], [293.3, "\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d0\u05d5\u05e8\u05da \u05d4\u05e7\u05d8\u05e2 \u05d5\u05d1\u05de\u05e8\u05d5\u05d5\u05d7 \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd, \u05d5\u05e0\u05e8\u05d0\u05d4 \u05d0\u05ea \u05d6\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e2\u05dc \u05e1\u05d9\u05de\u05d5\u05e0\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da."], [300.6, "\u05d4\u05ea\u05e0\u05d5\u05d7\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05db\u05d9\u05d5\u05d5\u05df \u05e9\u05dc \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d9\u05d7\u05e1 \u05dc\u05db\u05d5\u05d7 \u05d4\u05de\u05e9\u05d9\u05db\u05d4."], [304.8, "\u05d1\u05ea\u05e7\u05df ISO 6947 \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea \u05d1\u05d0\u05d5\u05ea\u05d9\u05d5\u05ea: PA \u05d4\u05d9\u05d0 \u05ea\u05e0\u05d5\u05d7\u05d4 \u05e9\u05d8\u05d5\u05d7\u05d4, \u05d5-PB \u05d4\u05d9\u05d0 \u05e8\u05d9\u05ea\u05d5\u05da fillet \u05d0\u05d5\u05e4\u05e7\u05d9."], [315.8, "PC \u05d4\u05d9\u05d0 \u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05d5\u05e4\u05e7\u05d9 \u05e2\u05dc \u05e7\u05d9\u05e8 \u05d0\u05e0\u05db\u05d9, \u05d5-PE \u05d4\u05d9\u05d0 \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05e2\u05dc \u05d4\u05e8\u05d0\u05e9."], [321.7, "PF \u05d5-PG \u05d4\u05df \u05ea\u05e0\u05d5\u05d7\u05d5\u05ea \u05d0\u05e0\u05db\u05d9\u05d5\u05ea: PF \u05de\u05dc\u05de\u05d8\u05d4 \u05dc\u05de\u05e2\u05dc\u05d4, \u05d5-PG \u05de\u05dc\u05de\u05e2\u05dc\u05d4 \u05dc\u05de\u05d8\u05d4."], [329.3, "\u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9 AWS \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05e1\u05e4\u05e8 \u05d5\u05d1\u05d0\u05d5\u05ea: G \u05dc\u05e8\u05d9\u05ea\u05d5\u05da \u05e7\u05ea, \u05d5-F \u05dc\u05e8\u05d9\u05ea\u05d5\u05da fillet."], [339.0, "\u05dc\u05de\u05e9\u05dc, 1G \u05d4\u05d9\u05d0 \u05ea\u05e0\u05d5\u05d7\u05d4 \u05e9\u05d8\u05d5\u05d7\u05d4, 2G \u05d0\u05d5\u05e4\u05e7\u05d9\u05ea, 3G \u05d0\u05e0\u05db\u05d9\u05ea \u05d5-4G \u05de\u05e2\u05dc \u05d4\u05e8\u05d0\u05e9."], [348.6, "\u05d1\u05e6\u05d9\u05e0\u05d5\u05e8\u05d5\u05ea \u05d9\u05e9 \u05d2\u05dd 5G, \u05e6\u05d9\u05e0\u05d5\u05e8 \u05d0\u05d5\u05e4\u05e7\u05d9 \u05e7\u05d1\u05d5\u05e2 \u05e9\u05d4\u05e8\u05ea\u05da \u05de\u05e7\u05d9\u05e3, \u05d5-6G, \u05e6\u05d9\u05e0\u05d5\u05e8 \u05e0\u05d8\u05d5\u05d9 \u05d1\u05d0\u05e8\u05d1\u05e2\u05d9\u05dd \u05d5\u05d7\u05de\u05e9 \u05de\u05e2\u05dc\u05d5\u05ea, \u05e9\u05d4\u05d9\u05d0 \u05d4\u05ea\u05e0\u05d5\u05d7\u05d4 \u05d4\u05e7\u05e9\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8."], [359.8, "\u05d4\u05ea\u05e0\u05d5\u05d7\u05d4 \u05de\u05e9\u05e4\u05d9\u05e2\u05d4 \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea \u05e2\u05dc \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4: \u05d1\u05ea\u05e0\u05d5\u05d7\u05d4 \u05e9\u05d8\u05d5\u05d7\u05d4 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05ea\u05da \u05d1\u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4 \u05d5\u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea, \u05d5\u05de\u05e2\u05dc \u05d4\u05e8\u05d0\u05e9 \u05d4\u05d0\u05de\u05d1\u05d8 \u05e0\u05d5\u05d8\u05d4 \u05dc\u05d9\u05e4\u05d5\u05dc."], [369.3, "\u05dc\u05db\u05df \u05de\u05e1\u05d5\u05d1\u05d1\u05d9\u05dd \u05d7\u05dc\u05e7\u05d9\u05dd \u05dc\u05ea\u05e0\u05d5\u05d7\u05d4 \u05e9\u05d8\u05d5\u05d7\u05d4 \u05db\u05e9\u05d0\u05e4\u05e9\u05e8, \u05d5\u05d1\u05d4\u05e1\u05de\u05db\u05ea \u05e8\u05ea\u05db\u05d9\u05dd \u05d4\u05ea\u05e0\u05d5\u05d7\u05d4 \u05d4\u05d9\u05d0 \u05d0\u05d7\u05d3 \u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05e9\u05e0\u05d1\u05d3\u05e7\u05d9\u05dd."], [378.0, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05e1\u05d5\u05d2 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d4\u05d5\u05d0 \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4, \u05d5\u05e1\u05d5\u05d2 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05e7\u05ea \u05d0\u05d5 fillet, \u05d4\u05d5\u05d0 \u05d0\u05d5\u05e4\u05df \u05d4\u05de\u05d9\u05dc\u05d5\u05d9."], [386.0, "\u05d4\u05db\u05e0\u05ea \u05d4\u05e7\u05e6\u05d5\u05d5\u05ea \u05e0\u05e7\u05d1\u05e2\u05ea \u05dc\u05e4\u05d9 \u05d4\u05e2\u05d5\u05d1\u05d9, \u05d5\u05d4\u05ea\u05e0\u05d5\u05d7\u05d4 \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05ea \u05e7\u05e6\u05d1 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d5\u05d0\u05ea \u05d4\u05e7\u05d5\u05e9\u05d9."], [392.2, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05ea\u05d7\u05d9\u05dc \u05d0\u05ea \u05ea\u05d4\u05dc\u05d9\u05db\u05d9 \u05d4\u05e7\u05e9\u05ea, \u05e2\u05dd \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4, \u05ea\u05d4\u05dc\u05d9\u05da 111."]]};
window.MH_TR["ch04"]={"t": "\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4", "l": [[3.0, "\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4, \u05ea\u05d4\u05dc\u05d9\u05da 111, \u05d4\u05d5\u05d0 \u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05e7\u05e9\u05ea \u05d4\u05d5\u05d5\u05ea\u05d9\u05e7 \u05d5\u05d4\u05e4\u05e9\u05d5\u05d8 \u05d1\u05d9\u05d5\u05ea\u05e8."], [10.0, "\u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05d5 SMAW \u05d0\u05d5 MMA, \u05d5\u05d1\u05e9\u05d8\u05d7 \u05e4\u05e9\u05d5\u05d8 \"\u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea\"."], [16.9, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df, \u05d4\u05e6\u05d9\u05d5\u05d3, \u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd, \u05d4\u05e9\u05d9\u05de\u05d5\u05e9\u05d9\u05dd, \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d4\u05d8\u05d9\u05e4\u05d5\u05e1\u05d9\u05d9\u05dd, \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."], [26.0, "\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d4\u05d9\u05d0 \u05de\u05d5\u05d8 \u05de\u05ea\u05db\u05ea \u05e9\u05de\u05e6\u05d5\u05e4\u05d4 \u05d1\u05e9\u05db\u05d1\u05d4 \u05e9\u05dc \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05e0\u05e8\u05dc\u05d9, \u05d4-flux."], [31.9, "\u05d4\u05e7\u05e9\u05ea \u05e0\u05d5\u05e6\u05e8\u05ea \u05d1\u05d9\u05df \u05e7\u05e6\u05d4 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05dc\u05d7\u05dc\u05e7, \u05d5\u05de\u05de\u05d9\u05e1\u05d4 \u05d2\u05dd \u05d0\u05ea \u05de\u05d5\u05d8 \u05d4\u05dc\u05d9\u05d1\u05d4 \u05d5\u05d2\u05dd \u05d0\u05ea \u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1."], [38.8, "\u05de\u05d5\u05d8 \u05d4\u05dc\u05d9\u05d1\u05d4 \u05e0\u05de\u05e1 \u05d5\u05de\u05e9\u05de\u05e9 \u05db\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9, \u05d5\u05dc\u05db\u05df \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05ea\u05e7\u05e6\u05e8\u05ea \u05d1\u05de\u05d4\u05dc\u05da \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [45.9, "\u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05e0\u05e9\u05e8\u05e3 \u05d5\u05e0\u05de\u05e1 \u05d9\u05d7\u05d3 \u05e2\u05dd \u05d4\u05de\u05d5\u05d8, \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e2\u05e0\u05df \u05d2\u05d6 \u05e9\u05de\u05d2\u05df \u05e2\u05dc \u05d4\u05e7\u05e9\u05ea \u05d5\u05e2\u05dc \u05d4\u05d0\u05de\u05d1\u05d8."], [52.8, "\u05d7\u05dc\u05e7 \u05de\u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d4\u05d5\u05e4\u05da \u05dc-slag, \u05e9\u05e6\u05e3 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05d0\u05de\u05d1\u05d8, \u05de\u05d2\u05df \u05e2\u05dc\u05d9\u05d5 \u05d1\u05d6\u05de\u05df \u05d4\u05d4\u05ea\u05de\u05e6\u05e7\u05d5\u05ea \u05d5\u05de\u05d0\u05d8 \u05d0\u05ea \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8."], [60.3, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4-slag \u05d1\u05e4\u05d8\u05d9\u05e9 \u05d5\u05d1\u05de\u05d1\u05e8\u05e9\u05ea \u05e4\u05dc\u05d3\u05d4, \u05d5\u05e8\u05e7 \u05d0\u05d6 \u05de\u05de\u05e9\u05d9\u05db\u05d9\u05dd \u05dc\u05e9\u05db\u05d1\u05d4 \u05d4\u05d1\u05d0\u05d4."], [67.4, "\u05dc\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d9\u05e9 \u05e2\u05d5\u05d3 \u05ea\u05e4\u05e7\u05d9\u05d3\u05d9\u05dd: \u05d4\u05d5\u05d0 \u05de\u05d9\u05d9\u05e6\u05d1 \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea, \u05de\u05d5\u05e1\u05d9\u05e3 \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea, \u05d5\u05de\u05e8\u05d7\u05d9\u05e7 \u05d7\u05de\u05e6\u05df \u05de\u05d4\u05d0\u05de\u05d1\u05d8."], [75.7, "\u05e1\u05d5\u05d2 \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05e7\u05d5\u05d1\u05e2 \u05d0\u05ea \u05d0\u05d5\u05e4\u05d9 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4."], [79.0, "\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05e8\u05d5\u05d8\u05d9\u05dc\u05d9\u05ea \u05e7\u05dc\u05d4 \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4, \u05e2\u05dd \u05e7\u05e9\u05ea \u05e8\u05db\u05d4 \u05d5\u05ea\u05e4\u05e8 \u05d9\u05e4\u05d4, \u05d5\u05de\u05e9\u05de\u05e9\u05ea \u05dc\u05e2\u05d1\u05d5\u05d3\u05d5\u05ea \u05db\u05dc\u05dc\u05d9\u05d5\u05ea."], [86.0, "\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d1\u05e1\u05d9\u05e1\u05d9\u05ea, low hydrogen, \u05e0\u05d5\u05ea\u05e0\u05ea \u05e8\u05d9\u05ea\u05d5\u05da \u05d7\u05d6\u05e7 \u05e9\u05d8\u05d5\u05d1 \u05d1\u05e2\u05d5\u05de\u05e1\u05d9 \u05d4\u05dc\u05dd \u05d5\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d5\u05ea, \u05d5\u05e2\u05de\u05d9\u05d3 \u05d1\u05e4\u05e0\u05d9 \u05e1\u05d3\u05e7\u05d9 \u05de\u05d9\u05de\u05df."], [95.9, "\u05d0\u05d1\u05dc \u05d4\u05d9\u05d0 \u05e1\u05d5\u05e4\u05d2\u05ea \u05dc\u05d7\u05d5\u05ea \u05de\u05d4\u05d0\u05d5\u05d5\u05d9\u05e8, \u05d5\u05dc\u05db\u05df \u05de\u05d9\u05d9\u05d1\u05e9\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05ea\u05e0\u05d5\u05e8 \u05dc\u05e4\u05d9 \u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05d4\u05d9\u05e6\u05e8\u05df, \u05d5\u05e9\u05d5\u05de\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d7\u05de\u05d4 \u05e2\u05d3 \u05d4\u05e9\u05d9\u05de\u05d5\u05e9."], [104.2, "\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05e6\u05dc\u05d5\u05dc\u05d5\u05d6\u05d9\u05ea \u05e0\u05d5\u05ea\u05e0\u05ea \u05d7\u05d3\u05d9\u05e8\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4, \u05d5\u05de\u05e9\u05de\u05e9\u05ea \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05e8\u05d9\u05ea\u05d5\u05da \u05e9\u05d5\u05e8\u05e9 \u05d1\u05e6\u05e0\u05e8\u05ea, \u05d1\u05ea\u05e0\u05d5\u05d7\u05d4 \u05d0\u05e0\u05db\u05d9\u05ea \u05db\u05dc\u05e4\u05d9 \u05de\u05d8\u05d4."], [112.5, "\u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9 AWS, \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05db\u05de\u05d5 E7018 \u05de\u05ea\u05e4\u05e8\u05e9\u05ea \u05db\u05da: \u05e9\u05d1\u05e2\u05d9\u05dd \u05d4\u05d5\u05d0 \u05d4\u05d7\u05d5\u05d6\u05e7 \u05d4\u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9, \u05d1\u05d0\u05dc\u05e4\u05d9 psi."], [124.1, "\u05d4\u05e1\u05e4\u05e8\u05d4 \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9\u05ea, \u05d0\u05d7\u05ea, \u05d0\u05d5\u05de\u05e8\u05ea \u05e9\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05db\u05dc \u05d4\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea, \u05d5\u05d4\u05e9\u05d9\u05dc\u05d5\u05d1 \u05e9\u05dc \u05e9\u05ea\u05d9 \u05d4\u05e1\u05e4\u05e8\u05d5\u05ea \u05d4\u05d0\u05d7\u05e8\u05d5\u05e0\u05d5\u05ea \u05de\u05ea\u05d0\u05e8 \u05d0\u05ea \u05e1\u05d5\u05d2 \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d5\u05d4\u05d6\u05e8\u05dd."], [134.4, "E6013 \u05d4\u05d9\u05d0 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05e8\u05d5\u05d8\u05d9\u05dc\u05d9\u05ea \u05e0\u05e4\u05d5\u05e6\u05d4, E7018 \u05d4\u05d9\u05d0 \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4, \u05d5-E6010 \u05d4\u05d9\u05d0 \u05e6\u05dc\u05d5\u05dc\u05d5\u05d6\u05d9\u05ea."], [144.9, "\u05d1\u05d0\u05d9\u05e8\u05d5\u05e4\u05d4 \u05de\u05e1\u05d5\u05d5\u05d2\u05d9\u05dd \u05dc\u05e4\u05d9 ISO 2560, \u05e2\u05dd \u05e7\u05d5\u05d3 \u05e9\u05de\u05ea\u05d0\u05e8 \u05d7\u05d5\u05d6\u05e7, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d1\u05d3\u05d9\u05e7\u05ea \u05d4\u05dc\u05dd, \u05e1\u05d5\u05d2 \u05e6\u05d9\u05e4\u05d5\u05d9 \u05d5\u05ea\u05db\u05d5\u05dc\u05ea \u05de\u05d9\u05de\u05df."], [156.2, "\u05d4\u05e6\u05d9\u05d5\u05d3 \u05e4\u05e9\u05d5\u05d8: \u05de\u05e7\u05d5\u05e8 \u05d4\u05e1\u05e4\u05e7 \u05d1\u05d6\u05e8\u05dd \u05e7\u05d1\u05d5\u05e2, \u05ea\u05e4\u05e1\u05df \u05dc\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4, \u05d5\u05db\u05d1\u05dc \u05d7\u05d6\u05e8\u05d4 \u05e2\u05dd \u05ea\u05e4\u05e1."], [163.3, "\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05d1\u05d5\u05d3 \u05d1\u05d6\u05e8\u05dd \u05d9\u05e9\u05e8 \u05d0\u05d5 \u05d1\u05d6\u05e8\u05dd \u05d7\u05d9\u05dc\u05d5\u05e4\u05d9\u05df, \u05dc\u05e4\u05d9 \u05e1\u05d5\u05d2 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4."], [168.5, "\u05d0\u05d9\u05df \u05e6\u05d5\u05e8\u05da \u05d1\u05d1\u05dc\u05d5\u05df \u05d2\u05d6, \u05d5\u05dc\u05db\u05df \u05d4\u05e6\u05d9\u05d5\u05d3 \u05e7\u05dc \u05dc\u05d4\u05e2\u05d1\u05e8\u05d4 \u05d5\u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05e9\u05d8\u05d7, \u05dc\u05d2\u05d5\u05d1\u05d4 \u05d5\u05dc\u05de\u05e7\u05d5\u05de\u05d5\u05ea \u05e6\u05e4\u05d5\u05e4\u05d9\u05dd."], [176.1, "\u05dc\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05d1\u05e1\u05d9\u05e1\u05d9\u05d5\u05ea \u05e6\u05e8\u05d9\u05da \u05d2\u05dd \u05ea\u05e0\u05d5\u05e8 \u05d9\u05d9\u05d1\u05d5\u05e9 \u05d5\u05ea\u05e0\u05d5\u05e8 \u05d4\u05d7\u05d6\u05e7\u05d4 \u05e0\u05d9\u05d9\u05d3."], [181.2, "\u05d5\u05db\u05de\u05d5\u05d1\u05df \u05de\u05e1\u05db\u05d4, \u05db\u05e4\u05e4\u05d5\u05ea, \u05e4\u05d8\u05d9\u05e9 \u05dc\u05d4\u05e1\u05e8\u05ea slag \u05d5\u05de\u05d1\u05e8\u05e9\u05ea \u05e4\u05dc\u05d3\u05d4."], [187.3, "\u05d4\u05e4\u05e8\u05de\u05d8\u05e8 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d4\u05d5\u05d0 \u05e7\u05d5\u05d8\u05e8 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4. \u05d4\u05e7\u05d8\u05e8\u05d9\u05dd \u05d4\u05e0\u05e4\u05d5\u05e6\u05d9\u05dd \u05d4\u05dd 2.5, 3.2 \u05d5-4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."], [196.2, "\u05d4\u05d6\u05e8\u05dd \u05e0\u05e7\u05d1\u05e2 \u05dc\u05e4\u05d9 \u05d4\u05e7\u05d5\u05d8\u05e8: \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05e9\u05dc 3.2 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e2\u05d5\u05d1\u05d3\u05ea \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05df 90 \u05dc-140 \u05d0\u05de\u05e4\u05e8 \u05d1\u05e2\u05e8\u05da, \u05dc\u05e4\u05d9 \u05d4\u05e1\u05d5\u05d2 \u05d5\u05d4\u05ea\u05e0\u05d5\u05d7\u05d4."], [206.9, "\u05d6\u05e8\u05dd \u05e0\u05de\u05d5\u05da \u05de\u05d3\u05d9 \u05d2\u05d5\u05e8\u05dd \u05dc\u05e7\u05e9\u05ea \u05dc\u05d0 \u05d9\u05e6\u05d9\u05d1\u05d4 \u05d5\u05dc\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da, \u05d5\u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05d2\u05d5\u05e8\u05dd \u05dc-undercut, \u05dc-spatter \u05d5\u05dc\u05d4\u05ea\u05d7\u05de\u05de\u05d5\u05ea \u05e9\u05dc \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4."], [217.2, "\u05d0\u05d5\u05e8\u05da \u05d4\u05e7\u05e9\u05ea \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05e2\u05e8\u05da \u05db\u05de\u05d5 \u05e7\u05d5\u05d8\u05e8 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4. \u05e7\u05e9\u05ea \u05d0\u05e8\u05d5\u05db\u05d4 \u05de\u05d3\u05d9 \u05d2\u05d5\u05e8\u05de\u05ea \u05dc\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05d5\u05dc\u05e4\u05d9\u05d6\u05d5\u05e8 \u05d4\u05d7\u05d5\u05dd."], [225.4, "\u05de\u05d8\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05dc\u05d0\u05d7\u05d5\u05e8, \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05d2\u05e8\u05d9\u05e8\u05d4 \u05e9\u05dc \u05d1\u05e2\u05e8\u05da \u05e2\u05e9\u05e8 \u05e2\u05d3 \u05e2\u05e9\u05e8\u05d9\u05dd \u05de\u05e2\u05dc\u05d5\u05ea, \u05db\u05da \u05e9\u05d4-slag \u05e0\u05e9\u05d0\u05e8 \u05de\u05d0\u05d7\u05d5\u05e8\u05d9 \u05d4\u05e7\u05e9\u05ea."], [234.1, "\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d4\u05ea\u05e7\u05d3\u05de\u05d5\u05ea \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05ea \u05e6\u05d5\u05e8\u05ea \u05d4\u05ea\u05e4\u05e8: \u05dc\u05d0\u05d8 \u05de\u05d3\u05d9 \u05e0\u05d5\u05ea\u05df \u05ea\u05e4\u05e8 \u05e8\u05d7\u05d1 \u05d5\u05d7\u05dd, \u05d5\u05de\u05d4\u05e8 \u05de\u05d3\u05d9 \u05e0\u05d5\u05ea\u05df \u05ea\u05e4\u05e8 \u05e6\u05e8 \u05e2\u05dd \u05d7\u05d3\u05d9\u05e8\u05d4 \u05d7\u05dc\u05e7\u05d9\u05ea."], [244.6, "\u05d1\u05db\u05dc \u05d4\u05d7\u05dc\u05e4\u05ea \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05e0\u05e9\u05d0\u05e8 \u05d1\u05d3\u05dc \u05e9\u05dc \u05db\u05de\u05d4 \u05e1\u05e0\u05d8\u05d9\u05de\u05d8\u05e8\u05d9\u05dd, \u05d5\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d4\u05ea\u05d7\u05d9\u05dc \u05d0\u05ea \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d4\u05d1\u05d0\u05d4 \u05e0\u05db\u05d5\u05df, \u05db\u05d3\u05d9 \u05dc\u05d0 \u05dc\u05d9\u05e6\u05d5\u05e8 \u05e4\u05d2\u05dd \u05d1\u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8."], [254.6, "\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05e9\u05dc \u05d4\u05e9\u05d8\u05d7: \u05de\u05d1\u05e0\u05d9 \u05e4\u05dc\u05d3\u05d4, \u05d2\u05e9\u05e8\u05d9\u05dd, \u05d0\u05d5\u05e0\u05d9\u05d5\u05ea, \u05e6\u05e0\u05e8\u05ea \u05d5\u05e2\u05d1\u05d5\u05d3\u05d5\u05ea \u05ea\u05d9\u05e7\u05d5\u05df \u05d5\u05d0\u05d7\u05d6\u05e7\u05d4."], [263.3, "\u05d4\u05d9\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05d7\u05de\u05df \u05d5\u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05d1\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05e0\u05de\u05d5\u05db\u05d4, \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05dc-\u05d7\u05dc\u05d3, \u05dc\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d9\u05e7\u05d4 \u05d5\u05dc\u05e6\u05d9\u05e4\u05d5\u05d9\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd."], [271.9, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea: \u05e6\u05d9\u05d5\u05d3 \u05d6\u05d5\u05dc \u05d5\u05e0\u05d9\u05d9\u05d3, \u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05db\u05dc \u05d4\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea, \u05d5\u05d0\u05d9\u05df \u05e6\u05d5\u05e8\u05da \u05d1\u05d2\u05d6, \u05d5\u05dc\u05db\u05df \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05ea\u05da \u05d2\u05dd \u05d1\u05e8\u05d5\u05d7."], [280.4, "\u05d4\u05d9\u05d0 \u05d2\u05dd \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05de\u05e7\u05d5\u05de\u05d5\u05ea \u05e9\u05e7\u05e9\u05d4 \u05dc\u05d4\u05db\u05e0\u05d9\u05e1 \u05d0\u05dc\u05d9\u05d4\u05dd \u05dc\u05e4\u05d9\u05d3 \u05e9\u05dc MIG."], [284.3, "\u05d4\u05d7\u05e1\u05e8\u05d5\u05e0\u05d5\u05ea: \u05d4\u05ea\u05e4\u05d5\u05e7\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05db\u05d9 \u05de\u05d7\u05dc\u05d9\u05e4\u05d9\u05dd \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05d5\u05de\u05e1\u05d9\u05e8\u05d9\u05dd slag \u05db\u05dc \u05d4\u05d6\u05de\u05df."], [290.4, "\u05d4\u05d9\u05d0 \u05d3\u05d5\u05e8\u05e9\u05ea \u05de\u05d9\u05d5\u05de\u05e0\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d5\u05e4\u05d7\u05d5\u05ea \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05e4\u05d7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05d5\u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd."], [295.7, "\u05d5\u05db\u05dc \u05e2\u05e6\u05d9\u05e8\u05d4 \u05d5\u05d4\u05ea\u05d7\u05dc\u05d4 \u05e9\u05dc \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d4\u05d9\u05d0 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05d1\u05d4 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05d5\u05e6\u05e8 \u05e4\u05d2\u05dd."], [301.6, "\u05d4\u05e4\u05d2\u05dd \u05d4\u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d5\u05d0 \u05d4\u05db\u05dc\u05dc\u05d5\u05ea slag: slag \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d1\u05d9\u05df \u05d4\u05e9\u05db\u05d1\u05d5\u05ea \u05db\u05d9 \u05dc\u05d0 \u05e0\u05d9\u05e7\u05d5 \u05d0\u05d5\u05ea\u05d5 \u05d4\u05d9\u05d8\u05d1."], [309.0, "\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05e0\u05d2\u05e8\u05de\u05d5\u05ea \u05de\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05dc\u05d7\u05d5\u05ea, \u05de\u05e7\u05e9\u05ea \u05d0\u05e8\u05d5\u05db\u05d4 \u05de\u05d3\u05d9, \u05d0\u05d5 \u05de\u05d7\u05dc\u05e7 \u05de\u05dc\u05d5\u05db\u05dc\u05da."], [315.3, "\u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05d1\u05e1\u05d9\u05e1\u05d9\u05d5\u05ea \u05de\u05d5\u05e4\u05d9\u05e2\u05d4 \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05d1\u05ea\u05d7\u05d9\u05dc\u05ea \u05d4\u05ea\u05e4\u05e8, \u05d5\u05dc\u05db\u05df \u05de\u05e6\u05d9\u05ea\u05d9\u05dd \u05de\u05e2\u05d8 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d5\u05d7\u05d5\u05d6\u05e8\u05d9\u05dd \u05d0\u05d7\u05d5\u05e8\u05d4."], [323.8, "undercut, \u05d7\u05e8\u05d9\u05e5 \u05dc\u05d0\u05d5\u05e8\u05da \u05e9\u05d5\u05dc\u05d9 \u05d4\u05ea\u05e4\u05e8, \u05e0\u05d2\u05e8\u05dd \u05de\u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05d0\u05d5 \u05de\u05e7\u05e9\u05ea \u05d0\u05e8\u05d5\u05db\u05d4."], [330.6, "\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da \u05e0\u05d2\u05e8\u05dd \u05de\u05d6\u05e8\u05dd \u05e0\u05de\u05d5\u05da, \u05de\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d3\u05d9 \u05d0\u05d5 \u05de\u05d6\u05d5\u05d5\u05d9\u05ea \u05dc\u05d0 \u05e0\u05db\u05d5\u05e0\u05d4."], [336.6, "\u05e1\u05d3\u05e7\u05d9 \u05de\u05d9\u05de\u05df \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e9\u05de\u05ea\u05e7\u05e9\u05d5\u05ea, \u05db\u05e9\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05dc\u05d7\u05d5\u05ea."], [342.5, "\u05d5\u05e4\u05d2\u05d9\u05e2\u05d5\u05ea \u05e7\u05e9\u05ea, arc strikes, \u05e0\u05d5\u05e6\u05e8\u05d5\u05ea \u05db\u05e9\u05de\u05e6\u05d9\u05ea\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea \u05de\u05d7\u05d5\u05e5 \u05dc\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05d4\u05df \u05e2\u05dc\u05d5\u05dc\u05d5\u05ea \u05dc\u05d4\u05d9\u05d5\u05ea \u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05ea\u05d7\u05dc\u05d4 \u05dc\u05e1\u05d3\u05e7."], [352.3, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4, \u05e8\u05d5\u05d1 \u05d4\u05e2\u05dc\u05d5\u05ea \u05d4\u05d9\u05d0 \u05e9\u05db\u05e8 \u05e2\u05d1\u05d5\u05d3\u05d4, \u05dc\u05d0 \u05d7\u05d5\u05de\u05e8."], [357.5, "\u05d4\u05e7\u05e9\u05ea \u05d3\u05d5\u05dc\u05e7\u05ea \u05e8\u05e7 \u05db\u05e8\u05d1\u05e2 \u05e2\u05d3 \u05e9\u05dc\u05d9\u05e9 \u05de\u05d6\u05de\u05df \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4, \u05d5\u05d4\u05e9\u05d0\u05e8 \u05d4\u05d5\u05dc\u05da \u05e2\u05dc \u05d4\u05d7\u05dc\u05e4\u05ea \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea, \u05d4\u05e1\u05e8\u05ea slag \u05d5\u05d4\u05db\u05e0\u05d4."], [365.9, "\u05e8\u05e7 \u05d1\u05e2\u05e8\u05da 60% \u05de\u05de\u05e9\u05e7\u05dc \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d4\u05d5\u05e4\u05da \u05dc\u05de\u05ea\u05db\u05ea \u05e8\u05d9\u05ea\u05d5\u05da. \u05d4\u05e9\u05d0\u05e8 \u05d4\u05d5\u05d0 \u05d1\u05d3\u05dc\u05d9\u05dd, slag \u05d5-spatter."], [374.6, "\u05e7\u05e6\u05d1 \u05d4\u05e0\u05d7\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05e0\u05de\u05d5\u05da, \u05d1\u05e2\u05e8\u05da \u05e7\u05d9\u05dc\u05d5\u05d2\u05e8\u05dd \u05d0\u05d7\u05d3 \u05e2\u05d3 2.5 \u05d1\u05e9\u05e2\u05ea \u05e7\u05e9\u05ea, \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05d5\u05ea \u05de\u05d0\u05e9\u05e8 \u05d1\u05ea\u05d4\u05dc\u05d9\u05db\u05d9 \u05d7\u05d5\u05d8."], [383.1, "\u05d5\u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05d1\u05e1\u05d9\u05e1\u05d9\u05d5\u05ea \u05de\u05ea\u05d5\u05d5\u05e1\u05e4\u05d9\u05dd \u05d9\u05d9\u05d1\u05d5\u05e9, \u05e9\u05de\u05d9\u05e8\u05d4, \u05d5\u05e4\u05e1\u05d5\u05dc\u05ea \u05e9\u05dc \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05e9\u05e0\u05d7\u05e9\u05e4\u05d5 \u05dc\u05dc\u05d7\u05d5\u05ea."], [389.7, "\u05dc\u05db\u05df \u05d1\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d0\u05e8\u05d5\u05db\u05d4 \u05d1\u05d1\u05d9\u05ea \u05de\u05dc\u05d0\u05db\u05d4 \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc-MIG, \u05dc-MAG \u05d0\u05d5 \u05dc\u05d7\u05d5\u05d8 \u05de\u05dc\u05d9\u05ea, \u05d5\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4 \u05e0\u05e9\u05d0\u05e8\u05ea \u05dc\u05e9\u05d8\u05d7, \u05dc\u05ea\u05d9\u05e7\u05d5\u05e0\u05d9\u05dd \u05d5\u05dc\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea."], [401.9, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4 \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05de\u05e1\u05e4\u05e7 \u05d2\u05dd \u05d2\u05d6, \u05d2\u05dd slag \u05d5\u05d2\u05dd \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea."], [409.1, "\u05d6\u05d4 \u05ea\u05d4\u05dc\u05d9\u05da \u05e4\u05e9\u05d5\u05d8, \u05e0\u05d9\u05d9\u05d3 \u05d5\u05e8\u05d1-\u05e9\u05d9\u05de\u05d5\u05e9\u05d9, \u05d0\u05d1\u05dc \u05d0\u05d9\u05d8\u05d9 \u05d5\u05ea\u05dc\u05d5\u05d9 \u05d1\u05e8\u05ea\u05da."], [414.8, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea MIG \u05d5-MAG, \u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05e9\u05de\u05d6\u05d9\u05e0\u05d9\u05dd \u05d0\u05ea \u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05db\u05d7\u05d5\u05d8 \u05e8\u05e6\u05d9\u05e3."]]};
window.MH_TR["ch05"]={"t": "\u05e8\u05d9\u05ea\u05d5\u05da MIG/MAG", "l": [[3.0, "\u05e8\u05d9\u05ea\u05d5\u05da MIG/MAG, \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd 131 \u05d5-135, \u05d4\u05d5\u05d0 \u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4 \u05db\u05d9\u05d5\u05dd."], [11.3, "\u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05d5 GMAW, \u05d5\u05d1\u05e9\u05d8\u05d7 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05d5 \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e4\u05e9\u05d5\u05d8 \"\u05e8\u05d9\u05ea\u05d5\u05da CO\u2082\"."], [18.9, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df, \u05d2\u05d6\u05d9 \u05d4\u05de\u05d2\u05df, \u05d4\u05e6\u05d9\u05d5\u05d3, \u05d0\u05d5\u05e4\u05e0\u05d9 \u05d4\u05e2\u05d1\u05e8\u05ea \u05d4\u05de\u05ea\u05db\u05ea, \u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd, \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."], [29.1, "\u05d1\u05de\u05e7\u05d5\u05dd \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05e7\u05e6\u05e8\u05d4, \u05d9\u05e9 \u05db\u05d0\u05df \u05d7\u05d5\u05d8 \u05de\u05ea\u05db\u05ea \u05e8\u05e6\u05d9\u05e3 \u05e9\u05de\u05d5\u05d6\u05df \u05de\u05e1\u05dc\u05d9\u05dc \u05d3\u05e8\u05da \u05d4\u05dc\u05e4\u05d9\u05d3."], [35.0, "\u05d4\u05d7\u05d5\u05d8 \u05e2\u05d5\u05d1\u05e8 \u05d3\u05e8\u05da \u05e6\u05d9\u05e0\u05d5\u05e8\u05d9\u05ea \u05de\u05d2\u05e2 \u05de\u05e0\u05d7\u05d5\u05e9\u05ea, \u05e9\u05de\u05e2\u05d1\u05d9\u05e8\u05d4 \u05d0\u05dc\u05d9\u05d5 \u05d0\u05ea \u05d4\u05d6\u05e8\u05dd \u05de\u05de\u05e7\u05d5\u05e8 \u05d4\u05d4\u05e1\u05e4\u05e7."], [41.2, "\u05d4\u05e7\u05e9\u05ea \u05e0\u05d5\u05e6\u05e8\u05ea \u05d1\u05d9\u05df \u05e7\u05e6\u05d4 \u05d4\u05d7\u05d5\u05d8 \u05dc\u05d7\u05dc\u05e7, \u05d5\u05de\u05de\u05d9\u05e1\u05d4 \u05d0\u05ea \u05d4\u05d7\u05d5\u05d8 \u05d5\u05d0\u05ea \u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1 \u05dc\u05d0\u05de\u05d1\u05d8 \u05de\u05e9\u05d5\u05ea\u05e3."], [48.0, "\u05d2\u05d6 \u05de\u05d2\u05df \u05d6\u05d5\u05e8\u05dd \u05de\u05d1\u05dc\u05d5\u05df, \u05d3\u05e8\u05da \u05e4\u05d9\u05d9\u05ea \u05d4\u05d2\u05d6, \u05d5\u05de\u05d2\u05df \u05e2\u05dc \u05d4\u05e7\u05e9\u05ea \u05d5\u05e2\u05dc \u05d4\u05d0\u05de\u05d1\u05d8 \u05de\u05e4\u05e0\u05d9 \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8."], [54.8, "\u05d0\u05d9\u05df \u05e6\u05d9\u05e4\u05d5\u05d9 \u05d5\u05d0\u05d9\u05df slag \u05db\u05de\u05d5 \u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4: \u05d0\u05ea \u05db\u05dc \u05d4\u05d4\u05d2\u05e0\u05d4 \u05e0\u05d5\u05ea\u05df \u05d4\u05d2\u05d6."], [60.5, "\u05d1\u05e8\u05d5\u05d1 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d5\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d7\u05e6\u05d9-\u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9: \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05d6\u05d9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05d7\u05d5\u05d8, \u05d5\u05d4\u05e8\u05ea\u05da \u05de\u05d5\u05d1\u05d9\u05dc \u05d0\u05ea \u05d4\u05dc\u05e4\u05d9\u05d3."], [68.0, "\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d1\u05d6\u05e8\u05dd \u05d9\u05e9\u05e8, \u05db\u05e9\u05d4\u05d7\u05d5\u05d8 \u05de\u05d7\u05d5\u05d1\u05e8 \u05dc\u05e7\u05d5\u05d8\u05d1 \u05d4\u05d7\u05d9\u05d5\u05d1\u05d9."], [73.6, "\u05d4\u05d4\u05d1\u05d3\u05dc \u05d1\u05d9\u05df 131 \u05dc-135 \u05d4\u05d5\u05d0 \u05d1\u05d2\u05d6 \u05d4\u05de\u05d2\u05df."], [78.9, "\u05d1-MIG, \u05ea\u05d4\u05dc\u05d9\u05da 131, \u05d4\u05d2\u05d6 \u05d0\u05d9\u05e0\u05e8\u05d8\u05d9: \u05d0\u05e8\u05d2\u05d5\u05df, \u05d4\u05dc\u05d9\u05d5\u05dd \u05d0\u05d5 \u05ea\u05e2\u05e8\u05d5\u05d1\u05ea \u05e9\u05dc\u05d4\u05dd. \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05de\u05d2\u05d9\u05d1 \u05e2\u05dd \u05d4\u05d0\u05de\u05d1\u05d8."], [88.1, "MIG \u05de\u05e9\u05de\u05e9 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05dc\u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05dc\u05de\u05ea\u05db\u05d5\u05ea \u05dc\u05d0 \u05d1\u05e8\u05d6\u05dc\u05d9\u05d5\u05ea."], [93.7, "\u05d1-MAG, \u05ea\u05d4\u05dc\u05d9\u05da 135, \u05d4\u05d2\u05d6 \u05e4\u05e2\u05d9\u05dc: \u05e4\u05d7\u05de\u05df \u05d3\u05d5-\u05d7\u05de\u05e6\u05e0\u05d9, \u05d0\u05d5 \u05d0\u05e8\u05d2\u05d5\u05df \u05e2\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05e9\u05dc \u05e4\u05d7\u05de\u05df \u05d3\u05d5-\u05d7\u05de\u05e6\u05e0\u05d9 \u05d0\u05d5 \u05d7\u05de\u05e6\u05df."], [103.9, "\u05d4\u05ea\u05e2\u05e8\u05d5\u05d1\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05dc\u05e4\u05dc\u05d3\u05d4 \u05d4\u05d9\u05d0 82% \u05d0\u05e8\u05d2\u05d5\u05df \u05d5-18% \u05e4\u05d7\u05de\u05df \u05d3\u05d5-\u05d7\u05de\u05e6\u05e0\u05d9."], [110.6, "\u05e4\u05d7\u05de\u05df \u05d3\u05d5-\u05d7\u05de\u05e6\u05e0\u05d9 \u05d8\u05d4\u05d5\u05e8 \u05d6\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8 \u05d5\u05e0\u05d5\u05ea\u05df \u05d7\u05d3\u05d9\u05e8\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4, \u05d0\u05d1\u05dc \u05d4\u05e7\u05e9\u05ea \u05e4\u05d7\u05d5\u05ea \u05d9\u05e6\u05d9\u05d1\u05d4 \u05d5\u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 spatter."], [118.4, "\u05dc\u05e4\u05dc\u05d3\u05ea \u05d0\u05dc-\u05d7\u05dc\u05d3 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d0\u05e8\u05d2\u05d5\u05df \u05e2\u05dd \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd \u05d1\u05d5\u05d3\u05d3\u05d9\u05dd \u05e9\u05dc \u05d7\u05de\u05e6\u05df \u05d0\u05d5 \u05e4\u05d7\u05de\u05df \u05d3\u05d5-\u05d7\u05de\u05e6\u05e0\u05d9."], [125.5, "\u05de\u05e7\u05d5\u05e8 \u05d4\u05d4\u05e1\u05e4\u05e7 \u05d1-MIG/MAG \u05e2\u05d5\u05d1\u05d3 \u05d1\u05de\u05ea\u05d7 \u05e7\u05d1\u05d5\u05e2, \u05d5\u05dc\u05d0 \u05d1\u05d6\u05e8\u05dd \u05e7\u05d1\u05d5\u05e2 \u05db\u05de\u05d5 \u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4."], [131.8, "\u05db\u05da \u05d0\u05d5\u05e8\u05da \u05d4\u05e7\u05e9\u05ea \u05de\u05ea\u05d9\u05d9\u05e6\u05d1 \u05de\u05e2\u05e6\u05de\u05d5: \u05d0\u05dd \u05d4\u05dc\u05e4\u05d9\u05d3 \u05de\u05ea\u05e8\u05d7\u05e7, \u05d4\u05d6\u05e8\u05dd \u05d9\u05d5\u05e8\u05d3, \u05d4\u05d7\u05d5\u05d8 \u05e0\u05de\u05e1 \u05dc\u05d0\u05d8 \u05d9\u05d5\u05ea\u05e8 \u05d5\u05d4\u05e7\u05e9\u05ea \u05de\u05ea\u05e7\u05e6\u05e8\u05ea \u05d7\u05d6\u05e8\u05d4."], [141.4, "\u05de\u05d6\u05d9\u05df \u05d4\u05d7\u05d5\u05d8 \u05d3\u05d5\u05d7\u05e3 \u05d0\u05ea \u05d4\u05d7\u05d5\u05d8 \u05d1\u05d2\u05dc\u05d2\u05dc\u05d9 \u05d4\u05e0\u05e2\u05d4: \u05d7\u05e8\u05d9\u05e5 V \u05dc\u05d7\u05d5\u05d8 \u05e4\u05dc\u05d3\u05d4, \u05d5\u05d7\u05e8\u05d9\u05e5 U \u05dc\u05d7\u05d5\u05d8 \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05e8\u05da."], [149.9, "\u05d1\u05ea\u05d5\u05da \u05db\u05d1\u05dc \u05d4\u05dc\u05e4\u05d9\u05d3 \u05d9\u05e9 \u05e6\u05d9\u05e0\u05d5\u05e8 \u05d4\u05d5\u05d1\u05dc\u05d4 \u05dc\u05d7\u05d5\u05d8, \u05e6\u05d9\u05e0\u05d5\u05e8 \u05dc\u05d2\u05d6 \u05d5\u05db\u05d1\u05dc \u05dc\u05d6\u05e8\u05dd."], [156.0, "\u05e7\u05d5\u05d8\u05e8\u05d9 \u05d4\u05d7\u05d5\u05d8 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d9\u05dd \u05d4\u05dd 0.8, 1.0 \u05d5-1.2 \u05de\"\u05de."], [162.2, "\u05d5\u05dc\u05e6\u05d9\u05d3\u05dd: \u05d1\u05dc\u05d5\u05df \u05d2\u05d6 \u05e2\u05dd \u05d5\u05e1\u05ea \u05d5\u05de\u05d3 \u05e1\u05e4\u05d9\u05e7\u05d4, \u05d5\u05db\u05d1\u05dc \u05d7\u05d6\u05e8\u05d4 \u05e2\u05dd \u05ea\u05e4\u05e1."], [169.4, "\u05d4\u05de\u05d0\u05e4\u05d9\u05d9\u05df \u05d4\u05d7\u05e9\u05d5\u05d1 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e9\u05dc MIG/MAG \u05d4\u05d5\u05d0 \u05d0\u05d5\u05e4\u05df \u05d4\u05e2\u05d1\u05e8\u05ea \u05d4\u05de\u05ea\u05db\u05ea \u05de\u05d4\u05d7\u05d5\u05d8 \u05dc\u05d0\u05de\u05d1\u05d8."], [175.4, "\u05d1\u05d4\u05e2\u05d1\u05e8\u05d4 \u05d1\u05e7\u05e6\u05e8, short arc, \u05d4\u05d7\u05d5\u05d8 \u05e0\u05d5\u05d2\u05e2 \u05d1\u05d0\u05de\u05d1\u05d8 \u05d5\u05e0\u05de\u05e1 \u05d1\u05e2\u05e9\u05e8\u05d5\u05ea \u05e2\u05d3 \u05de\u05d0\u05d5\u05ea \u05e7\u05e6\u05e8\u05d9\u05dd \u05d1\u05e9\u05e0\u05d9\u05d9\u05d4."], [183.4, "\u05d6\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05d1\u05d6\u05e8\u05dd \u05d5\u05d1\u05de\u05ea\u05d7 \u05e0\u05de\u05d5\u05db\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05e4\u05d7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd, \u05dc\u05e9\u05d5\u05e8\u05e9 \u05d5\u05dc\u05db\u05dc \u05d4\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea."], [190.6, "\u05d1\u05d4\u05e2\u05d1\u05e8\u05d4 \u05db\u05d3\u05d5\u05e8\u05d9\u05ea, \u05d8\u05d9\u05e4\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea \u05e0\u05d5\u05e4\u05dc\u05d5\u05ea \u05de\u05d4\u05d7\u05d5\u05d8 \u05dc\u05d0\u05de\u05d1\u05d8 \u05d1\u05e6\u05d5\u05e8\u05d4 \u05dc\u05d0 \u05e1\u05d3\u05d9\u05e8\u05d4, \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 spatter."], [197.1, "\u05d1\u05d4\u05e2\u05d1\u05e8\u05ea \u05e8\u05d9\u05e1\u05d5\u05e1, spray, \u05de\u05e2\u05dc \u05d6\u05e8\u05dd \u05d4\u05de\u05e2\u05d1\u05e8, \u05d4\u05d7\u05d5\u05d8 \u05e0\u05de\u05e1 \u05dc\u05d6\u05e8\u05dd \u05e9\u05dc \u05d8\u05d9\u05e4\u05d5\u05ea \u05d6\u05e2\u05d9\u05e8\u05d5\u05ea, \u05d1\u05dc\u05d9 \u05e7\u05e6\u05e8\u05d9\u05dd."], [205.5, "\u05d4\u05d9\u05d0 \u05d3\u05d5\u05e8\u05e9\u05ea \u05d2\u05d6 \u05e2\u05e9\u05d9\u05e8 \u05d1\u05d0\u05e8\u05d2\u05d5\u05df, \u05e0\u05d5\u05ea\u05e0\u05ea \u05d7\u05d3\u05d9\u05e8\u05d4 \u05d5\u05ea\u05e4\u05d5\u05e7\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d5\u05ea, \u05d5\u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd \u05d1\u05ea\u05e0\u05d5\u05d7\u05d4 \u05e9\u05d8\u05d5\u05d7\u05d4."], [213.0, "\u05d1\u05d4\u05e2\u05d1\u05e8\u05d4 \u05d1\u05e4\u05d5\u05dc\u05e1\u05d9\u05dd, pulse, \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05e7\u05e4\u05d9\u05e6\u05d4 \u05d0\u05ea \u05d4\u05d6\u05e8\u05dd \u05d1\u05d9\u05df \u05e2\u05e8\u05da \u05d1\u05e1\u05d9\u05e1 \u05dc\u05e9\u05d9\u05d0, \u05d5\u05db\u05dc \u05e4\u05d5\u05dc\u05e1 \u05de\u05e0\u05ea\u05e7 \u05d8\u05d9\u05e4\u05d4 \u05d0\u05d7\u05ea."], [222.2, "\u05db\u05da \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d9\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc \u05e8\u05d9\u05e1\u05d5\u05e1 \u05d1\u05d7\u05d5\u05dd \u05e0\u05de\u05d5\u05da \u05d9\u05d5\u05ea\u05e8: \u05de\u05e2\u05d8 spatter, \u05db\u05dc \u05d4\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea, \u05d5\u05de\u05ea\u05d0\u05d9\u05dd \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05dc\u05d0\u05dc-\u05d7\u05dc\u05d3."], [231.8, "\u05e9\u05e0\u05d9 \u05d4\u05de\u05ea\u05d2\u05d9\u05dd \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd \u05d1\u05de\u05db\u05d5\u05e0\u05d4 \u05d4\u05dd \u05de\u05ea\u05d7 \u05d5\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d6\u05e0\u05ea \u05d4\u05d7\u05d5\u05d8."], [237.2, "\u05d4\u05de\u05ea\u05d7 \u05e7\u05d5\u05d1\u05e2 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d0\u05ea \u05d0\u05d5\u05e8\u05da \u05d4\u05e7\u05e9\u05ea \u05d5\u05d0\u05ea \u05e8\u05d5\u05d7\u05d1 \u05d4\u05ea\u05e4\u05e8."], [241.5, "\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d6\u05e0\u05ea \u05d4\u05d7\u05d5\u05d8 \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05ea \u05d4\u05d6\u05e8\u05dd \u05d5\u05d0\u05ea \u05db\u05de\u05d5\u05ea \u05d4\u05de\u05ea\u05db\u05ea \u05e9\u05de\u05d5\u05e1\u05e4\u05ea."], [246.7, "\u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05e1\u05d9\u05e0\u05e8\u05d2\u05d9\u05d5\u05ea \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d7\u05d5\u05d8, \u05e7\u05d5\u05d8\u05e8 \u05d5\u05d2\u05d6, \u05d5\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05d0\u05ea \u05d4\u05de\u05ea\u05d7 \u05dc\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d4\u05d6\u05e0\u05d4."], [254.0, "\u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05d5\u05d8 \u05d4\u05d7\u05d5\u05e4\u05e9\u05d9, stickout, \u05d4\u05d5\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc 10 \u05e2\u05d3 15 \u05de\"\u05de \u05d1\u05d4\u05e2\u05d1\u05e8\u05d4 \u05d1\u05e7\u05e6\u05e8. \u05d7\u05d5\u05d8 \u05d0\u05e8\u05d5\u05da \u05de\u05d3\u05d9 \u05de\u05e7\u05d8\u05d9\u05df \u05d0\u05ea \u05d4\u05d6\u05e8\u05dd \u05d5\u05d0\u05ea \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4."], [265.3, "\u05e1\u05e4\u05d9\u05e7\u05ea \u05d4\u05d2\u05d6 \u05d4\u05d9\u05d0 \u05d1\u05e2\u05e8\u05da 12 \u05e2\u05d3 18 \u05dc\u05d9\u05d8\u05e8 \u05dc\u05d3\u05e7\u05d4. \u05d2\u05dd \u05e1\u05e4\u05d9\u05e7\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d3\u05d9 \u05de\u05d6\u05d9\u05e7\u05d4, \u05db\u05d9 \u05d4\u05d9\u05d0 \u05d9\u05d5\u05e6\u05e8\u05ea \u05de\u05e2\u05e8\u05d1\u05d5\u05dc\u05d5\u05ea \u05e9\u05de\u05d5\u05e9\u05db\u05d5\u05ea \u05d0\u05d5\u05d5\u05d9\u05e8."], [274.7, "\u05d1\u05d3\u05d7\u05d9\u05e4\u05d4, \u05d4\u05ea\u05e4\u05e8 \u05e9\u05d8\u05d5\u05d7 \u05d5\u05e8\u05d7\u05d1 \u05d9\u05d5\u05ea\u05e8 \u05d5\u05d4\u05d7\u05d3\u05d9\u05e8\u05d4 \u05e8\u05d3\u05d5\u05d3\u05d4. \u05d1\u05de\u05e9\u05d9\u05db\u05d4, \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d5\u05d4\u05ea\u05e4\u05e8 \u05e6\u05e8 \u05d5\u05d2\u05d1\u05d5\u05d4."], [284.7, "\u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05ea\u05de\u05d9\u05d3 \u05d3\u05d5\u05d7\u05e4\u05d9\u05dd \u05d0\u05ea \u05d4\u05dc\u05e4\u05d9\u05d3, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d2\u05d6 \u05d9\u05e7\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea \u05d5\u05d9\u05d2\u05df \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [291.8, "MIG/MAG \u05e0\u05de\u05e6\u05d0 \u05db\u05de\u05e2\u05d8 \u05d1\u05db\u05dc \u05de\u05e7\u05d5\u05dd: \u05de\u05d1\u05e0\u05d9 \u05e4\u05dc\u05d3\u05d4, \u05db\u05dc\u05d9 \u05e8\u05db\u05d1, \u05de\u05db\u05d5\u05e0\u05d5\u05ea, \u05d5\u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e8\u05d5\u05d1\u05d5\u05d8\u05d9."], [299.5, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea: \u05ea\u05e4\u05d5\u05e7\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d1\u05dc\u05d9 \u05d4\u05d7\u05dc\u05e4\u05ea \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05d5\u05d1\u05dc\u05d9 slag \u05d1\u05d9\u05df \u05e9\u05db\u05d1\u05d5\u05ea."], [305.3, "\u05d4\u05d5\u05d0 \u05e7\u05dc \u05d9\u05d7\u05e1\u05d9\u05ea \u05dc\u05dc\u05d9\u05de\u05d5\u05d3, \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05e8\u05d5\u05d1 \u05d4\u05de\u05ea\u05db\u05d5\u05ea, \u05d5\u05e7\u05dc \u05dc\u05d4\u05e4\u05d5\u05da \u05d0\u05d5\u05ea\u05d5 \u05dc\u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9."], [310.9, "\u05d4\u05d7\u05e1\u05e8\u05d5\u05e0\u05d5\u05ea: \u05d4\u05e8\u05d5\u05d7 \u05de\u05e2\u05d9\u05e4\u05d4 \u05d0\u05ea \u05d2\u05d6 \u05d4\u05de\u05d2\u05df, \u05d5\u05dc\u05db\u05df \u05d1\u05e9\u05d8\u05d7 \u05e4\u05ea\u05d5\u05d7 \u05e6\u05e8\u05d9\u05da \u05de\u05d7\u05e1\u05d4. \u05d2\u05dd \u05e8\u05d5\u05d7 \u05e9\u05dc \u05db-2 \u05de\u05d8\u05e8 \u05dc\u05e9\u05e0\u05d9\u05d9\u05d4 \u05e4\u05d5\u05d2\u05e2\u05ea \u05d1\u05d4\u05d2\u05e0\u05d4."], [321.0, "\u05d4\u05e6\u05d9\u05d5\u05d3 \u05db\u05d1\u05d3 \u05d5\u05de\u05d5\u05e8\u05db\u05d1 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d4\u05dc\u05e4\u05d9\u05d3 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d2\u05d9\u05e2 \u05e7\u05e8\u05d5\u05d1 \u05dc\u05ea\u05e4\u05e8."], [326.1, "\u05d5\u05d1\u05d4\u05e2\u05d1\u05e8\u05d4 \u05d1\u05e7\u05e6\u05e8, \u05e2\u05dc \u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd, \u05d9\u05e9 \u05e1\u05db\u05e0\u05d4 \u05de\u05de\u05e9\u05d9\u05ea \u05dc\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da \u05e9\u05dc\u05d0 \u05e8\u05d5\u05d0\u05d9\u05dd \u05de\u05d1\u05d7\u05d5\u05e5."], [334.2, "\u05d4\u05e4\u05d2\u05dd \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d5\u05d0 \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05de\u05d0\u05d5\u05d1\u05d3\u05df \u05d4\u05d2\u05e0\u05ea \u05d4\u05d2\u05d6: \u05e8\u05d5\u05d7, \u05e1\u05e4\u05d9\u05e7\u05d4 \u05dc\u05d0 \u05e0\u05db\u05d5\u05e0\u05d4, \u05d1\u05dc\u05d5\u05df \u05e8\u05d9\u05e7 \u05d0\u05d5 \u05e4\u05d9\u05d9\u05d4 \u05e1\u05ea\u05d5\u05de\u05d4 \u05d1-spatter."], [344.4, "\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da, cold lap, \u05de\u05d5\u05e4\u05d9\u05e2 \u05db\u05e9\u05d4\u05de\u05ea\u05d7 \u05e0\u05de\u05d5\u05da \u05de\u05d3\u05d9 \u05d0\u05d5 \u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d3\u05d9: \u05d4\u05ea\u05e4\u05e8 \u05e0\u05d7 \u05e2\u05dc \u05d4\u05e4\u05e0\u05d9\u05dd \u05d1\u05dc\u05d9 \u05dc\u05d4\u05ea\u05de\u05d6\u05d2."], [354.1, "\u05d1\u05e4\u05d7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd, \u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05d0\u05d5 \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d0\u05d9\u05d8\u05d9\u05ea \u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05dc\u05e9\u05e8\u05d9\u05e4\u05d4: \u05d7\u05d5\u05e8 \u05d1\u05e4\u05d7."], [361.0, "spatter \u05e8\u05d1 \u05e0\u05d5\u05d1\u05e2 \u05de\u05de\u05ea\u05d7 \u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05dd, \u05de\u05e4\u05d7\u05de\u05df \u05d3\u05d5-\u05d7\u05de\u05e6\u05e0\u05d9 \u05d8\u05d4\u05d5\u05e8 \u05d0\u05d5 \u05de\u05d7\u05d5\u05d8 \u05de\u05dc\u05d5\u05db\u05dc\u05da."], [367.5, "\u05d5\u05d9\u05e9 \u05d2\u05dd \u05ea\u05e7\u05dc\u05d5\u05ea \u05d4\u05d6\u05e0\u05d4: \u05e7\u05df \u05e6\u05d9\u05e4\u05d5\u05e8, \u05db\u05e9\u05d4\u05d7\u05d5\u05d8 \u05de\u05e1\u05ea\u05d1\u05da \u05d1\u05d2\u05dc\u05d2\u05dc\u05d9 \u05d4\u05d4\u05e0\u05e2\u05d4, \u05d5\u05e9\u05e8\u05d9\u05e4\u05d4 \u05dc\u05d0\u05d7\u05d5\u05e8, \u05db\u05e9\u05d4\u05d7\u05d5\u05d8 \u05e0\u05d3\u05d1\u05e7 \u05dc\u05e6\u05d9\u05e0\u05d5\u05e8\u05d9\u05ea \u05d4\u05de\u05d2\u05e2."], [377.5, "\u05d1\u05d4\u05e9\u05d5\u05d5\u05d0\u05d4 \u05dc\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4, MIG/MAG \u05d6\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8 \u05dc\u05db\u05dc \u05e7\"\u05d2 \u05de\u05ea\u05db\u05ea \u05de\u05e8\u05d5\u05ea\u05db\u05ea, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05d2\u05dc\u05dc \u05d6\u05de\u05df \u05e7\u05e9\u05ea \u05d0\u05e8\u05d5\u05da \u05d9\u05d5\u05ea\u05e8."], [385.9, "\u05e7\u05e6\u05d1 \u05d4\u05d4\u05e0\u05d7\u05d4 \u05d2\u05d1\u05d5\u05d4: \u05d1\u05e2\u05e8\u05da 2 \u05e2\u05d3 5 \u05e7\"\u05d2 \u05dc\u05e9\u05e2\u05ea \u05e7\u05e9\u05ea, \u05ea\u05dc\u05d5\u05d9 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05d5\u05d1\u05d0\u05d5\u05e4\u05df \u05d4\u05d4\u05e2\u05d1\u05e8\u05d4."], [393.4, "\u05d5\u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05d4\u05d7\u05d5\u05d8 \u05d4\u05d5\u05e4\u05da \u05dc\u05de\u05ea\u05db\u05ea \u05e8\u05d9\u05ea\u05d5\u05da, \u05dc\u05e2\u05d5\u05de\u05ea \u05db-60% \u05de\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4."], [398.8, "\u05de\u05d4 \u05db\u05df \u05de\u05d9\u05d9\u05e7\u05e8: \u05d2\u05d6 \u05de\u05d2\u05df, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05ea\u05e2\u05e8\u05d5\u05d1\u05d5\u05ea \u05e2\u05e9\u05d9\u05e8\u05d5\u05ea \u05d1\u05d0\u05e8\u05d2\u05d5\u05df, \u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05ea\u05db\u05dc\u05d9\u05dd \u05db\u05de\u05d5 \u05e6\u05d9\u05e0\u05d5\u05e8\u05d9\u05d5\u05ea \u05de\u05d2\u05e2 \u05d5\u05e4\u05d9\u05d5\u05ea."], [408.5, "\u05e0\u05d9\u05e7\u05d5\u05d9 spatter \u05d1\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d4\u05d5\u05d0 \u05d6\u05de\u05df \u05e2\u05d1\u05d5\u05d3\u05d4 \u05d9\u05e7\u05e8, \u05d5\u05dc\u05db\u05df \u05d1\u05d7\u05d9\u05e8\u05d4 \u05e0\u05db\u05d5\u05e0\u05d4 \u05e9\u05dc \u05d2\u05d6 \u05d5\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05d7\u05d5\u05e1\u05db\u05ea \u05db\u05e1\u05e3."], [416.3, "\u05d5\u05d4\u05d7\u05d9\u05e1\u05db\u05d5\u05df \u05d4\u05d2\u05d3\u05d5\u05dc \u05d1\u05d9\u05d5\u05ea\u05e8: \u05de\u05d9\u05db\u05d5\u05df \u05d5\u05e8\u05d5\u05d1\u05d5\u05d8\u05d9\u05dd, \u05e9\u05de\u05d0\u05e8\u05d9\u05db\u05d9\u05dd \u05d0\u05ea \u05d6\u05de\u05df \u05d4\u05e7\u05e9\u05ea \u05d5\u05de\u05e9\u05e4\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05d7\u05d9\u05d3\u05d5\u05ea."], [423.9, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d1-MIG/MAG \u05d7\u05d5\u05d8 \u05e8\u05e6\u05d9\u05e3 \u05d5\u05d2\u05d6 \u05de\u05d2\u05df \u05de\u05d7\u05dc\u05d9\u05e4\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d5\u05d0\u05ea \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9."], [430.7, "\u05d0\u05d5\u05e4\u05df \u05d4\u05d4\u05e2\u05d1\u05e8\u05d4, \u05d4\u05de\u05ea\u05d7 \u05d5\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d4\u05d6\u05e0\u05d4 \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05d0\u05ea \u05d0\u05d9\u05db\u05d5\u05ea \u05d4\u05ea\u05e4\u05e8."], [436.2, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d7\u05d5\u05d8 \u05de\u05dc\u05d9\u05ea, \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd 136 \u05d5-114, \u05e2\u05dd flux \u05d1\u05ea\u05d5\u05da \u05d4\u05d7\u05d5\u05d8."]]};
window.MH_TR["ch06"]={"t": "\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d7\u05d5\u05d8 \u05de\u05dc\u05d9\u05ea", "l": [[3.0, "\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d7\u05d5\u05d8 \u05de\u05dc\u05d9\u05ea, \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd 136 \u05d5-114, \u05de\u05e9\u05dc\u05d1 \u05d0\u05ea \u05d4\u05e8\u05e6\u05d9\u05e4\u05d5\u05ea \u05e9\u05dc MIG/MAG \u05e2\u05dd \u05d4-flux \u05e9\u05dc \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d4\u05de\u05e6\u05d5\u05e4\u05d4."], [12.4, "\u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05d5 FCAW, \u05d5\u05d4\u05d5\u05d0 \u05de\u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d4\u05d7\u05e9\u05d5\u05d1\u05d9\u05dd \u05d1\u05de\u05e1\u05e4\u05e0\u05d5\u05ea, \u05d1\u05de\u05d1\u05e0\u05d9\u05dd \u05db\u05d1\u05d3\u05d9\u05dd \u05d5\u05d1\u05e9\u05d8\u05d7."], [20.4, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05de\u05d1\u05e0\u05d4 \u05d4\u05d7\u05d5\u05d8, \u05e1\u05d5\u05d2\u05d9 \u05d4\u05d7\u05d5\u05d8\u05d9\u05dd, \u05d4\u05e6\u05d9\u05d5\u05d3, \u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd, \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."], [28.7, "\u05d7\u05d5\u05d8 \u05de\u05dc\u05d9\u05ea \u05d4\u05d5\u05d0 \u05e6\u05d9\u05e0\u05d5\u05e8 \u05d3\u05e7 \u05de\u05de\u05ea\u05db\u05ea, \u05de\u05de\u05d5\u05dc\u05d0 \u05d1\u05d0\u05d1\u05e7\u05d4."], [32.9, "\u05d4\u05d7\u05d5\u05d8 \u05de\u05d5\u05d6\u05df \u05d1\u05e8\u05e6\u05d9\u05e4\u05d5\u05ea \u05d3\u05e8\u05da \u05d4\u05dc\u05e4\u05d9\u05d3, \u05d1\u05d3\u05d9\u05d5\u05e7 \u05db\u05de\u05d5 \u05d1-MIG/MAG."], [37.4, "\u05d1\u05e7\u05e9\u05ea, \u05de\u05e2\u05d8\u05e4\u05ea \u05d4\u05de\u05ea\u05db\u05ea \u05e0\u05de\u05e1\u05d4 \u05d5\u05d9\u05d5\u05e6\u05e8\u05ea \u05d0\u05ea \u05e8\u05d5\u05d1 \u05de\u05ea\u05db\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05d4\u05d0\u05d1\u05e7\u05d4 \u05e9\u05d1\u05e4\u05e0\u05d9\u05dd \u05e0\u05de\u05e1\u05d4 \u05d0\u05d9\u05ea\u05d4."], [45.5, "\u05d4\u05de\u05e2\u05d8\u05e4\u05ea \u05d3\u05e7\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05db\u05df \u05d4\u05d6\u05e8\u05dd \u05de\u05ea\u05e8\u05db\u05d6 \u05d1\u05d4 \u05d5\u05d4\u05d7\u05d5\u05d8 \u05e0\u05de\u05e1 \u05de\u05d4\u05e8. \u05d6\u05d4 \u05e1\u05d5\u05d3 \u05d4\u05ea\u05e4\u05d5\u05e7\u05d4 \u05d4\u05d2\u05d1\u05d5\u05d4\u05d4."], [53.6, "\u05d4\u05d0\u05d1\u05e7\u05d4 \u05e2\u05d5\u05e9\u05d4 \u05d0\u05ea \u05de\u05d4 \u05e9\u05e2\u05d5\u05e9\u05d4 \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4: \u05de\u05d9\u05d9\u05e6\u05d1\u05ea \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea, \u05de\u05e8\u05d7\u05d9\u05e7\u05d4 \u05d7\u05de\u05e6\u05df \u05d5\u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea."], [62.0, "\u05d4\u05d9\u05d0 \u05d2\u05dd \u05d9\u05d5\u05e6\u05e8\u05ea \u05e9\u05db\u05d1\u05ea slag \u05e9\u05de\u05db\u05e1\u05d4 \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8 \u05d5\u05de\u05d2\u05d9\u05e0\u05d4 \u05e2\u05dc\u05d9\u05d5 \u05d1\u05d6\u05de\u05df \u05d4\u05d4\u05ea\u05e7\u05e8\u05e8\u05d5\u05ea."], [67.8, "\u05d5\u05d1\u05d7\u05dc\u05e7 \u05de\u05d4\u05d7\u05d5\u05d8\u05d9\u05dd \u05d4\u05d9\u05d0 \u05d2\u05dd \u05de\u05d9\u05d9\u05e6\u05e8\u05ea \u05d0\u05ea \u05d2\u05d6 \u05d4\u05de\u05d2\u05df \u05d1\u05e2\u05e6\u05de\u05d4, \u05db\u05da \u05e9\u05dc\u05d0 \u05e6\u05e8\u05d9\u05da \u05d1\u05dc\u05d5\u05df."], [73.9, "\u05d9\u05e9 \u05e9\u05ea\u05d9 \u05de\u05e9\u05e4\u05d7\u05d5\u05ea \u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea \u05e9\u05dc \u05d7\u05d5\u05d8\u05d9 \u05de\u05dc\u05d9\u05ea."], [77.2, "\u05d1\u05ea\u05d4\u05dc\u05d9\u05da 136, \u05d4\u05d7\u05d5\u05d8 \u05e2\u05d5\u05d1\u05d3 \u05e2\u05dd \u05d2\u05d6 \u05de\u05d2\u05df \u05e4\u05e2\u05d9\u05dc, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e4\u05d7\u05de\u05df \u05d3\u05d5-\u05d7\u05de\u05e6\u05e0\u05d9 \u05d0\u05d5 \u05ea\u05e2\u05e8\u05d5\u05d1\u05ea \u05e9\u05dc \u05d0\u05e8\u05d2\u05d5\u05df \u05d5\u05e4\u05d7\u05de\u05df \u05d3\u05d5-\u05d7\u05de\u05e6\u05e0\u05d9."], [87.1, "\u05d4\u05d4\u05d2\u05e0\u05d4 \u05db\u05e4\u05d5\u05dc\u05d4, \u05d2\u05dd \u05de\u05d4\u05d2\u05d6 \u05d5\u05d2\u05dd \u05de\u05d4-flux, \u05d5\u05dc\u05db\u05df \u05d4\u05ea\u05e4\u05e8 \u05d0\u05d9\u05db\u05d5\u05ea\u05d9 \u05d5\u05d4\u05e7\u05e9\u05ea \u05e0\u05e2\u05d9\u05de\u05d4."], [94.5, "\u05d1\u05ea\u05d4\u05dc\u05d9\u05da 114, \u05d4\u05d7\u05d5\u05d8 \u05de\u05d2\u05df \u05e2\u05dc \u05e2\u05e6\u05de\u05d5: \u05d4\u05d0\u05d1\u05e7\u05d4 \u05de\u05d9\u05d9\u05e6\u05e8\u05ea \u05d2\u05d6 \u05d5-slag, \u05d5\u05d0\u05d9\u05df \u05d1\u05db\u05dc\u05dc \u05d1\u05dc\u05d5\u05df \u05d2\u05d6."], [102.9, "\u05d6\u05d4 \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05e9\u05dc \u05d4\u05e9\u05d8\u05d7: \u05de\u05d1\u05e0\u05d9\u05dd, \u05e6\u05e0\u05e8\u05ea \u05d5\u05d0\u05ea\u05e8\u05d9 \u05d1\u05e0\u05d9\u05d9\u05d4, \u05d2\u05dd \u05d1\u05e8\u05d5\u05d7."], [108.6, "\u05d2\u05dd \u05db\u05d0\u05df \u05d9\u05e9 \u05d7\u05d5\u05d8\u05d9\u05dd \u05e8\u05d5\u05d8\u05d9\u05dc\u05d9\u05d9\u05dd, \u05e0\u05d5\u05d7\u05d9\u05dd \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05db\u05dc \u05d4\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea, \u05d5\u05d7\u05d5\u05d8\u05d9\u05dd \u05d1\u05e1\u05d9\u05e1\u05d9\u05d9\u05dd, \u05d7\u05d6\u05e7\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05d5\u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05de\u05d9\u05de\u05df."], [116.9, "\u05d4-slag \u05e9\u05dc \u05d7\u05d5\u05d8 \u05e8\u05d5\u05d8\u05d9\u05dc\u05d9 \u05de\u05ea\u05de\u05e6\u05e7 \u05de\u05d4\u05e8, \u05d5\u05ea\u05d5\u05de\u05da \u05d1\u05d0\u05de\u05d1\u05d8 \u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05e0\u05db\u05d9 \u05d5\u05de\u05e2\u05dc \u05d4\u05e8\u05d0\u05e9."], [123.1, "\u05d5\u05d9\u05e9 \u05d2\u05dd \u05d7\u05d5\u05d8 \u05e2\u05dd \u05dc\u05d9\u05d1\u05ea \u05de\u05ea\u05db\u05ea, \u05ea\u05d4\u05dc\u05d9\u05da 138: \u05d4\u05d0\u05d1\u05e7\u05d4 \u05d4\u05d9\u05d0 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d0\u05d1\u05e7\u05ea \u05de\u05ea\u05db\u05ea, \u05d5\u05db\u05de\u05e2\u05d8 \u05d0\u05d9\u05df slag."], [132.7, "\u05d4\u05e6\u05d9\u05d5\u05d3 \u05db\u05de\u05e2\u05d8 \u05d6\u05d4\u05d4 \u05dc\u05e6\u05d9\u05d5\u05d3 \u05e9\u05dc MIG/MAG: \u05de\u05e7\u05d5\u05e8 \u05d4\u05e1\u05e4\u05e7 \u05d1\u05de\u05ea\u05d7 \u05e7\u05d1\u05d5\u05e2, \u05de\u05d6\u05d9\u05df \u05d7\u05d5\u05d8 \u05d5\u05dc\u05e4\u05d9\u05d3."], [139.7, "\u05d0\u05d1\u05dc \u05d2\u05dc\u05d2\u05dc\u05d9 \u05d4\u05d4\u05e0\u05e2\u05d4 \u05de\u05e9\u05d5\u05e0\u05e0\u05d9\u05dd \u05d0\u05d5 \u05d1\u05d7\u05e8\u05d9\u05e5 \u05de\u05d9\u05d5\u05d7\u05d3, \u05db\u05d3\u05d9 \u05dc\u05de\u05e9\u05d5\u05da \u05d0\u05ea \u05d4\u05d7\u05d5\u05d8 \u05d1\u05dc\u05d9 \u05dc\u05de\u05e2\u05d5\u05da \u05d0\u05ea \u05d4\u05e6\u05d9\u05e0\u05d5\u05e8."], [146.3, "\u05d4\u05d7\u05d5\u05d8 \u05e8\u05da \u05d9\u05d5\u05ea\u05e8 \u05de\u05d7\u05d5\u05d8 \u05de\u05dc\u05d0, \u05d5\u05dc\u05db\u05df \u05dc\u05d0 \u05de\u05d4\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05d2\u05dc\u05d2\u05dc\u05d9\u05dd \u05d7\u05d6\u05e7 \u05de\u05d3\u05d9."], [151.8, "\u05e7\u05d5\u05d8\u05e8\u05d9 \u05d4\u05d7\u05d5\u05d8 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8: 1.2, 1.4 \u05d5-1.6 \u05de\"\u05de."], [159.5, "\u05d1\u05d7\u05d5\u05d8\u05d9\u05dd \u05e2\u05dd \u05d2\u05d6, \u05d4\u05d7\u05d5\u05d8 \u05de\u05d7\u05d5\u05d1\u05e8 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05e7\u05d5\u05d8\u05d1 \u05d4\u05d7\u05d9\u05d5\u05d1\u05d9."], [164.1, "\u05d1\u05e8\u05d5\u05d1 \u05d4\u05d7\u05d5\u05d8\u05d9\u05dd \u05e2\u05dd \u05de\u05d2\u05df \u05e2\u05e6\u05de\u05d9 \u05d4\u05e7\u05d5\u05d8\u05d1\u05d9\u05d5\u05ea \u05d4\u05e4\u05d5\u05db\u05d4: \u05d4\u05d7\u05d5\u05d8 \u05d1\u05e7\u05d5\u05d8\u05d1 \u05d4\u05e9\u05dc\u05d9\u05dc\u05d9. \u05ea\u05de\u05d9\u05d3 \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d1\u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05d4\u05d9\u05e6\u05e8\u05df."], [171.9, "\u05d5\u05d1\u05ea\u05d4\u05dc\u05d9\u05da 114 \u05d0\u05d9\u05df \u05d1\u05dc\u05d5\u05df, \u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05d1\u05d5\u05d3 \u05e2\u05dd \u05dc\u05e4\u05d9\u05d3 \u05d9\u05d9\u05e2\u05d5\u05d3\u05d9 \u05d1\u05dc\u05d9 \u05e4\u05d9\u05d9\u05ea \u05d2\u05d6."], [178.5, "\u05d2\u05dd \u05db\u05d0\u05df \u05d4\u05de\u05ea\u05d2\u05d9\u05dd \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd \u05d4\u05dd \u05de\u05ea\u05d7 \u05d5\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d6\u05e0\u05ea \u05d4\u05d7\u05d5\u05d8."], [183.8, "\u05de\u05ea\u05d7 \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05de\u05d0\u05e8\u05d9\u05da \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea, \u05de\u05e8\u05d7\u05d9\u05d1 \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8 \u05d5\u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05e1\u05db\u05e0\u05d4 \u05dc\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea."], [190.9, "\u05d0\u05d1\u05dc \u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05d5\u05d8 \u05d4\u05d7\u05d5\u05e4\u05e9\u05d9 \u05d0\u05e8\u05d5\u05da \u05d9\u05d5\u05ea\u05e8: \u05d1\u05d7\u05d5\u05d8\u05d9\u05dd \u05e2\u05dd \u05d2\u05d6, \u05d1\u05e2\u05e8\u05da 20 \u05e2\u05d3 25 \u05de\"\u05de."], [198.2, "\u05d1\u05d7\u05d5\u05d8\u05d9\u05dd \u05e2\u05dd \u05de\u05d2\u05df \u05e2\u05e6\u05de\u05d9 \u05d4\u05d5\u05d0 \u05e7\u05e8\u05d9\u05d8\u05d9 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3: \u05d4\u05d7\u05d5\u05dd \u05d1\u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05d5\u05e4\u05e9\u05d9 \u05de\u05e4\u05e2\u05d9\u05dc \u05d0\u05ea \u05d4\u05d0\u05d1\u05e7\u05d4, \u05d5\u05d7\u05d5\u05d8 \u05e7\u05e6\u05e8 \u05de\u05d3\u05d9 \u05d2\u05d5\u05e8\u05dd \u05dc\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea."], [207.4, "\u05d4\u05db\u05dc\u05dc \u05d4\u05d9\u05d3\u05d5\u05e2: \u05db\u05e9\u05d9\u05e9 slag, \u05de\u05d5\u05e9\u05db\u05d9\u05dd \u05d0\u05ea \u05d4\u05dc\u05e4\u05d9\u05d3."], [211.7, "\u05de\u05e9\u05d9\u05db\u05d4 \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05dc \u05db-10 \u05e2\u05d3 15 \u05de\u05e2\u05dc\u05d5\u05ea \u05de\u05e9\u05d0\u05d9\u05e8\u05d4 \u05d0\u05ea \u05d4-slag \u05de\u05d0\u05d7\u05d5\u05e8\u05d9 \u05d4\u05d0\u05de\u05d1\u05d8 \u05d5\u05de\u05d5\u05e0\u05e2\u05ea \u05e9\u05d0\u05e8\u05d9\u05d5\u05ea slag \u05d1\u05ea\u05d5\u05da \u05d4\u05ea\u05e4\u05e8."], [220.4, "\u05d1\u05d7\u05d5\u05d8 \u05e2\u05dd \u05dc\u05d9\u05d1\u05ea \u05de\u05ea\u05db\u05ea, \u05d1\u05dc\u05d9 slag, \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d3\u05d7\u05d5\u05e3 \u05db\u05de\u05d5 \u05d1\u05d7\u05d5\u05d8 \u05de\u05dc\u05d0."], [225.3, "\u05d5\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05e0\u05db\u05d9 \u05db\u05dc\u05e4\u05d9 \u05de\u05e2\u05dc\u05d4, \u05d7\u05d5\u05d8 \u05e8\u05d5\u05d8\u05d9\u05dc\u05d9 \u05de\u05d0\u05e4\u05e9\u05e8 \u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d7\u05e1\u05d9\u05ea, \u05db\u05d9 \u05d4-slag \u05de\u05d7\u05d6\u05d9\u05e7 \u05d0\u05ea \u05d4\u05d0\u05de\u05d1\u05d8 \u05d1\u05de\u05e7\u05d5\u05dd."], [233.9, "\u05d7\u05d5\u05d8\u05d9 \u05de\u05dc\u05d9\u05ea \u05e0\u05e4\u05d5\u05e6\u05d9\u05dd \u05d1\u05de\u05e1\u05e4\u05e0\u05d5\u05ea, \u05d1\u05de\u05d1\u05e0\u05d9 \u05e4\u05dc\u05d3\u05d4 \u05db\u05d1\u05d3\u05d9\u05dd, \u05d1\u05e4\u05dc\u05d8\u05e4\u05d5\u05e8\u05de\u05d5\u05ea \u05d9\u05de\u05d9\u05d5\u05ea, \u05d1\u05e6\u05e0\u05e8\u05ea \u05d5\u05d1\u05e6\u05d9\u05e4\u05d5\u05d9 \u05e7\u05e9\u05d4."], [241.9, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05df \u05d4\u05d2\u05d3\u05d5\u05dc: \u05e7\u05e6\u05d1 \u05d4\u05e0\u05d7\u05d4 \u05d2\u05d1\u05d5\u05d4, \u05d2\u05dd \u05d1\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea \u05e7\u05e9\u05d5\u05ea."], [246.6, "\u05d7\u05d3\u05d9\u05e8\u05d4 \u05d8\u05d5\u05d1\u05d4, \u05d5\u05e4\u05d7\u05d5\u05ea \u05e8\u05d2\u05d9\u05e9\u05d5\u05ea \u05dc\u05d7\u05dc\u05d5\u05d3\u05d4 \u05d5\u05dc\u05e7\u05e9\u05e7\u05e9\u05ea \u05de\u05d0\u05e9\u05e8 \u05d1\u05d7\u05d5\u05d8 \u05de\u05dc\u05d0."], [252.1, "\u05d4\u05d5\u05d0 \u05d2\u05dd \u05e1\u05dc\u05d7\u05e0\u05d9 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05e8\u05ea\u05da \u05de\u05d0\u05e9\u05e8 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4."], [256.1, "\u05d5\u05d1\u05ea\u05d4\u05dc\u05d9\u05da 114: \u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05e8\u05d5\u05d7, \u05d1\u05dc\u05d9 \u05d1\u05dc\u05d5\u05e0\u05d9\u05dd \u05d5\u05d1\u05dc\u05d9 \u05de\u05d7\u05e1\u05d5\u05ea."], [261.8, "\u05d4\u05d7\u05e1\u05e8\u05d5\u05e0\u05d5\u05ea: \u05e6\u05e8\u05d9\u05da \u05dc\u05e0\u05e7\u05d5\u05ea slag \u05d1\u05d9\u05df \u05e9\u05db\u05d1\u05d5\u05ea, \u05db\u05de\u05d5 \u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4."], [266.9, "\u05d4\u05d7\u05d5\u05d8 \u05d9\u05e7\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05db\u05dc \u05e7\"\u05d2 \u05de\u05d7\u05d5\u05d8 \u05de\u05dc\u05d0."], [270.2, "\u05d9\u05e9 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d0\u05d3\u05d9\u05dd, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05d7\u05d5\u05d8\u05d9\u05dd \u05e2\u05dd \u05de\u05d2\u05df \u05e2\u05e6\u05de\u05d9, \u05d5\u05dc\u05db\u05df \u05d7\u05d5\u05d1\u05d4 \u05d9\u05e0\u05d9\u05e7\u05d4 \u05d5\u05d0\u05d5\u05d5\u05e8\u05d5\u05e8."], [276.8, "\u05d5\u05d7\u05dc\u05e7 \u05de\u05d4\u05d7\u05d5\u05d8\u05d9\u05dd \u05e1\u05d5\u05e4\u05d2\u05d9\u05dd \u05dc\u05d7\u05d5\u05ea, \u05db\u05de\u05d5 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05e9\u05d5\u05de\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05e1\u05d2\u05d5\u05e8\u05d9\u05dd \u05d5\u05d9\u05d1\u05e9\u05d9\u05dd."], [284.0, "\u05d4\u05e4\u05d2\u05dd \u05d4\u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9 \u05d4\u05d5\u05d0 \u05e9\u05d0\u05e8\u05d9\u05d5\u05ea slag \u05d1\u05ea\u05d5\u05da \u05d4\u05ea\u05e4\u05e8: \u05db\u05e9\u05d3\u05d5\u05d7\u05e4\u05d9\u05dd \u05d0\u05ea \u05d4\u05dc\u05e4\u05d9\u05d3, \u05d0\u05d5 \u05dc\u05d0 \u05de\u05e0\u05e7\u05d9\u05dd \u05d4\u05d9\u05d8\u05d1 \u05d1\u05d9\u05df \u05e9\u05db\u05d1\u05d5\u05ea."], [292.9, "\u05d1\u05d7\u05d5\u05d8\u05d9\u05dd \u05e2\u05dd \u05de\u05d2\u05df \u05e2\u05e6\u05de\u05d9 \u05de\u05d5\u05e4\u05d9\u05e2\u05d5\u05ea \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05de\u05d5\u05d0\u05e8\u05db\u05d5\u05ea, \u05db\u05e9\u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05d5\u05d8 \u05d4\u05d7\u05d5\u05e4\u05e9\u05d9 \u05e7\u05e6\u05e8 \u05de\u05d3\u05d9 \u05d0\u05d5 \u05d4\u05de\u05ea\u05d7 \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9."], [301.7, "\u05d1\u05d7\u05d5\u05d8\u05d9\u05dd \u05e2\u05dd \u05d2\u05d6 \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d5\u05e4\u05d9\u05e2 \u05e1\u05d9\u05de\u05e0\u05d9 \u05d2\u05d6, \u05e9\u05e7\u05e2\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05ea\u05e4\u05e8, \u05de\u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05d0\u05d5 \u05de\u05dc\u05db\u05dc\u05d5\u05da \u05d5\u05dc\u05d7\u05d5\u05ea."], [310.7, "\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da \u05de\u05d5\u05e4\u05d9\u05e2 \u05db\u05e9\u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d0\u05d9\u05d8\u05d9\u05ea \u05de\u05d3\u05d9, \u05d5\u05d4\u05d0\u05de\u05d1\u05d8 \u05d5\u05d4-slag \u05e8\u05e6\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e7\u05e9\u05ea."], [317.5, "\u05d5\u05d7\u05d5\u05d8 \u05dc\u05d7 \u05de\u05db\u05e0\u05d9\u05e1 \u05de\u05d9\u05de\u05df, \u05e9\u05e2\u05dc\u05d5\u05dc \u05dc\u05d2\u05e8\u05d5\u05dd \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e9\u05de\u05ea\u05e7\u05e9\u05d5\u05ea."], [322.6, "\u05e8\u05d5\u05d1 \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05e0\u05de\u05e0\u05e2\u05d9\u05dd \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e0\u05db\u05d5\u05e0\u05d4, \u05d1\u05d0\u05d5\u05e8\u05da \u05d7\u05d5\u05d8 \u05d7\u05d5\u05e4\u05e9\u05d9 \u05dc\u05e4\u05d9 \u05d4\u05d9\u05e6\u05e8\u05df \u05d5\u05d1\u05e0\u05d9\u05e7\u05d5\u05d9 \u05d8\u05d5\u05d1."], [329.6, "\u05d7\u05d5\u05d8 \u05de\u05dc\u05d9\u05ea \u05e2\u05d5\u05dc\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05db\u05dc \u05e7\"\u05d2 \u05de\u05d7\u05d5\u05d8 \u05de\u05dc\u05d0, \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d1\u05e2\u05e8\u05da \u05e4\u05d9 \u05e9\u05e0\u05d9\u05d9\u05dd."], [335.6, "\u05d0\u05d1\u05dc \u05e8\u05d5\u05d1 \u05d4\u05e2\u05dc\u05d5\u05ea \u05d4\u05d9\u05d0 \u05e9\u05db\u05e8 \u05e2\u05d1\u05d5\u05d3\u05d4, \u05d5\u05db\u05d0\u05df \u05d7\u05d5\u05d8 \u05d4\u05de\u05dc\u05d9\u05ea \u05de\u05e0\u05e6\u05d7."], [340.4, "\u05e7\u05e6\u05d1 \u05d4\u05d4\u05e0\u05d7\u05d4 \u05e9\u05dc\u05d5 \u05d2\u05d1\u05d5\u05d4, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea \u05d0\u05e0\u05db\u05d9\u05d5\u05ea, \u05e9\u05d1\u05d4\u05df \u05d7\u05d5\u05d8 \u05de\u05dc\u05d0 \u05d5\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d0\u05d9\u05d8\u05d9\u05d9\u05dd."], [347.1, "\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05e0\u05d9\u05e7\u05d5\u05d9 slag \u05d1\u05d9\u05df \u05e9\u05db\u05d1\u05d5\u05ea \u05de\u05d5\u05e1\u05d9\u05e3 \u05d6\u05de\u05df, \u05d5\u05d9\u05e2\u05d9\u05dc\u05d5\u05ea \u05d4\u05d7\u05d5\u05d8 \u05e0\u05de\u05d5\u05db\u05d4 \u05de\u05e2\u05d8 \u05de\u05d6\u05d5 \u05e9\u05dc \u05d7\u05d5\u05d8 \u05de\u05dc\u05d0."], [354.3, "\u05d1\u05ea\u05d4\u05dc\u05d9\u05da 114 \u05d7\u05d5\u05e1\u05db\u05d9\u05dd \u05d2\u05d6, \u05d1\u05dc\u05d5\u05e0\u05d9\u05dd \u05d5\u05de\u05d7\u05e1\u05d5\u05ea \u05e8\u05d5\u05d7, \u05d0\u05d1\u05dc \u05de\u05e9\u05e7\u05d9\u05e2\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05d1\u05d9\u05e0\u05d9\u05e7\u05ea \u05d0\u05d3\u05d9\u05dd."], [361.8, "\u05d1\u05e9\u05d5\u05e8\u05d4 \u05d4\u05ea\u05d7\u05ea\u05d5\u05e0\u05d4: \u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd, \u05d1\u05ea\u05e4\u05e8\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd \u05d5\u05d1\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea \u05e7\u05e9\u05d5\u05ea, \u05d7\u05d5\u05d8 \u05de\u05dc\u05d9\u05ea \u05d4\u05d5\u05d0 \u05dc\u05e8\u05d5\u05d1 \u05d4\u05d6\u05d5\u05dc \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05db\u05dc \u05de\u05d8\u05e8 \u05ea\u05e4\u05e8."], [371.8, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d7\u05d5\u05d8 \u05de\u05dc\u05d9\u05ea \u05d4\u05d5\u05d0 \u05d7\u05d5\u05d8 \u05e6\u05d9\u05e0\u05d5\u05e8\u05d9 \u05e2\u05dd flux \u05d1\u05e4\u05e0\u05d9\u05dd."], [376.5, "136 \u05e2\u05d5\u05d1\u05d3 \u05e2\u05dd \u05d2\u05d6, 114 \u05de\u05d2\u05df \u05e2\u05dc \u05e2\u05e6\u05de\u05d5, \u05d5-138 \u05db\u05de\u05e2\u05d8 \u05d1\u05dc\u05d9 slag."], [384.8, "\u05d5\u05db\u05e9\u05d9\u05e9 slag, \u05de\u05d5\u05e9\u05db\u05d9\u05dd \u05d0\u05ea \u05d4\u05dc\u05e4\u05d9\u05d3."], [387.8, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e8\u05d9\u05ea\u05d5\u05da TIG, \u05ea\u05d4\u05dc\u05d9\u05da 141, \u05d4\u05e7\u05e9\u05ea \u05d4\u05e0\u05e7\u05d9\u05d9\u05d4 \u05d5\u05d4\u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d1\u05d9\u05d5\u05ea\u05e8."]]};
window.MH_TR["ch07"]={"t": "\u05e8\u05d9\u05ea\u05d5\u05da TIG", "l": [[3.0, "\u05e8\u05d9\u05ea\u05d5\u05da TIG, \u05ea\u05d4\u05dc\u05d9\u05da 141, \u05d4\u05d5\u05d0 \u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05e0\u05e7\u05d9 \u05d5\u05d4\u05de\u05d3\u05d5\u05d9\u05e7 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05e2\u05d1\u05d5\u05d3\u05ea \u05d9\u05d3."], [10.3, "\u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05d5 GTAW, \u05d5\u05d1\u05e9\u05d8\u05d7 \u05d1\u05d9\u05e9\u05e8\u05d0\u05dc \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05d5 \u05e4\u05e9\u05d5\u05d8 \"\u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05e8\u05d2\u05d5\u05df\"."], [17.2, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df, \u05d0\u05ea \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05ea \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df, \u05d0\u05ea \u05e1\u05d5\u05d2\u05d9 \u05d4\u05d6\u05e8\u05dd, \u05d0\u05ea \u05d4\u05d8\u05db\u05e0\u05d9\u05e7\u05d4, \u05d0\u05ea \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."], [26.6, "\u05d1-TIG \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05dc\u05d0 \u05e0\u05de\u05e1\u05d4: \u05d4\u05d9\u05d0 \u05e2\u05e9\u05d5\u05d9\u05d4 \u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df, \u05d5\u05ea\u05e4\u05e7\u05d9\u05d3\u05d4 \u05e8\u05e7 \u05dc\u05d4\u05d7\u05d6\u05d9\u05e7 \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea."], [33.4, "\u05d4\u05e7\u05e9\u05ea \u05e0\u05d5\u05e6\u05e8\u05ea \u05d1\u05d9\u05df \u05e7\u05e6\u05d4 \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05dc\u05d7\u05dc\u05e7, \u05d5\u05de\u05de\u05d9\u05e1\u05d4 \u05d0\u05ea \u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1."], [39.0, "\u05d2\u05d6 \u05d0\u05d9\u05e0\u05e8\u05d8\u05d9, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d0\u05e8\u05d2\u05d5\u05df, \u05de\u05d2\u05df \u05e2\u05dc \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df, \u05e2\u05dc \u05d4\u05e7\u05e9\u05ea \u05d5\u05e2\u05dc \u05d4\u05d0\u05de\u05d1\u05d8."], [46.0, "\u05d0\u05ea \u05d7\u05d5\u05de\u05e8 \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d1\u05e0\u05e4\u05e8\u05d3, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05d3, \u05db\u05de\u05d5\u05d8 \u05d3\u05e7 \u05e9\u05d8\u05d5\u05d1\u05dc\u05d9\u05dd \u05d1\u05d0\u05de\u05d1\u05d8."], [52.2, "\u05d1\u05e4\u05d7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05d0\u05e4\u05e9\u05e8 \u05d2\u05dd \u05dc\u05e8\u05ea\u05da \u05d1\u05dc\u05d9 \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9 \u05d1\u05db\u05dc\u05dc, \u05e8\u05e7 \u05d1\u05d4\u05ea\u05db\u05d4 \u05e9\u05dc \u05e9\u05ea\u05d9 \u05d4\u05e9\u05e4\u05d5\u05ea."], [58.5, "\u05db\u05dc\u05d5\u05de\u05e8: \u05d9\u05d3 \u05d0\u05d7\u05ea \u05e2\u05dc \u05d4\u05dc\u05e4\u05d9\u05d3, \u05d9\u05d3 \u05e9\u05e0\u05d9\u05d9\u05d4 \u05e2\u05dc \u05d4\u05de\u05d5\u05d8, \u05d5\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05e8\u05d2\u05dc \u05e2\u05dc \u05d3\u05d5\u05d5\u05e9\u05ea \u05d4\u05d6\u05e8\u05dd."], [65.5, "\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4: \u05d0\u05d9\u05df spatter, \u05d0\u05d9\u05df slag, \u05d5\u05d4\u05d7\u05d5\u05dd \u05e0\u05e9\u05dc\u05d8 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05e8\u05d1."], [71.6, "\u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05e0\u05de\u05e1 \u05e8\u05e7 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 3,400 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05e9\u05d5\u05e8\u05d3 \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea."], [78.5, "\u05dc\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05ea\u05d7\u05de\u05d5\u05e6\u05d5\u05ea, \u05e9\u05de\u05e7\u05dc\u05d5\u05ea \u05e2\u05dc \u05d4\u05d4\u05e6\u05ea\u05d4 \u05d5\u05de\u05d9\u05d9\u05e6\u05d1\u05d5\u05ea \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea, \u05d5\u05db\u05dc \u05e1\u05d5\u05d2 \u05de\u05e1\u05d5\u05de\u05df \u05d1\u05e6\u05d1\u05e2."], [86.0, "\u05e6\u05e8\u05d9\u05d5\u05dd \u05de\u05e1\u05d5\u05de\u05df \u05d1\u05d0\u05e4\u05d5\u05e8, \u05dc\u05e0\u05ea\u05df \u05d1\u05d6\u05d4\u05d1 \u05d0\u05d5 \u05d1\u05db\u05d7\u05d5\u05dc, \u05d5\u05ea\u05d5\u05e8\u05d9\u05d5\u05dd \u05d1\u05d0\u05d3\u05d5\u05dd. \u05d4\u05ea\u05d5\u05e8\u05d9\u05d5\u05dd \u05e8\u05d3\u05d9\u05d5\u05d0\u05e7\u05d8\u05d9\u05d1\u05d9 \u05de\u05e2\u05d8, \u05d5\u05dc\u05db\u05df \u05de\u05d7\u05dc\u05d9\u05e4\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e1\u05d5\u05d2\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd."], [96.8, "\u05d1\u05d6\u05e8\u05dd \u05d9\u05e9\u05e8 \u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd \u05d0\u05ea \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05dc\u05d7\u05d5\u05d3, \u05ea\u05de\u05d9\u05d3 \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d5\u05dc\u05d0 \u05dc\u05e8\u05d5\u05d7\u05d1\u05d4."], [102.8, "\u05d7\u05d5\u05d3 \u05d7\u05d3 \u05e0\u05d5\u05ea\u05df \u05e7\u05e9\u05ea \u05e6\u05e8\u05d4 \u05d5\u05de\u05de\u05d5\u05e7\u05d3\u05ea; \u05d7\u05d5\u05d3 \u05e7\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05e0\u05d5\u05ea\u05df \u05e7\u05e9\u05ea \u05e8\u05d7\u05d1\u05d4."], [109.3, "\u05d2\u05d6 \u05d4\u05de\u05d2\u05df \u05d4\u05d5\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d0\u05e8\u05d2\u05d5\u05df \u05d8\u05d4\u05d5\u05e8. \u05ea\u05d5\u05e1\u05e4\u05ea \u05d4\u05dc\u05d9\u05d5\u05dd \u05e0\u05d5\u05ea\u05e0\u05ea \u05e7\u05e9\u05ea \u05d7\u05de\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05dc\u05e0\u05d7\u05d5\u05e9\u05ea \u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd."], [118.4, "\u05d5\u05d4\u05d2\u05d6 \u05d6\u05d5\u05e8\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05e6\u05ea\u05d4 \u05d5\u05e0\u05de\u05e9\u05da \u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9 \u05d4\u05e7\u05e9\u05ea, \u05db\u05d3\u05d9 \u05dc\u05d4\u05d2\u05df \u05e2\u05dc \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d5\u05e2\u05dc \u05d4\u05ea\u05e4\u05e8 \u05d1\u05d6\u05de\u05df \u05d4\u05d4\u05ea\u05e7\u05e8\u05e8\u05d5\u05ea."], [128.0, "\u05d1\u05d7\u05d9\u05e8\u05ea \u05d4\u05d6\u05e8\u05dd \u05d1-TIG \u05d4\u05d9\u05d0 \u05e7\u05e8\u05d9\u05d8\u05d9\u05ea."], [130.8, "\u05dc\u05e8\u05d5\u05d1 \u05d4\u05de\u05ea\u05db\u05d5\u05ea \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d1\u05d6\u05e8\u05dd \u05d9\u05e9\u05e8, \u05db\u05e9\u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d1\u05e7\u05d5\u05d8\u05d1 \u05d4\u05e9\u05dc\u05d9\u05dc\u05d9."], [136.0, "\u05db\u05da \u05db\u05e9\u05e0\u05d9 \u05e9\u05dc\u05d9\u05e9 \u05de\u05d4\u05d7\u05d5\u05dd \u05e0\u05db\u05e0\u05e1\u05d9\u05dd \u05dc\u05d7\u05dc\u05e7, \u05d5\u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05e0\u05e9\u05d0\u05e8 \u05e7\u05e8 \u05d9\u05d7\u05e1\u05d9\u05ea. \u05d6\u05d4 \u05d4\u05de\u05e6\u05d1 \u05dc\u05e4\u05dc\u05d3\u05d4, \u05dc\u05d0\u05dc-\u05d7\u05dc\u05d3, \u05dc\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d5\u05dc\u05e0\u05d7\u05d5\u05e9\u05ea."], [146.3, "\u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05dc\u05de\u05d2\u05e0\u05d6\u05d9\u05d5\u05dd \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d6\u05e8\u05dd \u05d7\u05d9\u05dc\u05d5\u05e4\u05d9\u05df."], [150.5, "\u05d1\u05d7\u05e6\u05d9 \u05d4\u05d7\u05d9\u05d5\u05d1\u05d9 \u05d4\u05e7\u05e9\u05ea \u05de\u05e4\u05e8\u05e7\u05ea \u05d0\u05ea \u05e9\u05db\u05d1\u05ea \u05d4\u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05d4\u05e7\u05e9\u05d4 \u05e9\u05e2\u05dc \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05d5\u05d1\u05d7\u05e6\u05d9 \u05d4\u05e9\u05dc\u05d9\u05dc\u05d9 \u05d4\u05d9\u05d0 \u05d7\u05d5\u05d3\u05e8\u05ea \u05dc\u05e2\u05d5\u05de\u05e7."], [158.9, "\u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05de\u05d5\u05d3\u05e8\u05e0\u05d9\u05d5\u05ea \u05de\u05db\u05d5\u05d5\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05d9\u05d6\u05d5\u05df \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05d4\u05d7\u05e6\u05d0\u05d9\u05dd: \u05d9\u05d5\u05ea\u05e8 \u05e0\u05d9\u05e7\u05d5\u05d9 \u05d0\u05d5 \u05d9\u05d5\u05ea\u05e8 \u05d7\u05d3\u05d9\u05e8\u05d4."], [165.8, "\u05d5\u05d1\u05e4\u05d7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e4\u05d5\u05dc\u05e1\u05d9\u05dd, \u05db\u05d3\u05d9 \u05dc\u05e9\u05dc\u05d5\u05d8 \u05d1\u05d7\u05d5\u05dd \u05d5\u05dc\u05de\u05e0\u05d5\u05e2 \u05e9\u05e8\u05d9\u05e4\u05d4 \u05d5\u05e2\u05d9\u05d5\u05d5\u05ea."], [172.4, "\u05de\u05e7\u05d5\u05e8 \u05d4\u05d4\u05e1\u05e4\u05e7 \u05e2\u05d5\u05d1\u05d3 \u05d1\u05d6\u05e8\u05dd \u05e7\u05d1\u05d5\u05e2, \u05db\u05de\u05d5 \u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4."], [177.1, "\u05d4\u05d4\u05e6\u05ea\u05d4 \u05e0\u05e2\u05e9\u05d9\u05ea \u05d1\u05ea\u05d3\u05e8 \u05d2\u05d1\u05d5\u05d4 \u05d0\u05d5 \u05d1\u05d4\u05e8\u05de\u05d4 \u05e2\u05d3\u05d9\u05e0\u05d4, \u05d1\u05dc\u05d9 \u05dc\u05d2\u05e2\u05ea \u05d1\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d1\u05d7\u05dc\u05e7, \u05db\u05d3\u05d9 \u05dc\u05d0 \u05dc\u05d6\u05d4\u05dd \u05d0\u05d5\u05ea\u05d5."], [184.4, "\u05d4\u05dc\u05e4\u05d9\u05d3 \u05de\u05e7\u05d5\u05e8\u05e8 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d0\u05d5 \u05d1\u05de\u05d9\u05dd, \u05d5\u05d1\u05e7\u05e6\u05d4\u05d5 \u05db\u05d5\u05e1 \u05e7\u05e8\u05de\u05d9\u05ea \u05e9\u05de\u05db\u05d5\u05d5\u05e0\u05ea \u05d0\u05ea \u05d4\u05d2\u05d6."], [190.4, "\u05d0\u05ea \u05d4\u05d6\u05e8\u05dd \u05de\u05e4\u05e2\u05d9\u05dc\u05d9\u05dd \u05d1\u05de\u05ea\u05d2 \u05e2\u05dc \u05d4\u05dc\u05e4\u05d9\u05d3, \u05d0\u05d5 \u05d1\u05d3\u05d5\u05d5\u05e9\u05ea \u05e8\u05d2\u05dc \u05e9\u05de\u05d0\u05e4\u05e9\u05e8\u05ea \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05d5\u05ea\u05d5 \u05ea\u05d5\u05da \u05db\u05d3\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da."], [197.3, "\u05d4\u05dc\u05e4\u05d9\u05d3 \u05de\u05d5\u05d8\u05d4 \u05d1\u05db\u05e2\u05e9\u05e8 \u05e2\u05d3 \u05d7\u05de\u05e9 \u05e2\u05e9\u05e8\u05d4 \u05de\u05e2\u05dc\u05d5\u05ea \u05de\u05d4\u05d0\u05e0\u05da, \u05d5\u05d3\u05d5\u05d7\u05e4\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05e7\u05d3\u05d9\u05de\u05d4."], [202.8, "\u05d0\u05ea \u05d4\u05de\u05d5\u05d8 \u05de\u05db\u05e0\u05d9\u05e1\u05d9\u05dd \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e0\u05de\u05d5\u05db\u05d4 \u05dc\u05e9\u05e4\u05ea \u05d4\u05d0\u05de\u05d1\u05d8 \u05d4\u05e7\u05d3\u05de\u05d9\u05ea, \u05d5\u05dc\u05d0 \u05dc\u05ea\u05d5\u05da \u05d4\u05e7\u05e9\u05ea."], [208.5, "\u05e7\u05e6\u05d4 \u05d4\u05de\u05d5\u05d8 \u05e0\u05e9\u05d0\u05e8 \u05ea\u05de\u05d9\u05d3 \u05d1\u05ea\u05d5\u05da \u05de\u05e2\u05d8\u05e4\u05ea \u05d4\u05d2\u05d6, \u05db\u05d3\u05d9 \u05e9\u05dc\u05d0 \u05d9\u05ea\u05d7\u05de\u05e6\u05df."], [213.4, "\u05d5\u05d0\u05d5\u05e8\u05da \u05d4\u05e7\u05e9\u05ea \u05e7\u05e6\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d1\u05e2\u05e8\u05da \u05db\u05de\u05d5 \u05e7\u05d5\u05d8\u05e8 \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df."], [218.7, "\u05db\u05dc\u05dc \u05d0\u05e6\u05d1\u05e2 \u05dc\u05e4\u05dc\u05d3\u05d4: \u05d1\u05e2\u05e8\u05da 40 \u05d0\u05de\u05e4\u05e8 \u05dc\u05db\u05dc \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e9\u05dc \u05dc\u05d5\u05d7."], [223.9, "\u05e7\u05d5\u05d8\u05e8\u05d9 \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d4\u05e0\u05e4\u05d5\u05e6\u05d9\u05dd \u05d4\u05dd 1.6, 2.4 \u05d5-3.2 \u05de\"\u05de, \u05dc\u05e4\u05d9 \u05d4\u05d6\u05e8\u05dd."], [232.3, "\u05e1\u05e4\u05d9\u05e7\u05ea \u05d4\u05d0\u05e8\u05d2\u05d5\u05df \u05d4\u05d9\u05d0 \u05d1\u05e2\u05e8\u05da 6 \u05e2\u05d3 12 \u05dc\u05d9\u05d8\u05e8 \u05dc\u05d3\u05e7\u05d4, \u05dc\u05e4\u05d9 \u05d2\u05d5\u05d3\u05dc \u05d4\u05db\u05d5\u05e1."], [238.1, "\u05d1\u05d0\u05dc-\u05d7\u05dc\u05d3 \u05d5\u05d1\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05de\u05d6\u05e8\u05d9\u05de\u05d9\u05dd \u05d0\u05e8\u05d2\u05d5\u05df \u05d2\u05dd \u05de\u05e6\u05d3 \u05d4\u05e9\u05d5\u05e8\u05e9, \u05db\u05d3\u05d9 \u05e9\u05d4\u05e6\u05d3 \u05d4\u05e4\u05e0\u05d9\u05de\u05d9 \u05dc\u05d0 \u05d9\u05ea\u05d7\u05de\u05e6\u05df."], [244.8, "\u05d1\u05e1\u05d5\u05e3 \u05d4\u05ea\u05e4\u05e8 \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d6\u05e8\u05dd \u05d1\u05d4\u05d3\u05e8\u05d2\u05d4, \u05db\u05d3\u05d9 \u05dc\u05de\u05dc\u05d0 \u05d0\u05ea \u05d4\u05de\u05db\u05ea\u05e9 \u05d5\u05dc\u05de\u05e0\u05d5\u05e2 \u05e1\u05d3\u05e7."], [251.0, "\u05d5\u05dc\u05e4\u05e0\u05d9 \u05d4\u05db\u05d5\u05dc, \u05e0\u05d9\u05e7\u05d5\u05d9: \u05e9\u05d5\u05de\u05df, \u05e6\u05d1\u05e2 \u05d5\u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05d4\u05d5\u05e8\u05e1\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8."], [257.9, "TIG \u05d4\u05d5\u05d0 \u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05dc\u05d0\u05dc-\u05d7\u05dc\u05d3, \u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05dc\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd."], [262.7, "\u05d4\u05d5\u05d0 \u05de\u05e9\u05de\u05e9 \u05dc\u05e4\u05d7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd, \u05dc\u05e9\u05d5\u05e8\u05e9 \u05d1\u05e6\u05e0\u05e8\u05ea, \u05d5\u05d1\u05ea\u05e2\u05e9\u05d9\u05d5\u05ea \u05d4\u05ea\u05e2\u05d5\u05e4\u05d4, \u05d4\u05de\u05d6\u05d5\u05df \u05d5\u05d4\u05ea\u05e8\u05d5\u05e4\u05d5\u05ea."], [269.6, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea: \u05d4\u05d0\u05d9\u05db\u05d5\u05ea \u05d4\u05d2\u05d1\u05d5\u05d4\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05ea\u05e4\u05e8 \u05e0\u05e7\u05d9 \u05d5\u05d9\u05e4\u05d4, \u05d1\u05dc\u05d9 spatter \u05d5\u05d1\u05dc\u05d9 slag."], [276.4, "\u05e9\u05dc\u05d9\u05d8\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d1\u05d7\u05d5\u05dd, \u05db\u05dc \u05d4\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea, \u05d5\u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05d4\u05de\u05ea\u05db\u05d5\u05ea."], [281.2, "\u05d4\u05d7\u05e1\u05e8\u05d5\u05e0\u05d5\u05ea: \u05d4\u05d5\u05d0 \u05d0\u05d9\u05d8\u05d9 \u05de\u05d0\u05d5\u05d3, \u05d5\u05e7\u05e6\u05d1 \u05d4\u05d4\u05e0\u05d7\u05d4 \u05e0\u05de\u05d5\u05da."], [286.0, "\u05d4\u05d5\u05d0 \u05d3\u05d5\u05e8\u05e9 \u05de\u05d9\u05d5\u05de\u05e0\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4: \u05e9\u05ea\u05d9 \u05d9\u05d3\u05d9\u05d9\u05dd \u05d5\u05e8\u05d2\u05dc \u05e9\u05e2\u05d5\u05d1\u05d3\u05d5\u05ea \u05d9\u05d7\u05d3."], [291.0, "\u05d4\u05d5\u05d0 \u05e8\u05d2\u05d9\u05e9 \u05de\u05d0\u05d5\u05d3 \u05dc\u05e0\u05d9\u05e7\u05d9\u05d5\u05df \u05d5\u05dc\u05e8\u05d5\u05d7."], [294.0, "\u05d5\u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05de\u05e9\u05ea\u05dc\u05dd \u05dc\u05d1\u05d3\u05d5."], [297.7, "\u05e4\u05d2\u05dd \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9 \u05dc-TIG \u05d4\u05d5\u05d0 \u05e9\u05d0\u05e8\u05d9\u05d5\u05ea \u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d1\u05ea\u05e4\u05e8: \u05db\u05e9\u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05e0\u05d5\u05d2\u05e2 \u05d1\u05d0\u05de\u05d1\u05d8, \u05d0\u05d5 \u05db\u05e9\u05d4\u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05dc\u05e7\u05d5\u05d8\u05e8 \u05e9\u05dc\u05d5."], [306.2, "\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05e0\u05d2\u05e8\u05de\u05d5\u05ea \u05de\u05d0\u05d5\u05d1\u05d3\u05df \u05d2\u05d6, \u05de\u05e8\u05d5\u05d7, \u05d0\u05d5 \u05de\u05de\u05ea\u05db\u05ea \u05d5\u05de\u05d5\u05d8 \u05e9\u05dc\u05d0 \u05e0\u05d5\u05e7\u05d5 \u05de\u05e9\u05de\u05df \u05d5\u05dc\u05d7\u05d5\u05ea."], [313.1, "\u05d1\u05d0\u05dc-\u05d7\u05dc\u05d3, \u05d1\u05dc\u05d9 \u05d2\u05d6 \u05de\u05e6\u05d3 \u05d4\u05e9\u05d5\u05e8\u05e9, \u05d4\u05e6\u05d3 \u05d4\u05e4\u05e0\u05d9\u05de\u05d9 \u05de\u05ea\u05d7\u05de\u05e6\u05df \u05d5\u05de\u05e9\u05d7\u05d9\u05e8. \u05d6\u05d4 \u05e4\u05d2\u05dd \u05e9\u05e4\u05d5\u05e1\u05dc \u05e6\u05e0\u05e8\u05ea."], [321.6, "\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da \u05de\u05d5\u05e4\u05d9\u05e2 \u05db\u05e9\u05d4\u05d6\u05e8\u05dd \u05e0\u05de\u05d5\u05da \u05de\u05d3\u05d9, \u05d0\u05d5 \u05db\u05e9\u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05de\u05d5\u05d8 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05e0\u05d5\u05e6\u05e8 \u05d0\u05de\u05d1\u05d8."], [328.1, "\u05e1\u05d3\u05e7 \u05de\u05db\u05ea\u05e9 \u05de\u05d5\u05e4\u05d9\u05e2 \u05db\u05e9\u05de\u05db\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea."], [332.2, "\u05d5\u05e0\u05d2\u05d9\u05e2\u05d4 \u05e9\u05dc \u05d4\u05de\u05d5\u05d8 \u05d1\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05de\u05d6\u05d4\u05de\u05ea \u05d0\u05d5\u05ea\u05d5: \u05e2\u05d5\u05e6\u05e8\u05d9\u05dd \u05d5\u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd \u05de\u05d7\u05d3\u05e9."], [338.5, "TIG \u05d4\u05d5\u05d0 \u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d0\u05d9\u05d8\u05d9 \u05d1\u05d9\u05d5\u05ea\u05e8: \u05d1\u05e2\u05e8\u05da \u05d7\u05e6\u05d9 \u05e2\u05d3 \u05e7\u05d9\u05dc\u05d5\u05d2\u05e8\u05dd \u05de\u05ea\u05db\u05ea \u05dc\u05e9\u05e2\u05d4."], [344.7, "\u05d5\u05dc\u05db\u05df \u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05d4\u05e2\u05dc\u05d5\u05ea \u05d4\u05d9\u05d0 \u05e9\u05db\u05e8 \u05e2\u05d1\u05d5\u05d3\u05d4 \u05e9\u05dc \u05e8\u05ea\u05da \u05de\u05d9\u05d5\u05de\u05df."], [349.4, "\u05d4\u05d0\u05e8\u05d2\u05d5\u05df, \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d5\u05d4\u05de\u05d5\u05d8\u05d5\u05ea \u05d4\u05dd \u05d7\u05dc\u05e7 \u05e7\u05d8\u05df \u05de\u05d4\u05e2\u05dc\u05d5\u05ea."], [353.9, "\u05d0\u05d1\u05dc \u05d4\u05db\u05e0\u05d4, \u05e0\u05d9\u05e7\u05d5\u05d9, \u05d4\u05d6\u05e8\u05de\u05ea \u05d2\u05d6 \u05de\u05e6\u05d3 \u05d4\u05e9\u05d5\u05e8\u05e9 \u05d5\u05e9\u05d7\u05d6\u05d5\u05e8 \u05d4\u05d7\u05d5\u05d3 \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d6\u05de\u05df."], [360.3, "\u05d4\u05e4\u05ea\u05e8\u05d5\u05df \u05d4\u05e0\u05e4\u05d5\u05e5: \u05e9\u05d5\u05e8\u05e9 \u05d1-TIG, \u05d5\u05de\u05d9\u05dc\u05d5\u05d9 \u05d1\u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05d4\u05d9\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05db\u05de\u05d5 MIG/MAG \u05d0\u05d5 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4."], [367.4, "\u05d5\u05d1\u05ea\u05e4\u05e8\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd \u05d1\u05e4\u05dc\u05d3\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4, TIG \u05db\u05de\u05e2\u05d8 \u05d0\u05e3 \u05e4\u05e2\u05dd \u05d0\u05d9\u05e0\u05d5 \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05d4\u05d6\u05d5\u05dc\u05d4."], [373.0, "\u05d5\u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e1\u05d3\u05e8\u05ea\u05d9, TIG \u05de\u05de\u05d5\u05db\u05df \u05d0\u05d5 \u05de\u05e1\u05dc\u05d5\u05dc\u05d9 \u05dc\u05e6\u05e0\u05e8\u05ea \u05de\u05e7\u05e6\u05e8 \u05d0\u05ea \u05d4\u05d6\u05de\u05df \u05d5\u05e9\u05d5\u05de\u05e8 \u05e2\u05dc \u05d0\u05d9\u05db\u05d5\u05ea \u05d0\u05d7\u05d9\u05d3\u05d4."], [380.8, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d1-TIG \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05dc\u05d0 \u05e0\u05de\u05e1, \u05d5\u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05ea\u05d5\u05d5\u05e1\u05e3 \u05d1\u05e0\u05e4\u05e8\u05d3."], [386.5, "\u05d6\u05e8\u05dd \u05d9\u05e9\u05e8 \u05dc\u05e8\u05d5\u05d1 \u05d4\u05de\u05ea\u05db\u05d5\u05ea, \u05d5\u05d6\u05e8\u05dd \u05d7\u05d9\u05dc\u05d5\u05e4\u05d9\u05df \u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd."], [391.1, "\u05d0\u05d9\u05db\u05d5\u05ea \u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9\u05ea \u05d1\u05de\u05d7\u05d9\u05e8 \u05e9\u05dc \u05d6\u05de\u05df. \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e8\u05d9\u05ea\u05d5\u05da \u05e4\u05dc\u05d6\u05de\u05d4, \u05ea\u05d4\u05dc\u05d9\u05da 15."]]};
window.MH_TR["ch08"]={"t": "\u05e8\u05d9\u05ea\u05d5\u05da \u05e4\u05dc\u05d6\u05de\u05d4", "l": [[3.0, "\u05e8\u05d9\u05ea\u05d5\u05da \u05e4\u05dc\u05d6\u05de\u05d4, \u05ea\u05d4\u05dc\u05d9\u05da 15, \u05d4\u05d5\u05d0 \u05e7\u05e8\u05d5\u05d1 \u05de\u05e9\u05e4\u05d7\u05d4 \u05e9\u05dc TIG, \u05d0\u05d1\u05dc \u05e2\u05dd \u05e7\u05e9\u05ea \u05de\u05e8\u05d5\u05db\u05d6\u05ea \u05d5\u05d7\u05de\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8."], [10.8, "\u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05d5 PAW, \u05d5\u05d4\u05d5\u05d0 \u05de\u05e9\u05de\u05e9 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05de\u05d3\u05d5\u05d9\u05e7 \u05d5\u05de\u05de\u05d5\u05db\u05df."], [16.3, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df, \u05d0\u05ea \u05e9\u05dc\u05d5\u05e9\u05ea \u05de\u05e6\u05d1\u05d9 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4, \u05d0\u05ea \u05d4\u05e6\u05d9\u05d5\u05d3, \u05d0\u05ea \u05d4\u05d4\u05e9\u05d5\u05d5\u05d0\u05d4 \u05dc-TIG, \u05d0\u05ea \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."], [26.2, "\u05ea\u05d7\u05e9\u05d1\u05d5 \u05e2\u05dc \u05e6\u05d9\u05e0\u05d5\u05e8 \u05de\u05d9\u05dd: \u05db\u05e9\u05dc\u05d5\u05d7\u05e6\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e6\u05d4 \u05d1\u05d0\u05e6\u05d1\u05e2, \u05d4\u05e1\u05d9\u05dc\u05d5\u05df \u05e0\u05e2\u05e9\u05d4 \u05e6\u05e8, \u05de\u05d4\u05d9\u05e8 \u05d5\u05d7\u05d6\u05e7."], [33.2, "\u05d1\u05e4\u05dc\u05d6\u05de\u05d4 \u05e2\u05d5\u05e9\u05d9\u05dd \u05d0\u05ea \u05d6\u05d4 \u05dc\u05e7\u05e9\u05ea: \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05ea \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d9\u05d5\u05e9\u05d1\u05ea \u05d1\u05ea\u05d5\u05da \u05e4\u05d9\u05d9\u05d4 \u05de\u05e0\u05d7\u05d5\u05e9\u05ea, \u05e2\u05dd \u05e4\u05ea\u05d7 \u05e7\u05d8\u05df \u05de\u05d0\u05d5\u05d3."], [41.0, "\u05d2\u05d6 \u05d4\u05e4\u05dc\u05d6\u05de\u05d4, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d0\u05e8\u05d2\u05d5\u05df, \u05d6\u05d5\u05e8\u05dd \u05d3\u05e8\u05da \u05d4\u05e4\u05ea\u05d7 \u05d4\u05d6\u05d4, \u05d5\u05d4\u05e7\u05e9\u05ea \u05e0\u05d3\u05d7\u05e1\u05ea \u05d3\u05e8\u05db\u05d5."], [48.1, "\u05d4\u05e7\u05e9\u05ea \u05d4\u05d3\u05d7\u05d5\u05e1\u05d4 \u05e6\u05e8\u05d4, \u05d9\u05e6\u05d9\u05d1\u05d4 \u05d5\u05de\u05e8\u05d5\u05db\u05d6\u05ea, \u05d5\u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d1\u05ea\u05d5\u05db\u05d4 \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05d9\u05d5\u05ea\u05e8 \u05de\u05e2\u05e9\u05e8\u05d9\u05dd \u05d0\u05dc\u05e3 \u05de\u05e2\u05dc\u05d5\u05ea."], [56.0, "\u05d4\u05d7\u05d5\u05dd \u05d4\u05d6\u05d4 \u05de\u05e8\u05d5\u05db\u05d6 \u05d1\u05e9\u05d8\u05d7 \u05e7\u05d8\u05df \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05d7\u05d5\u05d3\u05e8 \u05e2\u05de\u05d5\u05e7 \u05d5\u05de\u05d4\u05e8."], [61.5, "\u05de\u05e1\u05d1\u05d9\u05d1 \u05dc\u05e4\u05d9\u05d9\u05d4 \u05d6\u05d5\u05e8\u05dd \u05d2\u05d6 \u05de\u05d2\u05df \u05e0\u05e4\u05e8\u05d3, \u05e9\u05de\u05d2\u05df \u05e2\u05dc \u05d4\u05d0\u05de\u05d1\u05d8, \u05d1\u05d3\u05d9\u05d5\u05e7 \u05db\u05de\u05d5 \u05d1-TIG."], [67.7, "\u05d4\u05d4\u05e6\u05ea\u05d4 \u05de\u05ea\u05d7\u05d9\u05dc\u05d4 \u05d1\u05e7\u05e9\u05ea \u05e2\u05d6\u05e8 \u05e7\u05d8\u05e0\u05d4, \u05d1\u05d9\u05df \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05dc\u05e4\u05d9\u05d9\u05d4, \u05e9\u05e0\u05d3\u05dc\u05e7\u05ea \u05d1\u05ea\u05d3\u05e8 \u05d2\u05d1\u05d5\u05d4."], [74.3, "\u05db\u05e9\u05de\u05ea\u05e7\u05e8\u05d1\u05d9\u05dd \u05dc\u05d7\u05dc\u05e7, \u05d4\u05e7\u05e9\u05ea \u05e2\u05d5\u05d1\u05e8\u05ea \u05d0\u05dc\u05d9\u05d5. \u05d6\u05d5 \u05e7\u05e9\u05ea \u05de\u05d5\u05e2\u05d1\u05e8\u05ea, \u05d5\u05d6\u05d5 \u05d4\u05e7\u05e9\u05ea \u05e9\u05de\u05e8\u05ea\u05db\u05ea."], [82.2, "\u05d0\u05d2\u05d1, \u05d7\u05d9\u05ea\u05d5\u05da \u05e4\u05dc\u05d6\u05de\u05d4 \u05e2\u05d5\u05d1\u05d3 \u05e2\u05dc \u05d0\u05d5\u05ea\u05d5 \u05e2\u05d9\u05e7\u05e8\u05d5\u05df, \u05e8\u05e7 \u05e2\u05dd \u05d6\u05e8\u05d9\u05de\u05ea \u05d2\u05d6 \u05d7\u05d6\u05e7\u05d4 \u05e9\u05de\u05e2\u05d9\u05e4\u05d4 \u05d0\u05ea \u05d4\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d5\u05ea\u05db\u05ea."], [89.9, "\u05dc\u05e8\u05d9\u05ea\u05d5\u05da \u05e4\u05dc\u05d6\u05de\u05d4 \u05d9\u05e9 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05de\u05e6\u05d1\u05d9 \u05e2\u05d1\u05d5\u05d3\u05d4, \u05dc\u05e4\u05d9 \u05d4\u05d6\u05e8\u05dd."], [94.3, "\u05de\u05d9\u05e7\u05e8\u05d5 \u05e4\u05dc\u05d6\u05de\u05d4 \u05e2\u05d5\u05d1\u05d3 \u05d1\u05d6\u05e8\u05de\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd, \u05de\u05e2\u05e9\u05d9\u05e8\u05d9\u05ea \u05d0\u05de\u05e4\u05e8 \u05d5\u05e2\u05d3 \u05db\u05d7\u05de\u05d9\u05e9\u05d4 \u05e2\u05e9\u05e8 \u05d0\u05de\u05e4\u05e8."], [100.3, "\u05d4\u05d5\u05d0 \u05de\u05e8\u05ea\u05da \u05e8\u05d3\u05d9\u05d3\u05d9\u05dd \u05d5\u05e4\u05d7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05d7\u05d9\u05d9\u05e9\u05e0\u05d9\u05dd \u05d5\u05de\u05e4\u05d5\u05d7\u05d9\u05dd, \u05d1\u05d3\u05d9\u05d5\u05e7 \u05e9\u05e7\u05e9\u05d4 \u05dc\u05d4\u05e9\u05d9\u05d2 \u05d1-TIG."], [107.3, "\u05d1\u05de\u05e6\u05d1 \u05d4\u05ea\u05db\u05d4, \u05d1\u05d6\u05e8\u05dd \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9, \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d1\u05d3 \u05db\u05de\u05d5 TIG \u05de\u05e9\u05d5\u05e4\u05e8: \u05e7\u05e9\u05ea \u05d9\u05e6\u05d9\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d0\u05de\u05d1\u05d8 \u05e8\u05d2\u05d9\u05dc."], [115.1, "\u05d5\u05d4\u05de\u05e6\u05d1 \u05d4\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d5\u05d0 \u05d7\u05d5\u05e8 \u05de\u05e4\u05ea\u05d7."], [118.8, "\u05d1\u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4, \u05e1\u05d9\u05dc\u05d5\u05df \u05d4\u05e4\u05dc\u05d6\u05de\u05d4 \u05d7\u05d5\u05d3\u05e8 \u05d0\u05ea \u05db\u05dc \u05e2\u05d5\u05d1\u05d9 \u05d4\u05dc\u05d5\u05d7 \u05d5\u05e4\u05d5\u05ea\u05d7 \u05d1\u05d5 \u05d7\u05d5\u05e8 \u05e7\u05d8\u05df."], [124.7, "\u05db\u05e9\u05d4\u05dc\u05e4\u05d9\u05d3 \u05de\u05ea\u05e7\u05d3\u05dd, \u05d4\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d5\u05ea\u05db\u05ea \u05d6\u05d5\u05e8\u05de\u05ea \u05e1\u05d1\u05d9\u05d1 \u05d4\u05d7\u05d5\u05e8 \u05d5\u05e0\u05e1\u05d2\u05e8\u05ea \u05de\u05d0\u05d7\u05d5\u05e8\u05d9\u05d5, \u05d5\u05d9\u05d5\u05e6\u05e8\u05ea \u05ea\u05e4\u05e8 \u05de\u05dc\u05d0."], [132.3, "\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05d0\u05d5\u05ea \u05d0\u05ea \u05d6\u05d4 \u05d2\u05dd \u05de\u05dc\u05de\u05d8\u05d4: \u05e1\u05d9\u05dc\u05d5\u05df \u05e4\u05dc\u05d6\u05de\u05d4 \u05e7\u05d8\u05df \u05d9\u05d5\u05e6\u05d0 \u05de\u05e6\u05d3 \u05d4\u05e9\u05d5\u05e8\u05e9 \u05d1\u05d6\u05de\u05df \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [138.4, "\u05db\u05da \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d1\u05de\u05e2\u05d1\u05e8 \u05d0\u05d7\u05d3, \u05d1\u05dc\u05d9 \u05d4\u05db\u05e0\u05ea \u05e9\u05e4\u05d5\u05ea \u05d5\u05d1\u05dc\u05d9 \u05de\u05d9\u05dc\u05d5\u05d9, \u05e2\u05d3 \u05db\u05e9\u05de\u05d5\u05e0\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d1\u05d0\u05dc-\u05d7\u05dc\u05d3."], [145.5, "\u05d1\u05e1\u05d5\u05e3 \u05d4\u05ea\u05e4\u05e8 \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d1\u05d4\u05d3\u05e8\u05d2\u05d4 \u05d0\u05ea \u05d4\u05d6\u05e8\u05dd \u05d5\u05d0\u05ea \u05d2\u05d6 \u05d4\u05e4\u05dc\u05d6\u05de\u05d4, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d7\u05d5\u05e8 \u05d9\u05d9\u05e1\u05d2\u05e8 \u05d1\u05dc\u05d9 \u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05e4\u05d2\u05dd."], [153.8, "\u05de\u05e7\u05d5\u05e8 \u05d4\u05d4\u05e1\u05e4\u05e7 \u05e2\u05d5\u05d1\u05d3 \u05d1\u05d6\u05e8\u05dd \u05e7\u05d1\u05d5\u05e2, \u05db\u05de\u05d5 \u05d1-TIG, \u05d5\u05dc\u05e6\u05d9\u05d3\u05d5 \u05d9\u05d7\u05d9\u05d3\u05ea \u05d1\u05e7\u05e8\u05d4 \u05dc\u05e7\u05e9\u05ea \u05d4\u05e2\u05d6\u05e8 \u05d5\u05dc\u05e9\u05e0\u05d9 \u05d4\u05d2\u05d6\u05d9\u05dd."], [161.8, "\u05d4\u05dc\u05e4\u05d9\u05d3 \u05de\u05e7\u05d5\u05e8\u05e8 \u05d1\u05de\u05d9\u05dd, \u05d5\u05d4\u05e4\u05d9\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05d7\u05dc\u05e7 \u05de\u05ea\u05db\u05dc\u05d4, \u05d1\u05db\u05de\u05d4 \u05e7\u05d5\u05d8\u05e8\u05d9 \u05e4\u05ea\u05d7."], [167.6, "\u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05e8\u05d1\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05d0\u05e9\u05e8 \u05d1-TIG: \u05d6\u05e8\u05dd, \u05e7\u05d5\u05d8\u05e8 \u05d4\u05e4\u05ea\u05d7, \u05e1\u05e4\u05d9\u05e7\u05ea \u05d2\u05d6 \u05d4\u05e4\u05dc\u05d6\u05de\u05d4, \u05d2\u05d6 \u05d4\u05de\u05d2\u05df, \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d4\u05ea\u05e7\u05d3\u05de\u05d5\u05ea, \u05d5\u05e2\u05d5\u05de\u05e7 \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d1\u05ea\u05d5\u05da \u05d4\u05e4\u05d9\u05d9\u05d4."], [179.3, "\u05e1\u05e4\u05d9\u05e7\u05ea \u05d2\u05d6 \u05d4\u05e4\u05dc\u05d6\u05de\u05d4 \u05e7\u05d8\u05e0\u05d4, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e4\u05d7\u05d5\u05ea \u05de\u05db\u05de\u05d4 \u05dc\u05d9\u05d8\u05e8\u05d9\u05dd \u05dc\u05d3\u05e7\u05d4. \u05d9\u05d5\u05ea\u05e8 \u05de\u05d3\u05d9 \u05d2\u05d6 \u05db\u05d1\u05e8 \u05de\u05ea\u05d7\u05d9\u05dc \u05dc\u05d7\u05ea\u05d5\u05da."], [186.8, "\u05dc\u05d0\u05dc-\u05d7\u05dc\u05d3 \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05d0\u05e8\u05d2\u05d5\u05df \u05de\u05e2\u05d8 \u05de\u05d9\u05de\u05df, \u05e9\u05de\u05d7\u05de\u05dd \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea \u05d5\u05de\u05e9\u05d0\u05d9\u05e8 \u05ea\u05e4\u05e8 \u05e0\u05e7\u05d9."], [192.9, "\u05d5\u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05d1\u05e0\u05d7\u05d5\u05e9\u05ea \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d2\u05dd \u05d1\u05ea\u05d5\u05e1\u05e4\u05ea \u05d4\u05dc\u05d9\u05d5\u05dd."], [197.2, "\u05d0\u05dd \u05e6\u05e8\u05d9\u05da, \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d7\u05d5\u05d8 \u05de\u05d9\u05dc\u05d5\u05d9 \u05e7\u05e8, \u05e9\u05de\u05d5\u05d6\u05df \u05dc\u05d0\u05de\u05d1\u05d8 \u05de\u05d4\u05e6\u05d3."], [202.0, "\u05e8\u05d5\u05d1 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4, \u05d5\u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d7\u05d5\u05e8 \u05de\u05e4\u05ea\u05d7, \u05e0\u05e2\u05e9\u05d9\u05ea \u05de\u05de\u05d5\u05db\u05e0\u05ea: \u05e2\u05d2\u05dc\u05d4, \u05de\u05e1\u05dc\u05d5\u05dc \u05d0\u05d5 \u05e8\u05d5\u05d1\u05d5\u05d8."], [209.8, "\u05de\u05d4 \u05d4\u05d4\u05d1\u05d3\u05dc \u05d4\u05de\u05e2\u05e9\u05d9 \u05d1\u05d9\u05df \u05e4\u05dc\u05d6\u05de\u05d4 \u05dc-TIG?"], [213.0, "\u05e7\u05e9\u05ea \u05d4-TIG \u05e8\u05d7\u05d1\u05d4, \u05d1\u05e6\u05d5\u05e8\u05ea \u05d7\u05e8\u05d5\u05d8, \u05d5\u05dc\u05db\u05df \u05db\u05dc \u05e9\u05d9\u05e0\u05d5\u05d9 \u05d1\u05de\u05e8\u05d7\u05e7 \u05de\u05d4\u05d7\u05dc\u05e7 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05e8\u05d5\u05d7\u05d1 \u05d4\u05ea\u05e4\u05e8."], [220.8, "\u05e7\u05e9\u05ea \u05d4\u05e4\u05dc\u05d6\u05de\u05d4 \u05db\u05de\u05e2\u05d8 \u05d2\u05dc\u05d9\u05dc\u05d9\u05ea, \u05d5\u05dc\u05db\u05df \u05d4\u05d9\u05d0 \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05d5\u05ea \u05e8\u05d2\u05d9\u05e9\u05d4 \u05dc\u05de\u05e8\u05d7\u05e7."], [226.1, "\u05d4\u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05de\u05e8\u05d5\u05db\u05d6\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05e2\u05dd \u05d0\u05d6\u05d5\u05e8 \u05de\u05d5\u05e9\u05e4\u05e2 \u05d7\u05d5\u05dd \u05e6\u05e8 \u05d5\u05e2\u05d9\u05d5\u05d5\u05ea \u05e7\u05d8\u05df."], [233.1, "\u05d5\u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05de\u05d5\u05d2\u05df \u05d1\u05ea\u05d5\u05da \u05d4\u05e4\u05d9\u05d9\u05d4: \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05e0\u05d5\u05d2\u05e2 \u05d1\u05d0\u05de\u05d1\u05d8, \u05d5\u05d0\u05d9\u05df \u05e9\u05d0\u05e8\u05d9\u05d5\u05ea \u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d1\u05ea\u05e4\u05e8."], [239.9, "\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05dc\u05db\u05d5\u05d5\u05df, \u05d5\u05d4\u05dc\u05e4\u05d9\u05d3 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8, \u05db\u05da \u05e9\u05e7\u05e9\u05d4 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05d0\u05d9\u05ea\u05d5 \u05dc\u05de\u05e7\u05d5\u05de\u05d5\u05ea \u05e6\u05e4\u05d5\u05e4\u05d9\u05dd."], [247.8, "\u05e4\u05dc\u05d6\u05de\u05d4 \u05de\u05e9\u05de\u05e9\u05ea \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e6\u05d9\u05e0\u05d5\u05e8\u05d5\u05ea \u05d0\u05dc-\u05d7\u05dc\u05d3 \u05d1\u05ea\u05e4\u05e8 \u05d0\u05d5\u05e8\u05db\u05d9, \u05d1\u05ea\u05e2\u05d5\u05e4\u05d4, \u05d1\u05e6\u05d9\u05d5\u05d3 \u05e8\u05e4\u05d5\u05d0\u05d9 \u05d5\u05d1\u05de\u05db\u05e9\u05d5\u05e8."], [255.3, "\u05d5\u05d2\u05e8\u05e1\u05d4 \u05e9\u05dc\u05d4, \u05e2\u05dd \u05d0\u05d1\u05e7\u05ea \u05de\u05ea\u05db\u05ea, \u05de\u05e9\u05de\u05e9\u05ea \u05dc\u05e6\u05d9\u05e4\u05d5\u05d9 \u05e7\u05e9\u05d4 \u05e9\u05dc \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05e0\u05e9\u05d7\u05e7\u05d9\u05dd."], [261.4, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea: \u05d7\u05d3\u05d9\u05e8\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05d1\u05de\u05e2\u05d1\u05e8 \u05d0\u05d7\u05d3, \u05d5\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4."], [266.2, "\u05ea\u05e4\u05e8 \u05e6\u05e8, \u05e2\u05d9\u05d5\u05d5\u05ea \u05e7\u05d8\u05df, \u05d5\u05d7\u05d6\u05e8\u05ea\u05d9\u05d5\u05ea \u05de\u05e6\u05d5\u05d9\u05e0\u05ea \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e1\u05d3\u05e8\u05ea\u05d9."], [271.3, "\u05d5\u05d1\u05de\u05d9\u05e7\u05e8\u05d5 \u05e4\u05dc\u05d6\u05de\u05d4: \u05e9\u05dc\u05d9\u05d8\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd."], [275.6, "\u05d4\u05d7\u05e1\u05e8\u05d5\u05e0\u05d5\u05ea: \u05d4\u05e6\u05d9\u05d5\u05d3 \u05d9\u05e7\u05e8 \u05d5\u05de\u05d5\u05e8\u05db\u05d1, \u05d5\u05d4\u05dc\u05e4\u05d9\u05d3 \u05e8\u05d2\u05d9\u05e9 \u05d5\u05d3\u05d5\u05e8\u05e9 \u05ea\u05d7\u05d6\u05d5\u05e7\u05d4."], [281.4, "\u05d4\u05d4\u05ea\u05d0\u05de\u05d4 \u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d7\u05d9\u05d9\u05d1\u05ea \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05ea, \u05db\u05d9 \u05d4\u05e7\u05e9\u05ea \u05e6\u05e8\u05d4 \u05d5\u05dc\u05d0 \u05de\u05db\u05e1\u05d4 \u05de\u05e8\u05d5\u05d5\u05d7\u05d9\u05dd."], [287.9, "\u05d5\u05d7\u05d5\u05e8 \u05de\u05e4\u05ea\u05d7 \u05e2\u05d5\u05d1\u05d3 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05ea\u05e0\u05d5\u05d7\u05d4 \u05e9\u05d8\u05d5\u05d7\u05d4, \u05d5\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e8\u05e7 \u05d1\u05de\u05d9\u05db\u05d5\u05df."], [294.2, "\u05e4\u05d2\u05dd \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9 \u05dc\u05d7\u05d5\u05e8 \u05de\u05e4\u05ea\u05d7 \u05d4\u05d5\u05d0 \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05d5\u05de\u05e0\u05d4\u05e8\u05d5\u05ea, \u05db\u05e9\u05d4\u05d7\u05d5\u05e8 \u05dc\u05d0 \u05d9\u05e6\u05d9\u05d1."], [299.9, "\u05d1\u05e1\u05d5\u05e3 \u05d4\u05ea\u05e4\u05e8, \u05d1\u05dc\u05d9 \u05d9\u05e8\u05d9\u05d3\u05d4 \u05d4\u05d3\u05e8\u05d2\u05ea\u05d9\u05ea, \u05e0\u05e9\u05d0\u05e8 \u05d7\u05d5\u05e8 \u05d0\u05d5 \u05de\u05db\u05ea\u05e9 \u05e9\u05dc\u05d0 \u05e0\u05e1\u05d2\u05e8."], [306.1, "\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d3\u05d9 \u05d2\u05d5\u05e8\u05de\u05ea \u05dc\u05d7\u05e8\u05d9\u05e6\u05d9\u05dd \u05d1\u05e9\u05d5\u05dc\u05d9 \u05d4\u05ea\u05e4\u05e8."], [310.1, "\u05de\u05e8\u05d5\u05d5\u05d7 \u05d0\u05d5 \u05d4\u05e1\u05d8\u05d4 \u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05dc\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da, \u05db\u05d9 \u05d4\u05e7\u05e9\u05ea \u05e4\u05e9\u05d5\u05d8 \u05de\u05e4\u05e1\u05e4\u05e1\u05ea."], [316.5, "\u05d5\u05d9\u05e9 \u05e4\u05d2\u05dd \u05e9\u05e4\u05d5\u05d2\u05e2 \u05d1\u05e6\u05d9\u05d5\u05d3: \u05e7\u05e9\u05ea \u05db\u05e4\u05d5\u05dc\u05d4, \u05db\u05e9\u05d4\u05e7\u05e9\u05ea \u05e7\u05d5\u05e4\u05e6\u05ea \u05d2\u05dd \u05dc\u05e4\u05d9\u05d9\u05d4 \u05d5\u05e9\u05d5\u05e8\u05e4\u05ea \u05d0\u05d5\u05ea\u05d4."], [323.3, "\u05d4\u05d9\u05d0 \u05e0\u05d2\u05e8\u05de\u05ea \u05de\u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05dc\u05e4\u05ea\u05d7, \u05de\u05d2\u05d6 \u05e4\u05dc\u05d6\u05de\u05d4 \u05de\u05d5\u05e2\u05d8, \u05d0\u05d5 \u05de\u05e4\u05d9\u05d9\u05d4 \u05e9\u05e0\u05d2\u05e2\u05d4 \u05d1\u05d7\u05dc\u05e7."], [330.1, "\u05e8\u05d5\u05d1 \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05e0\u05de\u05e0\u05e2\u05d9\u05dd \u05d1\u05d4\u05db\u05e0\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea, \u05d1\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05d1\u05d3\u05d5\u05e7\u05d9\u05dd \u05d5\u05d1\u05e4\u05d9\u05d9\u05d4 \u05ea\u05e7\u05d9\u05e0\u05d4."], [336.6, "\u05de\u05db\u05d5\u05e0\u05ea \u05e4\u05dc\u05d6\u05de\u05d4 \u05e2\u05d5\u05dc\u05d4 \u05d1\u05e2\u05e8\u05da \u05e4\u05d9 \u05e9\u05e0\u05d9\u05d9\u05dd \u05e2\u05d3 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05de\u05de\u05db\u05d5\u05e0\u05ea TIG."], [341.4, "\u05e4\u05d9\u05d5\u05ea, \u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d5\u05d2\u05d6 \u05d4\u05dd \u05d4\u05d5\u05e6\u05d0\u05d4 \u05e9\u05d5\u05d8\u05e4\u05ea, \u05d5\u05d4\u05e4\u05d9\u05d9\u05d4 \u05e0\u05e9\u05d7\u05e7\u05ea \u05e2\u05dd \u05d4\u05d6\u05de\u05df."], [347.5, "\u05d0\u05d1\u05dc \u05d1\u05e2\u05d1\u05d5\u05d3\u05d4 \u05e1\u05d3\u05e8\u05ea\u05d9\u05ea, \u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05de\u05d7\u05d6\u05d9\u05e8\u05d4 \u05d0\u05ea \u05d4\u05d4\u05e9\u05e7\u05e2\u05d4."], [351.5, "\u05de\u05e2\u05d1\u05e8 \u05d0\u05d7\u05d3 \u05d1\u05de\u05e7\u05d5\u05dd \u05db\u05de\u05d4 \u05de\u05e2\u05d1\u05e8\u05d9\u05dd, \u05d1\u05dc\u05d9 \u05d4\u05db\u05e0\u05ea \u05e9\u05e4\u05d5\u05ea \u05d5\u05d1\u05dc\u05d9 \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9."], [357.1, "\u05e4\u05d7\u05d5\u05ea \u05e2\u05d9\u05d5\u05d5\u05ea, \u05db\u05dc\u05d5\u05de\u05e8 \u05e4\u05d7\u05d5\u05ea \u05d9\u05d9\u05e9\u05d5\u05e8 \u05d5\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [361.8, "\u05d0\u05d1\u05dc \u05dc\u05ea\u05d9\u05e7\u05d5\u05df \u05d1\u05d5\u05d3\u05d3 \u05d0\u05d5 \u05dc\u05e2\u05d1\u05d5\u05d3\u05ea \u05d9\u05d3, TIG \u05e2\u05d3\u05d9\u05d9\u05df \u05d6\u05d5\u05dc \u05d5\u05e4\u05e9\u05d5\u05d8 \u05d9\u05d5\u05ea\u05e8."], [367.3, "\u05d5\u05dc\u05db\u05df \u05e4\u05dc\u05d6\u05de\u05d4 \u05de\u05e9\u05ea\u05dc\u05de\u05ea \u05db\u05e9\u05d9\u05e9 \u05d4\u05e8\u05d1\u05d4 \u05ea\u05e4\u05e8\u05d9\u05dd \u05d6\u05d4\u05d9\u05dd \u05d5\u05d0\u05e8\u05d5\u05db\u05d9\u05dd, \u05d1\u05d0\u05dc-\u05d7\u05dc\u05d3 \u05d0\u05d5 \u05d1\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd."], [374.9, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05e4\u05dc\u05d6\u05de\u05d4 \u05d4\u05d9\u05d0 TIG \u05e2\u05dd \u05e7\u05e9\u05ea \u05d3\u05d7\u05d5\u05e1\u05d4, \u05de\u05e8\u05d5\u05db\u05d6\u05ea \u05d5\u05d7\u05de\u05d4."], [380.5, "\u05de\u05d9\u05e7\u05e8\u05d5 \u05e4\u05dc\u05d6\u05de\u05d4 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd, \u05d5\u05d7\u05d5\u05e8 \u05de\u05e4\u05ea\u05d7 \u05dc\u05d7\u05d3\u05d9\u05e8\u05d4 \u05de\u05dc\u05d0\u05d4 \u05d1\u05de\u05e2\u05d1\u05e8 \u05d0\u05d7\u05d3."], [386.2, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e8\u05d9\u05ea\u05d5\u05da \u05ea\u05ea \u05d0\u05d1\u05e7\u05ea\u05d9, \u05ea\u05d4\u05dc\u05d9\u05da 12, \u05d0\u05dc\u05d5\u05e3 \u05d4\u05ea\u05e4\u05d5\u05e7\u05d4 \u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd."]]};
window.MH_TR["ch09"]={"t": "\u05e8\u05d9\u05ea\u05d5\u05da \u05ea\u05ea-\u05d0\u05d1\u05e7\u05ea\u05d9", "l": [[3.0, "\u05e8\u05d9\u05ea\u05d5\u05da \u05ea\u05ea \u05d0\u05d1\u05e7\u05ea\u05d9, \u05ea\u05d4\u05dc\u05d9\u05da 12, \u05d4\u05d5\u05d0 \u05d0\u05dc\u05d5\u05e3 \u05d4\u05ea\u05e4\u05d5\u05e7\u05d4 \u05e9\u05dc \u05e2\u05d5\u05dc\u05dd \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd \u05d5\u05d1\u05ea\u05e4\u05e8\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd."], [11.4, "\u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05d5 SAW, \u05d5\u05d4\u05d5\u05d0 \u05db\u05de\u05e2\u05d8 \u05ea\u05de\u05d9\u05d3 \u05de\u05de\u05d5\u05db\u05df."], [15.7, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df, \u05d0\u05ea \u05d4\u05d0\u05d1\u05e7\u05d4 \u05d5\u05d4\u05d7\u05d5\u05d8, \u05d0\u05ea \u05d4\u05e6\u05d9\u05d5\u05d3, \u05d0\u05ea \u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd, \u05d0\u05ea \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."], [25.1, "\u05d7\u05d5\u05d8 \u05e8\u05e6\u05d9\u05e3 \u05de\u05d5\u05d6\u05df \u05d0\u05dc \u05d4\u05ea\u05e4\u05e8, \u05d1\u05d3\u05d9\u05d5\u05e7 \u05db\u05de\u05d5 \u05d1-MIG/MAG."], [29.0, "\u05d0\u05d1\u05dc \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e7\u05e9\u05ea, \u05de\u05db\u05e1\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8 \u05d1\u05e2\u05e8\u05d9\u05de\u05d4 \u05e9\u05dc \u05d0\u05d1\u05e7\u05d4 \u05d2\u05e8\u05d2\u05e8\u05d9\u05ea."], [34.1, "\u05d4\u05e7\u05e9\u05ea \u05d1\u05d5\u05e2\u05e8\u05ea \u05de\u05ea\u05d7\u05ea \u05dc\u05d0\u05d1\u05e7\u05d4, \u05d5\u05dc\u05db\u05df \u05dc\u05d0 \u05e8\u05d5\u05d0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05db\u05dc\u05dc."], [38.7, "\u05d0\u05d9\u05df \u05d4\u05d1\u05d6\u05e7, \u05db\u05de\u05e2\u05d8 \u05d0\u05d9\u05df \u05d0\u05d3\u05d9\u05dd \u05d5\u05d0\u05d9\u05df spatter."], [42.5, "\u05d1\u05d2\u05dc\u05dc \u05e9\u05d4\u05e7\u05e9\u05ea \u05de\u05d5\u05e1\u05ea\u05e8\u05ea, \u05d0\u05d9\u05df \u05e6\u05d5\u05e8\u05da \u05d1\u05de\u05e1\u05db\u05d4 \u05db\u05d4\u05d4; \u05de\u05e1\u05e4\u05d9\u05e7\u05d9\u05dd \u05de\u05e9\u05e7\u05e4\u05d9 \u05de\u05d2\u05df."], [48.1, "\u05d7\u05dc\u05e7 \u05de\u05d4\u05d0\u05d1\u05e7\u05d4 \u05e0\u05de\u05e1, \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e9\u05db\u05d1\u05ea slag \u05e9\u05de\u05d2\u05d9\u05e0\u05d4 \u05e2\u05dc \u05d4\u05d0\u05de\u05d1\u05d8 \u05d5\u05e2\u05dc \u05d4\u05ea\u05e4\u05e8 \u05d1\u05d6\u05de\u05df \u05d4\u05d4\u05ea\u05e7\u05e8\u05e8\u05d5\u05ea."], [55.2, "\u05d4\u05d0\u05d1\u05e7\u05d4 \u05e9\u05dc\u05d0 \u05e0\u05de\u05e1\u05d4 \u05e0\u05e9\u05d0\u05d1\u05ea \u05d7\u05d6\u05e8\u05d4, \u05d5\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4 \u05e9\u05d5\u05d1."], [59.7, "\u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05e2\u05d5\u05d1\u05d3 \u05d1\u05d6\u05e8\u05de\u05d9\u05dd \u05d2\u05d1\u05d5\u05d4\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05de\u05db\u05de\u05d4 \u05de\u05d0\u05d5\u05ea \u05d5\u05e2\u05d3 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d0\u05dc\u05e3 \u05d0\u05de\u05e4\u05e8 \u05d1\u05d7\u05d5\u05d8 \u05d0\u05d7\u05d3."], [66.1, "\u05d5\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4: \u05d7\u05d3\u05d9\u05e8\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4, \u05ea\u05e4\u05e8 \u05d7\u05dc\u05e7 \u05d5\u05d0\u05d7\u05d9\u05d3, \u05d5-slag \u05e9\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05de\u05ea\u05e7\u05dc\u05e3 \u05de\u05e2\u05e6\u05de\u05d5."], [74.0, "\u05d4\u05d0\u05d1\u05e7\u05d4 \u05d4\u05d9\u05d0 \u05d7\u05e6\u05d9 \u05de\u05d4\u05ea\u05d4\u05dc\u05d9\u05da."], [76.6, "\u05d9\u05e9 \u05d0\u05d1\u05e7\u05d4 \u05de\u05d5\u05ea\u05db\u05ea, \u05e9\u05d4\u05d5\u05ea\u05db\u05d4 \u05d5\u05e0\u05d8\u05d7\u05e0\u05d4, \u05d5\u05d9\u05e9 \u05d0\u05d1\u05e7\u05d4 \u05de\u05d2\u05d5\u05d1\u05e9\u05ea, \u05e9\u05d2\u05e8\u05d2\u05e8\u05d9\u05d4 \u05d4\u05d5\u05d3\u05d1\u05e7\u05d5 \u05d9\u05d7\u05d3."], [83.9, "\u05dc\u05d0\u05d1\u05e7\u05d4 \u05de\u05d2\u05d5\u05d1\u05e9\u05ea \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea, \u05d5\u05dc\u05db\u05df \u05d4\u05d9\u05d0 \u05e0\u05e4\u05d5\u05e6\u05d4 \u05de\u05d0\u05d5\u05d3."], [89.5, "\u05d0\u05d1\u05e7\u05d4 \u05d1\u05e1\u05d9\u05e1\u05d9\u05ea \u05e0\u05d5\u05ea\u05e0\u05ea \u05d7\u05d5\u05d6\u05e7 \u05d8\u05d5\u05d1 \u05d1\u05d4\u05dc\u05dd \u05d5\u05d1\u05e7\u05d5\u05e8; \u05d0\u05d1\u05e7\u05d4 \u05d7\u05d5\u05de\u05e6\u05d9\u05ea \u05e0\u05d5\u05ea\u05e0\u05ea \u05ea\u05e4\u05e8 \u05d9\u05e4\u05d4 \u05d5\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4."], [97.4, "\u05d4\u05d0\u05d1\u05e7\u05d4 \u05e1\u05d5\u05e4\u05d2\u05ea \u05dc\u05d7\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05d9\u05d9\u05d1\u05e9\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d5\u05e9\u05d5\u05de\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d9\u05d1\u05e9\u05d4, \u05d1\u05d3\u05d9\u05d5\u05e7 \u05db\u05de\u05d5 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05d1\u05e1\u05d9\u05e1\u05d9\u05d5\u05ea."], [104.9, "\u05d0\u05d1\u05e7\u05d4 \u05dc\u05d7\u05d4 \u05de\u05db\u05e0\u05d9\u05e1\u05d4 \u05de\u05d9\u05de\u05df \u05dc\u05ea\u05e4\u05e8, \u05d5\u05de\u05e9\u05dd \u05d4\u05d3\u05e8\u05da \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd \u05e7\u05e6\u05e8\u05d4."], [110.3, "\u05d4\u05d7\u05d5\u05d8 \u05d5\u05d4\u05d0\u05d1\u05e7\u05d4 \u05e0\u05d1\u05d7\u05e8\u05d9\u05dd \u05d5\u05de\u05e1\u05d5\u05d5\u05d2\u05d9\u05dd \u05d9\u05d7\u05d3, \u05db\u05e6\u05de\u05d3, \u05db\u05d9 \u05e9\u05e0\u05d9\u05d4\u05dd \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05d0\u05ea \u05d4\u05e8\u05db\u05d1 \u05d4\u05ea\u05e4\u05e8."], [118.1, "\u05d1\u05e2\u05e8\u05da, \u05e2\u05dc \u05db\u05dc \u05e7\u05d9\u05dc\u05d5\u05d2\u05e8\u05dd \u05d7\u05d5\u05d8 \u05e6\u05d5\u05e8\u05db\u05d9\u05dd \u05db\u05e7\u05d9\u05dc\u05d5\u05d2\u05e8\u05dd \u05d0\u05d1\u05e7\u05d4."], [123.2, "\u05e8\u05d0\u05e9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e2 \u05e2\u05dc \u05e2\u05d2\u05dc\u05d4 \u05dc\u05d0\u05d5\u05e8\u05da \u05de\u05e1\u05d9\u05dc\u05d4, \u05d0\u05d5 \u05e2\u05dc \u05d6\u05e8\u05d5\u05e2 \u05e9\u05e0\u05e2\u05d4 \u05de\u05e2\u05dc \u05d4\u05d7\u05dc\u05e7."], [128.9, "\u05d1\u05ea\u05e4\u05e8\u05d9\u05dd \u05d4\u05d9\u05e7\u05e4\u05d9\u05d9\u05dd, \u05d4\u05d7\u05dc\u05e7 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05e2\u05dc \u05d2\u05dc\u05d2\u05dc\u05d5\u05ea, \u05d5\u05d4\u05e8\u05d0\u05e9 \u05e2\u05d5\u05de\u05d3 \u05d1\u05de\u05e7\u05d5\u05dd."], [134.3, "\u05e2\u05dc \u05e8\u05d0\u05e9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d9\u05e9 \u05de\u05d6\u05d9\u05df \u05d7\u05d5\u05d8, \u05e6\u05d9\u05e0\u05d5\u05e8\u05d9\u05ea \u05de\u05d2\u05e2, \u05d5\u05de\u05e9\u05e4\u05da \u05e9\u05de\u05e4\u05d6\u05e8 \u05d0\u05ea \u05d4\u05d0\u05d1\u05e7\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e7\u05e9\u05ea."], [141.4, "\u05de\u05e7\u05d5\u05e8 \u05d4\u05d4\u05e1\u05e4\u05e7 \u05d9\u05db\u05d5\u05dc \u05dc\u05e2\u05d1\u05d5\u05d3 \u05d1\u05d6\u05e8\u05dd \u05d9\u05e9\u05e8 \u05d0\u05d5 \u05d1\u05d6\u05e8\u05dd \u05d7\u05d9\u05dc\u05d5\u05e4\u05d9\u05df."], [146.2, "\u05db\u05d3\u05d9 \u05dc\u05d4\u05e2\u05dc\u05d5\u05ea \u05d0\u05ea \u05d4\u05ea\u05e4\u05d5\u05e7\u05d4, \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d1\u05db\u05de\u05d4 \u05d7\u05d5\u05d8\u05d9\u05dd \u05d0\u05d7\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e9\u05e0\u05d9, \u05d1\u05d0\u05d5\u05ea\u05d5 \u05d0\u05de\u05d1\u05d8."], [151.9, "\u05d0\u05d5 \u05d1\u05e9\u05e0\u05d9 \u05d7\u05d5\u05d8\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05d9\u05d7\u05d3, \u05d3\u05e8\u05da \u05d0\u05d5\u05ea\u05d4 \u05e6\u05d9\u05e0\u05d5\u05e8\u05d9\u05ea \u05de\u05d2\u05e2."], [156.0, "\u05d5\u05d1\u05de\u05e7\u05d5\u05dd \u05d7\u05d5\u05d8 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05ea\u05da \u05e2\u05dd \u05e1\u05e8\u05d8 \u05e8\u05d7\u05d1, \u05db\u05d3\u05d9 \u05dc\u05e6\u05e4\u05d5\u05ea \u05e9\u05d8\u05d7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd, \u05dc\u05de\u05e9\u05dc \u05d3\u05d5\u05e4\u05df \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05e9\u05dc \u05de\u05db\u05dc \u05dc\u05d7\u05e5."], [165.3, "\u05d5\u05dc\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd \u05de\u05d0\u05d5\u05d3 \u05d9\u05e9 \u05d2\u05dd \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05de\u05e8\u05d5\u05d5\u05d7 \u05e6\u05e8, \u05e9\u05d7\u05d5\u05e1\u05da \u05d4\u05e8\u05d1\u05d4 \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9."], [171.7, "\u05d4\u05d6\u05e8\u05dd \u05e7\u05d5\u05d1\u05e2 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d0\u05ea \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4."], [174.5, "\u05d4\u05de\u05ea\u05d7 \u05e7\u05d5\u05d1\u05e2 \u05d0\u05ea \u05e8\u05d5\u05d7\u05d1 \u05d4\u05ea\u05e4\u05e8, \u05d5\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d4\u05ea\u05e7\u05d3\u05de\u05d5\u05ea \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05ea \u05d2\u05d5\u05d3\u05dc\u05d5."], [179.9, "\u05e7\u05d5\u05d8\u05e8\u05d9 \u05d4\u05d7\u05d5\u05d8 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d9\u05dd \u05d4\u05dd 2.4, 3.2 \u05d5-4 \u05de\"\u05de."], [186.4, "\u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05d5\u05d8 \u05d4\u05d7\u05d5\u05e4\u05e9\u05d9 \u05d0\u05e8\u05d5\u05da \u05d9\u05d7\u05e1\u05d9\u05ea, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc 25 \u05e2\u05d3 35 \u05de\"\u05de."], [193.0, "\u05d2\u05d5\u05d1\u05d4 \u05e9\u05db\u05d1\u05ea \u05d4\u05d0\u05d1\u05e7\u05d4 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05d3\u05d9\u05d5\u05e7 \u05de\u05e1\u05e4\u05d9\u05e7 \u05db\u05d3\u05d9 \u05dc\u05db\u05e1\u05d5\u05ea \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea."], [198.3, "\u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05de\u05d3\u05d9 \u05d2\u05d5\u05e8\u05de\u05ea \u05dc\u05d4\u05d1\u05d6\u05e7\u05d9\u05dd \u05d5\u05dc\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea. \u05e9\u05db\u05d1\u05d4 \u05e2\u05d1\u05d4 \u05de\u05d3\u05d9 \u05e4\u05d5\u05d2\u05e2\u05ea \u05d1\u05e6\u05d5\u05e8\u05ea \u05d4\u05ea\u05e4\u05e8."], [205.9, "\u05d4\u05d0\u05d1\u05e7\u05d4 \u05e0\u05e9\u05e4\u05db\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05e8\u05e7 \u05d1\u05ea\u05e0\u05d5\u05d7\u05d4 \u05e9\u05d8\u05d5\u05d7\u05d4, \u05d0\u05d5 \u05d1\u05ea\u05e4\u05e8 \u05e4\u05d9\u05e0\u05ea\u05d9 \u05d0\u05d5\u05e4\u05e7\u05d9."], [212.2, "\u05d5\u05d1\u05de\u05e2\u05d1\u05e8 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05e6\u05e8\u05d9\u05da \u05d2\u05d9\u05d1\u05d5\u05d9 \u05de\u05ea\u05d7\u05ea \u05dc\u05e9\u05d5\u05e8\u05e9: \u05e4\u05e1 \u05e0\u05d7\u05d5\u05e9\u05ea, \u05de\u05e6\u05e2 \u05d0\u05d1\u05e7\u05d4, \u05d0\u05d5 \u05e9\u05d5\u05e8\u05e9 \u05d1\u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05d7\u05e8."], [220.5, "\u05e8\u05d9\u05ea\u05d5\u05da \u05ea\u05ea \u05d0\u05d1\u05e7\u05ea\u05d9 \u05de\u05e9\u05de\u05e9 \u05d1\u05de\u05db\u05dc\u05d9 \u05dc\u05d7\u05e5, \u05d1\u05e6\u05d9\u05e0\u05d5\u05e8\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd, \u05d1\u05d1\u05e0\u05d9\u05d9\u05ea \u05d0\u05d5\u05e0\u05d9\u05d5\u05ea, \u05d1\u05ea\u05d5\u05e8\u05e0\u05d9 \u05e8\u05d5\u05d7, \u05d1\u05d2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d1\u05e7\u05d5\u05e8\u05d5\u05ea."], [229.8, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05df \u05d4\u05d2\u05d3\u05d5\u05dc: \u05e7\u05e6\u05d1 \u05d4\u05e0\u05d7\u05d4 \u05d2\u05d1\u05d5\u05d4 \u05de\u05d0\u05d5\u05d3, \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e2\u05e9\u05e8\u05d5\u05ea \u05e7\u05d9\u05dc\u05d5\u05d2\u05e8\u05de\u05d9\u05dd \u05dc\u05e9\u05e2\u05d4."], [235.7, "\u05d7\u05d3\u05d9\u05e8\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4, \u05db\u05dc\u05d5\u05de\u05e8 \u05e4\u05d7\u05d5\u05ea \u05de\u05e2\u05d1\u05e8\u05d9\u05dd \u05d5\u05e4\u05d7\u05d5\u05ea \u05d4\u05db\u05e0\u05d4."], [240.3, "\u05dc\u05d5\u05d7 \u05e9\u05dc \u05db\u05d7\u05de\u05d9\u05e9\u05d4 \u05e2\u05e9\u05e8 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05ea\u05da \u05d1\u05e9\u05e0\u05d9 \u05de\u05e2\u05d1\u05e8\u05d9\u05dd \u05d1\u05dc\u05d1\u05d3, \u05d0\u05d7\u05d3 \u05de\u05db\u05dc \u05e6\u05d3."], [246.8, "\u05d0\u05d9\u05db\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d5\u05d0\u05d7\u05d9\u05d3\u05d4, \u05d1\u05dc\u05d9 \u05d4\u05d1\u05d6\u05e7, \u05e2\u05dd \u05de\u05e2\u05d8 \u05d0\u05d3\u05d9\u05dd, \u05d5\u05d1\u05dc\u05d9 \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05e9\u05dc \u05e8\u05ea\u05da."], [253.1, "\u05d4\u05d7\u05e1\u05e8\u05d5\u05e0\u05d5\u05ea: \u05e8\u05e7 \u05ea\u05e0\u05d5\u05d7\u05d4 \u05e9\u05d8\u05d5\u05d7\u05d4 \u05d0\u05d5 \u05ea\u05e4\u05e8 \u05e4\u05d9\u05e0\u05ea\u05d9 \u05d0\u05d5\u05e4\u05e7\u05d9."], [257.7, "\u05d4\u05e6\u05d9\u05d5\u05d3 \u05db\u05d1\u05d3 \u05d5\u05d9\u05e7\u05e8, \u05d5\u05de\u05e9\u05ea\u05dc\u05dd \u05e8\u05e7 \u05d1\u05ea\u05e4\u05e8\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd \u05d5\u05d9\u05e9\u05e8\u05d9\u05dd \u05d0\u05d5 \u05d4\u05d9\u05e7\u05e4\u05d9\u05d9\u05dd."], [263.7, "\u05dc\u05d0 \u05e8\u05d5\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05db\u05d9\u05d5\u05d5\u05df \u05de\u05d3\u05d5\u05d9\u05e7 \u05e9\u05dc \u05d4\u05e8\u05d0\u05e9 \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05ea\u05e4\u05e8."], [269.5, "\u05d5\u05d4\u05d7\u05d5\u05dd \u05d4\u05d2\u05d1\u05d5\u05d4 \u05e2\u05dc\u05d5\u05dc \u05dc\u05e4\u05d2\u05d5\u05e2 \u05d1\u05d7\u05d5\u05d6\u05e7 \u05d1\u05d4\u05dc\u05dd \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05de\u05d5\u05e9\u05e4\u05e2 \u05d7\u05d5\u05dd, \u05d1\u05d7\u05dc\u05e7 \u05de\u05d4\u05e4\u05dc\u05d3\u05d5\u05ea."], [276.4, "\u05e4\u05d2\u05dd \u05e7\u05dc\u05d0\u05e1\u05d9 \u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05ea\u05ea \u05d0\u05d1\u05e7\u05ea\u05d9 \u05d4\u05d5\u05d0 \u05e1\u05d3\u05e7 \u05d4\u05ea\u05de\u05e6\u05e7\u05d5\u05ea \u05d1\u05de\u05e8\u05db\u05d6 \u05d4\u05ea\u05e4\u05e8."], [281.7, "\u05d4\u05d5\u05d0 \u05de\u05d5\u05e4\u05d9\u05e2 \u05db\u05e9\u05d4\u05ea\u05e4\u05e8 \u05e2\u05de\u05d5\u05e7 \u05d5\u05e6\u05e8 \u05de\u05d3\u05d9, \u05d5\u05d4\u05de\u05ea\u05db\u05ea \u05de\u05ea\u05de\u05e6\u05e7\u05ea \u05de\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd \u05d5\u05e0\u05e1\u05d3\u05e7\u05ea \u05d1\u05d0\u05de\u05e6\u05e2."], [289.0, "\u05d4\u05d5\u05d0 \u05e0\u05de\u05e0\u05e2 \u05db\u05e9\u05d4\u05ea\u05e4\u05e8 \u05e8\u05d7\u05d1 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e2\u05d5\u05de\u05e7\u05d5: \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05de\u05e2\u05d8 \u05d6\u05e8\u05dd, \u05d0\u05d5 \u05de\u05e2\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05ea\u05d7."], [295.8, "\u05e9\u05d0\u05e8\u05d9\u05d5\u05ea slag \u05d1\u05d9\u05df \u05e9\u05db\u05d1\u05d5\u05ea \u05de\u05d5\u05e4\u05d9\u05e2\u05d5\u05ea \u05db\u05e9\u05dc\u05d0 \u05de\u05e0\u05e7\u05d9\u05dd \u05d4\u05d9\u05d8\u05d1, \u05d0\u05d5 \u05db\u05e9\u05d9\u05e9 \u05d7\u05e8\u05d9\u05e6\u05d9\u05dd \u05d1\u05e9\u05d5\u05dc\u05d9 \u05d4\u05ea\u05e4\u05e8."], [303.7, "\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05e0\u05d2\u05e8\u05de\u05d5\u05ea \u05de\u05d0\u05d1\u05e7\u05d4 \u05dc\u05d7\u05d4, \u05de\u05d7\u05dc\u05d5\u05d3\u05d4 \u05d5\u05de\u05e9\u05de\u05df, \u05d0\u05d5 \u05de\u05db\u05d9\u05e1\u05d5\u05d9 \u05d0\u05d1\u05e7\u05d4 \u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7."], [310.0, "\u05d1\u05dc\u05d9 \u05d2\u05d9\u05d1\u05d5\u05d9, \u05d4\u05d6\u05e8\u05dd \u05d4\u05d2\u05d1\u05d5\u05d4 \u05e4\u05e9\u05d5\u05d8 \u05e9\u05d5\u05e8\u05e3 \u05d0\u05ea \u05d4\u05e9\u05d5\u05e8\u05e9."], [314.3, "\u05d5\u05e1\u05d8\u05d9\u05d9\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d5\u05d8 \u05de\u05e7\u05d5 \u05d4\u05ea\u05e4\u05e8 \u05d2\u05d5\u05e8\u05de\u05ea \u05dc\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da. \u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05e2\u05e7\u05d1 \u05ea\u05e4\u05e8."], [321.2, "\u05d5\u05d1\u05d6\u05e8\u05dd \u05d9\u05e9\u05e8, \u05e9\u05d3\u05d4 \u05de\u05d2\u05e0\u05d8\u05d9 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05e1\u05d9\u05d8 \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea. \u05dc\u05db\u05df \u05d1\u05d7\u05d5\u05d8\u05d9\u05dd \u05de\u05e8\u05d5\u05d1\u05d9\u05dd \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d2\u05dd \u05d1\u05d6\u05e8\u05dd \u05d7\u05d9\u05dc\u05d5\u05e4\u05d9\u05df."], [330.3, "\u05d4\u05e6\u05d9\u05d5\u05d3 \u05d9\u05e7\u05e8: \u05e8\u05d0\u05e9 \u05e8\u05d9\u05ea\u05d5\u05da, \u05e2\u05d2\u05dc\u05d4 \u05d0\u05d5 \u05d6\u05e8\u05d5\u05e2, \u05d2\u05dc\u05d2\u05dc\u05d5\u05ea, \u05d5\u05de\u05e2\u05e8\u05db\u05ea \u05dc\u05e9\u05d0\u05d9\u05d1\u05ea \u05d0\u05d1\u05e7\u05d4."], [337.4, "\u05d2\u05dd \u05d4\u05db\u05e0\u05d4, \u05db\u05d9\u05d5\u05d5\u05df \u05d5\u05e7\u05d9\u05d1\u05d5\u05e2 \u05dc\u05d5\u05e7\u05d7\u05d9\u05dd \u05d6\u05de\u05df, \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05e7\u05e9\u05ea \u05e0\u05d3\u05dc\u05e7\u05ea."], [342.6, "\u05d0\u05d1\u05dc \u05db\u05e9\u05d4\u05d9\u05d0 \u05e0\u05d3\u05dc\u05e7\u05ea, \u05d4\u05d9\u05d0 \u05e2\u05d5\u05d1\u05d3\u05ea \u05d4\u05e8\u05d1\u05d4 \u05d6\u05de\u05df: \u05d6\u05de\u05df \u05d4\u05e7\u05e9\u05ea \u05d2\u05d1\u05d5\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d5\u05e7\u05e6\u05d1 \u05d4\u05d4\u05e0\u05d7\u05d4 \u05e2\u05e6\u05d5\u05dd."], [350.1, "\u05d4\u05d0\u05d1\u05e7\u05d4 \u05e2\u05d5\u05dc\u05d4 \u05db\u05e1\u05e3, \u05d0\u05d1\u05dc \u05d7\u05dc\u05e7 \u05d2\u05d3\u05d5\u05dc \u05de\u05de\u05e0\u05d4 \u05de\u05de\u05d5\u05d7\u05d6\u05e8."], [354.3, "\u05d4\u05d7\u05d5\u05d8 \u05d5\u05d4\u05d0\u05d1\u05e7\u05d4 \u05d4\u05dd \u05e8\u05e7 \u05d7\u05dc\u05e7 \u05e7\u05d8\u05df \u05de\u05d4\u05e2\u05dc\u05d5\u05ea. \u05d2\u05dd \u05db\u05d0\u05df, \u05d4\u05d6\u05de\u05df \u05d4\u05d5\u05d0 \u05d4\u05db\u05e1\u05e3."], [360.8, "\u05d1\u05ea\u05e4\u05e8\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd \u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd, \u05d4\u05d5\u05d0 \u05dc\u05e8\u05d5\u05d1 \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05d6\u05d5\u05dc \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05db\u05dc \u05de\u05d8\u05e8 \u05ea\u05e4\u05e8."], [367.1, "\u05d5\u05d1\u05e2\u05d1\u05d5\u05d3\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea, \u05e7\u05e6\u05e8\u05d5\u05ea \u05d0\u05d5 \u05d1\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea, \u05d4\u05d5\u05d0 \u05e4\u05e9\u05d5\u05d8 \u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05dd."], [372.9, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05ea\u05ea \u05d0\u05d1\u05e7\u05ea\u05d9 \u05d4\u05e7\u05e9\u05ea \u05d1\u05d5\u05e2\u05e8\u05ea \u05de\u05ea\u05d7\u05ea \u05dc\u05d0\u05d1\u05e7\u05d4, \u05d1\u05d6\u05e8\u05de\u05d9\u05dd \u05d2\u05d1\u05d5\u05d4\u05d9\u05dd \u05de\u05d0\u05d5\u05d3."], [380.0, "\u05ea\u05e4\u05d5\u05e7\u05d4 \u05d5\u05d0\u05d9\u05db\u05d5\u05ea \u05de\u05e2\u05d5\u05dc\u05d5\u05ea, \u05d0\u05d1\u05dc \u05e8\u05e7 \u05de\u05de\u05d5\u05db\u05df, \u05d5\u05e8\u05e7 \u05d1\u05ea\u05e0\u05d5\u05d7\u05d4 \u05e9\u05d8\u05d5\u05d7\u05d4."], [385.3, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea, \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd 21, 22 \u05d5-23: \u05e0\u05e7\u05d5\u05d3\u05d4, \u05ea\u05e4\u05e8 \u05d5\u05d1\u05dc\u05d9\u05d8\u05d5\u05ea."]]};
window.MH_TR["ch10"]={"t": "\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea", "l": [[3.0, "\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea, \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd 21, 22 \u05d5-23, \u05de\u05e8\u05ea\u05da \u05d1\u05dc\u05d9 \u05e7\u05e9\u05ea, \u05d1\u05dc\u05d9 \u05d2\u05d6 \u05d5\u05d1\u05dc\u05d9 \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9: \u05e8\u05e7 \u05d6\u05e8\u05dd, \u05dc\u05d7\u05e5 \u05d5\u05d6\u05de\u05df."], [15.1, "\u05d6\u05d5 \u05d4\u05e9\u05d9\u05d8\u05d4 \u05e9\u05de\u05d7\u05d6\u05d9\u05e7\u05d4 \u05d0\u05ea \u05e8\u05d5\u05d1 \u05d2\u05d5\u05e4\u05d9 \u05d4\u05de\u05db\u05d5\u05e0\u05d9\u05d5\u05ea \u05d1\u05e2\u05d5\u05dc\u05dd."], [18.8, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df, \u05d0\u05ea \u05de\u05d7\u05d6\u05d5\u05e8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d0\u05ea \u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05e0\u05e7\u05d5\u05d3\u05d4, \u05d4\u05ea\u05e4\u05e8 \u05d5\u05d4\u05d1\u05dc\u05d9\u05d8\u05d5\u05ea, \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd, \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."], [29.8, "\u05e9\u05ea\u05d9 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05de\u05e0\u05d7\u05d5\u05e9\u05ea \u05dc\u05d5\u05d7\u05e6\u05d5\u05ea \u05d0\u05ea \u05d4\u05e4\u05d7\u05d9\u05dd \u05d6\u05d4 \u05dc\u05d6\u05d4."], [33.7, "\u05d3\u05e8\u05db\u05df \u05e2\u05d5\u05d1\u05e8 \u05d6\u05e8\u05dd \u05d7\u05d6\u05e7 \u05de\u05d0\u05d5\u05d3, \u05d0\u05dc\u05e4\u05d9 \u05d5\u05e2\u05d3 \u05e2\u05e9\u05e8\u05d5\u05ea \u05d0\u05dc\u05e4\u05d9 \u05d0\u05de\u05e4\u05e8, \u05dc\u05de\u05e9\u05da \u05e9\u05d1\u05e8\u05d9\u05e8 \u05e9\u05e0\u05d9\u05d9\u05d4."], [40.4, "\u05dc\u05db\u05dc \u05de\u05e2\u05d1\u05e8 \u05d6\u05e8\u05dd \u05d9\u05e9 \u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea, \u05d5\u05d4\u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05d7\u05d5\u05dd."], [45.5, "\u05d4\u05d7\u05d5\u05dd \u05ea\u05dc\u05d5\u05d9 \u05d1\u05e8\u05d9\u05d1\u05d5\u05e2 \u05d4\u05d6\u05e8\u05dd: \u05d6\u05e8\u05dd \u05db\u05e4\u05d5\u05dc \u05e0\u05d5\u05ea\u05df \u05d7\u05d5\u05dd \u05e4\u05d9 \u05d0\u05e8\u05d1\u05e2\u05d4."], [50.9, "\u05d4\u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea \u05d4\u05d2\u05d1\u05d5\u05d4\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e0\u05de\u05e6\u05d0\u05ea \u05d1\u05de\u05d2\u05e2 \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05d4\u05e4\u05d7\u05d9\u05dd, \u05d5\u05e9\u05dd \u05d4\u05de\u05ea\u05db\u05ea \u05e0\u05de\u05e1\u05d4 \u05e8\u05d0\u05e9\u05d5\u05e0\u05d4."], [57.8, "\u05e0\u05d5\u05e6\u05e8\u05ea \u05e2\u05d3\u05e9\u05d4 \u05e7\u05d8\u05e0\u05d4 \u05e9\u05dc \u05de\u05ea\u05db\u05ea \u05de\u05d5\u05ea\u05db\u05ea \u05d1\u05d9\u05df \u05d4\u05e4\u05d7\u05d9\u05dd, \u05d5\u05d4\u05d9\u05d0 \u05de\u05ea\u05de\u05e6\u05e7\u05ea \u05dc\u05e0\u05e7\u05d5\u05d3\u05ea \u05e8\u05d9\u05ea\u05d5\u05da."], [64.1, "\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05e2\u05e9\u05d5\u05d9\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05de\u05e7\u05d5\u05e8\u05e8\u05d5\u05ea \u05d1\u05de\u05d9\u05dd, \u05db\u05d3\u05d9 \u05e9\u05d4\u05df \u05e2\u05e6\u05de\u05df \u05dc\u05d0 \u05d9\u05ea\u05d7\u05de\u05de\u05d5 \u05d5\u05dc\u05d0 \u05d9\u05d9\u05e6\u05de\u05d3\u05d5."], [71.0, "\u05d4\u05dc\u05d7\u05e5 \u05e9\u05d5\u05de\u05e8 \u05e2\u05dc \u05de\u05d2\u05e2 \u05d8\u05d5\u05d1, \u05d5\u05de\u05d5\u05e0\u05e2 \u05de\u05d4\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d5\u05ea\u05db\u05ea \u05dc\u05d1\u05e8\u05d5\u05d7 \u05d4\u05d7\u05d5\u05e6\u05d4."], [76.9, "\u05db\u05dc \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e2\u05d5\u05d1\u05e8\u05ea \u05de\u05d7\u05d6\u05d5\u05e8 \u05e7\u05d1\u05d5\u05e2 \u05e9\u05dc \u05d0\u05e8\u05d1\u05e2\u05d4 \u05e9\u05dc\u05d1\u05d9\u05dd."], [80.9, "\u05dc\u05d7\u05d9\u05e6\u05d4: \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05e1\u05d5\u05d2\u05e8\u05d5\u05ea \u05e2\u05dc \u05d4\u05e4\u05d7\u05d9\u05dd \u05d5\u05d1\u05d5\u05e0\u05d5\u05ea \u05db\u05d5\u05d7, \u05e2\u05d5\u05d3 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d6\u05e8\u05dd."], [86.7, "\u05e8\u05d9\u05ea\u05d5\u05da: \u05d4\u05d6\u05e8\u05dd \u05e2\u05d5\u05d1\u05e8, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05e9\u05e0\u05d9\u05d9\u05d4 \u05d1\u05dc\u05d1\u05d3."], [91.9, "\u05d4\u05d7\u05d6\u05e7\u05d4: \u05d4\u05d6\u05e8\u05dd \u05e0\u05e2\u05e6\u05e8, \u05d0\u05d1\u05dc \u05d4\u05dc\u05d7\u05e5 \u05e0\u05e9\u05d0\u05e8 \u05e2\u05d3 \u05e9\u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05de\u05ea\u05de\u05e6\u05e7\u05ea."], [98.1, "\u05e9\u05d7\u05e8\u05d5\u05e8: \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05e0\u05e4\u05ea\u05d7\u05d5\u05ea, \u05d5\u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05dc\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d4\u05d1\u05d0\u05d4."], [102.6, "\u05e9\u05dc\u05d5\u05e9\u05ea \u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd \u05d4\u05dd \u05d6\u05e8\u05dd, \u05d6\u05de\u05df \u05d5\u05db\u05d5\u05d7 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4."], [108.2, "\u05db\u05d5\u05d7 \u05e0\u05de\u05d5\u05da \u05de\u05d3\u05d9 \u05d2\u05d5\u05e8\u05dd \u05dc\u05d4\u05ea\u05d6\u05d4; \u05db\u05d5\u05d7 \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05de\u05e7\u05d8\u05d9\u05df \u05d0\u05ea \u05d4\u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea \u05d1\u05de\u05d2\u05e2, \u05d5\u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d9\u05d5\u05e6\u05d0\u05ea \u05e7\u05d8\u05e0\u05d4."], [115.9, "\u05db\u05dc\u05dc \u05d0\u05e6\u05d1\u05e2 \u05dc\u05e7\u05d5\u05d8\u05e8 \u05d4\u05e0\u05e7\u05d5\u05d3\u05d4: \u05d7\u05de\u05e9 \u05db\u05e4\u05d5\u05dc \u05d4\u05e9\u05d5\u05e8\u05e9 \u05e9\u05dc \u05e2\u05d5\u05d1\u05d9 \u05d4\u05e4\u05d7 \u05d1\u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd."], [122.0, "\u05dc\u05de\u05e9\u05dc, \u05dc\u05e4\u05d7 \u05e9\u05dc \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d0\u05d7\u05d3, \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05e9\u05dc \u05db\u05d7\u05de\u05d9\u05e9\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."], [128.5, "\u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e7\u05d5\u05d3\u05d4, \u05ea\u05d4\u05dc\u05d9\u05da 21, \u05d4\u05d5\u05d0 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8."], [133.3, "\u05d2\u05d5\u05e3 \u05e9\u05dc \u05de\u05db\u05d5\u05e0\u05d9\u05ea \u05d0\u05d7\u05ea \u05de\u05d7\u05d6\u05d9\u05e7 \u05d0\u05dc\u05e4\u05d9 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05e8\u05d5\u05d1\u05df \u05e0\u05e2\u05e9\u05d5\u05ea \u05d1\u05e8\u05d5\u05d1\u05d5\u05d8\u05d9\u05dd."], [139.1, "\u05d1\u05e8\u05d5\u05d1\u05d5\u05d8, \u05de\u05dc\u05e7\u05d7\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05de\u05e6\u05d0\u05d9\u05dd \u05e2\u05dc \u05d4\u05d6\u05e8\u05d5\u05e2, \u05d5\u05d4\u05dd \u05e0\u05e2\u05d9\u05dd \u05de\u05e0\u05e7\u05d5\u05d3\u05d4 \u05dc\u05e0\u05e7\u05d5\u05d3\u05d4."], [144.9, "\u05d1\u05e1\u05d3\u05e0\u05d4 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05db\u05d5\u05e0\u05d4 \u05e2\u05d5\u05de\u05d3\u05ea, \u05e9\u05d1\u05d4 \u05de\u05d1\u05d9\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d0\u05dc \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea."], [150.5, "\u05de\u05e7\u05d5\u05e8\u05d5\u05ea \u05d4\u05d4\u05e1\u05e4\u05e7 \u05d4\u05de\u05d5\u05d3\u05e8\u05e0\u05d9\u05d9\u05dd \u05d4\u05dd \u05de\u05de\u05d9\u05e8\u05d9\u05dd \u05d1\u05ea\u05d3\u05e8 \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9, \u05e9\u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05d6\u05e8\u05dd \u05d9\u05e9\u05e8 \u05de\u05d1\u05d5\u05e7\u05e8 \u05d5\u05de\u05d3\u05d5\u05d9\u05e7."], [157.7, "\u05e7\u05e6\u05d5\u05ea \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05e0\u05e9\u05d7\u05e7\u05d9\u05dd \u05d5\u05de\u05ea\u05e8\u05d7\u05d1\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05de\u05d7\u05d3\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d1\u05d0\u05d5\u05e4\u05df \u05e7\u05d1\u05d5\u05e2."], [164.3, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05ea\u05e4\u05e8, \u05ea\u05d4\u05dc\u05d9\u05da 22, \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05d4\u05df \u05d2\u05dc\u05d2\u05dc\u05d9\u05dd \u05de\u05e1\u05ea\u05d5\u05d1\u05d1\u05d9\u05dd."], [170.2, "\u05d4\u05d6\u05e8\u05dd \u05e2\u05d5\u05d1\u05e8 \u05d1\u05e4\u05d5\u05dc\u05e1\u05d9\u05dd, \u05d5\u05d4\u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d7\u05d5\u05e4\u05e4\u05d5\u05ea \u05d6\u05d5 \u05dc\u05d6\u05d5 \u05d5\u05d9\u05d5\u05e6\u05e8\u05d5\u05ea \u05ea\u05e4\u05e8 \u05e8\u05e6\u05d9\u05e3 \u05d5\u05d0\u05d8\u05d5\u05dd."], [176.6, "\u05db\u05da \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05de\u05db\u05dc\u05d9 \u05d3\u05dc\u05e7, \u05ea\u05d5\u05e4\u05d9\u05dd \u05d5\u05e4\u05d7\u05d9\u05d5\u05ea, \u05e9\u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05ea \u05d0\u05d8\u05d5\u05de\u05d9\u05dd \u05dc\u05e0\u05d5\u05d6\u05dc \u05d5\u05dc\u05d2\u05d6."], [182.9, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05dc\u05d9\u05d8\u05d5\u05ea, \u05ea\u05d4\u05dc\u05d9\u05da 23, \u05de\u05d8\u05d1\u05d9\u05e2\u05d9\u05dd \u05d1\u05dc\u05d9\u05d8\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea \u05d1\u05d0\u05d7\u05d3 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd."], [189.7, "\u05d4\u05d1\u05dc\u05d9\u05d8\u05d5\u05ea \u05de\u05e8\u05db\u05d6\u05d5\u05ea \u05d0\u05ea \u05d4\u05d6\u05e8\u05dd, \u05d5\u05db\u05da \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05ea\u05da \u05db\u05de\u05d4 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea."], [195.6, "\u05db\u05da \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d0\u05d5\u05de\u05d9\u05dd \u05d5\u05d1\u05e8\u05d2\u05d9\u05dd \u05dc\u05e4\u05d7\u05d9\u05dd, \u05d1\u05e4\u05e1 \u05d9\u05d9\u05e6\u05d5\u05e8, \u05d1\u05e9\u05e0\u05d9\u05d9\u05d4 \u05d0\u05d7\u05ea."], [201.0, "\u05d5\u05d9\u05e9 \u05d2\u05dd \u05e8\u05d9\u05ea\u05d5\u05da \u05e8\u05d0\u05e9 \u05d1\u05e8\u05d0\u05e9 \u05d1\u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea, \u05dc\u05d7\u05d9\u05d1\u05d5\u05e8 \u05de\u05d5\u05d8\u05d5\u05ea, \u05e9\u05e8\u05e9\u05e8\u05d0\u05d5\u05ea \u05d5\u05de\u05e1\u05d9\u05dc\u05d5\u05ea \u05e8\u05db\u05d1\u05ea."], [207.3, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d1\u05d6\u05e7, \u05d4\u05e7\u05e6\u05d5\u05d5\u05ea \u05de\u05ea\u05d7\u05de\u05de\u05d9\u05dd \u05d1\u05e0\u05d9\u05e6\u05d5\u05e6\u05d5\u05ea \u05d5\u05d0\u05d6 \u05e0\u05dc\u05d7\u05e6\u05d9\u05dd \u05d1\u05db\u05d5\u05d7, \u05d5\u05d4\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d5\u05ea\u05db\u05ea \u05e0\u05d3\u05d7\u05e7\u05ea \u05d4\u05d7\u05d5\u05e6\u05d4."], [216.0, "\u05e4\u05dc\u05d3\u05d4 \u05d3\u05dc\u05ea \u05e4\u05d7\u05de\u05df \u05d4\u05d9\u05d0 \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05e7\u05dc \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea."], [220.5, "\u05e4\u05d7 \u05de\u05d2\u05d5\u05dc\u05d5\u05d5\u05df \u05d3\u05d5\u05e8\u05e9 \u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d4\u05d0\u05d1\u05e5 \u05e9\u05d5\u05d7\u05e7 \u05d0\u05ea \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05de\u05d4\u05e8."], [226.2, "\u05d0\u05dc-\u05d7\u05dc\u05d3 \u05de\u05ea\u05e8\u05ea\u05da \u05d4\u05d9\u05d8\u05d1, \u05db\u05d9 \u05d4\u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea \u05e9\u05dc\u05d5 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05e4\u05d7\u05d5\u05ea \u05d6\u05e8\u05dd."], [232.0, "\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d4\u05d5\u05d0 \u05d4\u05d0\u05ea\u05d2\u05e8: \u05d4\u05d5\u05d0 \u05de\u05d5\u05dc\u05d9\u05da \u05d8\u05d5\u05d1 \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05d6\u05e8\u05de\u05d9\u05dd \u05e2\u05e6\u05d5\u05de\u05d9\u05dd, \u05d5\u05d4\u05d5\u05d0 \u05e0\u05d3\u05d1\u05e7 \u05dc\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea."], [239.6, "\u05d5\u05e4\u05dc\u05d3\u05d5\u05ea \u05d1\u05d7\u05d5\u05d6\u05e7 \u05d2\u05d1\u05d5\u05d4 \u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05dc\u05d7\u05e5 \u05d2\u05d1\u05d5\u05d4 \u05d5\u05d1\u05e7\u05e8\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea, \u05db\u05d3\u05d9 \u05e9\u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05dc\u05d0 \u05ea\u05d4\u05d9\u05d4 \u05e9\u05d1\u05d9\u05e8\u05d4."], [246.5, "\u05d5\u05d1\u05db\u05dc \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd, \u05d4\u05e4\u05d7\u05d9\u05dd \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05ea \u05e0\u05e7\u05d9\u05d9\u05dd: \u05e9\u05de\u05df, \u05e6\u05d1\u05e2 \u05d5\u05d7\u05dc\u05d5\u05d3\u05d4 \u05de\u05e9\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea \u05d5\u05d0\u05ea \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4."], [255.2, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea: \u05de\u05d4\u05d9\u05e8 \u05de\u05d0\u05d5\u05d3, \u05e9\u05d1\u05e8\u05d9\u05e8 \u05e9\u05e0\u05d9\u05d9\u05d4 \u05dc\u05e0\u05e7\u05d5\u05d3\u05d4."], [259.5, "\u05d1\u05dc\u05d9 \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9, \u05d1\u05dc\u05d9 \u05d2\u05d6 \u05d5\u05d1\u05dc\u05d9 \u05d4\u05db\u05e0\u05ea \u05e9\u05e4\u05d5\u05ea."], [263.6, "\u05e2\u05d9\u05d5\u05d5\u05ea \u05e7\u05d8\u05df, \u05d5\u05d0\u05d5\u05d8\u05d5\u05de\u05e6\u05d9\u05d4 \u05de\u05dc\u05d0\u05d4 \u05d1\u05e7\u05dc\u05d5\u05ea."], [267.2, "\u05d4\u05d7\u05e1\u05e8\u05d5\u05e0\u05d5\u05ea: \u05e8\u05e7 \u05d7\u05d9\u05d1\u05d5\u05e8 \u05d7\u05e4\u05d9\u05e4\u05d4, \u05e9\u05de\u05d5\u05e1\u05d9\u05e3 \u05de\u05e9\u05e7\u05dc \u05d5\u05d7\u05d5\u05de\u05e8."], [272.0, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e6\u05e8\u05d9\u05da \u05d2\u05d9\u05e9\u05d4 \u05de\u05e9\u05e0\u05d9 \u05e6\u05d3\u05d9 \u05d4\u05d7\u05dc\u05e7."], [276.2, "\u05d4\u05e2\u05d5\u05d1\u05d9 \u05de\u05d5\u05d2\u05d1\u05dc, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05e4\u05d7\u05d9\u05dd \u05e9\u05dc \u05db\u05de\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd."], [280.4, "\u05d5\u05e7\u05e9\u05d4 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d0\u05ea \u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d1\u05dc\u05d9 \u05dc\u05d4\u05e8\u05d5\u05e1 \u05d0\u05d5\u05ea\u05d4."], [284.1, "\u05d4\u05e4\u05d2\u05dd \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d4\u05d5\u05d0 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e7\u05d8\u05e0\u05d4 \u05de\u05d3\u05d9, \u05d0\u05d5 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d3\u05d1\u05d5\u05e7\u05d4 \u05e9\u05dc\u05d0 \u05e0\u05de\u05e1\u05d4 \u05d1\u05db\u05dc\u05dc."], [289.8, "\u05d4\u05d5\u05d0 \u05e0\u05d2\u05e8\u05dd \u05de\u05d6\u05e8\u05dd \u05e0\u05de\u05d5\u05da, \u05de\u05d6\u05de\u05df \u05e7\u05e6\u05e8, \u05d0\u05d5 \u05de\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05e9\u05d7\u05d5\u05e7\u05d5\u05ea."], [294.8, "\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05e9\u05d4\u05ea\u05e8\u05d7\u05d1\u05d4 \u05de\u05e4\u05d6\u05e8\u05ea \u05d0\u05ea \u05d4\u05d6\u05e8\u05dd \u05e2\u05dc \u05e9\u05d8\u05d7 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05e7\u05d8\u05e0\u05d4. \u05dc\u05db\u05df \u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05de\u05d2\u05d3\u05d9\u05dc\u05d5\u05ea \u05d0\u05ea \u05d4\u05d6\u05e8\u05dd \u05d1\u05d4\u05d3\u05e8\u05d2\u05d4 \u05dc\u05d0\u05d5\u05e8\u05da \u05d7\u05d9\u05d9 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4."], [305.7, "\u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9, \u05d0\u05d5 \u05db\u05d5\u05d7 \u05e0\u05de\u05d5\u05da, \u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05dc\u05d4\u05ea\u05d6\u05d4: \u05de\u05ea\u05db\u05ea \u05de\u05d5\u05ea\u05db\u05ea \u05e9\u05e0\u05e4\u05dc\u05d8\u05ea \u05de\u05d4\u05e0\u05e7\u05d5\u05d3\u05d4."], [312.9, "\u05e9\u05e7\u05e2 \u05e2\u05de\u05d5\u05e7 \u05de\u05d3\u05d9 \u05e9\u05dc \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d1\u05e4\u05d7 \u05de\u05d7\u05dc\u05d9\u05e9 \u05d0\u05ea \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d5\u05e4\u05d5\u05d2\u05e2 \u05d1\u05de\u05e8\u05d0\u05d4."], [318.2, "\u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05de\u05d3\u05d9 \u05d6\u05d5 \u05dc\u05d6\u05d5 \u05d2\u05d5\u05e8\u05de\u05d5\u05ea \u05dc\u05d4\u05e1\u05d8\u05ea \u05d6\u05e8\u05dd: \u05d7\u05dc\u05e7 \u05de\u05d4\u05d6\u05e8\u05dd \u05d1\u05d5\u05e8\u05d7 \u05d3\u05e8\u05da \u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d4\u05e7\u05d5\u05d3\u05de\u05ea."], [325.8, "\u05d0\u05ea \u05d4\u05d0\u05d9\u05db\u05d5\u05ea \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d1\u05e7\u05e8\u05d9\u05e2\u05ea \u05d3\u05d2\u05d9\u05de\u05d5\u05ea: \u05e7\u05d5\u05dc\u05e4\u05d9\u05dd \u05d0\u05d5 \u05de\u05e4\u05e8\u05d9\u05d3\u05d9\u05dd \u05d1\u05db\u05d5\u05d7, \u05d5\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05ea \u05e7\u05d5\u05d8\u05e8 \u05d4\u05e0\u05e7\u05d5\u05d3\u05d4."], [332.8, "\u05d5\u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d2\u05dd \u05d1\u05d1\u05d3\u05d9\u05e7\u05d4 \u05e2\u05dc \u05e7\u05d5\u05dc\u05d9\u05ea \u05d5\u05d1\u05e0\u05d9\u05d8\u05d5\u05e8 \u05e9\u05dc \u05d4\u05d6\u05e8\u05dd \u05d1\u05d6\u05de\u05df \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [339.2, "\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d5\u05e8\u05d5\u05d1\u05d5\u05d8\u05d9\u05dd \u05e2\u05d5\u05dc\u05d9\u05dd \u05d4\u05e8\u05d1\u05d4, \u05d5\u05e6\u05d5\u05e8\u05db\u05d9\u05dd \u05d4\u05e1\u05e4\u05e7 \u05d7\u05e9\u05de\u05dc\u05d9 \u05d2\u05d1\u05d5\u05d4."], [344.1, "\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05de\u05ea\u05db\u05dc\u05d5\u05ea \u05d5\u05d7\u05d9\u05d3\u05d5\u05d3 \u05e9\u05d5\u05d8\u05e3 \u05d4\u05dd \u05d4\u05d5\u05e6\u05d0\u05d4 \u05e7\u05d1\u05d5\u05e2\u05d4."], [348.1, "\u05d0\u05d1\u05dc \u05d4\u05e2\u05dc\u05d5\u05ea \u05dc\u05db\u05dc \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05de\u05d0\u05d5\u05d3: \u05e9\u05d1\u05e8\u05d9\u05e8 \u05e9\u05e0\u05d9\u05d9\u05d4, \u05d1\u05dc\u05d9 \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9 \u05d5\u05d1\u05dc\u05d9 \u05d2\u05d6."], [354.6, "\u05e9\u05d5\u05dc\u05d9 \u05d4\u05d7\u05e4\u05d9\u05e4\u05d4 \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05de\u05e2\u05d8 \u05d7\u05d5\u05de\u05e8 \u05d5\u05de\u05e9\u05e7\u05dc, \u05d5\u05d6\u05d4 \u05de\u05d7\u05d9\u05e8 \u05e9\u05de\u05e9\u05dc\u05de\u05d9\u05dd \u05d1\u05ea\u05db\u05e0\u05d5\u05df."], [360.5, "\u05d5\u05dc\u05db\u05df \u05db\u05d3\u05d0\u05d9 \u05dc\u05ea\u05db\u05e0\u05df \u05d0\u05ea \u05d4\u05de\u05d5\u05e6\u05e8 \u05de\u05e8\u05d0\u05e9 \u05dc\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea: \u05e9\u05d5\u05dc\u05d9\u05d9\u05dd, \u05d2\u05d9\u05e9\u05d4 \u05d5\u05de\u05e8\u05d7\u05e7\u05d9\u05dd \u05d1\u05d9\u05df \u05d4\u05e0\u05e7\u05d5\u05d3\u05d5\u05ea."], [368.0, "\u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d4\u05de\u05d5\u05e0\u05d9 \u05e9\u05dc \u05e4\u05d7\u05d9\u05dd, \u05d0\u05d9\u05df \u05db\u05de\u05e2\u05d8 \u05e9\u05d9\u05d8\u05d4 \u05d6\u05d5\u05dc\u05d4 \u05d5\u05de\u05d4\u05d9\u05e8\u05d4 \u05d9\u05d5\u05ea\u05e8."], [373.3, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea \u05d4\u05d5\u05d0 \u05d6\u05e8\u05dd, \u05dc\u05d7\u05e5 \u05d5\u05d6\u05de\u05df, \u05d1\u05dc\u05d9 \u05e7\u05e9\u05ea \u05d5\u05d1\u05dc\u05d9 \u05de\u05d9\u05dc\u05d5\u05d9."], [380.1, "\u05e0\u05e7\u05d5\u05d3\u05d4, \u05ea\u05e4\u05e8 \u05d5\u05d1\u05dc\u05d9\u05d8\u05d5\u05ea, \u05db\u05d5\u05dc\u05dd \u05d1\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9 \u05d7\u05e4\u05d9\u05e4\u05d4 \u05d5\u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d4\u05de\u05d5\u05e0\u05d9."], [385.8, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e8\u05d9\u05ea\u05d5\u05da \u05dc\u05d9\u05d9\u05d6\u05e8, \u05ea\u05d4\u05dc\u05d9\u05da 52, \u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05de\u05e8\u05d5\u05db\u05d6\u05ea \u05d1\u05e7\u05e8\u05df \u05d0\u05d5\u05e8."]]};
window.MH_TR["ch11"]={"t": "\u05e8\u05d9\u05ea\u05d5\u05da \u05dc\u05d9\u05d9\u05d6\u05e8", "l": [[3.0, "\u05e8\u05d9\u05ea\u05d5\u05da \u05dc\u05d9\u05d9\u05d6\u05e8, \u05ea\u05d4\u05dc\u05d9\u05da 52, \u05de\u05e8\u05db\u05d6 \u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05e2\u05e6\u05d5\u05de\u05d4 \u05d1\u05e0\u05e7\u05d5\u05d3\u05d4 \u05e7\u05d8\u05e0\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d1\u05e2\u05d6\u05e8\u05ea \u05e7\u05e8\u05df \u05d0\u05d5\u05e8."], [11.0, "\u05d4\u05d5\u05d0 \u05de\u05d4\u05d9\u05e8, \u05de\u05d3\u05d5\u05d9\u05e7, \u05d5\u05db\u05de\u05e2\u05d8 \u05d1\u05dc\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05e9\u05d5\u05dc\u05d8 \u05d4\u05d9\u05d5\u05dd \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05ea \u05d4\u05e8\u05db\u05d1, \u05d4\u05e1\u05d5\u05dc\u05dc\u05d5\u05ea \u05d5\u05d4\u05de\u05db\u05e9\u05d5\u05e8 \u05d4\u05e8\u05e4\u05d5\u05d0\u05d9."], [19.4, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df, \u05d0\u05ea \u05e1\u05d5\u05d2\u05d9 \u05d4\u05dc\u05d9\u05d9\u05d6\u05e8\u05d9\u05dd, \u05d0\u05ea \u05d4\u05e6\u05d9\u05d5\u05d3 \u05d5\u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd, \u05d0\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d4\u05d9\u05d1\u05e8\u05d9\u05d3\u05d9, \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd, \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."], [30.6, "\u05e7\u05e8\u05df \u05d4\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d4\u05d9\u05d0 \u05d0\u05d5\u05e8 \u05de\u05e8\u05d5\u05db\u05d6, \u05d1\u05d0\u05d5\u05e8\u05da \u05d2\u05dc \u05d0\u05d7\u05d3, \u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05de\u05e7\u05d3 \u05d1\u05e2\u05d3\u05e9\u05d4."], [36.3, "\u05d4\u05e2\u05d3\u05e9\u05d4 \u05de\u05de\u05e7\u05d3\u05ea \u05d0\u05ea \u05d4\u05e7\u05e8\u05df \u05dc\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05e9\u05dc \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."], [41.3, "\u05e6\u05e4\u05d9\u05e4\u05d5\u05ea \u05d4\u05d4\u05e1\u05e4\u05e7 \u05d1\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d4\u05d6\u05d5 \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05de\u05d9\u05dc\u05d9\u05d5\u05e0\u05d9 \u05d5\u05d5\u05d0\u05d8 \u05dc\u05e1\u05e0\u05d8\u05d9\u05de\u05d8\u05e8 \u05e8\u05d1\u05d5\u05e2."], [46.5, "\u05d1\u05e6\u05e4\u05d9\u05e4\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d7\u05e1\u05d9\u05ea, \u05d4\u05dc\u05d9\u05d9\u05d6\u05e8 \u05de\u05d7\u05de\u05dd \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05d4\u05d7\u05d5\u05dd \u05de\u05ea\u05e4\u05e9\u05d8 \u05e4\u05e0\u05d9\u05de\u05d4 \u05d1\u05d4\u05d5\u05dc\u05db\u05d4. \u05d4\u05ea\u05e4\u05e8 \u05e8\u05d7\u05d1 \u05d5\u05e8\u05d3\u05d5\u05d3, \u05db\u05de\u05d5 \u05d1-TIG."], [56.5, "\u05d1\u05e6\u05e4\u05d9\u05e4\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d4\u05de\u05ea\u05db\u05ea \u05de\u05ea\u05d0\u05d3\u05d4, \u05d5\u05e0\u05e4\u05ea\u05d7 \u05d1\u05d4 \u05d7\u05d5\u05e8 \u05e6\u05e8 \u05de\u05dc\u05d0 \u05d0\u05d3\u05d9\u05dd: \u05d7\u05d5\u05e8 \u05de\u05e4\u05ea\u05d7."], [63.5, "\u05d4\u05e7\u05e8\u05df \u05d7\u05d5\u05d3\u05e8\u05ea \u05d3\u05e8\u05da \u05d4\u05d7\u05d5\u05e8 \u05dc\u05e2\u05d5\u05de\u05e7, \u05d5\u05d4\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d5\u05ea\u05db\u05ea \u05e0\u05e1\u05d2\u05e8\u05ea \u05de\u05d0\u05d7\u05d5\u05e8\u05d9\u05d5, \u05d1\u05d3\u05d9\u05d5\u05e7 \u05db\u05de\u05d5 \u05d1\u05e4\u05dc\u05d6\u05de\u05d4."], [70.6, "\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4: \u05ea\u05e4\u05e8 \u05e6\u05e8 \u05d5\u05e2\u05de\u05d5\u05e7, \u05e9\u05e2\u05d5\u05de\u05e7\u05d5 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05e4\u05d9 \u05e2\u05e9\u05e8\u05d4 \u05de\u05e8\u05d5\u05d7\u05d1\u05d5."], [76.6, "\u05d2\u05d6 \u05de\u05d2\u05df, \u05d0\u05e8\u05d2\u05d5\u05df, \u05d4\u05dc\u05d9\u05d5\u05dd \u05d0\u05d5 \u05d7\u05e0\u05e7\u05df, \u05de\u05d2\u05df \u05e2\u05dc \u05d4\u05d0\u05de\u05d1\u05d8 \u05d5\u05de\u05e4\u05d6\u05e8 \u05d0\u05ea \u05e2\u05e0\u05df \u05d4\u05d0\u05d3\u05d9\u05dd."], [83.5, "\u05d5\u05d0\u05d9\u05df \u05de\u05d2\u05e2 \u05d1\u05d9\u05df \u05d4\u05db\u05dc\u05d9 \u05dc\u05d7\u05dc\u05e7: \u05d0\u05d9\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05e9\u05e0\u05e9\u05d7\u05e7\u05ea, \u05d5\u05d0\u05d9\u05df \u05db\u05d5\u05d7 \u05e2\u05dc \u05d4\u05d7\u05dc\u05e7."], [90.3, "\u05d9\u05e9 \u05db\u05de\u05d4 \u05e1\u05d5\u05d2\u05d9\u05dd \u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd \u05e9\u05dc \u05de\u05e7\u05d5\u05e8\u05d5\u05ea \u05dc\u05d9\u05d9\u05d6\u05e8."], [93.4, "\u05dc\u05d9\u05d9\u05d6\u05e8 \u05e4\u05d7\u05de\u05df \u05d3\u05d5 \u05d7\u05de\u05e6\u05e0\u05d9 \u05d4\u05d5\u05d0 \u05d4\u05d5\u05d5\u05ea\u05d9\u05e7: \u05dc\u05d9\u05d9\u05d6\u05e8 \u05d2\u05d6, \u05e9\u05d4\u05e7\u05e8\u05df \u05e9\u05dc\u05d5 \u05de\u05d5\u05e2\u05d1\u05e8\u05ea \u05d1\u05de\u05e8\u05d0\u05d5\u05ea."], [99.9, "\u05d4\u05d9\u05d5\u05dd \u05e9\u05d5\u05dc\u05d8\u05d9\u05dd \u05e4\u05d9\u05d9\u05d1\u05e8 \u05dc\u05d9\u05d9\u05d6\u05e8 \u05d5\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d3\u05d9\u05e1\u05e7: \u05d9\u05e2\u05d9\u05dc\u05d9\u05dd, \u05e7\u05d5\u05de\u05e4\u05e7\u05d8\u05d9\u05d9\u05dd, \u05d5\u05d4\u05e7\u05e8\u05df \u05e9\u05dc\u05d4\u05dd \u05e2\u05d5\u05d1\u05e8\u05ea \u05d1\u05e1\u05d9\u05d1 \u05d0\u05d5\u05e4\u05d8\u05d9 \u05d2\u05de\u05d9\u05e9 \u05d9\u05e9\u05e8 \u05d0\u05dc \u05e8\u05d0\u05e9 \u05d4\u05e8\u05d5\u05d1\u05d5\u05d8."], [109.4, "\u05d4\u05d9\u05e2\u05d9\u05dc\u05d5\u05ea \u05e9\u05dc\u05d4\u05dd \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05d6\u05d5 \u05e9\u05dc \u05dc\u05d9\u05d9\u05d6\u05e8 \u05e4\u05d7\u05de\u05df \u05d3\u05d5 \u05d7\u05de\u05e6\u05e0\u05d9, \u05d5\u05dc\u05db\u05df \u05d4\u05dd \u05d7\u05e1\u05db\u05d5\u05e0\u05d9\u05d9\u05dd \u05d1\u05d7\u05e9\u05de\u05dc."], [116.4, "\u05dc\u05d9\u05d9\u05d6\u05e8\u05d9 \u05d3\u05d9\u05d5\u05d3\u05d4 \u05de\u05e9\u05de\u05e9\u05d9\u05dd \u05dc\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d4\u05d5\u05dc\u05db\u05d4 \u05d5\u05dc\u05d4\u05dc\u05d7\u05de\u05d4, \u05e2\u05dd \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e8\u05d7\u05d1\u05d4 \u05d5\u05d0\u05d7\u05d9\u05d3\u05d4."], [122.6, "\u05dc\u05d9\u05d9\u05d6\u05e8\u05d9\u05dd \u05d1\u05e4\u05d5\u05dc\u05e1\u05d9\u05dd \u05e7\u05e6\u05e8\u05d9\u05dd \u05de\u05e9\u05de\u05e9\u05d9\u05dd \u05dc\u05e8\u05d9\u05ea\u05d5\u05da \u05d6\u05e2\u05d9\u05e8: \u05ea\u05db\u05e9\u05d9\u05d8\u05d9\u05dd, \u05de\u05db\u05e9\u05d5\u05e8 \u05e8\u05e4\u05d5\u05d0\u05d9 \u05d5\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05e7\u05d4."], [129.5, "\u05d4\u05d4\u05e1\u05e4\u05e7\u05d9\u05dd \u05e0\u05e2\u05d9\u05dd \u05de\u05e2\u05e9\u05e8\u05d5\u05ea \u05d5\u05d5\u05d0\u05d8 \u05d5\u05e2\u05d3 \u05e2\u05e9\u05e8\u05d5\u05ea \u05d0\u05dc\u05e4\u05d9 \u05d5\u05d5\u05d0\u05d8."], [134.3, "\u05e8\u05d0\u05e9 \u05d4\u05dc\u05d9\u05d9\u05d6\u05e8 \u05db\u05d5\u05dc\u05dc \u05e2\u05d3\u05e9\u05d4 \u05e9\u05de\u05d9\u05d9\u05e9\u05e8\u05ea \u05d0\u05ea \u05d4\u05e7\u05e8\u05df, \u05e2\u05d3\u05e9\u05ea \u05de\u05d9\u05e7\u05d5\u05d3, \u05d5\u05d6\u05db\u05d5\u05db\u05d9\u05ea \u05de\u05d2\u05df \u05e9\u05de\u05d7\u05dc\u05d9\u05e4\u05d9\u05dd \u05db\u05e9\u05d4\u05d9\u05d0 \u05de\u05ea\u05dc\u05db\u05dc\u05db\u05ea."], [142.2, "crossjet, \u05e1\u05db\u05d9\u05df \u05d0\u05d5\u05d5\u05d9\u05e8 \u05de\u05ea\u05d7\u05ea \u05dc\u05e2\u05d3\u05e9\u05d4, \u05de\u05e2\u05d9\u05e3 \u05d4\u05ea\u05d6\u05d5\u05ea \u05d5\u05d0\u05d3\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05dd \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05dc\u05d6\u05db\u05d5\u05db\u05d9\u05ea."], [149.3, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05e8\u05d7\u05d5\u05e7, \u05e1\u05e7\u05e0\u05e8 \u05e2\u05dd \u05de\u05e8\u05d0\u05d5\u05ea \u05de\u05d6\u05d9\u05d6 \u05d0\u05ea \u05d4\u05e7\u05e8\u05df \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea, \u05d5\u05d4\u05e8\u05d5\u05d1\u05d5\u05d8 \u05dc\u05d0 \u05e6\u05e8\u05d9\u05da \u05dc\u05e0\u05d5\u05e2 \u05dc\u05db\u05dc \u05ea\u05e4\u05e8."], [156.4, "\u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd \u05d4\u05dd \u05d4\u05e1\u05e4\u05e7, \u05de\u05d4\u05d9\u05e8\u05d5\u05ea, \u05de\u05d9\u05e7\u05d5\u05dd \u05d4\u05de\u05d5\u05e7\u05d3 \u05d5\u05d2\u05d5\u05d3\u05dc \u05d4\u05e0\u05e7\u05d5\u05d3\u05d4."], [162.8, "\u05d1-wobble, \u05ea\u05e0\u05d5\u05d3\u05d4 \u05e7\u05d8\u05e0\u05d4 \u05d5\u05de\u05d4\u05d9\u05e8\u05d4 \u05e9\u05dc \u05d4\u05e7\u05e8\u05df, \u05de\u05e8\u05d7\u05d9\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8 \u05d5\u05de\u05de\u05dc\u05d0\u05d9\u05dd \u05de\u05e8\u05d5\u05d5\u05d7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd."], [169.6, "\u05d0\u05d1\u05dc \u05d4\u05d4\u05ea\u05d0\u05de\u05d4 \u05d7\u05d9\u05d9\u05d1\u05ea \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05de\u05d0\u05d5\u05d3: \u05d4\u05de\u05e8\u05d5\u05d5\u05d7 \u05d4\u05de\u05d5\u05ea\u05e8 \u05d4\u05d5\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."], [176.8, "\u05d5\u05dc\u05db\u05df \u05de\u05e7\u05d1\u05e2\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d4\u05d9\u05d8\u05d1, \u05d5\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05e2\u05e7\u05d1 \u05ea\u05e4\u05e8."], [182.3, "\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d9\u05d1\u05e8\u05d9\u05d3\u05d9 \u05de\u05e9\u05dc\u05d1 \u05dc\u05d9\u05d9\u05d6\u05e8 \u05e2\u05dd \u05e7\u05e9\u05ea \u05e9\u05dc MIG/MAG \u05d1\u05d0\u05d5\u05ea\u05d5 \u05d0\u05de\u05d1\u05d8."], [187.3, "\u05d4\u05dc\u05d9\u05d9\u05d6\u05e8 \u05e0\u05d5\u05ea\u05df \u05d7\u05d3\u05d9\u05e8\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4, \u05d5\u05d4\u05e7\u05e9\u05ea \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9 \u05d5\u05de\u05d2\u05e9\u05e8\u05ea \u05e2\u05dc \u05de\u05e8\u05d5\u05d5\u05d7\u05d9\u05dd."], [193.6, "\u05db\u05da \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8, \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05d3\u05d9\u05d5\u05e7 \u05d1\u05d4\u05db\u05e0\u05d4."], [199.3, "\u05d4\u05e9\u05d9\u05d8\u05d4 \u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05de\u05e1\u05e4\u05e0\u05d5\u05ea, \u05d1\u05e4\u05d0\u05e0\u05dc\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05d5\u05d1\u05e6\u05e0\u05e8\u05ea."], [204.3, "\u05e4\u05dc\u05d3\u05d5\u05ea \u05d5\u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05dc-\u05d7\u05dc\u05d3 \u05de\u05ea\u05e8\u05ea\u05db\u05d5\u05ea \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d1\u05e6\u05d5\u05e8\u05d4 \u05de\u05e6\u05d5\u05d9\u05e0\u05ea."], [209.6, "\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05d7\u05d6\u05d9\u05e8 \u05d7\u05dc\u05e7 \u05d2\u05d3\u05d5\u05dc \u05de\u05d4\u05e7\u05e8\u05df, \u05d5\u05e0\u05d5\u05d8\u05d4 \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d3\u05d5\u05e8\u05e9 \u05d4\u05e1\u05e4\u05e7 \u05d2\u05d1\u05d5\u05d4 \u05d5\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9."], [218.0, "\u05e0\u05d7\u05d5\u05e9\u05ea \u05de\u05d7\u05d6\u05d9\u05e8\u05d4 \u05db\u05de\u05e2\u05d8 \u05d0\u05ea \u05db\u05dc \u05d4\u05d0\u05d5\u05e8 \u05d4\u05d0\u05d9\u05e0\u05e4\u05e8\u05d0 \u05d0\u05d3\u05d5\u05dd, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4 \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8\u05d9\u05dd \u05d1\u05e6\u05d1\u05e2 \u05d9\u05e8\u05d5\u05e7 \u05d0\u05d5 \u05db\u05d7\u05d5\u05dc."], [225.7, "\u05dc\u05d9\u05d9\u05d6\u05e8 \u05de\u05d0\u05e4\u05e9\u05e8 \u05d2\u05dd \u05dc\u05e8\u05ea\u05da \u05de\u05ea\u05db\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea \u05d6\u05d5 \u05dc\u05d6\u05d5, \u05dc\u05de\u05e9\u05dc \u05dc\u05e9\u05d5\u05e0\u05d9\u05d5\u05ea \u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d1\u05e1\u05d5\u05dc\u05dc\u05d5\u05ea."], [232.9, "\u05d5\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05de\u05ea\u05e8\u05ea\u05da \u05d4\u05d9\u05d8\u05d1, \u05db\u05dc \u05e2\u05d5\u05d3 \u05de\u05d2\u05e0\u05d9\u05dd \u05e2\u05dc\u05d9\u05d5 \u05d1\u05d2\u05d6 \u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d4\u05e7\u05e8\u05df \u05e2\u05d1\u05e8\u05d4."], [238.9, "\u05d1\u05e4\u05d7 \u05de\u05d2\u05d5\u05dc\u05d5\u05d5\u05df \u05d1\u05d7\u05e4\u05d9\u05e4\u05d4, \u05d0\u05d3\u05d9 \u05d4\u05d0\u05d1\u05e5 \u05e0\u05dc\u05db\u05d3\u05d9\u05dd \u05d1\u05d9\u05df \u05d4\u05e4\u05d7\u05d9\u05dd \u05d5\u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05de\u05e8\u05d5\u05d5\u05d7 \u05d6\u05e2\u05d9\u05e8 \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd."], [248.7, "\u05dc\u05d9\u05d9\u05d6\u05e8 \u05de\u05e9\u05de\u05e9 \u05d1\u05d2\u05d5\u05e4\u05d9 \u05de\u05db\u05d5\u05e0\u05d9\u05d5\u05ea, \u05d1\u05d2\u05d2\u05d5\u05ea \u05d5\u05d1-tailored blanks, \u05d1\u05e1\u05d5\u05dc\u05dc\u05d5\u05ea, \u05d1\u05ea\u05de\u05e1\u05d5\u05e8\u05d5\u05ea, \u05d1\u05de\u05db\u05e9\u05d5\u05e8 \u05e8\u05e4\u05d5\u05d0\u05d9 \u05d5\u05d1\u05ea\u05db\u05e9\u05d9\u05d8\u05d9\u05dd."], [258.0, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea: \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e9\u05dc \u05de\u05d8\u05e8\u05d9\u05dd \u05d1\u05d3\u05e7\u05d4."], [261.2, "\u05d0\u05d6\u05d5\u05e8 \u05de\u05d5\u05e9\u05e4\u05e2 \u05d7\u05d5\u05dd \u05e6\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d5\u05e2\u05d9\u05d5\u05d5\u05ea \u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9."], [265.1, "\u05d1\u05dc\u05d9 \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9, \u05e2\u05dd \u05d2\u05d9\u05e9\u05d4 \u05de\u05e6\u05d3 \u05d0\u05d7\u05d3 \u05d1\u05dc\u05d1\u05d3, \u05d5\u05d0\u05d5\u05d8\u05d5\u05de\u05e6\u05d9\u05d4 \u05de\u05dc\u05d0\u05d4."], [270.1, "\u05d4\u05d7\u05e1\u05e8\u05d5\u05e0\u05d5\u05ea: \u05e6\u05d9\u05d5\u05d3 \u05d9\u05e7\u05e8 \u05de\u05d0\u05d5\u05d3."], [273.2, "\u05d3\u05e8\u05d9\u05e9\u05ea \u05d3\u05d9\u05d5\u05e7 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d1\u05d4\u05db\u05e0\u05d4 \u05d5\u05d1\u05e7\u05d9\u05d1\u05d5\u05e2."], [277.0, "\u05e1\u05db\u05e0\u05d4 \u05d1\u05d8\u05d9\u05d7\u05d5\u05ea\u05d9\u05ea: \u05d4\u05e7\u05e8\u05df \u05d1\u05dc\u05ea\u05d9 \u05e0\u05e8\u05d0\u05d9\u05ea \u05d5\u05e4\u05d5\u05d2\u05e2\u05ea \u05d1\u05e2\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05ea\u05d0 \u05e1\u05d2\u05d5\u05e8 \u05d5\u05de\u05d5\u05d2\u05df."], [284.6, "\u05d5\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05de\u05d4\u05d9\u05e8 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d9\u05e6\u05d5\u05e8 \u05d0\u05d6\u05d5\u05e8 \u05e7\u05e9\u05d4 \u05d5\u05e9\u05d1\u05d9\u05e8 \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05de\u05df."], [290.9, "\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05de\u05d5\u05e4\u05d9\u05e2\u05d5\u05ea \u05db\u05e9\u05d7\u05d5\u05e8 \u05d4\u05de\u05e4\u05ea\u05d7 \u05e7\u05d5\u05e8\u05e1 \u05d5\u05dc\u05d5\u05db\u05d3 \u05d2\u05d6, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05d7\u05d3\u05d9\u05e8\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4."], [297.1, "\u05d4\u05ea\u05d6\u05d5\u05ea \u05d5\u05ea\u05e4\u05e8 \u05e9\u05e7\u05d5\u05e2 \u05e0\u05d2\u05e8\u05de\u05d9\u05dd \u05de\u05d4\u05e1\u05e4\u05e7 \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9, \u05d0\u05d5 \u05de\u05de\u05d5\u05e7\u05d3 \u05dc\u05d0 \u05e0\u05db\u05d5\u05df."], [302.9, "\u05d1\u05d2\u05dc\u05dc \u05e9\u05d4\u05e7\u05e8\u05df \u05e6\u05e8\u05d4, \u05e1\u05d8\u05d9\u05d9\u05d4 \u05e7\u05d8\u05e0\u05d4 \u05de\u05e7\u05d5 \u05d4\u05ea\u05e4\u05e8 \u05d2\u05d5\u05e8\u05de\u05ea \u05dc\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da."], [308.5, "\u05e1\u05d3\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d2\u05d5\u05e4\u05e8\u05d9\u05ea, \u05db\u05e9\u05d4\u05de\u05ea\u05db\u05ea \u05de\u05ea\u05de\u05e6\u05e7\u05ea \u05de\u05d4\u05e8."], [314.9, "\u05d5\u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d3\u05d9 \u05de\u05d5\u05e4\u05d9\u05e2 humping: \u05d4\u05ea\u05e4\u05e8 \u05e0\u05e9\u05d1\u05e8 \u05dc\u05d2\u05d5\u05e9\u05d9\u05dd \u05d1\u05de\u05e7\u05d5\u05dd \u05ea\u05e4\u05e8 \u05d7\u05dc\u05e7."], [321.6, "\u05d5\u05de\u05d5\u05e7\u05d3 \u05e9\u05d6\u05d6, \u05d0\u05d5 \u05d6\u05db\u05d5\u05db\u05d9\u05ea \u05de\u05d2\u05df \u05de\u05dc\u05d5\u05db\u05dc\u05db\u05ea, \u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05dc\u05d7\u05d3\u05d9\u05e8\u05d4 \u05d7\u05dc\u05e7\u05d9\u05ea."], [327.0, "\u05d0\u05ea \u05e8\u05d5\u05d1 \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05de\u05d0\u05ea\u05e8\u05d9\u05dd \u05d1\u05e0\u05d9\u05d8\u05d5\u05e8: \u05de\u05e6\u05dc\u05de\u05d5\u05ea \u05d5\u05d7\u05d9\u05d9\u05e9\u05e0\u05d9\u05dd \u05e9\u05e2\u05d5\u05e7\u05d1\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d0\u05de\u05d1\u05d8 \u05d1\u05d6\u05de\u05df \u05d0\u05de\u05ea."], [334.9, "\u05d4\u05d4\u05e9\u05e7\u05e2\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d0\u05d5\u05d3: \u05de\u05e7\u05d5\u05e8 \u05dc\u05d9\u05d9\u05d6\u05e8, \u05e8\u05d5\u05d1\u05d5\u05d8, \u05d0\u05d5\u05e4\u05d8\u05d9\u05e7\u05d4 \u05d5\u05ea\u05d0 \u05d1\u05d8\u05d9\u05d7\u05d5\u05ea \u05e1\u05d2\u05d5\u05e8."], [341.2, "\u05d0\u05d1\u05dc \u05d4\u05e2\u05dc\u05d5\u05ea \u05d4\u05e9\u05d5\u05d8\u05e4\u05ea \u05e0\u05de\u05d5\u05db\u05d4: \u05d0\u05d9\u05df \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9, \u05e6\u05e8\u05d9\u05db\u05ea \u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05dc\u05db\u05dc \u05de\u05d8\u05e8 \u05e0\u05de\u05d5\u05db\u05d4, \u05d5\u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d0\u05d5\u05d3."], [349.7, "\u05e4\u05d7\u05d5\u05ea \u05e2\u05d9\u05d5\u05d5\u05ea, \u05db\u05dc\u05d5\u05de\u05e8 \u05e4\u05d7\u05d5\u05ea \u05d9\u05d9\u05e9\u05d5\u05e8 \u05d5\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [354.5, "\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d4\u05d3\u05d9\u05d5\u05e7 \u05d4\u05e0\u05d3\u05e8\u05e9 \u05de\u05e2\u05d1\u05d9\u05e8 \u05e2\u05dc\u05d5\u05ea \u05dc\u05d4\u05db\u05e0\u05d4: \u05d7\u05d9\u05ea\u05d5\u05da \u05de\u05d3\u05d5\u05d9\u05e7, \u05e7\u05d9\u05d1\u05d5\u05e2 \u05d5\u05d1\u05e7\u05e8\u05d4."], [361.5, "\u05d5\u05dc\u05db\u05df \u05dc\u05d9\u05d9\u05d6\u05e8 \u05de\u05e9\u05ea\u05dc\u05dd \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d4\u05de\u05d5\u05e0\u05d9 \u05d5\u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9."], [366.0, "\u05d5\u05d1\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05d5\u05d3\u05d3\u05ea, \u05d4\u05db\u05e0\u05d4 \u05d5\u05db\u05d9\u05d5\u05d5\u05df \u05dc\u05d5\u05e7\u05d7\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05d6\u05de\u05df \u05de\u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e2\u05e6\u05de\u05d5."], [371.8, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05dc\u05d9\u05d9\u05d6\u05e8 \u05d4\u05d5\u05d0 \u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05de\u05e8\u05d5\u05db\u05d6\u05ea \u05d1\u05e7\u05e8\u05df \u05d0\u05d5\u05e8, \u05d1\u05d4\u05d5\u05dc\u05db\u05d4 \u05d0\u05d5 \u05d1\u05d7\u05d5\u05e8 \u05de\u05e4\u05ea\u05d7."], [378.4, "\u05de\u05d4\u05d9\u05e8, \u05de\u05d3\u05d5\u05d9\u05e7 \u05d5\u05d1\u05dc\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea, \u05d0\u05d1\u05dc \u05d3\u05d5\u05e8\u05e9 \u05d4\u05e9\u05e7\u05e2\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d5\u05d4\u05db\u05e0\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea."], [384.2, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd, \u05ea\u05d4\u05dc\u05d9\u05da 51, \u05d4\u05e7\u05e8\u05df \u05d4\u05d7\u05d6\u05e7\u05d4 \u05de\u05db\u05d5\u05dc\u05df, \u05d1\u05ea\u05d5\u05da \u05d5\u05d0\u05e7\u05d5\u05dd."]]};
window.MH_TR["ch12"]={"t": "\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd", "l": [[3.0, "\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd, \u05ea\u05d4\u05dc\u05d9\u05da 51, \u05de\u05e8\u05ea\u05da \u05d1\u05e2\u05d6\u05e8\u05ea \u05d0\u05dc\u05d5\u05de\u05d4 \u05e9\u05dc \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05de\u05d4\u05d9\u05e8\u05d9\u05dd, \u05d1\u05ea\u05d5\u05da \u05ea\u05d0 \u05d5\u05d0\u05e7\u05d5\u05dd."], [11.5, "\u05d6\u05d4 \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05e2\u05dd \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4 \u05d4\u05e2\u05de\u05d5\u05e7\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8: \u05ea\u05e4\u05e8 \u05d0\u05d7\u05d3 \u05d9\u05db\u05d5\u05dc \u05dc\u05d7\u05d1\u05e8 \u05e4\u05dc\u05d3\u05d4 \u05d1\u05e2\u05d5\u05d1\u05d9 \u05e9\u05dc \u05d9\u05d5\u05ea\u05e8 \u05de-100 \u05de\u05f4\u05de."], [19.4, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df, \u05d0\u05ea \u05d4\u05de\u05db\u05d5\u05e0\u05d4, \u05d0\u05ea \u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd, \u05d0\u05ea \u05e8\u05de\u05d5\u05ea \u05d4\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd, \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd, \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."], [29.8, "\u05d1\u05ea\u05d5\u05ea\u05d7 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd, \u05e7\u05ea\u05d5\u05d3\u05d4 \u05de\u05d7\u05d5\u05de\u05de\u05ea \u05de\u05e9\u05d7\u05e8\u05e8\u05ea \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd."], [34.4, "\u05de\u05ea\u05d7 \u05d2\u05d1\u05d5\u05d4, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05df 30 \u05dc-200 \u05e7\u05d9\u05dc\u05d5-\u05d5\u05d5\u05dc\u05d8, \u05de\u05d0\u05d9\u05e5 \u05d0\u05d5\u05ea\u05dd \u05dc\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e9\u05dc \u05d1\u05e2\u05e8\u05da \u05d7\u05e6\u05d9 \u05de\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d0\u05d5\u05e8."], [42.6, "\u05e1\u05dc\u05d9\u05dc \u05de\u05d2\u05e0\u05d8\u05d9 \u05de\u05de\u05e7\u05d3 \u05d0\u05ea \u05d4\u05d0\u05dc\u05d5\u05de\u05d4 \u05dc\u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05dc \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05de\u05f4\u05de, \u05d5\u05e1\u05dc\u05d9\u05dc\u05d9 \u05d4\u05e1\u05d8\u05d4 \u05de\u05d6\u05d9\u05d6\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea."], [50.1, "\u05db\u05e9\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05e4\u05d5\u05d2\u05e2\u05d9\u05dd \u05d1\u05de\u05ea\u05db\u05ea, \u05d4\u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05e9\u05dc\u05d4\u05dd \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05d7\u05d5\u05dd, \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea."], [56.1, "\u05e6\u05e4\u05d9\u05e4\u05d5\u05ea \u05d4\u05d4\u05e1\u05e4\u05e7 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d5\u05d4\u05de\u05ea\u05db\u05ea \u05de\u05ea\u05d0\u05d3\u05d4 \u05d5\u05e4\u05d5\u05ea\u05d7\u05ea \u05d7\u05d5\u05e8 \u05de\u05e4\u05ea\u05d7, \u05db\u05de\u05d5 \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8."], [63.1, "\u05d4\u05d7\u05d5\u05e8 \u05d7\u05d5\u05d3\u05e8 \u05dc\u05e2\u05d5\u05de\u05e7, \u05d5\u05d4\u05ea\u05e4\u05e8 \u05d9\u05d5\u05e6\u05d0 \u05e6\u05e8 \u05de\u05d0\u05d5\u05d3: \u05d4\u05e2\u05d5\u05de\u05e7 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05e4\u05d9 25 \u05de\u05d4\u05e8\u05d5\u05d7\u05d1."], [70.8, "\u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05d4\u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05e0\u05db\u05e0\u05e1\u05ea \u05dc\u05d7\u05dc\u05e7, \u05d5\u05dc\u05db\u05df \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d7\u05e1\u05db\u05d5\u05e0\u05d9 \u05de\u05d0\u05d5\u05d3 \u05d1\u05d7\u05e9\u05de\u05dc."], [76.6, "\u05d5\u05dc\u05de\u05d4 \u05d5\u05d0\u05e7\u05d5\u05dd? \u05db\u05d9 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8, \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05de\u05ea\u05e0\u05d2\u05e9\u05d9\u05dd \u05d1\u05de\u05d5\u05dc\u05e7\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05d6 \u05d5\u05de\u05ea\u05e4\u05d6\u05e8\u05d9\u05dd."], [82.7, "\u05d4\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d2\u05dd \u05de\u05d2\u05df \u05e2\u05dc \u05d4\u05de\u05ea\u05db\u05ea \u05de\u05d7\u05de\u05e6\u05df \u05d5\u05de\u05d7\u05e0\u05e7\u05df, \u05d1\u05dc\u05d9 \u05e9\u05d5\u05dd \u05d2\u05d6 \u05de\u05d2\u05df."], [88.6, "\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05db\u05d5\u05dc\u05dc\u05ea \u05d0\u05ea \u05ea\u05d5\u05ea\u05d7 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd, \u05e1\u05e4\u05e7 \u05de\u05ea\u05d7 \u05d2\u05d1\u05d5\u05d4, \u05ea\u05d0 \u05d5\u05d0\u05e7\u05d5\u05dd \u05d5\u05de\u05e9\u05d0\u05d1\u05d5\u05ea."], [95.1, "\u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05d5\u05e9\u05d1\u05d9\u05dd \u05d1\u05ea\u05d0 \u05e2\u05dc \u05e9\u05d5\u05dc\u05d7\u05df \u05e9\u05d6\u05d6, \u05d0\u05d5 \u05e2\u05dc \u05d4\u05ea\u05e7\u05df \u05e9\u05de\u05e1\u05d5\u05d1\u05d1 \u05d0\u05d5\u05ea\u05dd, \u05d5\u05d4\u05ea\u05d5\u05ea\u05d7 \u05e0\u05e9\u05d0\u05e8 \u05d1\u05de\u05e7\u05d5\u05dd."], [102.5, "\u05dc\u05e4\u05e0\u05d9 \u05db\u05dc \u05e8\u05d9\u05ea\u05d5\u05da \u05e9\u05d5\u05d0\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8 \u05de\u05d4\u05ea\u05d0, \u05d5\u05d6\u05d4 \u05dc\u05d5\u05e7\u05d7 \u05de\u05db\u05de\u05d4 \u05e9\u05e0\u05d9\u05d5\u05ea \u05d5\u05e2\u05d3 \u05d3\u05e7\u05d5\u05ea \u05d0\u05e8\u05d5\u05db\u05d5\u05ea, \u05dc\u05e4\u05d9 \u05d2\u05d5\u05d3\u05dc \u05d4\u05ea\u05d0."], [110.3, "\u05db\u05e9\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05e4\u05d5\u05d2\u05e2\u05d9\u05dd \u05d1\u05de\u05ea\u05db\u05ea \u05e0\u05d5\u05e6\u05e8\u05ea \u05d2\u05dd \u05e7\u05e8\u05d9\u05e0\u05ea \u05e8\u05e0\u05d8\u05d2\u05df, \u05d5\u05dc\u05db\u05df \u05e7\u05d9\u05e8\u05d5\u05ea \u05d4\u05ea\u05d0 \u05e2\u05e9\u05d5\u05d9\u05d9\u05dd \u05e4\u05dc\u05d3\u05d4 \u05e2\u05d1\u05d4, \u05d5\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d2\u05dd \u05e2\u05d5\u05e4\u05e8\u05ea."], [119.3, "\u05d4\u05de\u05e4\u05e2\u05d9\u05dc \u05e8\u05d5\u05d0\u05d4 \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8 \u05d3\u05e8\u05da \u05d7\u05dc\u05d5\u05df \u05de\u05d5\u05d2\u05df \u05d0\u05d5 \u05de\u05e6\u05dc\u05de\u05d4, \u05d5\u05dc\u05d0 \u05de\u05ea\u05e7\u05e8\u05d1 \u05dc\u05e7\u05e8\u05df."], [125.2, "\u05d5\u05d0\u05d5\u05ea\u05d4 \u05e7\u05e8\u05df \u05de\u05e9\u05de\u05e9\u05ea \u05d2\u05dd \u05dc\u05d0\u05d9\u05ea\u05d5\u05e8: \u05e1\u05d5\u05e8\u05e7\u05d9\u05dd \u05d0\u05d9\u05ea\u05d4 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d5\u05de\u05d5\u05e6\u05d0\u05d9\u05dd \u05d0\u05ea \u05e7\u05d5 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [132.3, "\u05d4\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05de\u05e0\u05d5\u05d4\u05dc\u05d5\u05ea \u05d1\u05de\u05d7\u05e9\u05d1, \u05d5\u05db\u05dc \u05e8\u05d9\u05ea\u05d5\u05da \u05d7\u05d5\u05d6\u05e8 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05e2\u05dc \u05d0\u05d5\u05ea\u05dd \u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd."], [138.4, "\u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd \u05d4\u05dd \u05de\u05ea\u05d7 \u05d4\u05d4\u05d0\u05e6\u05d4, \u05d6\u05e8\u05dd \u05d4\u05e7\u05e8\u05df, \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d5\u05de\u05d9\u05e7\u05d5\u05dd \u05d4\u05de\u05d5\u05e7\u05d3."], [145.7, "\u05d4\u05e1\u05e4\u05e7 \u05d4\u05e7\u05e8\u05df \u05d4\u05d5\u05d0 \u05d4\u05de\u05ea\u05d7 \u05db\u05e4\u05d5\u05dc \u05d4\u05d6\u05e8\u05dd: \u05dc\u05de\u05e9\u05dc, 60 \u05e7\u05d9\u05dc\u05d5-\u05d5\u05d5\u05dc\u05d8 \u05db\u05e4\u05d5\u05dc 100 \u05de\u05d9\u05dc\u05d9\u05d0\u05de\u05e4\u05e8 \u05d4\u05dd 6 \u05e7\u05d9\u05dc\u05d5\u05d5\u05d0\u05d8."], [154.6, "\u05d9\u05d5\u05ea\u05e8 \u05d4\u05e1\u05e4\u05e7, \u05d0\u05d5 \u05e4\u05d7\u05d5\u05ea \u05de\u05d4\u05d9\u05e8\u05d5\u05ea, \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05d7\u05d3\u05d9\u05e8\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8."], [159.8, "\u05de\u05d5\u05e7\u05d3 \u05de\u05e2\u05d8 \u05de\u05ea\u05d7\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e0\u05d5\u05ea\u05df \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d0\u05ea \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4 \u05d4\u05d8\u05d5\u05d1\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8."], [165.1, "\u05e1\u05dc\u05d9\u05dc\u05d9 \u05d4\u05d4\u05e1\u05d8\u05d4 \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05e0\u05d9\u05e2 \u05d0\u05ea \u05d4\u05e7\u05e8\u05df \u05d1\u05ea\u05d1\u05e0\u05d9\u05ea \u05e7\u05d8\u05e0\u05d4, \u05db\u05de\u05d5 \u05e2\u05d9\u05d2\u05d5\u05dc, \u05db\u05d3\u05d9 \u05dc\u05d9\u05d9\u05e6\u05d1 \u05d0\u05ea \u05d4\u05d0\u05de\u05d1\u05d8 \u05d5\u05dc\u05d4\u05e8\u05d7\u05d9\u05d1 \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8."], [173.6, "\u05d1\u05e1\u05d5\u05e3 \u05d4\u05ea\u05e4\u05e8 \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d6\u05e8\u05dd \u05d1\u05d4\u05d3\u05e8\u05d2\u05d4, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d7\u05d5\u05e8 \u05d9\u05d9\u05e1\u05d2\u05e8 \u05d1\u05dc\u05d9 \u05d7\u05dc\u05dc."], [179.4, "\u05d4\u05d4\u05db\u05e0\u05d4 \u05d3\u05d5\u05de\u05d4 \u05dc\u05dc\u05d9\u05d9\u05d6\u05e8: \u05d7\u05d9\u05d1\u05d5\u05e8 \u05e7\u05ea \u05d9\u05e9\u05e8, \u05d1\u05dc\u05d9 \u05d7\u05e8\u05d9\u05e5, \u05e2\u05dd \u05d4\u05ea\u05d0\u05de\u05d4 \u05d4\u05d3\u05d5\u05e7\u05d4 \u05d5\u05d1\u05dc\u05d9 \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9."], [187.3, "\u05d9\u05e9 \u05e9\u05dc\u05d5\u05e9 \u05e8\u05de\u05d5\u05ea \u05e2\u05d1\u05d5\u05d3\u05d4 \u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea."], [189.9, "\u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e8\u05df \u05d4\u05d7\u05d3\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d5\u05d0\u05ea \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4 \u05d4\u05e2\u05de\u05d5\u05e7\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d5\u05d6\u05d5 \u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4."], [197.4, "\u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d7\u05dc\u05e7\u05d9 \u05d4\u05e9\u05d0\u05d9\u05d1\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d5\u05d4\u05e7\u05e8\u05df \u05de\u05e2\u05d8 \u05e8\u05d7\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d6\u05d4 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e1\u05d3\u05e8\u05ea\u05d9, \u05dc\u05de\u05e9\u05dc \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d1\u05e8\u05db\u05d1."], [206.8, "\u05d5\u05d9\u05e9 \u05d2\u05dd \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8, \u05d1\u05dc\u05d9 \u05ea\u05d0: \u05d4\u05de\u05e8\u05d7\u05e7 \u05dc\u05d7\u05dc\u05e7 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05e7\u05e6\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d5\u05d4\u05d7\u05d3\u05d9\u05e8\u05d4 \u05e7\u05d8\u05e0\u05d4 \u05d9\u05d5\u05ea\u05e8."], [214.4, "\u05d1\u05de\u05e1\u05e4\u05d5\u05e8 ISO, \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d4\u05d5\u05d0 \u05ea\u05d4\u05dc\u05d9\u05da 511, \u05d5\u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05ea\u05d4\u05dc\u05d9\u05da 512."], [223.5, "\u05d1\u05d6\u05db\u05d5\u05ea \u05d4\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd, \u05d6\u05d4 \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05de\u05d5\u05e2\u05d3\u05e3 \u05dc\u05de\u05ea\u05db\u05d5\u05ea \u05e9\u05de\u05d2\u05d9\u05d1\u05d5\u05ea \u05d1\u05e7\u05dc\u05d5\u05ea \u05e2\u05dd \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8, \u05db\u05de\u05d5 \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d5\u05d6\u05d9\u05e8\u05e7\u05d5\u05e0\u05d9\u05d5\u05dd."], [231.0, "\u05d5\u05d2\u05dd \u05dc\u05de\u05ea\u05db\u05d5\u05ea \u05e2\u05dd \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05ea\u05db\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d0\u05d5\u05d3: \u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df, \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05e0\u05d9\u05d5\u05d1\u05d9\u05d5\u05dd \u05d5\u05d8\u05e0\u05d8\u05dc\u05d5\u05dd."], [238.4, "\u05e0\u05d7\u05d5\u05e9\u05ea \u05de\u05ea\u05e8\u05ea\u05db\u05ea \u05d8\u05d5\u05d1 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d0\u05e9\u05e8 \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8, \u05db\u05d9 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05dc\u05d0 \u05de\u05d5\u05d7\u05d6\u05e8\u05d9\u05dd \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05db\u05de\u05d5 \u05d4\u05d0\u05d5\u05e8."], [245.3, "\u05d0\u05e4\u05e9\u05e8 \u05d2\u05dd \u05dc\u05e8\u05ea\u05da \u05de\u05ea\u05db\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea \u05d6\u05d5 \u05dc\u05d6\u05d5, \u05db\u05de\u05d5 \u05e0\u05d7\u05d5\u05e9\u05ea \u05dc\u05e4\u05dc\u05d3\u05d4, \u05d0\u05d5 \u05e0\u05d7\u05d5\u05e9\u05ea \u05dc\u05e0\u05d9\u05d5\u05d1\u05d9\u05d5\u05dd."], [251.5, "\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05ea\u05e8\u05ea\u05db\u05d5\u05ea \u05d4\u05d9\u05d8\u05d1, \u05d0\u05d1\u05dc \u05e6\u05e8\u05d9\u05da \u05dc\u05e0\u05d8\u05e8\u05dc \u05d1\u05d4\u05df \u05de\u05d2\u05e0\u05d8\u05d9\u05d5\u05ea \u05e9\u05d0\u05e8\u05d9\u05ea, \u05d0\u05d7\u05e8\u05ea \u05d4\u05e9\u05d3\u05d4 \u05d4\u05de\u05d2\u05e0\u05d8\u05d9 \u05de\u05e1\u05d9\u05d8 \u05d0\u05ea \u05d4\u05e7\u05e8\u05df."], [259.3, "\u05d5\u05de\u05ea\u05db\u05d5\u05ea \u05e9\u05de\u05ea\u05d0\u05d3\u05d5\u05ea \u05d1\u05e7\u05dc\u05d5\u05ea, \u05db\u05de\u05d5 \u05d0\u05d1\u05e5, \u05e7\u05d3\u05de\u05d9\u05d5\u05dd \u05d5\u05de\u05d2\u05e0\u05d6\u05d9\u05d5\u05dd, \u05d5\u05d2\u05dd \u05e4\u05dc\u05d9\u05d6 \u05d5\u05e4\u05d7 \u05de\u05d2\u05d5\u05dc\u05d5\u05d5\u05df, \u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d5\u05ea: \u05d4\u05d0\u05d3\u05d9\u05dd \u05de\u05d6\u05d4\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05d0 \u05d5\u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea."], [272.1, "\u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05e9\u05de\u05e9 \u05d1\u05ea\u05e2\u05d5\u05e4\u05d4 \u05d5\u05d1\u05d7\u05dc\u05dc, \u05d1\u05d7\u05dc\u05e7\u05d9 \u05de\u05e0\u05d5\u05e2\u05d9 \u05e1\u05d9\u05dc\u05d5\u05df, \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4 \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05ea, \u05d1\u05de\u05d0\u05d9\u05e6\u05d9 \u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d5\u05d1\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05dc\u05ea\u05d9\u05d1\u05d5\u05ea \u05d4\u05d9\u05dc\u05d5\u05db\u05d9\u05dd."], [282.2, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea: \u05d7\u05d3\u05d9\u05e8\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05d1\u05de\u05e2\u05d1\u05e8 \u05d0\u05d7\u05d3, \u05d1\u05de\u05e7\u05d5\u05dd \u05e2\u05e9\u05e8\u05d5\u05ea \u05de\u05e2\u05d1\u05e8\u05d9\u05dd \u05d1\u05e7\u05e9\u05ea."], [288.4, "\u05d0\u05d6\u05d5\u05e8 \u05de\u05d5\u05e9\u05e4\u05e2 \u05d7\u05d5\u05dd \u05e6\u05e8 \u05de\u05d0\u05d5\u05d3 \u05d5\u05e2\u05d9\u05d5\u05d5\u05ea \u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9, \u05db\u05da \u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05ea\u05da \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05db\u05d1\u05e8 \u05e2\u05d5\u05d1\u05d3\u05d5 \u05dc\u05d2\u05de\u05e8."], [295.3, "\u05ea\u05e4\u05e8 \u05e0\u05e7\u05d9 \u05de\u05d0\u05d5\u05d3 \u05d1\u05d6\u05db\u05d5\u05ea \u05d4\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd, \u05d1\u05dc\u05d9 \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9 \u05d5\u05d1\u05dc\u05d9 \u05d2\u05d6."], [300.2, "\u05d5\u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05de\u05d5\u05d7\u05e9\u05d1, \u05e9\u05d7\u05d5\u05d6\u05e8 \u05e2\u05dc \u05e2\u05e6\u05de\u05d5 \u05d1\u05d3\u05d9\u05d5\u05e7."], [303.7, "\u05d4\u05d7\u05e1\u05e8\u05d5\u05e0\u05d5\u05ea: \u05e6\u05d9\u05d5\u05d3 \u05d9\u05e7\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d5\u05d2\u05d5\u05d3\u05dc \u05d4\u05d7\u05dc\u05e7 \u05de\u05d5\u05d2\u05d1\u05dc \u05dc\u05d2\u05d5\u05d3\u05dc \u05d4\u05ea\u05d0."], [309.3, "\u05d6\u05de\u05df \u05e9\u05d0\u05d9\u05d1\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05db\u05dc \u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05d4\u05ea\u05d0\u05de\u05d4 \u05d4\u05d3\u05d5\u05e7\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd."], [314.6, "\u05e7\u05e8\u05d9\u05e0\u05ea \u05e8\u05e0\u05d8\u05d2\u05df \u05e9\u05de\u05d7\u05d9\u05d9\u05d1\u05ea \u05de\u05d9\u05d2\u05d5\u05df, \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05e9\u05e2\u05dc\u05d5\u05dc \u05dc\u05d9\u05e6\u05d5\u05e8 \u05d0\u05d6\u05d5\u05e8 \u05e7\u05e9\u05d4 \u05d5\u05e9\u05d1\u05d9\u05e8 \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05de\u05df."], [323.1, "\u05d4\u05e4\u05d2\u05dd \u05d4\u05de\u05e1\u05d5\u05db\u05df \u05d1\u05d9\u05d5\u05ea\u05e8: \u05d4\u05e7\u05e8\u05df \u05de\u05d7\u05d8\u05d9\u05d0\u05d4 \u05d0\u05ea \u05e7\u05d5 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8. \u05d4\u05ea\u05e4\u05e8 \u05e0\u05e8\u05d0\u05d4 \u05ea\u05e7\u05d9\u05df \u05de\u05dc\u05de\u05e2\u05dc\u05d4, \u05d0\u05d1\u05dc \u05dc\u05de\u05d8\u05d4 \u05d9\u05e9 \u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da."], [332.3, "\u05d6\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05d1\u05d2\u05dc\u05dc \u05de\u05d2\u05e0\u05d8\u05d9\u05d5\u05ea \u05e9\u05d0\u05e8\u05d9\u05ea, \u05d0\u05d5 \u05d4\u05ea\u05d0\u05de\u05d4 \u05dc\u05d0 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea, \u05d5\u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05d1\u05d9\u05dd."], [338.6, "\u05d1\u05d7\u05d3\u05d9\u05e8\u05d4 \u05d7\u05dc\u05e7\u05d9\u05ea, \u05d4\u05e9\u05d5\u05e8\u05e9 \u05d9\u05d5\u05e6\u05d0 \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3, \u05e2\u05dd \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d7\u05d3\u05d5\u05ea \u05d5\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05d1\u05ea\u05d7\u05ea\u05d9\u05ea. \u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 spiking."], [347.0, "\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05e0\u05d5\u05e6\u05e8\u05d5\u05ea \u05d2\u05dd \u05de\u05dc\u05db\u05dc\u05d5\u05da, \u05de\u05e9\u05de\u05df, \u05d0\u05d5 \u05de\u05d0\u05d3\u05d9\u05dd \u05e9\u05dc \u05de\u05ea\u05db\u05d5\u05ea \u05e9\u05de\u05ea\u05d0\u05d3\u05d5\u05ea \u05d1\u05e7\u05dc\u05d5\u05ea."], [353.5, "\u05d1\u05d4\u05e1\u05e4\u05e7 \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9, \u05de\u05ea\u05db\u05ea \u05e0\u05e4\u05dc\u05d8\u05ea \u05de\u05d4\u05d0\u05de\u05d1\u05d8, \u05d5\u05e0\u05e9\u05d0\u05e8 \u05ea\u05e4\u05e8 \u05e9\u05e7\u05d5\u05e2."], [359.1, "\u05d5\u05d1\u05e1\u05d5\u05e3 \u05d4\u05ea\u05e4\u05e8, \u05d0\u05dd \u05de\u05db\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e8\u05df \u05de\u05d4\u05e8 \u05de\u05d3\u05d9, \u05e0\u05e9\u05d0\u05e8 \u05d7\u05dc\u05dc \u05d0\u05d5 \u05e1\u05d3\u05e7."], [365.4, "\u05dc\u05db\u05df \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d1\u05e6\u05d9\u05dc\u05d5\u05dd \u05e8\u05e0\u05d8\u05d2\u05df \u05d0\u05d5 \u05d1\u05d0\u05d5\u05dc\u05d8\u05e8\u05e1\u05d0\u05d5\u05e0\u05d3, \u05d5\u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e1\u05d3\u05e8\u05ea\u05d9 \u05d2\u05dd \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d3\u05d5\u05d2\u05de\u05d0\u05d5\u05ea \u05dc\u05d1\u05d3\u05d9\u05e7\u05d4."], [372.7, "\u05d4\u05d4\u05e9\u05e7\u05e2\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d0\u05d5\u05d3: \u05ea\u05d5\u05ea\u05d7, \u05e1\u05e4\u05e7 \u05de\u05ea\u05d7 \u05d2\u05d1\u05d5\u05d4, \u05ea\u05d0 \u05d5\u05d0\u05e7\u05d5\u05dd, \u05de\u05e9\u05d0\u05d1\u05d5\u05ea \u05d5\u05de\u05d9\u05d2\u05d5\u05df."], [380.1, "\u05d6\u05de\u05df \u05d4\u05e9\u05d0\u05d9\u05d1\u05d4 \u05de\u05ea\u05d5\u05d5\u05e1\u05e3 \u05dc\u05db\u05dc \u05de\u05d7\u05d6\u05d5\u05e8, \u05d5\u05dc\u05db\u05df \u05de\u05db\u05e0\u05d9\u05e1\u05d9\u05dd \u05dc\u05ea\u05d0 \u05db\u05de\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05d7\u05d3."], [386.1, "\u05d4\u05d4\u05db\u05e0\u05d4 \u05d9\u05e7\u05e8\u05d4: \u05e2\u05d9\u05d1\u05d5\u05d3 \u05de\u05d3\u05d5\u05d9\u05e7 \u05e9\u05dc \u05d4\u05e9\u05d5\u05dc\u05d9\u05d9\u05dd, \u05e0\u05d9\u05e7\u05d5\u05d9 \u05d5\u05e0\u05d9\u05d8\u05e8\u05d5\u05dc \u05de\u05d2\u05e0\u05d8\u05d9\u05d5\u05ea."], [391.9, "\u05d0\u05d1\u05dc \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05d1\u05d9\u05dd, \u05de\u05e2\u05d1\u05e8 \u05d0\u05d7\u05d3 \u05de\u05d7\u05dc\u05d9\u05e3 \u05e2\u05e9\u05e8\u05d5\u05ea \u05de\u05e2\u05d1\u05e8\u05d9\u05dd, \u05d1\u05dc\u05d9 \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9 \u05d5\u05d1\u05dc\u05d9 \u05d2\u05d6."], [398.9, "\u05d5\u05e4\u05d7\u05d5\u05ea \u05e2\u05d9\u05d5\u05d5\u05ea, \u05db\u05dc\u05d5\u05de\u05e8 \u05e4\u05d7\u05d5\u05ea \u05d9\u05d9\u05e9\u05d5\u05e8 \u05d5\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [403.8, "\u05d5\u05dc\u05db\u05df \u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05de\u05e9\u05ea\u05dc\u05de\u05ea \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05d1\u05d9\u05dd, \u05d9\u05e7\u05e8\u05d9\u05dd \u05d0\u05d5 \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd, \u05d5\u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e1\u05d3\u05e8\u05ea\u05d9 \u05d2\u05d3\u05d5\u05dc."], [411.8, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d0\u05dc\u05d5\u05de\u05ea \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05de\u05d4\u05d9\u05e8\u05d9\u05dd \u05d1\u05ea\u05d5\u05da \u05d5\u05d0\u05e7\u05d5\u05dd, \u05e9\u05de\u05e8\u05ea\u05db\u05ea \u05dc\u05e2\u05d5\u05de\u05e7 \u05e8\u05d1 \u05d1\u05ea\u05e4\u05e8 \u05e6\u05e8."], [418.5, "\u05e0\u05e7\u05d9, \u05de\u05d3\u05d5\u05d9\u05e7 \u05d5\u05d1\u05dc\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea, \u05d0\u05d1\u05dc \u05d3\u05d5\u05e8\u05e9 \u05e6\u05d9\u05d5\u05d3 \u05d9\u05e7\u05e8, \u05ea\u05d0 \u05d5\u05d0\u05e7\u05d5\u05dd \u05d5\u05d4\u05ea\u05d0\u05de\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea."], [425.4, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d7\u05d9\u05db\u05d5\u05da, \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd 42 \u05d5-43, \u05e9\u05de\u05d7\u05d1\u05e8 \u05de\u05ea\u05db\u05d5\u05ea \u05d1\u05dc\u05d9 \u05dc\u05d4\u05de\u05d9\u05e1 \u05d0\u05d5\u05ea\u05df."]]};
window.MH_TR["ch13"]={"t": "\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d7\u05d9\u05db\u05d5\u05da", "l": [[3.0, "\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d7\u05d9\u05db\u05d5\u05da, \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd 42 \u05d5-43, \u05de\u05d7\u05d1\u05e8 \u05de\u05ea\u05db\u05d5\u05ea \u05d1\u05dc\u05d9 \u05dc\u05d4\u05de\u05d9\u05e1 \u05d0\u05d5\u05ea\u05df."], [10.0, "\u05d4\u05d7\u05d5\u05dd \u05e0\u05d5\u05e6\u05e8 \u05de\u05d7\u05d9\u05db\u05d5\u05da, \u05d4\u05de\u05ea\u05db\u05ea \u05de\u05ea\u05e8\u05db\u05db\u05ea, \u05d5\u05dc\u05d7\u05e5 \u05d7\u05d6\u05e7 \u05de\u05d7\u05d1\u05e8 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05dc\u05d2\u05d5\u05e3 \u05d0\u05d7\u05d3."], [17.0, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d7\u05d9\u05db\u05d5\u05da \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1\u05d9, \u05d0\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05dc\u05d9\u05e0\u05d9\u05d0\u05e8\u05d9, \u05d0\u05ea FSW, \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd, \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05dd."], [27.5, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d7\u05d9\u05db\u05d5\u05da \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9, \u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05de\u05d4\u05e8, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d4\u05e9\u05e0\u05d9 \u05de\u05d5\u05d7\u05d6\u05e7 \u05d1\u05de\u05e7\u05d5\u05dd."], [33.8, "\u05dc\u05d5\u05d7\u05e6\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d6\u05d4 \u05d0\u05dc \u05d6\u05d4, \u05d5\u05d4\u05d7\u05d9\u05db\u05d5\u05da \u05de\u05d7\u05de\u05dd \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05de\u05d2\u05e2 \u05ea\u05d5\u05da \u05e9\u05e0\u05d9\u05d5\u05ea."], [39.0, "\u05d4\u05de\u05ea\u05db\u05ea \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05d7\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05e0\u05de\u05e1\u05d4: \u05d4\u05d9\u05d0 \u05de\u05ea\u05e8\u05db\u05db\u05ea, \u05db\u05de\u05d5 \u05e4\u05dc\u05e1\u05d8\u05dc\u05d9\u05e0\u05d4."], [45.3, "\u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05e8\u05da \u05e0\u05d3\u05d7\u05e7 \u05d4\u05d7\u05d5\u05e6\u05d4, \u05d5\u05dc\u05d5\u05e7\u05d7 \u05d0\u05d9\u05ea\u05d5 \u05d0\u05ea \u05d4\u05ea\u05d7\u05de\u05d5\u05e6\u05d5\u05ea \u05d5\u05d4\u05dc\u05db\u05dc\u05d5\u05da \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [51.1, "\u05d5\u05d0\u05d6 \u05e2\u05d5\u05e6\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1 \u05d5\u05de\u05d2\u05d1\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05dc\u05d7\u05e5: \u05d6\u05d4 \u05e9\u05dc\u05d1 \u05d4\u05d7\u05d9\u05e9\u05d5\u05dc."], [56.7, "\u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05ea\u05e7\u05e6\u05e8\u05d9\u05dd \u05de\u05e2\u05d8, \u05d5\u05e1\u05d1\u05d9\u05d1 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e0\u05d5\u05e6\u05e8\u05ea \u05d8\u05d1\u05e2\u05ea \u05e9\u05dc \u05d7\u05d5\u05de\u05e8 \u05e9\u05e0\u05d3\u05d7\u05e7 \u05d4\u05d7\u05d5\u05e6\u05d4, \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea flash."], [64.3, "\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4: \u05d7\u05d9\u05d1\u05d5\u05e8 \u05d1\u05db\u05dc \u05e9\u05d8\u05d7 \u05d4\u05d7\u05ea\u05da, \u05d1\u05dc\u05d9 \u05d0\u05de\u05d1\u05d8 \u05de\u05d5\u05ea\u05da, \u05d5\u05dc\u05db\u05df \u05d1\u05dc\u05d9 \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05d5\u05d1\u05dc\u05d9 \u05e1\u05d3\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd."], [72.4, "\u05db\u05dc \u05d4\u05de\u05d7\u05d6\u05d5\u05e8 \u05e0\u05de\u05e9\u05da \u05e9\u05e0\u05d9\u05d5\u05ea \u05d1\u05d5\u05d3\u05d3\u05d5\u05ea, \u05d5\u05d4\u05d5\u05d0 \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9 \u05dc\u05d2\u05de\u05e8\u05d9."], [77.5, "\u05d9\u05e9 \u05e9\u05ea\u05d9 \u05e9\u05d9\u05d8\u05d5\u05ea \u05d4\u05e0\u05e2\u05d4 \u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea."], [80.2, "\u05d1\u05d4\u05e0\u05e2\u05d4 \u05d9\u05e9\u05d9\u05e8\u05d4, \u05de\u05e0\u05d5\u05e2 \u05de\u05e1\u05d5\u05d1\u05d1 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e7\u05d1\u05d5\u05e2\u05d4, \u05d5\u05d1\u05e1\u05d5\u05e3 \u05d1\u05dc\u05dd \u05e2\u05d5\u05e6\u05e8 \u05d0\u05d5\u05ea\u05d5."], [86.8, "\u05d1\u05e9\u05d9\u05d8\u05ea \u05d4\u05d0\u05d9\u05e0\u05e8\u05e6\u05d9\u05d4 \u05de\u05e1\u05d5\u05d1\u05d1\u05d9\u05dd \u05d2\u05dc\u05d2\u05dc \u05ea\u05e0\u05d5\u05e4\u05d4, \u05de\u05e0\u05ea\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05e0\u05d5\u05e2, \u05d5\u05d4\u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05e9\u05d0\u05d2\u05d5\u05e8\u05d4 \u05d1\u05d2\u05dc\u05d2\u05dc \u05de\u05d1\u05e6\u05e2\u05ea \u05d0\u05ea \u05db\u05dc \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [95.4, "\u05d1\u05de\u05e1\u05e4\u05d5\u05e8 ISO, \u05d4\u05e0\u05e2\u05d4 \u05d9\u05e9\u05d9\u05e8\u05d4 \u05d4\u05d9\u05d0 \u05ea\u05d4\u05dc\u05d9\u05da 421, \u05d5\u05d0\u05d9\u05e0\u05e8\u05e6\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05ea\u05d4\u05dc\u05d9\u05da 422."], [104.1, "\u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd \u05d4\u05dd \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1, \u05dc\u05d7\u05e5 \u05d4\u05d7\u05d9\u05db\u05d5\u05da, \u05dc\u05d7\u05e5 \u05d4\u05d7\u05d9\u05e9\u05d5\u05dc, \u05d5\u05d6\u05de\u05df \u05d4\u05d7\u05d9\u05db\u05d5\u05da \u05d0\u05d5 \u05de\u05d9\u05d3\u05ea \u05d4\u05d4\u05ea\u05e7\u05e6\u05e8\u05d5\u05ea."], [113.0, "\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05d5\u05d3\u05d3\u05ea \u05d0\u05ea \u05d4\u05d4\u05ea\u05e7\u05e6\u05e8\u05d5\u05ea \u05d1\u05db\u05dc \u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05d6\u05d4 \u05d2\u05dd \u05db\u05dc\u05d9 \u05d1\u05e7\u05e8\u05d4: \u05d0\u05dd \u05d4\u05d9\u05d0 \u05d7\u05d5\u05e8\u05d2\u05ea, \u05d4\u05d7\u05dc\u05e7 \u05d7\u05e9\u05d5\u05d3."], [120.2, "\u05dc\u05e4\u05d7\u05d5\u05ea \u05d0\u05d7\u05d3 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05e2\u05d2\u05d5\u05dc, \u05db\u05de\u05d5 \u05de\u05d5\u05d8 \u05d0\u05d5 \u05e6\u05d9\u05e0\u05d5\u05e8, \u05db\u05d3\u05d9 \u05e9\u05d0\u05e4\u05e9\u05e8 \u05d9\u05d4\u05d9\u05d4 \u05dc\u05e1\u05d5\u05d1\u05d1 \u05d0\u05d5\u05ea\u05d5."], [127.1, "\u05d5\u05d1\u05e1\u05d5\u05e3 \u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4-flash \u05d1\u05d7\u05e8\u05d9\u05d8\u05d4, \u05d0\u05d5 \u05d1\u05db\u05dc\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da \u05e9\u05d1\u05ea\u05d5\u05da \u05d4\u05de\u05db\u05d5\u05e0\u05d4."], [132.9, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d7\u05d9\u05db\u05d5\u05da \u05dc\u05d9\u05e0\u05d9\u05d0\u05e8\u05d9, \u05d4\u05d7\u05dc\u05e7 \u05dc\u05d0 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1, \u05d0\u05dc\u05d0 \u05e0\u05e2 \u05d4\u05dc\u05d5\u05da \u05d5\u05e9\u05d5\u05d1 \u05d1\u05ea\u05e0\u05d5\u05e2\u05d4 \u05e7\u05e6\u05e8\u05d4 \u05d5\u05de\u05d4\u05d9\u05e8\u05d4."], [139.8, "\u05db\u05da \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05ea\u05da \u05d2\u05dd \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05d0\u05d9\u05e0\u05dd \u05e2\u05d2\u05d5\u05dc\u05d9\u05dd."], [143.1, "\u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d4\u05de\u05e4\u05d5\u05e8\u05e1\u05dd: \u05d7\u05d9\u05d1\u05d5\u05e8 \u05dc\u05d4\u05d1\u05d9\u05dd \u05dc\u05d3\u05d9\u05e1\u05e7 \u05d1\u05de\u05e0\u05d5\u05e2\u05d9 \u05e1\u05d9\u05dc\u05d5\u05df, \u05d5\u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 blisk."], [149.6, "\u05d1\u05dc\u05d9 \u05d1\u05e8\u05d2\u05d9\u05dd \u05d5\u05d1\u05dc\u05d9 \u05d7\u05e8\u05d9\u05e6\u05d9 \u05e0\u05e2\u05d9\u05dc\u05d4: \u05d4\u05d3\u05d9\u05e1\u05e7 \u05d5\u05d4\u05dc\u05d4\u05d1\u05d9\u05dd \u05d4\u05d5\u05e4\u05db\u05d9\u05dd \u05dc\u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3, \u05e7\u05dc \u05d5\u05d7\u05d6\u05e7 \u05d9\u05d5\u05ea\u05e8."], [157.5, "FSW, \u05ea\u05d4\u05dc\u05d9\u05da 43, \u05e4\u05d5\u05ea\u05d7 \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05d4 \u05d1\u05e9\u05e0\u05ea 1991, \u05d5\u05e9\u05d9\u05e0\u05d4 \u05d0\u05ea \u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd."], [166.4, "\u05db\u05d0\u05df \u05d4\u05db\u05dc\u05d9 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1, \u05d5\u05dc\u05d0 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd: \u05db\u05dc\u05d9 \u05e2\u05dd \u05db\u05ea\u05e3 \u05e8\u05d7\u05d1\u05d4 \u05d5\u05e4\u05d9\u05df \u05e7\u05e6\u05e8 \u05d1\u05e7\u05e6\u05d4."], [173.1, "\u05e9\u05e0\u05d9 \u05d4\u05dc\u05d5\u05d7\u05d5\u05ea \u05de\u05d5\u05e6\u05de\u05d3\u05d9\u05dd \u05d6\u05d4 \u05dc\u05d6\u05d4, \u05d5\u05de\u05d4\u05d5\u05d3\u05e7\u05d9\u05dd \u05d7\u05d6\u05e7 \u05e2\u05dc \u05de\u05e9\u05d8\u05d7 \u05ea\u05de\u05d9\u05db\u05d4, backing."], [178.9, "\u05d4\u05db\u05dc\u05d9 \u05d4\u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05e0\u05e0\u05e2\u05e5 \u05d1\u05e7\u05d5 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8, \u05e2\u05d3 \u05e9\u05d4\u05db\u05ea\u05e3 \u05e0\u05d5\u05d2\u05e2\u05ea \u05d1\u05e4\u05e0\u05d9 \u05d4\u05dc\u05d5\u05d7\u05d5\u05ea."], [184.5, "\u05d4\u05d7\u05d9\u05db\u05d5\u05da, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05de\u05ea\u05d7\u05ea \u05dc\u05db\u05ea\u05e3, \u05de\u05e8\u05db\u05da \u05d0\u05ea \u05d4\u05de\u05ea\u05db\u05ea \u05e1\u05d1\u05d9\u05d1 \u05d4\u05e4\u05d9\u05df."], [189.5, "\u05d4\u05db\u05dc\u05d9 \u05de\u05ea\u05e7\u05d3\u05dd \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05ea\u05e4\u05e8, \u05d5\u05d4\u05e4\u05d9\u05df \u05de\u05e2\u05e8\u05d1\u05dc \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd \u05d5\u05de\u05e2\u05d1\u05d9\u05e8 \u05d0\u05d5\u05ea\u05d5 \u05d0\u05d7\u05d5\u05e8\u05d4."], [196.3, "\u05d4\u05db\u05ea\u05e3 \u05dc\u05d5\u05d7\u05e6\u05ea \u05de\u05dc\u05de\u05e2\u05dc\u05d4 \u05d5\u05de\u05d7\u05e9\u05dc\u05ea \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8, \u05d5\u05de\u05d0\u05d7\u05d5\u05e8 \u05e0\u05e9\u05d0\u05e8 \u05ea\u05e4\u05e8 \u05de\u05d5\u05e6\u05e7, \u05e2\u05dd \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05d1\u05e6\u05d5\u05e8\u05ea \u05e7\u05e9\u05ea\u05d5\u05ea."], [204.7, "\u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd: \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e1\u05d9\u05d1\u05d5\u05d1, \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05ea\u05e7\u05d3\u05de\u05d5\u05ea, \u05db\u05d5\u05d7 \u05dc\u05d7\u05d9\u05e6\u05d4, \u05d5\u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05d8\u05d9\u05d4 \u05e7\u05d8\u05e0\u05d4 \u05e9\u05dc \u05d4\u05db\u05dc\u05d9."], [212.1, "\u05d4\u05db\u05d5\u05d7\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05de\u05db\u05d5\u05e0\u05d4 \u05e7\u05e9\u05d9\u05d7\u05d4 \u05d0\u05d5 \u05e8\u05d5\u05d1\u05d5\u05d8 \u05d7\u05d6\u05e7, \u05d5\u05e7\u05d9\u05d1\u05d5\u05e2 \u05d7\u05d6\u05e7."], [218.7, "\u05d5\u05d1\u05e1\u05d5\u05e3 \u05d4\u05ea\u05e4\u05e8, \u05db\u05e9\u05d4\u05db\u05dc\u05d9 \u05d9\u05d5\u05e6\u05d0, \u05e0\u05e9\u05d0\u05e8 \u05d7\u05d5\u05e8. \u05dc\u05db\u05df \u05de\u05e1\u05d9\u05d9\u05de\u05d9\u05dd \u05e2\u05dc \u05d7\u05ea\u05d9\u05db\u05ea \u05e2\u05d5\u05d3\u05e3 \u05e9\u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d0\u05d7\u05e8 \u05db\u05da, \u05d0\u05d5 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e4\u05d9\u05df \u05e0\u05e9\u05dc\u05e3."], [229.5, "FSW \u05de\u05e6\u05d8\u05d9\u05d9\u05df \u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05db\u05d5\u05dc\u05dc \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05db\u05de\u05d5 2024 \u05d5-7075, \u05e9\u05db\u05de\u05e2\u05d8 \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05ea\u05da \u05d1\u05d4\u05ea\u05db\u05d4 \u05d1\u05d2\u05dc\u05dc \u05e1\u05d3\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd."], [240.4, "\u05d2\u05dd \u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05de\u05d2\u05e0\u05d6\u05d9\u05d5\u05dd \u05de\u05ea\u05e8\u05ea\u05db\u05d9\u05dd \u05d4\u05d9\u05d8\u05d1."], [243.6, "\u05e4\u05dc\u05d3\u05d4 \u05d5\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d0\u05e4\u05e9\u05e8\u05d9\u05d9\u05dd, \u05d0\u05d1\u05dc \u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05db\u05dc\u05d9\u05dd \u05de\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05d5\u05d9\u05e7\u05e8\u05d9\u05dd, \u05e9\u05e0\u05e9\u05d7\u05e7\u05d9\u05dd \u05de\u05d4\u05e8."], [250.0, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05d1\u05e8 \u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05e6\u05d9\u05e8\u05d5\u05e3: \u05e4\u05dc\u05d3\u05d4 \u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05e0\u05d7\u05d5\u05e9\u05ea \u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e0\u05d9\u05e7\u05dc \u05dc\u05e4\u05dc\u05d3\u05d4."], [258.8, "\u05db\u05d9 \u05d1\u05dc\u05d9 \u05d4\u05ea\u05db\u05d4 \u05e0\u05d5\u05e6\u05e8\u05d5\u05ea \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05d5\u05ea \u05ea\u05e8\u05db\u05d5\u05d1\u05d5\u05ea \u05e9\u05d1\u05d9\u05e8\u05d5\u05ea, \u05de\u05d0\u05dc\u05d4 \u05e9\u05de\u05d5\u05e4\u05d9\u05e2\u05d5\u05ea \u05db\u05e9\u05e9\u05ea\u05d9 \u05d4\u05de\u05ea\u05db\u05d5\u05ea \u05e0\u05de\u05e1\u05d5\u05ea \u05d9\u05d7\u05d3."], [265.9, "\u05d5\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e9\u05e7\u05e9\u05d4 \u05dc\u05d7\u05de\u05dd \u05d1\u05d7\u05d9\u05db\u05d5\u05da, \u05db\u05de\u05d5 \u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d9\u05e7\u05d4 \u05e2\u05dd \u05d2\u05e8\u05e4\u05d9\u05d8, \u05e4\u05d7\u05d5\u05ea \u05de\u05ea\u05d0\u05d9\u05de\u05d9\u05dd."], [272.3, "\u05e8\u05d9\u05ea\u05d5\u05da \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9 \u05de\u05e9\u05de\u05e9 \u05d1\u05e6\u05d9\u05e8\u05d9 \u05d4\u05e0\u05e2\u05d4 \u05d5\u05e1\u05e8\u05e0\u05d9\u05dd, \u05d1\u05e9\u05e1\u05ea\u05d5\u05de\u05d9 \u05de\u05e0\u05d5\u05e2, \u05d1\u05de\u05d5\u05d8\u05d5\u05ea \u05e9\u05dc \u05d1\u05d5\u05db\u05e0\u05d5\u05ea \u05d4\u05d9\u05d3\u05e8\u05d0\u05d5\u05dc\u05d9\u05d5\u05ea, \u05d1\u05e6\u05d9\u05e0\u05d5\u05e8\u05d5\u05ea \u05e7\u05d9\u05d3\u05d5\u05d7 \u05d5\u05d1\u05e6\u05d9\u05e8 \u05e9\u05dc \u05d8\u05d5\u05e8\u05d1\u05d5."], [282.6, "FSW \u05de\u05e9\u05de\u05e9 \u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e1\u05d9\u05e4\u05d5\u05df \u05e9\u05dc \u05d0\u05d5\u05e0\u05d9\u05d5\u05ea, \u05d1\u05e7\u05e8\u05d5\u05e0\u05d5\u05ea \u05e8\u05db\u05d1\u05ea, \u05d1\u05de\u05d9\u05db\u05dc\u05d9 \u05d3\u05dc\u05e7 \u05e9\u05dc \u05e8\u05e7\u05d8\u05d5\u05ea \u05d5\u05d1\u05de\u05d2\u05e9\u05d9 \u05e1\u05d5\u05dc\u05dc\u05d5\u05ea \u05dc\u05e8\u05db\u05d1 \u05d7\u05e9\u05de\u05dc\u05d9."], [292.2, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea: \u05d0\u05d9\u05df \u05d4\u05ea\u05db\u05d4, \u05d5\u05dc\u05db\u05df \u05d0\u05d9\u05df \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea, \u05d0\u05d9\u05df \u05e1\u05d3\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd \u05d5\u05d0\u05d9\u05df \u05d4\u05ea\u05d6\u05d5\u05ea."], [299.6, "\u05d7\u05d5\u05d6\u05e7 \u05d2\u05d1\u05d5\u05d4, \u05e2\u05d9\u05d5\u05d5\u05ea \u05e7\u05d8\u05df, \u05d5\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d8\u05d5\u05d1\u05d5\u05ea \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8."], [304.3, "\u05d1\u05dc\u05d9 \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9, \u05d1\u05dc\u05d9 \u05d2\u05d6 \u05de\u05d2\u05df \u05d5\u05d1\u05dc\u05d9 \u05d0\u05d3\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05d7\u05d6\u05e8\u05ea\u05d9\u05d5\u05ea \u05de\u05dc\u05d0\u05d4."], [310.0, "\u05d4\u05d7\u05e1\u05e8\u05d5\u05e0\u05d5\u05ea: \u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05db\u05d1\u05d3\u05d5\u05ea \u05d5\u05d9\u05e7\u05e8\u05d5\u05ea, \u05d5\u05db\u05d5\u05d7\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05e9\u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05e7\u05d9\u05d1\u05d5\u05e2 \u05d7\u05d6\u05e7."], [316.2, "\u05e6\u05d5\u05e8\u05d5\u05ea \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05de\u05d5\u05d2\u05d1\u05dc\u05d5\u05ea: \u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9 \u05d7\u05dc\u05e7 \u05e2\u05d2\u05d5\u05dc, \u05d5\u05d1-FSW \u05d1\u05e2\u05d9\u05e7\u05e8 \u05ea\u05e4\u05e8\u05d9\u05dd \u05d9\u05e9\u05e8\u05d9\u05dd \u05d5\u05e4\u05e9\u05d5\u05d8\u05d9\u05dd."], [324.7, "\u05d5\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9 \u05d9\u05e9 \u05e4\u05d7\u05ea \u05d7\u05d5\u05de\u05e8 \u05d1\u05d4\u05ea\u05e7\u05e6\u05e8\u05d5\u05ea, \u05d5\u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e1\u05d9\u05e8 \u05d0\u05ea \u05d4-flash."], [330.8, "\u05d1-FSW, \u05d7\u05d5\u05dd \u05d0\u05d5 \u05dc\u05d7\u05e5 \u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7\u05d9\u05dd \u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05d7\u05dc\u05dc \u05d0\u05e8\u05d5\u05da \u05d1\u05e6\u05d5\u05e8\u05ea \u05de\u05e0\u05d4\u05e8\u05d4 \u05d1\u05ea\u05d5\u05da \u05d4\u05ea\u05e4\u05e8, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e6\u05d3 \u05d0\u05d7\u05d3 \u05e9\u05dc\u05d5."], [340.4, "\u05e4\u05d9\u05df \u05e7\u05e6\u05e8 \u05de\u05d3\u05d9 \u05de\u05e9\u05d0\u05d9\u05e8 \u05d1\u05e9\u05d5\u05e8\u05e9 \u05e7\u05d5 \u05e9\u05dc\u05d0 \u05d4\u05ea\u05d7\u05d1\u05e8. \u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 kissing bond, \u05d5\u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05dc\u05d2\u05dc\u05d5\u05ea \u05d0\u05d5\u05ea\u05d5."], [348.4, "\u05d7\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05d9\u05d5\u05e6\u05e8 \u05d4\u05e8\u05d1\u05d4 flash \u05d1\u05e6\u05d3\u05d3\u05d9\u05dd, \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05de\u05d7\u05d5\u05e1\u05e4\u05e1\u05d9\u05dd \u05d5\u05ea\u05e4\u05e8 \u05d3\u05e7 \u05de\u05d3\u05d9."], [355.0, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9, \u05dc\u05d7\u05e5 \u05d0\u05d5 \u05d6\u05de\u05df \u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7\u05d9\u05dd \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05d0\u05d6\u05d5\u05e8 \u05dc\u05d0 \u05de\u05d7\u05d5\u05d1\u05e8, \u05dc\u05e8\u05d5\u05d1 \u05d1\u05de\u05e8\u05db\u05d6 \u05d4\u05d7\u05ea\u05da."], [363.0, "\u05d5\u05dc\u05db\u05dc\u05d5\u05da \u05d0\u05d5 \u05e6\u05d1\u05e2 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05de\u05d2\u05e2, \u05d0\u05d5 \u05d6\u05de\u05df \u05d7\u05d9\u05db\u05d5\u05da \u05e7\u05e6\u05e8 \u05de\u05d3\u05d9, \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d7\u05de\u05d5\u05e6\u05d5\u05ea \u05d1\u05ea\u05d5\u05da \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8."], [370.1, "\u05dc\u05db\u05df \u05de\u05d1\u05e7\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05e2\u05e6\u05de\u05d5: \u05de\u05d4\u05d9\u05e8\u05d5\u05ea, \u05db\u05d5\u05d7\u05d5\u05ea \u05d5\u05d4\u05ea\u05e7\u05e6\u05e8\u05d5\u05ea \u05e0\u05de\u05d3\u05d3\u05d9\u05dd \u05d5\u05e0\u05e8\u05e9\u05de\u05d9\u05dd \u05d1\u05db\u05dc \u05e8\u05d9\u05ea\u05d5\u05da."], [377.5, "\u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d3\u05d5\u05d2\u05de\u05d0\u05d5\u05ea \u05d1\u05d7\u05d9\u05ea\u05d5\u05da, \u05d1\u05db\u05e4\u05d9\u05e4\u05d4 \u05d5\u05d1\u05d0\u05d5\u05dc\u05d8\u05e8\u05e1\u05d0\u05d5\u05e0\u05d3."], [382.2, "\u05d4\u05d4\u05e9\u05e7\u05e2\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4: \u05de\u05db\u05d5\u05e0\u05d4 \u05db\u05d1\u05d3\u05d4 \u05d5\u05e7\u05e9\u05d9\u05d7\u05d4, \u05e2\u05dd \u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05d9\u05d3\u05e8\u05d0\u05d5\u05dc\u05d9\u05ea \u05d7\u05d6\u05e7\u05d4."], [388.2, "\u05d0\u05d1\u05dc \u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9 \u05d4\u05de\u05d7\u05d6\u05d5\u05e8 \u05d4\u05d5\u05d0 \u05e9\u05e0\u05d9\u05d5\u05ea, \u05d1\u05dc\u05d9 \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05de\u05ea\u05db\u05dc\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05de\u05d7\u05d9\u05e8 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d4\u05de\u05d5\u05e0\u05d9 \u05e0\u05de\u05d5\u05da \u05de\u05d0\u05d5\u05d3."], [396.7, "\u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05d0\u05d5\u05e8\u05da \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05d2\u05dc\u05dc \u05d4\u05d4\u05ea\u05e7\u05e6\u05e8\u05d5\u05ea, \u05d5\u05dc\u05d4\u05e1\u05d9\u05e8 \u05d0\u05ea \u05d4-flash \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3."], [402.1, "\u05d1-FSW \u05d4\u05db\u05dc\u05d9 \u05d5\u05d4\u05e7\u05d9\u05d1\u05d5\u05e2 \u05d9\u05e7\u05e8\u05d9\u05dd, \u05d5\u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d1\u05e4\u05dc\u05d3\u05d4 \u05e0\u05de\u05d5\u05db\u05d4."], [407.8, "\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d4\u05d5\u05d0 \u05d7\u05d5\u05e1\u05da \u05d4\u05db\u05e0\u05ea \u05e9\u05d5\u05dc\u05d9\u05d9\u05dd, \u05d9\u05d9\u05e9\u05d5\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d5\u05ea\u05d9\u05e7\u05d5\u05e0\u05d9 \u05e4\u05d2\u05de\u05d9\u05dd."], [414.3, "\u05d5\u05dc\u05db\u05df \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d7\u05d9\u05db\u05d5\u05da \u05de\u05e9\u05ea\u05dc\u05dd \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e1\u05d3\u05e8\u05ea\u05d9, \u05d1\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd, \u05d5\u05d1\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e9\u05dc \u05de\u05ea\u05db\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea."], [422.2, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d7\u05d9\u05db\u05d5\u05da \u05de\u05d7\u05d1\u05e8 \u05d1\u05de\u05e6\u05d1 \u05de\u05d5\u05e6\u05e7, \u05e2\u05dd \u05d7\u05d5\u05dd \u05de\u05d7\u05d9\u05db\u05d5\u05da \u05d5\u05dc\u05d7\u05e5 \u05e9\u05de\u05d7\u05e9\u05dc."], [429.3, "\u05e1\u05d9\u05d1\u05d5\u05d1\u05d9 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05d2\u05d5\u05dc\u05d9\u05dd, \u05dc\u05d9\u05e0\u05d9\u05d0\u05e8\u05d9 \u05dc\u05dc\u05d4\u05d1\u05d9\u05dd, \u05d5-FSW \u05dc\u05dc\u05d5\u05d7\u05d5\u05ea \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd."], [436.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05d4\u05dc\u05d7\u05de\u05d4 \u05e8\u05db\u05d4 \u05d5\u05d4\u05dc\u05d7\u05de\u05d4 \u05e7\u05e9\u05d4, \u05e9\u05d1\u05d4\u05df \u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1 \u05d1\u05db\u05dc\u05dc \u05dc\u05d0 \u05e0\u05de\u05e1\u05d4."]]};
window.MH_TR["ch14"]={"t": "\u05d4\u05dc\u05d7\u05de\u05d4 \u05e8\u05db\u05d4 \u05d5\u05e7\u05e9\u05d4", "l": [[3.0, "\u05d4\u05dc\u05d7\u05de\u05d4 \u05de\u05d7\u05d1\u05e8\u05ea \u05de\u05ea\u05db\u05d5\u05ea \u05d1\u05e2\u05d6\u05e8\u05ea \u05de\u05ea\u05db\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05e9\u05e0\u05de\u05e1\u05d4, \u05d1\u05d6\u05de\u05df \u05e9\u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1 \u05e0\u05e9\u05d0\u05e8\u05ea \u05de\u05d5\u05e6\u05e7\u05d4."], [10.1, "\u05d4\u05d2\u05d1\u05d5\u05dc \u05d4\u05d5\u05d0 450 \u05de\u05e2\u05dc\u05d5\u05ea: \u05de\u05ea\u05d7\u05ea\u05d9\u05d5 \u05d6\u05d5 \u05d4\u05dc\u05d7\u05de\u05d4 \u05e8\u05db\u05d4, \u05d5\u05de\u05e2\u05dc\u05d9\u05d5 \u05d4\u05dc\u05d7\u05de\u05d4 \u05e7\u05e9\u05d4."], [18.4, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df, \u05d0\u05ea \u05e9\u05e0\u05d9 \u05e1\u05d5\u05d2\u05d9 \u05d4\u05d4\u05dc\u05d7\u05de\u05d4, \u05d0\u05ea \u05e9\u05d9\u05d8\u05d5\u05ea \u05d4\u05d7\u05d9\u05de\u05d5\u05dd, \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd, \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d4."], [27.8, "\u05db\u05d3\u05d9 \u05e9\u05d4\u05dc\u05d7\u05de\u05d4 \u05ea\u05e6\u05dc\u05d9\u05d7, \u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05d4\u05de\u05d5\u05ea\u05db\u05ea \u05e6\u05e8\u05d9\u05db\u05d4 \u05dc\u05d4\u05e8\u05d8\u05d9\u05d1 \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05de\u05ea\u05db\u05ea: \u05dc\u05d4\u05ea\u05e4\u05e9\u05d8 \u05e2\u05dc\u05d9\u05d4\u05dd, \u05d5\u05dc\u05d0 \u05dc\u05d4\u05ea\u05db\u05d3\u05e8\u05e8 \u05db\u05de\u05d5 \u05d8\u05d9\u05e4\u05ea \u05de\u05d9\u05dd \u05e2\u05dc \u05e9\u05de\u05df."], [38.3, "\u05d4\u05e8\u05d8\u05d1\u05d4 \u05d8\u05d5\u05d1\u05d4 \u05d0\u05e4\u05e9\u05e8\u05d9\u05ea \u05e8\u05e7 \u05e2\u05dc \u05de\u05ea\u05db\u05ea \u05e0\u05e7\u05d9\u05d9\u05d4, \u05d1\u05dc\u05d9 \u05e9\u05db\u05d1\u05ea \u05ea\u05d7\u05de\u05d5\u05e6\u05ea."], [43.0, "\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1-flux: \u05d4\u05d5\u05d0 \u05de\u05e1\u05d9\u05e8 \u05d0\u05ea \u05d4\u05ea\u05d7\u05de\u05d5\u05e6\u05d5\u05ea, \u05d5\u05de\u05d2\u05df \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d1\u05d6\u05de\u05df \u05d4\u05d7\u05d9\u05de\u05d5\u05dd."], [49.3, "\u05d4\u05de\u05e8\u05d5\u05d5\u05d7 \u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e6\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d5\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05e0\u05e9\u05d0\u05d1\u05ea \u05dc\u05ea\u05d5\u05db\u05d5 \u05de\u05e2\u05e6\u05de\u05d4, \u05d1\u05db\u05d5\u05d7 \u05e0\u05d9\u05de\u05d9, \u05db\u05de\u05d5 \u05de\u05d9\u05dd \u05d1\u05e6\u05d9\u05e0\u05d5\u05e8 \u05d3\u05e7."], [57.6, "\u05d1\u05d4\u05dc\u05d7\u05de\u05d4 \u05e7\u05e9\u05d4, \u05d4\u05de\u05e8\u05d5\u05d5\u05d7 \u05d4\u05d8\u05d9\u05e4\u05d5\u05e1\u05d9 \u05d4\u05d5\u05d0 \u05d1\u05d9\u05df 0.05 \u05dc-0.15 \u05de\u05f4\u05de."], [63.9, "\u05de\u05e8\u05d5\u05d5\u05d7 \u05d2\u05d3\u05d5\u05dc \u05de\u05d3\u05d9 \u05de\u05d7\u05dc\u05d9\u05e9 \u05d0\u05ea \u05d4\u05db\u05d5\u05d7 \u05d4\u05e0\u05d9\u05de\u05d9, \u05d5\u05de\u05e8\u05d5\u05d5\u05d7 \u05e7\u05d8\u05df \u05de\u05d3\u05d9 \u05dc\u05d0 \u05de\u05d0\u05e4\u05e9\u05e8 \u05dc\u05de\u05ea\u05db\u05ea \u05dc\u05d4\u05d9\u05db\u05e0\u05e1."], [70.7, "\u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05de\u05d2\u05e2 \u05e0\u05d5\u05e6\u05e8\u05ea \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05e9\u05d1\u05d4 \u05d4\u05de\u05ea\u05db\u05d5\u05ea \u05de\u05ea\u05e2\u05e8\u05d1\u05d1\u05d5\u05ea, \u05d5\u05d6\u05d4 \u05de\u05d4 \u05e9\u05de\u05d7\u05d6\u05d9\u05e7 \u05d0\u05ea \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8."], [77.6, "\u05d5\u05d1\u05d2\u05dc\u05dc \u05e9\u05d8\u05d7 \u05d4\u05de\u05d2\u05e2 \u05d4\u05d2\u05d3\u05d5\u05dc, \u05d7\u05d9\u05d1\u05d5\u05e8 \u05d1\u05d7\u05e4\u05d9\u05e4\u05d4 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05d7\u05d6\u05e7 \u05d9\u05d5\u05ea\u05e8 \u05de\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05e2\u05e6\u05de\u05d4."], [84.6, "\u05d4\u05dc\u05d7\u05de\u05d4 \u05e8\u05db\u05d4, \u05ea\u05d4\u05dc\u05d9\u05da 94, \u05e2\u05d5\u05d1\u05d3\u05ea \u05de\u05ea\u05d7\u05ea \u05dc-450 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e1\u05d1\u05d9\u05d1 200 \u05e2\u05d3 250."], [94.0, "\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05d1\u05d5\u05e1\u05e1\u05ea \u05e2\u05dc \u05d1\u05d3\u05d9\u05dc: \u05e4\u05e2\u05dd \u05d1\u05d3\u05d9\u05dc \u05e2\u05d5\u05e4\u05e8\u05ea, \u05d5\u05d4\u05d9\u05d5\u05dd \u05d1\u05e2\u05d9\u05e7\u05e8 \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d1\u05dc\u05d9 \u05e2\u05d5\u05e4\u05e8\u05ea, \u05e2\u05dd \u05de\u05e2\u05d8 \u05db\u05e1\u05e3 \u05d5\u05e0\u05d7\u05d5\u05e9\u05ea."], [103.0, "\u05d4\u05d9\u05d0 \u05de\u05e9\u05de\u05e9\u05ea \u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05e7\u05d4, \u05d1\u05e6\u05e0\u05e8\u05ea \u05e0\u05d7\u05d5\u05e9\u05ea \u05dc\u05de\u05d9\u05dd, \u05d1\u05e8\u05d3\u05d9\u05d0\u05d8\u05d5\u05e8\u05d9\u05dd \u05d5\u05d1\u05e7\u05d5\u05e4\u05e1\u05d0\u05d5\u05ea \u05e9\u05d9\u05de\u05d5\u05e8\u05d9\u05dd."], [109.5, "\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d1\u05de\u05dc\u05d7\u05dd, \u05d1\u05dc\u05d4\u05d1\u05d4, \u05d0\u05d5 \u05d1\u05ea\u05e0\u05d5\u05e8 reflow, \u05e9\u05d1\u05d5 \u05de\u05d5\u05dc\u05d7\u05de\u05d9\u05dd \u05de\u05d0\u05d5\u05ea \u05e8\u05db\u05d9\u05d1\u05d9\u05dd \u05e2\u05dc \u05db\u05e8\u05d8\u05d9\u05e1 \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea."], [117.8, "\u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05e7\u05d4 \u05d4-flux \u05e2\u05d3\u05d9\u05df, \u05e2\u05dc \u05d1\u05e1\u05d9\u05e1 \u05e7\u05d5\u05dc\u05d5\u05e4\u05d5\u05e0\u05d9\u05d5\u05dd. \u05d1\u05e6\u05e0\u05e8\u05ea \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1-flux \u05d7\u05d5\u05de\u05e6\u05d9, \u05e9\u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05dc\u05e0\u05e7\u05d5\u05ea \u05d0\u05d7\u05e8 \u05db\u05da."], [126.4, "\u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc \u05d4\u05dc\u05d7\u05de\u05d4 \u05e8\u05db\u05d4 \u05e0\u05de\u05d5\u05da, \u05d5\u05dc\u05db\u05df \u05d4\u05d9\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05d0\u05d9\u05d8\u05d5\u05dd \u05d5\u05dc\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d7\u05e9\u05de\u05dc\u05d9, \u05d5\u05dc\u05d0 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e0\u05d5\u05e9\u05d0\u05d9\u05dd \u05e2\u05d5\u05de\u05e1."], [134.5, "\u05d5\u05d4\u05d9\u05d0 \u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d5\u05ea, \u05db\u05d9 \u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05ea\u05e8\u05db\u05db\u05ea."], [140.0, "\u05d4\u05dc\u05d7\u05de\u05d4 \u05e7\u05e9\u05d4, \u05ea\u05d4\u05dc\u05d9\u05da 91, \u05e2\u05d5\u05d1\u05d3\u05ea \u05de\u05e2\u05dc 450 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05df 600 \u05dc-1100."], [149.0, "\u05de\u05ea\u05db\u05d5\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05e2\u05dc \u05d1\u05e1\u05d9\u05e1 \u05db\u05e1\u05e3 \u05e0\u05de\u05e1\u05d5\u05ea \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 600 \u05e2\u05d3 800 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d6\u05d5\u05e8\u05de\u05d5\u05ea \u05d4\u05d9\u05d8\u05d1, \u05d5\u05de\u05ea\u05d0\u05d9\u05de\u05d5\u05ea \u05db\u05de\u05e2\u05d8 \u05dc\u05db\u05dc \u05de\u05ea\u05db\u05ea."], [158.1, "\u05e0\u05d7\u05d5\u05e9\u05ea \u05d6\u05e8\u05d7\u05df \u05de\u05e9\u05de\u05e9\u05ea \u05dc\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e0\u05d7\u05d5\u05e9\u05ea \u05dc\u05e0\u05d7\u05d5\u05e9\u05ea, \u05d1\u05dc\u05d9 flux, \u05db\u05d9 \u05d4\u05d6\u05e8\u05d7\u05df \u05de\u05e0\u05e7\u05d4 \u05d0\u05ea \u05d4\u05ea\u05d7\u05de\u05d5\u05e6\u05d5\u05ea \u05d1\u05e2\u05e6\u05de\u05d5."], [165.8, "\u05e4\u05dc\u05d9\u05d6 \u05d5\u05d1\u05e8\u05d5\u05e0\u05d6\u05d4 \u05d6\u05d5\u05dc\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8, \u05d5\u05de\u05e9\u05de\u05e9\u05d9\u05dd \u05dc\u05e4\u05dc\u05d3\u05d4 \u05d5\u05dc\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d9\u05e7\u05d4."], [170.8, "\u05de\u05ea\u05db\u05d5\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05e2\u05dc \u05d1\u05e1\u05d9\u05e1 \u05e0\u05d9\u05e7\u05dc \u05e2\u05d5\u05d1\u05d3\u05d5\u05ea \u05de\u05e2\u05dc 1000 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd, \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd \u05d1\u05de\u05e0\u05d5\u05e2\u05d9\u05dd."], [179.5, "\u05d5\u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d9\u05e9 \u05de\u05ea\u05db\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05e9\u05dc \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df, \u05e9\u05e0\u05de\u05e1\u05d4 \u05e8\u05e7 \u05de\u05e2\u05d8 \u05de\u05ea\u05d7\u05ea \u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05e2\u05e6\u05de\u05d5, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05e9\u05dc\u05d9\u05d8\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d1\u05d7\u05d5\u05dd."], [189.5, "\u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d4\u05d5\u05d0 \u05d7\u05e4\u05d9\u05e4\u05d4, \u05d1\u05d0\u05d5\u05e8\u05da \u05e9\u05dc \u05d1\u05e2\u05e8\u05da \u05e4\u05d9 3 \u05de\u05e2\u05d5\u05d1\u05d9 \u05d4\u05d7\u05dc\u05e7 \u05d4\u05d3\u05e7."], [195.6, "\u05de\u05e0\u05d9\u05d7\u05d9\u05dd \u05d0\u05ea \u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05d1\u05e6\u05d3 \u05d0\u05d7\u05d3, \u05d5\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e2\u05d3 \u05e9\u05d4\u05d9\u05d0 \u05e0\u05e9\u05d0\u05d1\u05ea \u05e2\u05d3 \u05d4\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9."], [201.9, "\u05d9\u05e9 \u05db\u05de\u05d4 \u05e9\u05d9\u05d8\u05d5\u05ea \u05d7\u05d9\u05de\u05d5\u05dd \u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea."], [204.4, "\u05d1\u05dc\u05d4\u05d1\u05d4, \u05d4\u05dc\u05d7\u05de\u05d4 \u05d9\u05d3\u05e0\u05d9\u05ea: \u05d2\u05de\u05d9\u05e9\u05d4 \u05d5\u05d6\u05d5\u05dc\u05d4, \u05d0\u05d1\u05dc \u05d4\u05d0\u05d9\u05db\u05d5\u05ea \u05ea\u05dc\u05d5\u05d9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d1\u05de\u05e4\u05e2\u05d9\u05dc."], [211.1, "\u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4, \u05e1\u05dc\u05d9\u05dc \u05de\u05d7\u05de\u05dd \u05e8\u05e7 \u05d0\u05ea \u05d0\u05d6\u05d5\u05e8 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8, \u05ea\u05d5\u05da \u05e9\u05e0\u05d9\u05d5\u05ea, \u05d5\u05d1\u05d0\u05d5\u05ea\u05d4 \u05e6\u05d5\u05e8\u05d4 \u05d1\u05db\u05dc \u05e4\u05e2\u05dd. \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e1\u05d3\u05e8\u05ea\u05d9."], [219.5, "\u05d1\u05ea\u05e0\u05d5\u05e8, \u05e2\u05dd \u05d0\u05d8\u05de\u05d5\u05e1\u05e4\u05d9\u05e8\u05d4 \u05de\u05d1\u05d5\u05e7\u05e8\u05ea \u05d0\u05d5 \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd, \u05de\u05dc\u05d7\u05d9\u05de\u05d9\u05dd \u05de\u05d0\u05d5\u05ea \u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea, \u05d5\u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d2\u05dd \u05d1\u05dc\u05d9 flux."], [228.1, "\u05d9\u05e9 \u05d2\u05dd \u05d4\u05dc\u05d7\u05de\u05d4 \u05d1\u05d8\u05d1\u05d9\u05dc\u05d4 \u05d1\u05d0\u05de\u05d1\u05d8, \u05d5\u05d4\u05dc\u05d7\u05de\u05d4 \u05d1\u05d7\u05d9\u05de\u05d5\u05dd \u05d7\u05e9\u05de\u05dc\u05d9 \u05d1\u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea."], [234.3, "\u05d5\u05d9\u05e9 braze welding, \u05ea\u05d4\u05dc\u05d9\u05da 97: \u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05d5\u05e0\u05d7\u05ea \u05db\u05de\u05d5 \u05ea\u05e4\u05e8 \u05e8\u05d9\u05ea\u05d5\u05da, \u05d1\u05dc\u05d9 \u05db\u05d5\u05d7 \u05e0\u05d9\u05de\u05d9. \u05db\u05da \u05de\u05ea\u05e7\u05e0\u05d9\u05dd \u05dc\u05de\u05e9\u05dc \u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d9\u05e7\u05d4 \u05e2\u05dd \u05d1\u05e8\u05d5\u05e0\u05d6\u05d4."], [246.5, "\u05d4\u05dc\u05d7\u05de\u05d4 \u05de\u05d7\u05d1\u05e8\u05ea \u05d1\u05e7\u05dc\u05d5\u05ea \u05de\u05ea\u05db\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea: \u05e0\u05d7\u05d5\u05e9\u05ea \u05dc\u05e4\u05dc\u05d3\u05d4, \u05e4\u05dc\u05d9\u05d6 \u05dc\u05d0\u05dc-\u05d7\u05dc\u05d3."], [253.2, "\u05db\u05da \u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05e4\u05dc\u05d7\u05d9 \u05e7\u05e8\u05d1\u05d9\u05d3 \u05dc\u05d2\u05d5\u05e3 \u05de\u05e4\u05dc\u05d3\u05d4, \u05d1\u05db\u05dc\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da, \u05d1\u05de\u05e7\u05d3\u05d7\u05d9\u05dd \u05d5\u05d1\u05de\u05e1\u05d5\u05e8\u05d9\u05dd."], [259.8, "\u05e2\u05dd \u05de\u05ea\u05db\u05d5\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05d9\u05d5\u05d7\u05d3\u05d5\u05ea \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05d1\u05e8 \u05d0\u05e4\u05d9\u05dc\u05d5 \u05e7\u05e8\u05de\u05d9\u05e7\u05d4 \u05dc\u05de\u05ea\u05db\u05ea."], [264.5, "\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d1\u05d2\u05dc\u05dc \u05e9\u05db\u05d1\u05ea \u05d4\u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05d4\u05e2\u05de\u05d9\u05d3\u05d4 \u05e9\u05dc\u05d5, \u05d5\u05d0\u05dc-\u05d7\u05dc\u05d3 \u05d3\u05d5\u05e8\u05e9 flux \u05e4\u05e2\u05d9\u05dc \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d0\u05d5 \u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd."], [273.1, "\u05d5\u05e4\u05e2\u05dd \u05d4\u05d9\u05d4 \u05e7\u05d3\u05de\u05d9\u05d5\u05dd \u05d1\u05d7\u05dc\u05e7 \u05de\u05de\u05ea\u05db\u05d5\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05e9\u05dc \u05db\u05e1\u05e3. \u05d4\u05d5\u05d0 \u05e8\u05e2\u05d9\u05dc, \u05d5\u05d4\u05d9\u05d5\u05dd \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d1\u05dc\u05d9 \u05e7\u05d3\u05de\u05d9\u05d5\u05dd."], [282.1, "\u05d4\u05dc\u05d7\u05de\u05d4 \u05e7\u05e9\u05d4 \u05de\u05e9\u05de\u05e9\u05ea \u05d1\u05e6\u05e0\u05e8\u05ea \u05de\u05d9\u05d6\u05d5\u05d2 \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8, \u05d1\u05de\u05d7\u05dc\u05d9\u05e4\u05d9 \u05d7\u05d5\u05dd, \u05d1\u05e8\u05d3\u05d9\u05d0\u05d8\u05d5\u05e8\u05d9\u05dd \u05e9\u05dc \u05e8\u05db\u05d1, \u05d1\u05db\u05dc\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da, \u05d1\u05ea\u05db\u05e9\u05d9\u05d8\u05d9\u05dd \u05d5\u05d1\u05e9\u05dc\u05d3\u05d5\u05ea \u05d0\u05d5\u05e4\u05e0\u05d9\u05d9\u05dd."], [292.7, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea: \u05d7\u05d5\u05dd \u05e0\u05de\u05d5\u05da \u05d9\u05d5\u05ea\u05e8 \u05de\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05dc\u05db\u05df \u05e4\u05d7\u05d5\u05ea \u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05e4\u05d7\u05d5\u05ea \u05e9\u05d9\u05e0\u05d5\u05d9 \u05d1\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc \u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1."], [300.4, "\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05d1\u05e8 \u05de\u05ea\u05db\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea \u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05de\u05d0\u05d5\u05d3."], [304.1, "\u05d1\u05ea\u05e0\u05d5\u05e8 \u05de\u05dc\u05d7\u05d9\u05de\u05d9\u05dd \u05d4\u05e8\u05d1\u05d4 \u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea, \u05d5\u05d4\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd \u05e0\u05e7\u05d9\u05d9\u05dd \u05d5\u05d0\u05d8\u05d5\u05de\u05d9\u05dd, \u05db\u05de\u05e2\u05d8 \u05d1\u05dc\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d0\u05d7\u05e8\u05d9."], [311.3, "\u05d4\u05d7\u05e1\u05e8\u05d5\u05e0\u05d5\u05ea: \u05d4\u05d7\u05d5\u05d6\u05e7 \u05e0\u05de\u05d5\u05da \u05de\u05d6\u05d4 \u05e9\u05dc \u05e8\u05d9\u05ea\u05d5\u05da, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05d4\u05dc\u05d7\u05de\u05d4 \u05e8\u05db\u05d4."], [317.1, "\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05de\u05d5\u05d2\u05d1\u05dc\u05ea \u05e2\u05dc \u05d9\u05d3\u05d9 \u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9."], [321.5, "\u05e6\u05e8\u05d9\u05da \u05de\u05e8\u05d5\u05d5\u05d7 \u05de\u05d3\u05d5\u05d9\u05e7 \u05d5\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e0\u05e7\u05d9\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05d5\u05e9\u05d0\u05e8\u05d9\u05d5\u05ea flux \u05e2\u05dc\u05d5\u05dc\u05d5\u05ea \u05dc\u05d2\u05e8\u05d5\u05dd \u05dc\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."], [328.7, "\u05d5\u05d1\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e9\u05dc \u05de\u05ea\u05db\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d9\u05d5\u05d5\u05e6\u05e8 \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d2\u05dc\u05d5\u05d5\u05e0\u05d9\u05ea \u05d1\u05e1\u05d1\u05d9\u05d1\u05d4 \u05dc\u05d7\u05d4."], [334.6, "\u05d4\u05e4\u05d2\u05dd \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d4\u05d5\u05d0 \u05de\u05d9\u05dc\u05d5\u05d9 \u05d7\u05dc\u05e7\u05d9: \u05d7\u05dc\u05dc\u05d9\u05dd \u05d1\u05ea\u05d5\u05da \u05d4\u05d7\u05e4\u05d9\u05e4\u05d4, \u05de\u05de\u05e8\u05d5\u05d5\u05d7 \u05dc\u05d0 \u05e0\u05db\u05d5\u05df \u05d0\u05d5 \u05de\u05d7\u05d9\u05de\u05d5\u05dd \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3."], [342.4, "flux \u05e9\u05dc\u05d0 \u05d9\u05e6\u05d0 \u05e0\u05e9\u05d0\u05e8 \u05db\u05dc\u05d5\u05d0 \u05d1\u05d7\u05d9\u05d1\u05d5\u05e8, \u05de\u05d7\u05dc\u05d9\u05e9 \u05d0\u05d5\u05ea\u05d5 \u05d5\u05d2\u05d5\u05e8\u05dd \u05dc\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."], [348.1, "\u05d4\u05e8\u05d8\u05d1\u05d4 \u05d2\u05e8\u05d5\u05e2\u05d4, \u05db\u05e9\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05ea\u05db\u05d3\u05e8\u05e8\u05ea \u05d5\u05dc\u05d0 \u05de\u05ea\u05e4\u05e9\u05d8\u05ea, \u05e0\u05d5\u05d1\u05e2\u05ea \u05de\u05de\u05e9\u05d8\u05d7 \u05de\u05dc\u05d5\u05db\u05dc\u05da \u05d0\u05d5 \u05de-flux \u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05dd."], [356.4, "\u05d7\u05d9\u05de\u05d5\u05dd \u05d9\u05ea\u05e8 \u05e9\u05d5\u05e8\u05e3 \u05d0\u05ea \u05d4-flux, \u05d5\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05ea\u05d7\u05d9\u05dc\u05d4 \u05dc\u05d4\u05de\u05d9\u05e1 \u05d5\u05dc\u05d0\u05db\u05d5\u05dc \u05d0\u05ea \u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1."], [363.1, "\u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05e7\u05d4, \u05d4\u05dc\u05d7\u05de\u05d4 \u05e7\u05e8\u05d4 \u05e0\u05e8\u05d0\u05d9\u05ea \u05d0\u05e4\u05d5\u05e8\u05d4 \u05d5\u05e2\u05db\u05d5\u05e8\u05d4, \u05d5\u05d4\u05de\u05d2\u05e2 \u05d4\u05d7\u05e9\u05de\u05dc\u05d9 \u05dc\u05d0 \u05d0\u05de\u05d9\u05df."], [369.6, "\u05d5\u05d1\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e7\u05e8\u05d1\u05d9\u05d3 \u05dc\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dc\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d5\u05e4\u05d9\u05e2 \u05e1\u05d3\u05e7\u05d9\u05dd, \u05db\u05d9 \u05e9\u05ea\u05d9 \u05d4\u05de\u05ea\u05db\u05d5\u05ea \u05de\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea \u05d1\u05e7\u05e6\u05d1 \u05e9\u05d5\u05e0\u05d4 \u05d1\u05d6\u05de\u05df \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8."], [377.3, "\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d1\u05e2\u05d9\u05df \u05e9\u05d4\u05de\u05ea\u05db\u05ea \u05d9\u05e6\u05d0\u05d4 \u05d1\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9 \u05e9\u05dc \u05d4\u05d7\u05e4\u05d9\u05e4\u05d4, \u05d1\u05d1\u05d3\u05d9\u05e7\u05ea \u05d3\u05dc\u05d9\u05e4\u05d4, \u05d1\u05d0\u05d5\u05dc\u05d8\u05e8\u05e1\u05d0\u05d5\u05e0\u05d3, \u05d1\u05e8\u05e0\u05d8\u05d2\u05df \u05d5\u05d1\u05d7\u05d9\u05ea\u05d5\u05da \u05d3\u05d5\u05d2\u05de\u05d0\u05d5\u05ea."], [386.7, "\u05de\u05ea\u05db\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05e2\u05dc \u05d1\u05e1\u05d9\u05e1 \u05db\u05e1\u05e3 \u05d9\u05e7\u05e8\u05d4, \u05d5\u05d4\u05de\u05d7\u05d9\u05e8 \u05e2\u05d5\u05dc\u05d4 \u05e2\u05dd \u05d0\u05d7\u05d5\u05d6 \u05d4\u05db\u05e1\u05e3. \u05e0\u05d7\u05d5\u05e9\u05ea \u05d6\u05e8\u05d7\u05df \u05d5\u05e4\u05dc\u05d9\u05d6 \u05d6\u05d5\u05dc\u05d9\u05dd \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8."], [395.5, "\u05d4\u05dc\u05d7\u05de\u05d4 \u05d9\u05d3\u05e0\u05d9\u05ea \u05d1\u05dc\u05d4\u05d1\u05d4 \u05d3\u05d5\u05e8\u05e9\u05ea \u05e2\u05d1\u05d5\u05d3\u05d4 \u05d5\u05de\u05d9\u05d5\u05de\u05e0\u05d5\u05ea, \u05d5\u05db\u05dc \u05d7\u05d9\u05d1\u05d5\u05e8 \u05dc\u05d5\u05e7\u05d7 \u05d6\u05de\u05df."], [401.6, "\u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd \u05d4\u05d5\u05d0 \u05d4\u05e9\u05e7\u05e2\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d5\u05de\u05d7\u05d6\u05d5\u05e8 \u05d1\u05d5 \u05e0\u05de\u05e9\u05da \u05e9\u05e2\u05d5\u05ea, \u05d0\u05d1\u05dc \u05d1\u05db\u05dc \u05de\u05d7\u05d6\u05d5\u05e8 \u05de\u05d5\u05dc\u05d7\u05de\u05d9\u05dd \u05de\u05d0\u05d5\u05ea \u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d4\u05de\u05d7\u05d9\u05e8 \u05dc\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e0\u05de\u05d5\u05da."], [411.5, "\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05d3\u05d5\u05e8\u05e9\u05ea \u05e1\u05dc\u05d9\u05dc \u05de\u05d5\u05ea\u05d0\u05dd \u05dc\u05db\u05dc \u05d7\u05dc\u05e7, \u05d0\u05d1\u05dc \u05de\u05e9\u05ea\u05dc\u05de\u05ea \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e1\u05d3\u05e8\u05ea\u05d9."], [416.9, "\u05d4\u05d4\u05db\u05e0\u05d4 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05e2\u05dc\u05d5\u05ea: \u05e0\u05d9\u05e7\u05d5\u05d9, \u05e2\u05d9\u05d1\u05d5\u05d3 \u05dc\u05de\u05e8\u05d5\u05d5\u05d7 \u05de\u05d3\u05d5\u05d9\u05e7, \u05d5\u05e0\u05d9\u05e7\u05d5\u05d9 \u05d4-flux \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05dc\u05d7\u05de\u05d4."], [424.3, "\u05d5\u05dc\u05db\u05df \u05d4\u05dc\u05d7\u05de\u05d4 \u05de\u05e9\u05ea\u05dc\u05de\u05ea \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd, \u05d1\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e9\u05dc \u05de\u05ea\u05db\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea, \u05d5\u05d1\u05d4\u05e8\u05d1\u05d4 \u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e1\u05d3\u05e8\u05ea\u05d9."], [433.3, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d1\u05d4\u05dc\u05d7\u05de\u05d4 \u05e8\u05e7 \u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05e0\u05de\u05e1\u05d4, \u05d5\u05e0\u05e9\u05d0\u05d1\u05ea \u05dc\u05de\u05e8\u05d5\u05d5\u05d7 \u05e6\u05e8 \u05d1\u05db\u05d5\u05d7 \u05e0\u05d9\u05de\u05d9."], [440.3, "\u05e8\u05db\u05d4 \u05de\u05ea\u05d7\u05ea \u05dc-450 \u05de\u05e2\u05dc\u05d5\u05ea, \u05dc\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05e7\u05d4 \u05d5\u05dc\u05d0\u05d9\u05d8\u05d5\u05dd. \u05e7\u05e9\u05d4 \u05de\u05e2\u05dc 450, \u05dc\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd \u05d7\u05d6\u05e7\u05d9\u05dd."], [449.6, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e8\u05d9\u05ea\u05d5\u05da \u05e8\u05d5\u05d1\u05d5\u05d8\u05d9 \u05d5\u05d0\u05d5\u05d8\u05d5\u05de\u05e6\u05d9\u05d4, \u05d0\u05d9\u05da \u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05e8\u05ea\u05db\u05ea \u05d0\u05dc\u05e4\u05d9 \u05ea\u05e4\u05e8\u05d9\u05dd \u05d1\u05d0\u05d5\u05ea\u05d4 \u05d0\u05d9\u05db\u05d5\u05ea."]]};
window.MH_TR["ch15"]={"t": "\u05e8\u05d9\u05ea\u05d5\u05da \u05e8\u05d5\u05d1\u05d5\u05d8\u05d9 \u05d5\u05d0\u05d5\u05d8\u05d5\u05de\u05e6\u05d9\u05d4", "l": [[3.0, "\u05e8\u05d9\u05ea\u05d5\u05da \u05e8\u05d5\u05d1\u05d5\u05d8\u05d9 \u05d5\u05d0\u05d5\u05d8\u05d5\u05de\u05e6\u05d9\u05d4: \u05d0\u05d9\u05da \u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05e8\u05ea\u05db\u05ea \u05d0\u05dc\u05e4\u05d9 \u05ea\u05e4\u05e8\u05d9\u05dd, \u05d1\u05d0\u05d5\u05ea\u05d4 \u05d0\u05d9\u05db\u05d5\u05ea, \u05de\u05e9\u05de\u05e8\u05ea \u05d0\u05d7\u05e8\u05d9 \u05de\u05e9\u05de\u05e8\u05ea."], [11.3, "\u05e8\u05d5\u05d1 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05e8\u05d5\u05d1\u05d5\u05d8\u05d9 \u05d1\u05e2\u05d5\u05dc\u05dd \u05d4\u05d5\u05d0 MIG/MAG, \u05d0\u05d1\u05dc \u05e8\u05d5\u05d1\u05d5\u05d8\u05d9\u05dd \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d2\u05dd \u05e2\u05dd TIG, \u05dc\u05d9\u05d9\u05d6\u05e8 \u05d5\u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e7\u05d5\u05d3\u05ea\u05d9."], [18.9, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05e8\u05de\u05d5\u05ea \u05d4\u05d0\u05d5\u05d8\u05d5\u05de\u05e6\u05d9\u05d4, \u05d0\u05ea \u05ea\u05d0 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d0\u05ea \u05d4\u05ea\u05db\u05e0\u05d5\u05ea \u05d5\u05d4\u05d7\u05d9\u05d9\u05e9\u05e0\u05d9\u05dd, \u05d0\u05ea \u05d4\u05d1\u05e2\u05d9\u05d5\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."], [28.2, "\u05d9\u05e9 \u05db\u05de\u05d4 \u05e8\u05de\u05d5\u05ea \u05e9\u05dc \u05d0\u05d5\u05d8\u05d5\u05de\u05e6\u05d9\u05d4 \u05d1\u05e8\u05d9\u05ea\u05d5\u05da."], [30.9, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d9\u05d3\u05e0\u05d9, \u05d4\u05e8\u05ea\u05da \u05e2\u05d5\u05e9\u05d4 \u05d4\u05db\u05d5\u05dc: \u05de\u05d6\u05d9\u05d6 \u05d0\u05ea \u05d4\u05dc\u05e4\u05d9\u05d3, \u05d5\u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4 \u05d2\u05dd \u05de\u05e7\u05e8\u05d1 \u05d0\u05ea \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05db\u05e9\u05d4\u05d9\u05d0 \u05e0\u05e9\u05e8\u05e4\u05ea."], [39.7, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d7\u05e6\u05d9 \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9, \u05db\u05de\u05d5 MIG/MAG \u05e8\u05d2\u05d9\u05dc, \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05d6\u05d9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05d7\u05d5\u05d8, \u05d5\u05d4\u05e8\u05ea\u05da \u05de\u05d6\u05d9\u05d6 \u05d0\u05ea \u05d4\u05dc\u05e4\u05d9\u05d3 \u05d1\u05d9\u05d3."], [48.0, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05de\u05d5\u05db\u05df, \u05de\u05e0\u05d2\u05e0\u05d5\u05df \u05de\u05d6\u05d9\u05d6 \u05d0\u05ea \u05d4\u05dc\u05e4\u05d9\u05d3, \u05d5\u05d4\u05de\u05e4\u05e2\u05d9\u05dc \u05de\u05e9\u05d2\u05d9\u05d7 \u05d5\u05de\u05ea\u05e7\u05df: \u05e2\u05d2\u05dc\u05d4 \u05e9\u05e0\u05d5\u05e1\u05e2\u05ea \u05e2\u05dc \u05de\u05e1\u05d9\u05dc\u05d4, \u05e8\u05d0\u05e9 \u05de\u05e1\u05dc\u05d5\u05dc\u05d9 \u05e1\u05d1\u05d9\u05d1 \u05e6\u05d9\u05e0\u05d5\u05e8, \u05d0\u05d5 \u05d6\u05e8\u05d5\u05e2 \u05de\u05e2\u05dc \u05de\u05db\u05d5\u05e0\u05d4 \u05ea\u05ea \u05d0\u05d1\u05e7\u05ea\u05d9\u05ea."], [61.0, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9, \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05d1\u05e6\u05e2\u05ea \u05d0\u05ea \u05db\u05dc \u05d4\u05de\u05d7\u05d6\u05d5\u05e8 \u05dc\u05d1\u05d3, \u05d5\u05d4\u05de\u05e4\u05e2\u05d9\u05dc \u05e8\u05e7 \u05de\u05e2\u05de\u05d9\u05e1 \u05d5\u05e4\u05d5\u05e8\u05e7 \u05d7\u05dc\u05e7\u05d9\u05dd."], [68.1, "\u05d5\u05e8\u05d9\u05ea\u05d5\u05da \u05e8\u05d5\u05d1\u05d5\u05d8\u05d9 \u05d4\u05d5\u05d0 \u05d0\u05d5\u05d8\u05d5\u05de\u05e6\u05d9\u05d4 \u05d2\u05de\u05d9\u05e9\u05d4: \u05d0\u05d5\u05ea\u05d5 \u05e8\u05d5\u05d1\u05d5\u05d8 \u05d9\u05db\u05d5\u05dc \u05dc\u05e8\u05ea\u05da \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd, \u05e8\u05e7 \u05de\u05d7\u05dc\u05d9\u05e4\u05d9\u05dd \u05ea\u05d5\u05db\u05e0\u05d9\u05ea."], [75.5, "\u05db\u05db\u05dc \u05e9\u05e2\u05d5\u05dc\u05d9\u05dd \u05d1\u05e8\u05de\u05ea \u05d4\u05d0\u05d5\u05d8\u05d5\u05de\u05e6\u05d9\u05d4, \u05d4\u05d0\u05d9\u05db\u05d5\u05ea \u05d0\u05d7\u05d9\u05d3\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d0\u05d1\u05dc \u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05d5\u05d0\u05d7\u05d9\u05d3\u05d9\u05dd \u05d2\u05d3\u05dc\u05d4."], [83.6, "\u05ea\u05d0 \u05e8\u05d9\u05ea\u05d5\u05da \u05e8\u05d5\u05d1\u05d5\u05d8\u05d9 \u05db\u05d5\u05dc\u05dc \u05d6\u05e8\u05d5\u05e2 \u05e8\u05d5\u05d1\u05d5\u05d8\u05d9\u05ea, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05dd \u05e9\u05d9\u05e9\u05d4 \u05e6\u05d9\u05e8\u05d9\u05dd, \u05e9\u05de\u05d2\u05d9\u05e2\u05d4 \u05db\u05de\u05e2\u05d8 \u05dc\u05db\u05dc \u05d6\u05d5\u05d5\u05d9\u05ea."], [90.8, "\u05d4\u05d1\u05e7\u05e8 \u05de\u05e4\u05e2\u05d9\u05dc \u05d0\u05ea \u05d4\u05d6\u05e8\u05d5\u05e2, \u05d5\u05de\u05d3\u05d1\u05e8 \u05e2\u05dd \u05de\u05e7\u05d5\u05e8 \u05d4\u05d6\u05e8\u05dd \u05d5\u05de\u05d6\u05d9\u05df \u05d4\u05d7\u05d5\u05d8, \u05db\u05d3\u05d9 \u05dc\u05e9\u05e0\u05d5\u05ea \u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05ea\u05e4\u05e8."], [98.4, "\u05e2\u05dc \u05d4\u05dc\u05e4\u05d9\u05d3 \u05d9\u05e9 \u05d7\u05d9\u05d9\u05e9\u05df \u05d4\u05ea\u05e0\u05d2\u05e9\u05d5\u05ea, \u05e9\u05e2\u05d5\u05e6\u05e8 \u05d0\u05ea \u05d4\u05e8\u05d5\u05d1\u05d5\u05d8 \u05d0\u05dd \u05d4\u05dc\u05e4\u05d9\u05d3 \u05e4\u05d5\u05d2\u05e2 \u05d1\u05de\u05e9\u05d4\u05d5."], [103.9, "\u05e9\u05d5\u05dc\u05d7\u05df \u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05de\u05d6\u05d9\u05d6 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7: \u05de\u05e1\u05d5\u05d1\u05d1 \u05d5\u05de\u05d8\u05d4 \u05d0\u05d5\u05ea\u05d5, \u05db\u05da \u05e9\u05d4\u05ea\u05e4\u05e8 \u05ea\u05de\u05d9\u05d3 \u05d9\u05d4\u05d9\u05d4 \u05d1\u05ea\u05e0\u05d5\u05d7\u05d4 \u05d4\u05e0\u05d5\u05d7\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e9\u05d8\u05d5\u05d7\u05d4."], [113.5, "\u05d4\u05ea\u05e7\u05e0\u05d9 \u05e7\u05d9\u05d1\u05d5\u05e2 \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d1\u05d0\u05d5\u05ea\u05d5 \u05de\u05e7\u05d5\u05dd, \u05d1\u05db\u05dc \u05de\u05d7\u05d6\u05d5\u05e8."], [118.6, "\u05d1\u05ea\u05d7\u05e0\u05ea \u05e0\u05d9\u05e7\u05d5\u05d9, \u05d4\u05e8\u05d5\u05d1\u05d5\u05d8 \u05de\u05e0\u05e7\u05d4 \u05d0\u05ea \u05d4\u05e4\u05d9\u05d9\u05d4 \u05de\u05d4\u05ea\u05d6\u05d5\u05ea, \u05de\u05e8\u05e1\u05e1 \u05e0\u05d2\u05d3 \u05d4\u05d9\u05d3\u05d1\u05e7\u05d5\u05ea, \u05d5\u05d7\u05d5\u05ea\u05da \u05d0\u05ea \u05e7\u05e6\u05d4 \u05d4\u05d7\u05d5\u05d8."], [126.2, "\u05d5\u05d4\u05db\u05d5\u05dc \u05d1\u05ea\u05d5\u05da \u05d2\u05d3\u05e8 \u05d1\u05d8\u05d9\u05d7\u05d5\u05ea \u05e2\u05dd \u05e9\u05e2\u05e8\u05d9\u05dd \u05d5\u05d7\u05d9\u05d9\u05e9\u05e0\u05d9\u05dd, \u05d5\u05de\u05e1\u05db\u05d9\u05dd \u05db\u05d4\u05d9\u05dd \u05e0\u05d2\u05d3 \u05e7\u05e8\u05d9\u05e0\u05ea \u05d4\u05e7\u05e9\u05ea."], [132.9, "\u05d1\u05ea\u05d0\u05d9\u05dd \u05e8\u05d1\u05d9\u05dd \u05d9\u05e9 \u05e9\u05ea\u05d9 \u05e2\u05de\u05d3\u05d5\u05ea: \u05d4\u05e8\u05d5\u05d1\u05d5\u05d8 \u05de\u05e8\u05ea\u05da \u05d1\u05e6\u05d3 \u05d0\u05d7\u05d3, \u05d5\u05d4\u05de\u05e4\u05e2\u05d9\u05dc \u05de\u05e2\u05de\u05d9\u05e1 \u05d7\u05dc\u05e7 \u05d7\u05d3\u05e9 \u05d1\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9."], [141.2, "\u05d4\u05d3\u05e8\u05da \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05dc\u05ea\u05db\u05e0\u05ea \u05d4\u05d9\u05d0 \u05e2\u05dd \u05e9\u05dc\u05d8 \u05ea\u05db\u05e0\u05d5\u05ea: \u05de\u05d6\u05d9\u05d6\u05d9\u05dd \u05d0\u05ea \u05d4\u05e8\u05d5\u05d1\u05d5\u05d8 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05e0\u05e7\u05d5\u05d3\u05d4, \u05d5\u05e9\u05d5\u05de\u05e8\u05d9\u05dd \u05db\u05dc \u05de\u05d9\u05e7\u05d5\u05dd."], [149.5, "\u05d1\u05db\u05dc \u05e0\u05e7\u05d5\u05d3\u05d4 \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05d2\u05dd \u05d0\u05ea \u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05dc\u05e4\u05d9\u05d3, \u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea, \u05d5\u05e4\u05e8\u05de\u05d8\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [155.2, "\u05d1\u05e8\u05d5\u05d1\u05d5\u05d8\u05d9\u05dd \u05e9\u05d9\u05ea\u05d5\u05e4\u05d9\u05d9\u05dd, cobot, \u05d0\u05e4\u05e9\u05e8 \u05e4\u05e9\u05d5\u05d8 \u05dc\u05ea\u05e4\u05d5\u05e1 \u05d0\u05ea \u05d4\u05d6\u05e8\u05d5\u05e2 \u05d1\u05d9\u05d3, \u05d5\u05dc\u05d4\u05d5\u05d1\u05d9\u05dc \u05d0\u05d5\u05ea\u05d4 \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05ea\u05e4\u05e8."], [162.1, "\u05d1\u05ea\u05db\u05e0\u05d5\u05ea offline \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05d5\u05db\u05e0\u05d9\u05ea \u05d1\u05de\u05d7\u05e9\u05d1, \u05e2\u05dc \u05de\u05d5\u05d3\u05dc \u05ea\u05dc\u05ea \u05de\u05de\u05d3\u05d9 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7, \u05d1\u05dc\u05d9 \u05dc\u05e2\u05e6\u05d5\u05e8 \u05d0\u05ea \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8."], [169.3, "\u05d4\u05e1\u05d9\u05de\u05d5\u05dc\u05e6\u05d9\u05d4 \u05de\u05e8\u05d0\u05d4 \u05de\u05e8\u05d0\u05e9 \u05d4\u05ea\u05e0\u05d2\u05e9\u05d5\u05d9\u05d5\u05ea, \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05e9\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d4\u05df, \u05d5\u05d6\u05de\u05df \u05de\u05d7\u05d6\u05d5\u05e8."], [175.7, "\u05d5\u05d1\u05db\u05dc \u05de\u05e7\u05e8\u05d4, \u05e7\u05e6\u05d4 \u05d4\u05dc\u05e4\u05d9\u05d3, \u05d4-TCP, \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05db\u05d5\u05d9\u05dc, \u05d0\u05d7\u05e8\u05ea \u05db\u05dc \u05d4\u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d6\u05d6\u05d5\u05ea \u05d9\u05d7\u05d3."], [183.6, "\u05e8\u05d5\u05d1\u05d5\u05d8 \u05dc\u05d0 \u05e8\u05d5\u05d0\u05d4 \u05db\u05de\u05d5 \u05e8\u05ea\u05da. \u05d0\u05dd \u05d4\u05d7\u05dc\u05e7 \u05d6\u05d6 \u05de\u05e2\u05d8, \u05d4\u05d5\u05d0 \u05d9\u05e8\u05ea\u05da \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8. \u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d7\u05d9\u05d9\u05e9\u05e0\u05d9\u05dd."], [192.1, "\u05d1-touch sensing, \u05d4\u05e8\u05d5\u05d1\u05d5\u05d8 \u05e0\u05d5\u05d2\u05e2 \u05d1\u05d7\u05dc\u05e7 \u05e2\u05dd \u05e7\u05e6\u05d4 \u05d4\u05d7\u05d5\u05d8, \u05d1\u05de\u05ea\u05d7 \u05e0\u05de\u05d5\u05da, \u05d5\u05de\u05d5\u05e6\u05d0 \u05d0\u05ea \u05de\u05d9\u05e7\u05d5\u05dd \u05d4\u05d3\u05e4\u05e0\u05d5\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [200.0, "\u05d1\u05de\u05e2\u05e7\u05d1 \u05d3\u05e8\u05da \u05d4\u05e7\u05e9\u05ea, \u05d4\u05dc\u05e4\u05d9\u05d3 \u05de\u05ea\u05e0\u05d5\u05d3\u05d3 \u05de\u05e6\u05d3 \u05dc\u05e6\u05d3, \u05d5\u05d4\u05d1\u05e7\u05e8 \u05de\u05d5\u05d3\u05d3 \u05d0\u05ea \u05e9\u05d9\u05e0\u05d5\u05d9\u05d9 \u05d4\u05d6\u05e8\u05dd, \u05d5\u05de\u05ea\u05e7\u05df \u05d0\u05ea \u05d4\u05de\u05e1\u05dc\u05d5\u05dc \u05d1\u05d6\u05de\u05df \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [208.9, "\u05d7\u05d9\u05d9\u05e9\u05df \u05dc\u05d9\u05d9\u05d6\u05e8 \u05e9\u05e8\u05e5 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05dc\u05e4\u05d9\u05d3 \u05e1\u05d5\u05e8\u05e7 \u05d0\u05ea \u05d4\u05d7\u05e8\u05d9\u05e5, \u05d5\u05de\u05ea\u05e7\u05df \u05d2\u05dd \u05d0\u05ea \u05d4\u05de\u05d9\u05e7\u05d5\u05dd \u05d5\u05d2\u05dd \u05d0\u05ea \u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05dc\u05e4\u05d9 \u05e8\u05d5\u05d7\u05d1 \u05d4\u05de\u05e8\u05d5\u05d5\u05d7."], [217.1, "\u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05e0\u05d9\u05d8\u05d5\u05e8 \u05e8\u05d5\u05e9\u05de\u05d5\u05ea \u05d6\u05e8\u05dd, \u05de\u05ea\u05d7 \u05d5\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d1\u05db\u05dc \u05ea\u05e4\u05e8, \u05d5\u05de\u05ea\u05e8\u05d9\u05e2\u05d5\u05ea \u05e2\u05dc \u05d7\u05e8\u05d9\u05d2\u05d5\u05ea."], [223.9, "\u05d5\u05db\u05da \u05dc\u05db\u05dc \u05d7\u05dc\u05e7 \u05d9\u05e9 \u05ea\u05d9\u05e2\u05d5\u05d3 \u05de\u05dc\u05d0 \u05e9\u05dc \u05d0\u05d9\u05da \u05d4\u05d5\u05d0 \u05e8\u05d5\u05ea\u05da."], [228.9, "\u05d4\u05e8\u05db\u05d1 \u05d4\u05d5\u05d0 \u05d4\u05d3\u05d5\u05d2\u05de\u05d4 \u05d4\u05de\u05d5\u05db\u05e8\u05ea: \u05e7\u05d5\u05d5\u05d9 \u05d9\u05d9\u05e6\u05d5\u05e8 \u05e9\u05dc \u05d2\u05d5\u05e4\u05d9 \u05de\u05db\u05d5\u05e0\u05d9\u05d5\u05ea, \u05e2\u05dd \u05de\u05d0\u05d5\u05ea \u05e8\u05d5\u05d1\u05d5\u05d8\u05d9\u05dd \u05dc\u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e7\u05d5\u05d3\u05ea\u05d9."], [235.8, "\u05e8\u05d5\u05d1\u05d5\u05d8\u05d9 MIG/MAG \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05e9\u05dc\u05d3\u05d5\u05ea, \u05de\u05d5\u05e9\u05d1\u05d9\u05dd, \u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05e4\u05dc\u05d9\u05d8\u05d4, \u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d7\u05e7\u05dc\u05d0\u05d9\u05d5\u05ea \u05d5\u05e6\u05d9\u05d5\u05d3 \u05db\u05d1\u05d3."], [242.9, "\u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05de\u05d5\u05db\u05df \u05de\u05e9\u05de\u05e9 \u05d1\u05e6\u05e0\u05e8\u05ea, \u05d1\u05de\u05d9\u05db\u05dc\u05d9\u05dd \u05d5\u05d1\u05de\u05d1\u05e0\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd, \u05e9\u05d1\u05d4\u05dd \u05d4\u05e8\u05d5\u05d1\u05d5\u05d8 \u05dc\u05d0 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05db\u05dc \u05de\u05e7\u05d5\u05dd."], [250.7, "\u05e8\u05d5\u05d1\u05d5\u05d8\u05d9\u05dd \u05e9\u05d9\u05ea\u05d5\u05e4\u05d9\u05d9\u05dd \u05e0\u05db\u05e0\u05e1\u05d9\u05dd \u05dc\u05e1\u05d3\u05e0\u05d0\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea, \u05dc\u05e1\u05d3\u05e8\u05d5\u05ea \u05e7\u05e6\u05e8\u05d5\u05ea, \u05db\u05d9 \u05e7\u05dc \u05dc\u05ea\u05db\u05e0\u05ea \u05d0\u05d5\u05ea\u05dd \u05d5\u05d0\u05d9\u05df \u05e6\u05d5\u05e8\u05da \u05d1\u05d2\u05d3\u05e8 \u05de\u05dc\u05d0\u05d4."], [259.3, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea: \u05d0\u05d9\u05db\u05d5\u05ea \u05d0\u05d7\u05d9\u05d3\u05d4, \u05ea\u05e4\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05ea\u05e4\u05e8."], [263.7, "\u05d4\u05e7\u05e9\u05ea \u05d3\u05d5\u05dc\u05e7\u05ea \u05d7\u05dc\u05e7 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05d6\u05de\u05df: \u05d1\u05e8\u05d5\u05d1\u05d5\u05d8 \u05d1\u05e2\u05e8\u05da 60 \u05e2\u05d3 80 \u05d0\u05d7\u05d5\u05d6, \u05dc\u05e2\u05d5\u05de\u05ea 20 \u05e2\u05d3 30 \u05d1\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d9\u05d3\u05e0\u05d9\u05ea."], [272.9, "\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05e4\u05d7\u05d5\u05ea \u05d4\u05ea\u05d6\u05d5\u05ea, \u05d5\u05e4\u05d7\u05d5\u05ea \u05e2\u05d1\u05d5\u05d3\u05ea \u05e0\u05d9\u05e7\u05d5\u05d9 \u05d5\u05ea\u05d9\u05e7\u05d5\u05df."], [278.1, "\u05d4\u05e8\u05ea\u05da \u05d9\u05d5\u05e6\u05d0 \u05de\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e2\u05e9\u05df \u05d5\u05d4\u05e7\u05e8\u05d9\u05e0\u05d4, \u05d5\u05e2\u05d5\u05d1\u05d3 \u05db\u05de\u05e4\u05e2\u05d9\u05dc \u05d5\u05de\u05ea\u05db\u05e0\u05ea."], [283.5, "\u05d4\u05d7\u05e1\u05e8\u05d5\u05e0\u05d5\u05ea: \u05d4\u05e9\u05e7\u05e2\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d1\u05ea\u05d0, \u05d1\u05d4\u05ea\u05e7\u05e0\u05d9\u05dd \u05d5\u05d1\u05ea\u05db\u05e0\u05d5\u05ea."], [288.7, "\u05d4\u05e8\u05d5\u05d1\u05d5\u05d8 \u05d3\u05d5\u05e8\u05e9 \u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05d5\u05d0\u05d7\u05d9\u05d3\u05d9\u05dd. \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05de\u05ea\u05e7\u05df \u05d7\u05d9\u05ea\u05d5\u05da \u05e2\u05e7\u05d5\u05dd \u05db\u05de\u05d5 \u05e9\u05e8\u05ea\u05da \u05e2\u05d5\u05e9\u05d4."], [295.3, "\u05d1\u05e1\u05d3\u05e8\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea, \u05d6\u05de\u05df \u05d4\u05ea\u05db\u05e0\u05d5\u05ea \u05d5\u05d4\u05db\u05e0\u05ea \u05d4\u05d4\u05ea\u05e7\u05e0\u05d9\u05dd \u05d9\u05db\u05d5\u05dc \u05dc\u05e2\u05dc\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e2\u05e6\u05de\u05d5."], [301.8, "\u05d5\u05e6\u05e8\u05d9\u05da \u05d0\u05e0\u05e9\u05d9\u05dd \u05e9\u05d9\u05d5\u05d3\u05e2\u05d9\u05dd \u05d2\u05dd \u05e8\u05d9\u05ea\u05d5\u05da \u05d5\u05d2\u05dd \u05e8\u05d5\u05d1\u05d5\u05d8\u05d9\u05e7\u05d4, \u05d5\u05dc\u05d0 \u05e7\u05dc \u05dc\u05de\u05e6\u05d5\u05d0 \u05d0\u05d5\u05ea\u05dd."], [307.7, "\u05d4\u05d1\u05e2\u05d9\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8: \u05d4\u05ea\u05e4\u05e8 \u05d6\u05d6 \u05de\u05d4\u05de\u05e7\u05d5\u05dd, \u05db\u05d9 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3\u05d9\u05dd, \u05d0\u05d5 \u05e9\u05d4\u05dc\u05e4\u05d9\u05d3 \u05d0\u05d5 \u05d4\u05d4\u05ea\u05e7\u05df \u05d6\u05d6\u05d5."], [316.1, "\u05de\u05e8\u05d5\u05d5\u05d7 \u05e9\u05de\u05e9\u05ea\u05e0\u05d4 \u05d1\u05d9\u05df \u05d7\u05dc\u05e7 \u05dc\u05d7\u05dc\u05e7 \u05d2\u05d5\u05e8\u05dd \u05dc\u05e9\u05e8\u05d9\u05e4\u05d4 \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd, \u05d0\u05d5 \u05dc\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da \u05d1\u05de\u05e8\u05d5\u05d5\u05d7 \u05e6\u05e8."], [323.5, "\u05e4\u05d9\u05d9\u05d4 \u05e1\u05ea\u05d5\u05de\u05d4 \u05d1\u05d4\u05ea\u05d6\u05d5\u05ea \u05e4\u05d5\u05d2\u05e2\u05ea \u05d1\u05d4\u05d2\u05e0\u05ea \u05d4\u05d2\u05d6, \u05d5\u05e0\u05d5\u05e6\u05e8\u05d5\u05ea \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea."], [329.1, "\u05d7\u05d5\u05d8 \u05e9\u05dc\u05d0 \u05de\u05d5\u05d6\u05df \u05d1\u05e8\u05e6\u05d9\u05e4\u05d5\u05ea, \u05d1\u05d2\u05dc\u05dc \u05e6\u05d9\u05e0\u05d5\u05e8 \u05e9\u05d7\u05d5\u05e7 \u05d0\u05d5 \u05de\u05ea\u05db\u05dc\u05d9\u05dd \u05d9\u05e9\u05e0\u05d9\u05dd, \u05d9\u05d5\u05e6\u05e8 \u05ea\u05e4\u05e8 \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3."], [336.0, "\u05dc\u05e4\u05d9\u05d3 \u05e9\u05d4\u05ea\u05e2\u05e7\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05ea\u05e0\u05d2\u05e9\u05d5\u05ea, \u05d1\u05dc\u05d9 \u05db\u05d9\u05d5\u05dc \u05de\u05d7\u05d3\u05e9, \u05de\u05d6\u05d9\u05d6 \u05d0\u05ea \u05db\u05dc \u05d4\u05ea\u05e4\u05e8\u05d9\u05dd."], [341.7, "\u05d5\u05e8\u05d5\u05d1\u05d5\u05d8 \u05d7\u05d5\u05d6\u05e8 \u05e2\u05dc \u05d0\u05d5\u05ea\u05d4 \u05d8\u05e2\u05d5\u05ea \u05d1\u05db\u05dc \u05d7\u05dc\u05e7, \u05dc\u05db\u05df \u05e4\u05d2\u05dd \u05d0\u05d7\u05d3 \u05d4\u05d5\u05e4\u05da \u05de\u05d4\u05e8 \u05dc\u05e1\u05d3\u05e8\u05d4 \u05e4\u05d2\u05d5\u05de\u05d4."], [348.4, "\u05d4\u05e4\u05ea\u05e8\u05d5\u05df: \u05d1\u05d3\u05d9\u05e7\u05ea \u05d7\u05dc\u05e7 \u05e8\u05d0\u05e9\u05d5\u05df, \u05e0\u05d9\u05d8\u05d5\u05e8, \u05ea\u05d7\u05d6\u05d5\u05e7\u05d4 \u05e7\u05d1\u05d5\u05e2\u05d4, \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05de\u05d3\u05d2\u05de\u05d9\u05d5\u05ea."], [355.7, "\u05ea\u05d0 \u05e8\u05d5\u05d1\u05d5\u05d8\u05d9 \u05e2\u05d5\u05dc\u05d4 \u05dc\u05d0 \u05e8\u05e7 \u05e8\u05d5\u05d1\u05d5\u05d8: \u05d2\u05dd \u05de\u05e7\u05d5\u05e8 \u05d6\u05e8\u05dd, \u05e9\u05d5\u05dc\u05d7\u05df \u05de\u05e1\u05ea\u05d5\u05d1\u05d1, \u05d2\u05d3\u05e8 \u05d1\u05d8\u05d9\u05d7\u05d5\u05ea, \u05d4\u05ea\u05e7\u05e0\u05d9\u05dd, \u05ea\u05db\u05e0\u05d5\u05ea \u05d5\u05d4\u05d3\u05e8\u05db\u05d4."], [365.3, "\u05d4\u05ea\u05e7\u05e0\u05d9 \u05d4\u05e7\u05d9\u05d1\u05d5\u05e2 \u05dc\u05d1\u05d3\u05dd \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05e2\u05dc\u05d5\u05ea \u05db\u05de\u05d5 \u05d4\u05e8\u05d5\u05d1\u05d5\u05d8, \u05d5\u05dc\u05db\u05dc \u05d7\u05dc\u05e7 \u05d7\u05d3\u05e9 \u05e6\u05e8\u05d9\u05da \u05d4\u05ea\u05e7\u05df \u05d7\u05d3\u05e9."], [372.3, "\u05d4\u05d4\u05d7\u05d6\u05e8 \u05e2\u05dc \u05d4\u05d4\u05e9\u05e7\u05e2\u05d4 \u05ea\u05dc\u05d5\u05d9 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05db\u05de\u05d5\u05ea: \u05db\u05de\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d6\u05d4\u05d9\u05dd, \u05db\u05de\u05d4 \u05de\u05e9\u05de\u05e8\u05d5\u05ea, \u05d5\u05db\u05de\u05d4 \u05e9\u05e0\u05d9\u05dd."], [379.3, "\u05d5\u05d2\u05dd \u05d1\u05d3\u05d9\u05d5\u05e7 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd: \u05d7\u05d9\u05ea\u05d5\u05da \u05d5\u05db\u05d9\u05e4\u05d5\u05e3 \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05d7\u05d5\u05e1\u05db\u05d9\u05dd \u05d7\u05d9\u05d9\u05e9\u05e0\u05d9\u05dd \u05d5\u05ea\u05d9\u05e7\u05d5\u05e0\u05d9\u05dd."], [385.6, "\u05d7\u05d9\u05e1\u05db\u05d5\u05df \u05d2\u05d3\u05d5\u05dc \u05de\u05d2\u05d9\u05e2 \u05de\u05d6\u05de\u05df \u05e7\u05e9\u05ea \u05d2\u05d1\u05d5\u05d4, \u05d5\u05e4\u05d7\u05d5\u05ea \u05ea\u05d9\u05e7\u05d5\u05e0\u05d9\u05dd \u05d5\u05e0\u05d9\u05e7\u05d5\u05d9."], [390.7, "\u05dc\u05db\u05df \u05e8\u05d5\u05d1\u05d5\u05d8 \u05de\u05e9\u05ea\u05dc\u05dd \u05d1\u05e1\u05d3\u05e8\u05d5\u05ea \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05d5\u05ea \u05d5\u05d2\u05d3\u05d5\u05dc\u05d5\u05ea, \u05d5-cobot \u05d0\u05d5 \u05ea\u05db\u05e0\u05d5\u05ea offline \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05e3 \u05d2\u05dd \u05dc\u05e1\u05d3\u05e8\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea."], [399.9, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05de\u05e8\u05d9\u05ea\u05d5\u05da \u05d9\u05d3\u05e0\u05d9, \u05d3\u05e8\u05da \u05d7\u05e6\u05d9 \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9 \u05d5\u05de\u05de\u05d5\u05db\u05df, \u05d5\u05e2\u05d3 \u05e8\u05d5\u05d1\u05d5\u05d8 \u05d2\u05de\u05d9\u05e9."], [406.5, "\u05d4\u05e8\u05d5\u05d1\u05d5\u05d8 \u05e0\u05d5\u05ea\u05df \u05d0\u05d9\u05db\u05d5\u05ea \u05d0\u05d7\u05d9\u05d3\u05d4 \u05d5\u05d6\u05de\u05df \u05e7\u05e9\u05ea \u05d2\u05d1\u05d5\u05d4, \u05d0\u05d1\u05dc \u05d3\u05d5\u05e8\u05e9 \u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd, \u05d4\u05ea\u05e7\u05e0\u05d9\u05dd, \u05d7\u05d9\u05d9\u05e9\u05e0\u05d9\u05dd \u05d5\u05ea\u05db\u05e0\u05d5\u05ea."], [414.9, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05de\u05ea\u05d7\u05d9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d4\u05e8\u05d1\u05d9\u05e2\u05d9, \u05de\u05d8\u05dc\u05d5\u05e8\u05d2\u05d9\u05d4: \u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05dc\u05d7\u05d5\u05de\u05e8 \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."]]};
window.MH_TR["ch16"]={"t": "\u05de\u05d8\u05dc\u05d5\u05e8\u05d2\u05d9\u05d4 \u05e9\u05dc \u05d4\u05e8\u05d9\u05ea\u05d5\u05da", "l": [[3.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e6\u05dc\u05d5\u05dc \u05e4\u05e0\u05d9\u05de\u05d4: \u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05dc\u05de\u05d1\u05e0\u05d4 \u05e9\u05dc \u05d4\u05de\u05ea\u05db\u05ea \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05dc\u05de\u05d4 \u05e9\u05dd \u05e0\u05d5\u05dc\u05d3\u05d9\u05dd \u05e8\u05d5\u05d1 \u05d4\u05e1\u05d3\u05e7\u05d9\u05dd."], [10.8, "\u05d1\u05e4\u05e8\u05e7 \u05d0\u05d7\u05ea \u05d4\u05db\u05e8\u05e0\u05d5 \u05d0\u05ea \u05d0\u05de\u05d1\u05d8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d5\u05d0\u05ea \u05d4-HAZ. \u05e2\u05db\u05e9\u05d9\u05d5 \u05e0\u05d1\u05d9\u05df \u05d0\u05ea \u05d4\u05de\u05e0\u05d2\u05e0\u05d5\u05e0\u05d9\u05dd \u05e9\u05de\u05d0\u05d7\u05d5\u05e8\u05d9\u05d4\u05dd."], [18.1, "\u05e0\u05e2\u05d1\u05d5\u05e8 \u05e2\u05dc \u05d4\u05de\u05d7\u05d6\u05d5\u05e8 \u05d4\u05ea\u05e8\u05de\u05d9, \u05d4\u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05d1-HAZ, \u05e9\u05d9\u05e0\u05d5\u05d9\u05d9 \u05d4\u05de\u05d1\u05e0\u05d4 \u05d1\u05e4\u05dc\u05d3\u05d4, \u05d4-CE, \u05e1\u05d3\u05e7\u05d9 \u05de\u05d9\u05de\u05df, \u05e1\u05d3\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd, \u05d5\u05e9\u05d9\u05d8\u05d5\u05ea \u05d4\u05e9\u05dc\u05d9\u05d8\u05d4."], [30.0, "\u05db\u05dc \u05e0\u05e7\u05d5\u05d3\u05d4 \u05dc\u05d9\u05d3 \u05d4\u05ea\u05e4\u05e8 \u05e2\u05d5\u05d1\u05e8\u05ea \u05de\u05d7\u05d6\u05d5\u05e8 \u05ea\u05e8\u05de\u05d9: \u05d4\u05d9\u05d0 \u05de\u05ea\u05d7\u05de\u05de\u05ea \u05de\u05d4\u05e8 \u05e2\u05d3 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05e9\u05d9\u05d0, \u05d5\u05d0\u05d6 \u05de\u05ea\u05e7\u05e8\u05e8\u05ea."], [38.4, "\u05db\u05db\u05dc \u05e9\u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05e8\u05d7\u05d5\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e7\u05d5 \u05d4\u05d4\u05d9\u05ea\u05d5\u05da, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05e9\u05d9\u05d0 \u05e9\u05dc\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8."], [44.1, "\u05d0\u05d1\u05dc \u05dc\u05d0 \u05e8\u05e7 \u05d4\u05e9\u05d9\u05d0 \u05e7\u05d5\u05d1\u05e2 \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4. \u05e7\u05e6\u05d1 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d7\u05e9\u05d5\u05d1 \u05dc\u05d0 \u05e4\u05d7\u05d5\u05ea."], [49.2, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d6\u05de\u05df \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05e9\u05de\u05d5\u05e0\u05d4 \u05de\u05d0\u05d5\u05ea \u05dc\u05d7\u05de\u05e9 \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea, \u05e9\u05e0\u05e7\u05e8\u05d0 t8/5."], [56.5, "\u05d6\u05de\u05df \u05e7\u05e6\u05e8 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8, \u05d5\u05d6\u05de\u05df \u05d0\u05e8\u05d5\u05da \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9."], [62.2, "heat input \u05d2\u05d1\u05d5\u05d4 \u05de\u05d0\u05e8\u05d9\u05da \u05d0\u05ea \u05d6\u05de\u05df \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8, \u05d5\u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d3\u05d9\u05dd \u05de\u05d0\u05e8\u05d9\u05da \u05d0\u05d5\u05ea\u05d5 \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8."], [68.2, "\u05d5\u05dc\u05d5\u05d7 \u05e2\u05d1\u05d4 \u05de\u05e7\u05e8\u05e8 \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05dc\u05d5\u05d7 \u05d3\u05e7, \u05db\u05d9 \u05d4\u05d7\u05d5\u05dd \u05d1\u05d5\u05e8\u05d7 \u05dc\u05db\u05dc \u05d4\u05db\u05d9\u05d5\u05d5\u05e0\u05d9\u05dd."], [74.5, "\u05d1\u05e4\u05dc\u05d3\u05d4, \u05d4-HAZ \u05de\u05ea\u05d7\u05dc\u05e7 \u05dc\u05db\u05de\u05d4 \u05d0\u05d6\u05d5\u05e8\u05d9\u05dd, \u05dc\u05e4\u05d9 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05e9\u05d9\u05d0."], [80.2, "\u05de\u05de\u05e9 \u05dc\u05d9\u05d3 \u05e7\u05d5 \u05d4\u05d4\u05d9\u05ea\u05d5\u05da, \u05de\u05e2\u05dc 1,100 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d2\u05d3\u05dc\u05d9\u05dd \u05de\u05d0\u05d5\u05d3: \u05d6\u05d4 \u05d0\u05d6\u05d5\u05e8 \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d4\u05d2\u05e1\u05d9\u05dd."], [88.5, "\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d2\u05e1\u05d9\u05dd \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7 \u05dc\u05e9\u05d1\u05d9\u05e8\u05d4, \u05d5\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d6\u05d4 \u05d2\u05dd \u05de\u05ea\u05e7\u05e9\u05d4. \u05dc\u05db\u05df \u05d6\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d4\u05de\u05e7\u05d5\u05dd \u05d4\u05d7\u05dc\u05e9 \u05d1\u05d9\u05d5\u05ea\u05e8."], [98.0, "\u05e7\u05e6\u05ea \u05d9\u05d5\u05ea\u05e8 \u05e8\u05d7\u05d5\u05e7, \u05e1\u05d1\u05d9\u05d1 900 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05de\u05ea\u05e2\u05d3\u05e0\u05d9\u05dd, \u05d5\u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d3\u05d5\u05d5\u05e7\u05d0 \u05d8\u05d5\u05d1\u05d5\u05ea."], [104.8, "\u05d1\u05d9\u05df 727 \u05dc-900 \u05de\u05e2\u05dc\u05d5\u05ea, \u05e8\u05e7 \u05d7\u05dc\u05e7 \u05de\u05d4\u05de\u05d1\u05e0\u05d4 \u05de\u05e9\u05ea\u05e0\u05d4: \u05d6\u05d4 \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d1\u05d9\u05df \u05e7\u05e8\u05d9\u05d8\u05d9."], [112.4, "\u05d5\u05de\u05ea\u05d7\u05ea \u05dc-727 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d4\u05de\u05d1\u05e0\u05d4 \u05dc\u05d0 \u05de\u05e9\u05ea\u05e0\u05d4, \u05d0\u05d1\u05dc \u05e4\u05dc\u05d3\u05d4 \u05e9\u05e2\u05d1\u05e8\u05d4 \u05d4\u05e7\u05e9\u05d9\u05d4 \u05e2\u05dc\u05d5\u05dc\u05d4 \u05dc\u05d4\u05ea\u05e8\u05db\u05da \u05e9\u05dd."], [120.5, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e9\u05dc \u05db\u05de\u05d4 \u05de\u05e2\u05d1\u05e8\u05d9\u05dd, \u05db\u05dc \u05de\u05e2\u05d1\u05e8 \u05de\u05d7\u05de\u05dd \u05de\u05d7\u05d3\u05e9 \u05d0\u05ea \u05e7\u05d5\u05d3\u05de\u05d5, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05e9\u05e4\u05e8 \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05e9\u05dc\u05d5."], [128.4, "\u05de\u05e2\u05dc 727 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [133.3, "\u05de\u05d4 \u05e9\u05e7\u05d5\u05e8\u05d4 \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05ea\u05dc\u05d5\u05d9 \u05d1\u05e7\u05e6\u05d1."], [136.7, "\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05e4\u05e8\u05d9\u05d8 \u05d5\u05e4\u05e8\u05dc\u05d9\u05d8: \u05de\u05d1\u05e0\u05d4 \u05e8\u05da \u05d5\u05d2\u05de\u05d9\u05e9."], [142.2, "\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05e0\u05d5\u05e6\u05e8 \u05d1\u05d9\u05d9\u05e0\u05d9\u05d8: \u05d7\u05d6\u05e7 \u05d5\u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8."], [147.0, "\u05d5\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05de\u05d0\u05d5\u05d3 \u05e0\u05d5\u05e6\u05e8 \u05de\u05e8\u05d8\u05e0\u05e1\u05d9\u05d8: \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d0\u05d1\u05dc \u05e9\u05d1\u05d9\u05e8."], [152.8, "\u05db\u05db\u05dc \u05e9\u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d7\u05de\u05df \u05d1\u05e4\u05dc\u05d3\u05d4, \u05d4\u05de\u05e8\u05d8\u05e0\u05e1\u05d9\u05d8 \u05e7\u05e9\u05d4 \u05d5\u05e9\u05d1\u05d9\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d2\u05dd \u05e7\u05dc \u05d9\u05d5\u05ea\u05e8 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d5."], [159.8, "\u05d2\u05dd \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05db\u05de\u05d5 \u05de\u05e0\u05d2\u05df, \u05db\u05e8\u05d5\u05dd \u05d5\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05de\u05e7\u05dc\u05d9\u05dd \u05e2\u05dc \u05d4\u05d9\u05d5\u05d5\u05e6\u05e8\u05d5\u05ea \u05de\u05e8\u05d8\u05e0\u05e1\u05d9\u05d8. \u05d6\u05d5 \u05d4\u05d4\u05ea\u05e7\u05e9\u05d5\u05ea \u05e9\u05dc \u05d4\u05e4\u05dc\u05d3\u05d4."], [169.0, "\u05db\u05d3\u05d9 \u05dc\u05d4\u05e2\u05e8\u05d9\u05da \u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05de\u05e8\u05d0\u05e9, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e9\u05d5\u05d5\u05d4 \u05e2\u05e8\u05da \u05e4\u05d7\u05de\u05df, CE."], [174.5, "\u05d4\u05e0\u05d5\u05e1\u05d7\u05d4 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05dc\u05e4\u05d7\u05de\u05df \u05d7\u05dc\u05e7 \u05de\u05d4\u05d4\u05e9\u05e4\u05e2\u05d4 \u05e9\u05dc \u05d4\u05de\u05e0\u05d2\u05df, \u05d4\u05db\u05e8\u05d5\u05dd, \u05d4\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05d4\u05d5\u05d5\u05e0\u05d3\u05d9\u05d5\u05dd, \u05d4\u05e0\u05d9\u05e7\u05dc \u05d5\u05d4\u05e0\u05d7\u05d5\u05e9\u05ea."], [182.9, "\u05de\u05ea\u05d7\u05ea \u05dc\u05d0\u05e8\u05d1\u05e2 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea, \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05ea\u05e8\u05ea\u05db\u05ea \u05d1\u05e7\u05dc\u05d5\u05ea, \u05d1\u05dc\u05d9 \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d3\u05d9\u05dd \u05d1\u05e2\u05d5\u05d1\u05d9\u05d9\u05dd \u05e8\u05d2\u05d9\u05dc\u05d9\u05dd."], [189.8, "\u05d1\u05d9\u05df \u05d0\u05e8\u05d1\u05e2 \u05dc\u05e9\u05e9 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05e6\u05e8\u05d9\u05da \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d3\u05d9\u05dd, \u05d5\u05db\u05db\u05dc \u05e9\u05d4-CE \u05d5\u05d4\u05e2\u05d5\u05d1\u05d9 \u05d2\u05d3\u05dc\u05d9\u05dd, \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e2\u05d5\u05dc\u05d4."], [197.3, "\u05d5\u05de\u05e2\u05dc \u05e9\u05e9 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea, \u05d4\u05e4\u05dc\u05d3\u05d4 \u05e7\u05e9\u05d4 \u05dc\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05d3\u05d5\u05e8\u05e9\u05ea \u05e0\u05d5\u05d4\u05dc \u05de\u05d9\u05d5\u05d7\u05d3."], [203.2, "\u05d4\u05e1\u05d3\u05e7 \u05d4\u05de\u05e1\u05d5\u05db\u05df \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05d5\u05d0 \u05e1\u05d3\u05e7 \u05de\u05d9\u05de\u05df, \u05e9\u05e0\u05e7\u05e8\u05d0 \u05d2\u05dd \u05e1\u05d3\u05e7 \u05e7\u05e8."], [209.2, "\u05d4\u05d5\u05d0 \u05e0\u05d5\u05e6\u05e8 \u05e8\u05e7 \u05db\u05e9\u05e9\u05dc\u05d5\u05e9\u05d4 \u05ea\u05e0\u05d0\u05d9\u05dd \u05de\u05ea\u05e7\u05d9\u05d9\u05de\u05d9\u05dd \u05d9\u05d7\u05d3: \u05de\u05d9\u05de\u05df \u05d1\u05ea\u05e4\u05e8, \u05de\u05d1\u05e0\u05d4 \u05e7\u05e9\u05d4, \u05d5\u05de\u05d0\u05de\u05e6\u05d9\u05dd."], [216.5, "\u05d4\u05de\u05d9\u05de\u05df \u05de\u05d2\u05d9\u05e2 \u05de\u05dc\u05d7\u05d5\u05ea \u05d1\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d0\u05d5 \u05d1-flux, \u05de\u05e9\u05de\u05df, \u05de\u05d7\u05dc\u05d5\u05d3\u05d4, \u05d5\u05de\u05d0\u05d5\u05d5\u05d9\u05e8 \u05dc\u05d7."], [224.1, "\u05d4\u05e7\u05e9\u05ea \u05de\u05e4\u05e8\u05e7\u05ea \u05d0\u05ea \u05d4\u05de\u05d9\u05dd, \u05d5\u05d4\u05de\u05d9\u05de\u05df \u05e0\u05db\u05e0\u05e1 \u05dc\u05d0\u05de\u05d1\u05d8, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05ea\u05e4\u05d6\u05e8 \u05d0\u05dc \u05d4-HAZ."], [231.4, "\u05d4\u05e1\u05d3\u05e7 \u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1-HAZ, \u05de\u05ea\u05d7\u05ea \u05dc\u05ea\u05e4\u05e8 \u05d0\u05d5 \u05d1\u05e9\u05d5\u05dc\u05d9 \u05d4\u05ea\u05e4\u05e8, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e8\u05e7 \u05e9\u05e2\u05d5\u05ea \u05d0\u05d5 \u05d9\u05de\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [241.4, "\u05dc\u05db\u05df \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e8\u05d2\u05d9\u05e9\u05d5\u05ea \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8 \u05e8\u05e7 \u05d0\u05d7\u05e8\u05d9 48 \u05e9\u05e2\u05d5\u05ea."], [247.3, "\u05de\u05d5\u05e0\u05e2\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05db\u05e9\u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05dc\u05e4\u05d7\u05d5\u05ea \u05d0\u05d7\u05d3 \u05de\u05e9\u05dc\u05d5\u05e9\u05ea \u05d4\u05ea\u05e0\u05d0\u05d9\u05dd: \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d3\u05dc\u05d9 \u05de\u05d9\u05de\u05df, \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05de\u05d9\u05d5\u05d1\u05e9\u05d5\u05ea \u05d1\u05ea\u05e0\u05d5\u05e8, \u05d5\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e0\u05e7\u05d9\u05d9\u05dd \u05d5\u05d9\u05d1\u05e9\u05d9\u05dd."], [257.1, "\u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d3\u05d9\u05dd \u05de\u05d0\u05d8 \u05d0\u05ea \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8, \u05d5\u05e0\u05d5\u05ea\u05df \u05dc\u05de\u05d9\u05de\u05df \u05d6\u05de\u05df \u05dc\u05e6\u05d0\u05ea, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d2\u05dd \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05db\u05d3\u05d9 \u05dc\u05d4\u05d5\u05e6\u05d9\u05d0 \u05d0\u05ea \u05e9\u05d0\u05e8\u05d9\u05ea \u05d4\u05de\u05d9\u05de\u05df."], [266.9, "\u05e1\u05d3\u05e7 \u05de\u05e1\u05d5\u05d2 \u05d0\u05d7\u05e8 \u05e0\u05d5\u05e6\u05e8 \u05d1\u05d6\u05de\u05df \u05d4\u05d4\u05ea\u05de\u05e6\u05e7\u05d5\u05ea \u05e2\u05e6\u05de\u05d4, \u05d5\u05dc\u05db\u05df \u05e0\u05e7\u05e8\u05d0 \u05e1\u05d3\u05e7 \u05d7\u05dd."], [273.1, "\u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d1\u05de\u05ea\u05db\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e6\u05d5\u05de\u05d7\u05d9\u05dd \u05de\u05d3\u05e4\u05e0\u05d5\u05ea \u05d4\u05d0\u05de\u05d1\u05d8, \u05d1\u05e6\u05d5\u05e8\u05ea \u05e2\u05de\u05d5\u05d3\u05d9\u05dd, \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05de\u05e8\u05db\u05d6."], [279.5, "\u05d1\u05e1\u05d5\u05e3 \u05d4\u05d4\u05ea\u05de\u05e6\u05e7\u05d5\u05ea \u05e0\u05e9\u05d0\u05e8\u05ea \u05d1\u05de\u05e8\u05db\u05d6 \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05e9\u05dc \u05e0\u05d5\u05d6\u05dc, \u05e2\u05dd \u05d6\u05d9\u05d4\u05d5\u05de\u05d9\u05dd \u05db\u05de\u05d5 \u05d2\u05d5\u05e4\u05e8\u05d9\u05ea \u05d5\u05d6\u05e8\u05d7\u05df, \u05e9\u05e0\u05de\u05e1\u05d9\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8."], [288.9, "\u05db\u05e9\u05d4\u05ea\u05e4\u05e8 \u05de\u05ea\u05db\u05d5\u05d5\u05e5, \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05d6\u05d5 \u05e0\u05e7\u05e8\u05e2\u05ea, \u05d5\u05e0\u05d5\u05e6\u05e8 \u05e1\u05d3\u05e7 \u05dc\u05d0\u05d5\u05e8\u05da \u05de\u05e8\u05db\u05d6 \u05d4\u05ea\u05e4\u05e8."], [295.3, "\u05ea\u05e4\u05e8 \u05e6\u05e8 \u05d5\u05e2\u05de\u05d5\u05e7 \u05de\u05d3\u05d9 \u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05df, \u05db\u05d9 \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05de\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd \u05e0\u05e4\u05d2\u05e9\u05d9\u05dd \u05d1\u05e7\u05d5 \u05d0\u05d7\u05d3 \u05d1\u05d0\u05de\u05e6\u05e2."], [302.6, "\u05dc\u05db\u05df \u05e9\u05d5\u05de\u05e8\u05d9\u05dd \u05e2\u05dc \u05d9\u05d7\u05e1 \u05e1\u05d1\u05d9\u05e8 \u05d1\u05d9\u05df \u05e2\u05d5\u05de\u05e7 \u05dc\u05e8\u05d5\u05d7\u05d1, \u05de\u05d2\u05d1\u05d9\u05dc\u05d9\u05dd \u05d2\u05d5\u05e4\u05e8\u05d9\u05ea \u05d5\u05d6\u05e8\u05d7\u05df, \u05d5\u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05de\u05ea\u05db\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05ea\u05d0\u05d9\u05de\u05d4."], [310.4, "\u05e8\u05d9\u05e1\u05d5\u05df \u05d7\u05d6\u05e7 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05e9\u05dc\u05d0 \u05de\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05dd \u05dc\u05d4\u05ea\u05db\u05d5\u05d5\u05e5, \u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e9\u05e0\u05d9 \u05e1\u05d5\u05d2\u05d9 \u05d4\u05e1\u05d3\u05e7\u05d9\u05dd."], [317.6, "\u05d2\u05dd \u05de\u05ea\u05db\u05d5\u05ea \u05e9\u05dc\u05d0 \u05de\u05e9\u05e0\u05d5\u05ea \u05e4\u05d0\u05d6\u05d4 \u05de\u05d5\u05e9\u05e4\u05e2\u05d5\u05ea \u05de\u05d4\u05d7\u05d5\u05dd."], [321.3, "\u05de\u05ea\u05db\u05ea \u05e9\u05d4\u05d5\u05e7\u05e9\u05ea\u05d4 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8 \u05de\u05ea\u05e8\u05db\u05db\u05ea \u05d1-HAZ, \u05db\u05d9 \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05de\u05ea\u05d2\u05d1\u05e9\u05d9\u05dd \u05de\u05d7\u05d3\u05e9."], [328.0, "\u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e9\u05d4\u05d5\u05e7\u05e9\u05d5 \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05db\u05de\u05d5 \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d1\u05de\u05e6\u05d1 T6, \u05de\u05d0\u05d1\u05d3\u05d5\u05ea \u05d7\u05dc\u05e7 \u05d2\u05d3\u05d5\u05dc \u05de\u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc\u05d4\u05df \u05d1-HAZ."], [336.6, "\u05d5\u05d1\u05db\u05dc \u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e9\u05d9\u05d5\u05e8\u05d9\u05d9\u05dd: \u05d4\u05ea\u05e4\u05e8 \u05de\u05ea\u05db\u05d5\u05d5\u05e5 \u05d1\u05e7\u05d9\u05e8\u05d5\u05e8, \u05d5\u05d4\u05d7\u05d5\u05de\u05e8 \u05e9\u05de\u05e1\u05d1\u05d9\u05d1 \u05de\u05ea\u05e0\u05d2\u05d3."], [344.5, "\u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05d2\u05d1\u05d5\u05dc \u05d4\u05db\u05e0\u05d9\u05e2\u05d4, \u05d5\u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05dc\u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd, \u05dc\u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05d5\u05dc\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."], [352.7, "\u05d4\u05e9\u05dc\u05d9\u05d8\u05d4 \u05d1\u05de\u05d8\u05dc\u05d5\u05e8\u05d2\u05d9\u05d4 \u05e0\u05e2\u05e9\u05d9\u05ea \u05d3\u05e8\u05da \u05e0\u05d5\u05d4\u05dc \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d4-WPS."], [358.1, "\u05d4\u05e0\u05d5\u05d4\u05dc \u05de\u05d2\u05d3\u05d9\u05e8 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d3\u05d9\u05dd, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9\u05ea \u05d1\u05d9\u05df \u05de\u05e2\u05d1\u05e8 \u05dc\u05de\u05e2\u05d1\u05e8, \u05d5\u05d8\u05d5\u05d5\u05d7 heat input."], [366.8, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05d1\u05d5\u05ea \u05d0\u05d5 \u05e8\u05d2\u05d9\u05e9\u05d5\u05ea \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da, PWHT."], [373.3, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05d7\u05de\u05df \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc-600 \u05e2\u05d3 650 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05dc\u05d0\u05d8."], [380.3, "\u05d6\u05d4 \u05de\u05e9\u05d7\u05e8\u05e8 \u05d0\u05ea \u05e8\u05d5\u05d1 \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9\u05d9\u05dd, \u05de\u05e8\u05db\u05da \u05d0\u05ea \u05d4\u05de\u05e8\u05d8\u05e0\u05e1\u05d9\u05d8, \u05d5\u05de\u05d5\u05e6\u05d9\u05d0 \u05de\u05d9\u05de\u05df."], [386.0, "\u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d3\u05d9\u05dd \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d6\u05de\u05df, \u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05d5\u05e2\u05dc\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05d4\u05dd \u05de\u05d5\u05d2\u05d3\u05e8\u05d9\u05dd \u05e8\u05e7 \u05db\u05e9\u05d1\u05d0\u05de\u05ea \u05e6\u05e8\u05d9\u05da."], [394.8, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d4\u05de\u05d1\u05e0\u05d4 \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e7\u05d1\u05e2 \u05dc\u05e4\u05d9 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05e9\u05d9\u05d0 \u05d5\u05e7\u05e6\u05d1 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8."], [401.2, "\u05e1\u05d3\u05e7\u05d9 \u05de\u05d9\u05de\u05df \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05de\u05de\u05d9\u05de\u05df, \u05de\u05d1\u05e0\u05d4 \u05e7\u05e9\u05d4 \u05d5\u05de\u05d0\u05de\u05e6\u05d9\u05dd. \u05e1\u05d3\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05d1\u05d4\u05ea\u05de\u05e6\u05e7\u05d5\u05ea, \u05d1\u05de\u05e8\u05db\u05d6 \u05d4\u05ea\u05e4\u05e8."], [410.2, "\u05d5\u05e9\u05d5\u05dc\u05d8\u05d9\u05dd \u05d1\u05db\u05dc \u05d6\u05d4 \u05d3\u05e8\u05da \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd, \u05d4\u05d7\u05d9\u05de\u05d5\u05dd \u05d4\u05de\u05e7\u05d3\u05d9\u05dd, \u05d4-heat input \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd."], [416.9, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e8\u05d9\u05ea\u05d5\u05da \u05e4\u05dc\u05d3\u05d5\u05ea, \u05de\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05d5\u05e2\u05d3 \u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05e1\u05d2\u05e1\u05d2\u05d5\u05ea."]]};
window.MH_TR["ch17"]={"t": "\u05e8\u05d9\u05ea\u05d5\u05da \u05e4\u05dc\u05d3\u05d5\u05ea", "l": [[3.0, "\u05e4\u05dc\u05d3\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05de\u05e8\u05d5\u05ea\u05da \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05e2\u05d5\u05dc\u05dd, \u05d0\u05d1\u05dc \u05d4\u05de\u05d9\u05dc\u05d4 \u05e4\u05dc\u05d3\u05d4 \u05de\u05db\u05e1\u05d4 \u05de\u05d0\u05d5\u05ea \u05e1\u05d5\u05d2\u05d9\u05dd, \u05d5\u05db\u05dc \u05de\u05e9\u05e4\u05d7\u05d4 \u05de\u05ea\u05e0\u05d4\u05d2\u05ea \u05d0\u05d7\u05e8\u05ea \u05d1\u05e8\u05d9\u05ea\u05d5\u05da."], [12.1, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d9\u05d9\u05e9\u05dd \u05d0\u05ea \u05d4\u05de\u05d8\u05dc\u05d5\u05e8\u05d2\u05d9\u05d4 \u05de\u05d4\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd \u05e2\u05dc \u05d4\u05de\u05e9\u05e4\u05d7\u05d5\u05ea \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea."], [17.5, "\u05e0\u05e2\u05d1\u05d5\u05e8 \u05e2\u05dc \u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05d7\u05de\u05df, \u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d1\u05e0\u05d4 \u05d5\u05d7\u05d5\u05d6\u05e7 \u05d2\u05d1\u05d5\u05d4, \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05e8\u05d5\u05dd \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05d0\u05e8\u05d1\u05e2 \u05de\u05e9\u05e4\u05d7\u05d5\u05ea \u05e9\u05dc \u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05dc-\u05d7\u05dc\u05d3, \u05d5\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea."], [29.7, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05d7\u05de\u05df, \u05d0\u05d7\u05d5\u05d6 \u05d4\u05e4\u05d7\u05de\u05df \u05e7\u05d5\u05d1\u05e2 \u05db\u05de\u05e2\u05d8 \u05d4\u05db\u05d5\u05dc."], [34.1, "\u05e4\u05dc\u05d3\u05d4 \u05d3\u05dc\u05ea \u05e4\u05d7\u05de\u05df, \u05e2\u05d3 \u05d1\u05e2\u05e8\u05da \u05e8\u05d1\u05e2 \u05d0\u05d7\u05d5\u05d6, \u05de\u05ea\u05e8\u05ea\u05db\u05ea \u05d1\u05e7\u05dc\u05d5\u05ea, \u05d5\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05dc\u05d9 \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d3\u05d9\u05dd."], [41.2, "\u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05e4\u05d7\u05de\u05df \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9, \u05e8\u05d1\u05e2 \u05e2\u05d3 \u05d7\u05e6\u05d9 \u05d0\u05d7\u05d5\u05d6, \u05d4-HAZ \u05de\u05ea\u05e7\u05e9\u05d4, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d3\u05d9\u05dd \u05d5\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d3\u05dc\u05d9 \u05de\u05d9\u05de\u05df."], [50.8, "\u05d5\u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05ea\u05d9\u05e8\u05ea \u05e4\u05d7\u05de\u05df, \u05de\u05e2\u05dc \u05d7\u05e6\u05d9 \u05d0\u05d7\u05d5\u05d6, \u05db\u05de\u05d5 \u05d1\u05e7\u05e4\u05d9\u05e6\u05d9\u05dd \u05d5\u05d1\u05db\u05dc\u05d9\u05dd, \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d5\u05d3\u05d5\u05e8\u05e9 \u05d7\u05d9\u05de\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4 \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d0\u05d7\u05e8\u05d9."], [60.5, "\u05e4\u05dc\u05d3\u05d5\u05ea \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05dc, \u05e2\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05d2\u05d5\u05e4\u05e8\u05d9\u05ea, \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d5\u05ea \u05dc\u05e8\u05d9\u05ea\u05d5\u05da, \u05db\u05d9 \u05d4\u05d2\u05d5\u05e4\u05e8\u05d9\u05ea \u05d2\u05d5\u05e8\u05de\u05ea \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd."], [67.7, "\u05d1\u05e4\u05dc\u05d3\u05d4 \u05de\u05d2\u05d5\u05dc\u05d5\u05d5\u05e0\u05ea, \u05d0\u05d3\u05d9 \u05d4\u05d0\u05d1\u05e5 \u05e8\u05e2\u05d9\u05dc\u05d9\u05dd \u05d5\u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05de\u05d0\u05d5\u05d5\u05e8\u05e8\u05d9\u05dd \u05d4\u05d9\u05d8\u05d1."], [77.7, "\u05d5\u05d7\u05dc\u05d5\u05d3\u05d4, \u05e6\u05d1\u05e2 \u05d5\u05e9\u05de\u05df \u05de\u05db\u05e0\u05d9\u05e1\u05d9\u05dd \u05de\u05d9\u05de\u05df \u05d5\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05e0\u05e7\u05d9\u05dd \u05e2\u05d3 \u05de\u05ea\u05db\u05ea \u05e0\u05e7\u05d9\u05d9\u05d4."], [86.1, "\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d1\u05e0\u05d4, \u05db\u05de\u05d5 S235 \u05d5-S355, \u05d4\u05df \u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d5\u05de\u05ea\u05e8\u05ea\u05db\u05d5\u05ea \u05d4\u05d9\u05d8\u05d1."], [95.1, "\u05d4\u05de\u05e1\u05e4\u05e8 \u05de\u05e6\u05d9\u05d9\u05df \u05d0\u05ea \u05d2\u05d1\u05d5\u05dc \u05d4\u05db\u05e0\u05d9\u05e2\u05d4 \u05d1\u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc."], [98.6, "\u05e4\u05dc\u05d3\u05d5\u05ea \u05d1\u05d7\u05d5\u05d6\u05e7 \u05d2\u05d1\u05d5\u05d4, \u05de\u05e2\u05dc 460 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc, \u05de\u05e7\u05d1\u05dc\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7 \u05de\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05e2\u05d3\u05d9\u05e0\u05d9\u05dd \u05d5\u05de\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd."], [106.5, "\u05d1\u05d4\u05df \u05d7\u05e9\u05d5\u05d1 \u05dc\u05e2\u05d1\u05d5\u05d3 \u05d1\u05d7\u05dc\u05d5\u05df heat input \u05e6\u05e8: \u05d9\u05d5\u05ea\u05e8 \u05de\u05d3\u05d9 \u05de\u05e8\u05db\u05da \u05d0\u05ea \u05d4-HAZ \u05d5\u05de\u05d2\u05d3\u05d9\u05dc \u05d1\u05d5 \u05d0\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd, \u05d5\u05e4\u05d7\u05d5\u05ea \u05de\u05d3\u05d9 \u05de\u05e7\u05e9\u05d4 \u05d0\u05d5\u05ea\u05d5."], [116.1, "\u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05de\u05ea\u05db\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05d1\u05d7\u05d5\u05d6\u05e7 \u05de\u05ea\u05d0\u05d9\u05dd, \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d2\u05dd \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7 \u05dc\u05e9\u05d1\u05d9\u05e8\u05d4 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4."], [122.6, "\u05d5\u05db\u05de\u05e2\u05d8 \u05ea\u05de\u05d9\u05d3 \u05e6\u05e8\u05d9\u05da \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d3\u05dc\u05d9 \u05de\u05d9\u05de\u05df, \u05d5\u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d3\u05d9\u05dd \u05dc\u05e4\u05d9 \u05d4\u05e2\u05d5\u05d1\u05d9."], [128.3, "\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05e8\u05d5\u05dd \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d5\u05de\u05e9\u05de\u05e9\u05d5\u05ea \u05d1\u05ea\u05d7\u05e0\u05d5\u05ea \u05db\u05d5\u05d7, \u05d1\u05d3\u05d5\u05d5\u05d3\u05d9\u05dd \u05d5\u05d1\u05e6\u05e0\u05e8\u05ea \u05e7\u05d9\u05d8\u05d5\u05e8."], [136.0, "\u05d4\u05df \u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05db\u05df \u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d3\u05d9\u05dd \u05d2\u05d1\u05d5\u05d4, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd 200 \u05e2\u05d3 300 \u05de\u05e2\u05dc\u05d5\u05ea."], [142.9, "\u05e9\u05d5\u05de\u05e8\u05d9\u05dd \u05e2\u05dc \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05dc\u05d0\u05d5\u05e8\u05da \u05db\u05dc \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05dc\u05d0 \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05dc\u05d7\u05dc\u05e7 \u05dc\u05d4\u05ea\u05e7\u05e8\u05e8 \u05d1\u05db\u05dc\u05dc \u05e2\u05d3 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd."], [150.2, "\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d5\u05d0 \u05db\u05de\u05e2\u05d8 \u05ea\u05de\u05d9\u05d3 \u05d7\u05d5\u05d1\u05d4, \u05db\u05d3\u05d9 \u05dc\u05e8\u05db\u05da \u05d0\u05ea \u05d4-HAZ \u05d5\u05dc\u05d4\u05d7\u05d6\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea."], [157.2, "\u05d5\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05d7\u05d9\u05d9\u05d1\u05ea \u05dc\u05d4\u05ea\u05d0\u05d9\u05dd \u05dc\u05d4\u05e8\u05db\u05d1, \u05d0\u05d7\u05e8\u05ea \u05d4\u05ea\u05e4\u05e8 \u05d9\u05d9\u05d7\u05dc\u05e9 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4."], [164.2, "\u05e4\u05dc\u05d3\u05ea \u05d0\u05dc-\u05d7\u05dc\u05d3 \u05de\u05db\u05d9\u05dc\u05d4 \u05dc\u05e4\u05d7\u05d5\u05ea \u05d0\u05d7\u05d3 \u05e2\u05e9\u05e8 \u05d0\u05d7\u05d5\u05d6 \u05db\u05e8\u05d5\u05dd, \u05e9\u05d9\u05d5\u05e6\u05e8 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e9\u05db\u05d1\u05ea \u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05d3\u05e7\u05d4 \u05e9\u05de\u05d2\u05d9\u05e0\u05d4 \u05de\u05e4\u05e0\u05d9 \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."], [172.8, "\u05d9\u05e9 \u05d0\u05e8\u05d1\u05e2 \u05de\u05e9\u05e4\u05d7\u05d5\u05ea \u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea, \u05d5\u05dc\u05db\u05dc \u05d0\u05d7\u05ea \u05d4\u05ea\u05e0\u05d4\u05d2\u05d5\u05ea \u05e9\u05d5\u05e0\u05d4 \u05d1\u05e8\u05d9\u05ea\u05d5\u05da."], [177.6, "\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05ea, \u05db\u05de\u05d5 304 \u05d5-316, \u05d4\u05d9\u05d0 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8."], [183.4, "\u05d5\u05d9\u05e9 \u05d2\u05dd \u05e4\u05e8\u05d9\u05d8\u05d9\u05ea, \u05de\u05e8\u05d8\u05e0\u05e1\u05d9\u05d8\u05d9\u05ea, \u05d5\u05d3\u05d5\u05e4\u05dc\u05e7\u05e1."], [188.3, "\u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05ea \u05d4\u05d9\u05d0 \u05d4\u05e7\u05dc\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05e8\u05d9\u05ea\u05d5\u05da: \u05d4\u05d9\u05d0 \u05dc\u05d0 \u05de\u05ea\u05e7\u05e9\u05d4, \u05d5\u05dc\u05d0 \u05e8\u05d2\u05d9\u05e9\u05d4 \u05dc\u05e1\u05d3\u05e7\u05d9 \u05de\u05d9\u05de\u05df."], [194.6, "\u05d0\u05d1\u05dc \u05d4\u05d9\u05d0 \u05de\u05ea\u05e4\u05e9\u05d8\u05ea \u05d9\u05d5\u05ea\u05e8 \u05d5\u05de\u05d5\u05dc\u05d9\u05db\u05d4 \u05d7\u05d5\u05dd \u05e4\u05d7\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05ea\u05e2\u05d5\u05d5\u05ea\u05ea \u05d9\u05d5\u05ea\u05e8 \u05de\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df."], [201.3, "\u05db\u05d3\u05d9 \u05dc\u05de\u05e0\u05d5\u05e2 \u05e1\u05d3\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd, \u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05db\u05d9\u05dc\u05d4 \u05de\u05e2\u05d8 \u05e4\u05e8\u05d9\u05d8, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05db\u05de\u05d4 \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd."], [207.9, "\u05d1\u05d9\u05df 450 \u05dc-850 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d4\u05db\u05e8\u05d5\u05dd \u05de\u05ea\u05d7\u05d1\u05e8 \u05dc\u05e4\u05d7\u05de\u05df, \u05d5\u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05dc\u05d0\u05d5\u05e8\u05da \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05d1\u05dc\u05d9 \u05d4\u05d2\u05e0\u05d4. \u05d6\u05d5 \u05e8\u05d2\u05d9\u05e9\u05d5\u05ea \u05dc\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d1\u05d9\u05df \u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05ea."], [220.4, "\u05d4\u05e4\u05ea\u05e8\u05d5\u05df \u05d4\u05d5\u05d0 \u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05de\u05e2\u05d8 \u05de\u05d0\u05d5\u05d3 \u05e4\u05d7\u05de\u05df, \u05e9\u05de\u05e1\u05d5\u05de\u05e0\u05d5\u05ea \u05d1\u05d0\u05d5\u05ea L, \u05d0\u05d5 \u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d9\u05d5\u05e6\u05d1\u05d5\u05ea \u05d1\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d0\u05d5 \u05d1\u05e0\u05d9\u05d5\u05d1\u05d9\u05d5\u05dd."], [229.0, "\u05d1\u05e6\u05d3 \u05d4\u05e9\u05d5\u05e8\u05e9 \u05de\u05d6\u05e8\u05d9\u05de\u05d9\u05dd \u05d0\u05e8\u05d2\u05d5\u05df \u05de\u05d0\u05d7\u05d5\u05e8\u05d9 \u05d4\u05ea\u05e4\u05e8, \u05d0\u05d7\u05e8\u05ea \u05d4\u05e9\u05d5\u05e8\u05e9 \u05de\u05ea\u05d7\u05de\u05e6\u05df \u05d5\u05e0\u05e8\u05d0\u05d4 \u05db\u05de\u05d5 \u05e1\u05d5\u05db\u05e8 \u05e9\u05e8\u05d5\u05e3."], [236.3, "\u05d0\u05ea \u05e6\u05d1\u05e2\u05d9 \u05d4\u05d7\u05d5\u05dd \u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d1\u05e0\u05d9\u05e7\u05d5\u05d9 \u05db\u05d9\u05de\u05d9 \u05d5\u05e4\u05e1\u05d9\u05d1\u05e6\u05d9\u05d4, \u05db\u05d3\u05d9 \u05dc\u05d4\u05d7\u05d6\u05d9\u05e8 \u05d0\u05ea \u05e9\u05db\u05d1\u05ea \u05d4\u05d4\u05d2\u05e0\u05d4."], [241.9, "\u05d5\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05d1\u05e8\u05e9\u05d5\u05ea \u05d5\u05db\u05dc\u05d9\u05dd \u05e0\u05e4\u05e8\u05d3\u05d9\u05dd, \u05db\u05d9 \u05e9\u05d1\u05d1\u05d9\u05dd \u05e9\u05dc \u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05dc\u05d7\u05dc\u05d5\u05d3\u05d4 \u05e2\u05dc \u05d4\u05d0\u05dc-\u05d7\u05dc\u05d3."], [249.8, "\u05e4\u05dc\u05d3\u05d4 \u05e4\u05e8\u05d9\u05d8\u05d9\u05ea, \u05db\u05de\u05d5 430, \u05e1\u05d5\u05d1\u05dc\u05ea \u05de\u05d2\u05d3\u05d9\u05dc\u05ea \u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d1-HAZ, \u05d5\u05dc\u05db\u05df \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05e2\u05dd heat input \u05e0\u05de\u05d5\u05da."], [258.8, "\u05e4\u05dc\u05d3\u05d4 \u05de\u05e8\u05d8\u05e0\u05e1\u05d9\u05d8\u05d9\u05ea, \u05db\u05de\u05d5 410 \u05d5-420, \u05de\u05ea\u05e7\u05e9\u05d4 \u05db\u05de\u05d5 \u05e4\u05dc\u05d3\u05d4 \u05e2\u05ea\u05d9\u05e8\u05ea \u05e4\u05d7\u05de\u05df, \u05d5\u05d3\u05d5\u05e8\u05e9\u05ea \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d3\u05d9\u05dd \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd."], [268.6, "\u05d3\u05d5\u05e4\u05dc\u05e7\u05e1, \u05db\u05de\u05d5 2205, \u05d1\u05e0\u05d5\u05d9\u05d4 \u05d1\u05e2\u05e8\u05da \u05d7\u05e6\u05d9 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d5\u05d7\u05e6\u05d9 \u05e4\u05e8\u05d9\u05d8, \u05d5\u05de\u05e9\u05dc\u05d1\u05ea \u05d7\u05d5\u05d6\u05e7 \u05d2\u05d1\u05d5\u05d4 \u05e2\u05dd \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05e6\u05d5\u05d9\u05e0\u05ea \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."], [279.0, "\u05db\u05d3\u05d9 \u05dc\u05e9\u05de\u05d5\u05e8 \u05e2\u05dc \u05d4\u05d0\u05d9\u05d6\u05d5\u05df \u05d4\u05d6\u05d4, \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05d7\u05dc\u05d5\u05df heat input \u05de\u05d5\u05d2\u05d3\u05e8, \u05d5\u05dc\u05d0 \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05de\u05d4\u05e8 \u05de\u05d3\u05d9."], [285.4, "\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05e2\u05e9\u05d9\u05e8\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05e0\u05d9\u05e7\u05dc, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d7\u05e0\u05e7\u05df \u05dc\u05d2\u05d6 \u05d4\u05de\u05d2\u05df."], [291.2, "\u05d5\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9\u05ea \u05d1\u05d9\u05df \u05de\u05e2\u05d1\u05e8\u05d9\u05dd \u05d7\u05e9\u05d5\u05d1\u05d4 \u05db\u05d0\u05df \u05d1\u05de\u05d9\u05d5\u05d7\u05d3."], [296.0, "\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e9\u05dc \u05d0\u05dc-\u05d7\u05dc\u05d3 \u05dc\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05e0\u05e4\u05d5\u05e5 \u05de\u05d0\u05d5\u05d3, \u05dc\u05de\u05e9\u05dc \u05d1\u05ea\u05de\u05d9\u05db\u05d5\u05ea \u05d5\u05d1\u05e6\u05e0\u05e8\u05ea."], [302.6, "\u05d4\u05d1\u05e2\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05d3\u05d9\u05dc\u05d5\u05dc: \u05e4\u05dc\u05d3\u05ea \u05d4\u05e4\u05d7\u05de\u05df \u05de\u05d3\u05dc\u05dc\u05ea \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8, \u05d5\u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05d5\u05e6\u05e8 \u05d1\u05d5 \u05de\u05e8\u05d8\u05e0\u05e1\u05d9\u05d8 \u05e9\u05d1\u05d9\u05e8."], [310.1, "\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05ea\u05db\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05e2\u05e9\u05d9\u05e8\u05d4 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3, \u05db\u05de\u05d5 309L, \u05e9\u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d3\u05d9\u05dc\u05d5\u05dc \u05e0\u05e9\u05d0\u05e8\u05ea \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05ea."], [318.6, "\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05ea \u05e9\u05e4\u05dc\u05e8 \u05de\u05d0\u05e4\u05e9\u05e8\u05ea \u05dc\u05d7\u05d6\u05d5\u05ea \u05de\u05e8\u05d0\u05e9 \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05e9\u05dc \u05d4\u05ea\u05e4\u05e8 \u05dc\u05e4\u05d9 \u05d4\u05d4\u05e8\u05db\u05d1."], [324.1, "\u05d5\u05d1\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd \u05e9\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05d7\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05ea\u05db\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05e2\u05dc \u05d1\u05e1\u05d9\u05e1 \u05e0\u05d9\u05e7\u05dc, \u05db\u05d9 \u05d4\u05d4\u05ea\u05e4\u05e9\u05d8\u05d5\u05ea \u05e9\u05dc\u05d4 \u05e7\u05e8\u05d5\u05d1\u05d4 \u05dc\u05e9\u05ea\u05d9 \u05d4\u05e4\u05dc\u05d3\u05d5\u05ea."], [332.7, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05e8\u05d9\u05ea\u05d5\u05da \u05e4\u05dc\u05d3\u05d5\u05ea?"], [334.8, "\u05de\u05ea\u05db\u05d5\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05e9\u05dc \u05d0\u05dc-\u05d7\u05dc\u05d3 \u05d5\u05e9\u05dc \u05e0\u05d9\u05e7\u05dc \u05d9\u05e7\u05e8\u05d5\u05ea \u05e4\u05d9 \u05db\u05de\u05d4 \u05de\u05de\u05ea\u05db\u05d5\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05e9\u05dc \u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df."], [341.6, "\u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d3\u05d9\u05dd \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05e6\u05d9\u05d5\u05d3, \u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05d5\u05e9\u05e2\u05d5\u05ea \u05e2\u05d1\u05d5\u05d3\u05d4, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05e8\u05d5\u05dd \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df."], [349.2, "\u05d1\u05d0\u05dc-\u05d7\u05dc\u05d3 \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d2\u05d6 \u05dc\u05d4\u05d2\u05e0\u05ea \u05d4\u05e9\u05d5\u05e8\u05e9, \u05e0\u05d9\u05e7\u05d5\u05d9 \u05db\u05d9\u05de\u05d9, \u05d5\u05e4\u05e1\u05d9\u05d1\u05e6\u05d9\u05d4."], [355.0, "\u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e8\u05d2\u05d9\u05e9\u05d5\u05ea \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea: \u05e7\u05e9\u05d9\u05d5\u05ea, \u05ea\u05db\u05d5\u05dc\u05ea \u05e4\u05e8\u05d9\u05d8, \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 48 \u05e9\u05e2\u05d5\u05ea."], [362.7, "\u05dc\u05db\u05df \u05d1\u05d7\u05d9\u05e8\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4 \u05db\u05d1\u05e8 \u05d1\u05e9\u05dc\u05d1 \u05d4\u05ea\u05db\u05df \u05de\u05e9\u05e4\u05d9\u05e2\u05d4 \u05de\u05d0\u05d5\u05d3 \u05e2\u05dc \u05e2\u05dc\u05d5\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [369.1, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05d7\u05de\u05df \u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05d7\u05d5\u05d6\u05e7 \u05d2\u05d1\u05d5\u05d4, \u05d4\u05e9\u05dc\u05d9\u05d8\u05d4 \u05d4\u05d9\u05d0 \u05d1\u05e4\u05d7\u05de\u05df, \u05d1\u05de\u05d9\u05de\u05df \u05d5\u05d1\u05e7\u05e6\u05d1 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8."], [377.4, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05e8\u05d5\u05dd \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d3\u05d9\u05dd \u05d2\u05d1\u05d5\u05d4 \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d4\u05dd \u05d7\u05d5\u05d1\u05d4."], [382.5, "\u05d5\u05d1\u05d0\u05dc-\u05d7\u05dc\u05d3, \u05e9\u05d5\u05de\u05e8\u05d9\u05dd \u05e2\u05dc \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4: \u05de\u05e2\u05d8 \u05e4\u05d7\u05de\u05df, \u05d4\u05d2\u05e0\u05ea \u05e9\u05d5\u05e8\u05e9, \u05e0\u05d9\u05e7\u05d5\u05d9, \u05d5\u05de\u05ea\u05db\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05ea\u05d0\u05d9\u05de\u05d4."], [390.8, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd."]]};
window.MH_TR["ch18"]={"t": "\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd", "l": [[3.0, "\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d4\u05df \u05de\u05ea\u05db\u05d5\u05ea \u05e7\u05dc\u05d5\u05ea, \u05d7\u05d6\u05e7\u05d5\u05ea \u05d5\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05d5\u05e9\u05ea\u05d9\u05d4\u05df \u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05d2\u05d9\u05e9\u05d4 \u05e9\u05d5\u05e0\u05d4 \u05dc\u05d2\u05de\u05e8\u05d9 \u05de\u05e4\u05dc\u05d3\u05d4."], [11.3, "\u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d4\u05d0\u05ea\u05d2\u05e8 \u05d4\u05d5\u05d0 \u05d4\u05d7\u05d5\u05dd, \u05d4\u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05d5\u05d4\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea. \u05d1\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d4\u05d0\u05ea\u05d2\u05e8 \u05d4\u05d5\u05d0 \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8 \u05e2\u05e6\u05de\u05d5."], [19.5, "\u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc \u05db\u05dc \u05de\u05ea\u05db\u05ea, \u05d0\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d5\u05de\u05ea\u05db\u05d5\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9, \u05d0\u05ea \u05e9\u05d9\u05d8\u05d5\u05ea \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4, \u05d0\u05ea \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8."], [28.6, "\u05e2\u05dc \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d9\u05e9 \u05e9\u05db\u05d1\u05ea \u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05d3\u05e7\u05d4 \u05d5\u05e7\u05e9\u05d4, \u05e9\u05e0\u05de\u05e1\u05d4 \u05e8\u05e7 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 2,000 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d1\u05d6\u05de\u05df \u05e9\u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05e2\u05e6\u05de\u05d5 \u05e0\u05de\u05e1 \u05d1-660."], [38.6, "\u05d0\u05dd \u05dc\u05d0 \u05de\u05e4\u05e8\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4, \u05d4\u05d9\u05d0 \u05e0\u05e9\u05d0\u05e8\u05ea \u05d1\u05ea\u05e4\u05e8 \u05d5\u05de\u05d5\u05e0\u05e2\u05ea \u05d4\u05d9\u05ea\u05d5\u05da."], [42.9, "\u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05d5\u05dc\u05d9\u05da \u05d7\u05d5\u05dd \u05e4\u05d9 \u05d0\u05e8\u05d1\u05e2\u05d4 \u05d1\u05e2\u05e8\u05da \u05de\u05e4\u05dc\u05d3\u05d4, \u05d5\u05dc\u05db\u05df \u05d4\u05d7\u05d5\u05dd \u05d1\u05d5\u05e8\u05d7 \u05de\u05d4\u05e8, \u05d5\u05e6\u05e8\u05d9\u05da \u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8."], [50.6, "\u05d1\u05d4\u05ea\u05d7\u05dc\u05ea \u05d4\u05ea\u05e4\u05e8 \u05d4\u05d7\u05dc\u05e7 \u05e2\u05d5\u05d3 \u05e7\u05e8, \u05d5\u05dc\u05e7\u05e8\u05d0\u05ea \u05d4\u05e1\u05d5\u05e3 \u05d4\u05d5\u05d0 \u05db\u05d1\u05e8 \u05d7\u05dd \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05db\u05df \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d6\u05e8\u05dd \u05d0\u05d5 \u05de\u05d2\u05d1\u05d9\u05e8\u05d9\u05dd \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05ea\u05e4\u05e8."], [60.5, "\u05d4\u05d5\u05d0 \u05dc\u05d0 \u05de\u05e9\u05e0\u05d4 \u05e6\u05d1\u05e2 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05ea\u05db\u05d4, \u05db\u05da \u05e9\u05e7\u05e9\u05d4 \u05dc\u05e8\u05d0\u05d5\u05ea \u05de\u05ea\u05d9 \u05d4\u05d5\u05d0 \u05e2\u05d5\u05de\u05d3 \u05dc\u05d4\u05d9\u05de\u05e1."], [65.8, "\u05d4\u05d5\u05d0 \u05de\u05ea\u05e4\u05e9\u05d8 \u05e4\u05d9 \u05e9\u05e0\u05d9\u05d9\u05dd \u05d1\u05e2\u05e8\u05da \u05de\u05e4\u05dc\u05d3\u05d4, \u05d5\u05dc\u05db\u05df \u05de\u05ea\u05e2\u05d5\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8."], [70.4, "\u05d5\u05de\u05d9\u05de\u05df \u05e0\u05de\u05e1 \u05d1\u05e7\u05dc\u05d5\u05ea \u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05e0\u05d5\u05d6\u05dc\u05d9, \u05d5\u05d9\u05d5\u05e6\u05d0 \u05de\u05de\u05e0\u05d5 \u05d1\u05d4\u05ea\u05de\u05e6\u05e7\u05d5\u05ea. \u05d6\u05d4 \u05d4\u05de\u05e7\u05d5\u05e8 \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9 \u05dc\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea."], [79.0, "\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05d7\u05d5\u05dc\u05e7\u05d5\u05ea \u05dc\u05e1\u05d3\u05e8\u05d5\u05ea, \u05dc\u05e4\u05d9 \u05d9\u05e1\u05d5\u05d3 \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2 \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9."], [84.1, "\u05e1\u05d3\u05e8\u05d5\u05ea \u05d4\u05d0\u05dc\u05e3, \u05e9\u05dc\u05d5\u05e9\u05ea \u05d4\u05d0\u05dc\u05e4\u05d9\u05dd \u05d5\u05d7\u05de\u05e9\u05ea \u05d4\u05d0\u05dc\u05e4\u05d9\u05dd \u05dc\u05d0 \u05de\u05d5\u05e7\u05e9\u05d5\u05ea \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05d5\u05de\u05ea\u05e8\u05ea\u05db\u05d5\u05ea \u05d4\u05d9\u05d8\u05d1."], [91.5, "\u05e1\u05d3\u05e8\u05ea \u05e9\u05e9\u05ea \u05d4\u05d0\u05dc\u05e4\u05d9\u05dd, \u05db\u05de\u05d5 6061, \u05de\u05d5\u05e7\u05e9\u05d9\u05ea \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05d5\u05e8\u05d2\u05d9\u05e9\u05d4 \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd \u05db\u05e9\u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d1\u05dc\u05d9 \u05de\u05ea\u05db\u05ea \u05de\u05d9\u05dc\u05d5\u05d9."], [100.7, "\u05e1\u05d3\u05e8\u05d5\u05ea \u05d4\u05d0\u05dc\u05e4\u05d9\u05d9\u05dd \u05d5\u05e9\u05d1\u05e2\u05ea \u05d4\u05d0\u05dc\u05e4\u05d9\u05dd, \u05e9\u05de\u05e9\u05de\u05e9\u05d5\u05ea \u05d1\u05ea\u05e2\u05d5\u05e4\u05d4, \u05d4\u05df \u05d4\u05e7\u05e9\u05d5\u05ea \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d4\u05ea\u05db\u05d4, \u05d5\u05dc\u05db\u05df \u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05df \u05d1-FSW \u05d0\u05d5 \u05d1\u05de\u05e1\u05de\u05e8\u05d5\u05ea."], [112.1, "\u05e9\u05ea\u05d9 \u05de\u05ea\u05db\u05d5\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05d4\u05df 4043, \u05e2\u05dd \u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df, \u05d5-5356, \u05e2\u05dd \u05de\u05d2\u05e0\u05d6\u05d9\u05d5\u05dd."], [120.8, "4043 \u05d6\u05d5\u05e8\u05de\u05ea \u05d8\u05d5\u05d1 \u05d9\u05d5\u05ea\u05e8 \u05d5\u05e4\u05d7\u05d5\u05ea \u05e8\u05d2\u05d9\u05e9\u05d4 \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd. 5356 \u05d7\u05d6\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d4\u05e6\u05d1\u05e2 \u05e9\u05dc\u05d4 \u05de\u05ea\u05d0\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05d0\u05d9\u05dc\u05d2\u05d5\u05df."], [133.3, "\u05d5\u05d1\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05de\u05d5\u05e7\u05e9\u05d5\u05ea, \u05db\u05de\u05d5 6061 \u05d1\u05de\u05e6\u05d1 T6, \u05d4-HAZ \u05de\u05d0\u05d1\u05d3 \u05d1\u05e2\u05e8\u05da \u05e9\u05dc\u05d9\u05e9 \u05de\u05d4\u05d7\u05d5\u05d6\u05e7, \u05d5\u05e6\u05e8\u05d9\u05da \u05dc\u05e7\u05d7\u05ea \u05d0\u05ea \u05d6\u05d4 \u05d1\u05d7\u05e9\u05d1\u05d5\u05df \u05db\u05d1\u05e8 \u05d1\u05ea\u05db\u05df."], [145.1, "\u05d1-TIG \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d1\u05d6\u05e8\u05dd \u05d7\u05d9\u05dc\u05d5\u05e4\u05d9\u05df: \u05d4\u05d7\u05e6\u05d9 \u05d4\u05d7\u05d9\u05d5\u05d1\u05d9 \u05de\u05e4\u05e8\u05e7 \u05d0\u05ea \u05d4\u05ea\u05d7\u05de\u05d5\u05e6\u05ea, \u05d5\u05d4\u05d7\u05e6\u05d9 \u05d4\u05e9\u05dc\u05d9\u05dc\u05d9 \u05d7\u05d5\u05d3\u05e8 \u05dc\u05e2\u05d5\u05de\u05e7."], [154.0, "\u05d1-MIG \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05e8\u05d9\u05e1\u05d5\u05e1 \u05d0\u05d5 \u05d1\u05e4\u05d5\u05dc\u05e1\u05d9\u05dd, \u05d5\u05ea\u05de\u05d9\u05d3 \u05d3\u05d5\u05d7\u05e4\u05d9\u05dd \u05d0\u05ea \u05d4\u05dc\u05e4\u05d9\u05d3."], [159.1, "\u05d2\u05d6 \u05d4\u05de\u05d2\u05df \u05d4\u05d5\u05d0 \u05d0\u05e8\u05d2\u05d5\u05df, \u05d5\u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d4\u05dc\u05d9\u05d5\u05dd, \u05db\u05d3\u05d9 \u05dc\u05e7\u05d1\u05dc \u05e7\u05e9\u05ea \u05d7\u05de\u05d4 \u05d9\u05d5\u05ea\u05e8."], [165.7, "\u05d7\u05d5\u05d8 \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05e8\u05da, \u05d5\u05dc\u05db\u05df \u05de\u05d6\u05d9\u05e0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e6\u05d9\u05e0\u05d5\u05e8 \u05e7\u05e6\u05e8, \u05d0\u05d5 \u05d1\u05de\u05e2\u05e8\u05db\u05ea \u05e9\u05d3\u05d5\u05d7\u05e4\u05ea \u05d5\u05de\u05d5\u05e9\u05db\u05ea \u05d9\u05d7\u05d3, \u05db\u05d3\u05d9 \u05e9\u05dc\u05d0 \u05d9\u05ea\u05e7\u05e4\u05dc."], [174.3, "\u05d4\u05e0\u05d9\u05e7\u05d5\u05d9 \u05d4\u05d5\u05d0 \u05d7\u05e6\u05d9 \u05de\u05d4\u05d4\u05e6\u05dc\u05d7\u05d4: \u05e7\u05d5\u05d3\u05dd \u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05e9\u05d5\u05de\u05df \u05d1\u05d0\u05e6\u05d8\u05d5\u05df \u05d0\u05d5 \u05d1\u05d0\u05dc\u05db\u05d5\u05d4\u05d5\u05dc, \u05d5\u05e8\u05e7 \u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05d1\u05e8\u05d9\u05e9\u05d9\u05dd \u05d1\u05de\u05d1\u05e8\u05e9\u05ea \u05d0\u05dc-\u05d7\u05dc\u05d3 \u05d9\u05d9\u05e2\u05d5\u05d3\u05d9\u05ea."], [183.7, "\u05d0\u05dd \u05de\u05d1\u05e8\u05d9\u05e9\u05d9\u05dd \u05e7\u05d5\u05d3\u05dd, \u05de\u05db\u05e0\u05d9\u05e1\u05d9\u05dd \u05d0\u05ea \u05d4\u05e9\u05d5\u05de\u05df \u05dc\u05ea\u05d5\u05da \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [187.9, "\u05d5\u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d6\u05de\u05df \u05e7\u05e6\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e0\u05d9\u05e7\u05d5\u05d9, \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05d7\u05d5\u05d6\u05e8\u05ea \u05d5\u05e1\u05d5\u05e4\u05d2\u05ea \u05dc\u05d7\u05d5\u05ea."], [194.2, "\u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05de\u05e8\u05d0\u05e9, \u05d0\u05d1\u05dc \u05d1\u05de\u05ea\u05d9\u05e0\u05d5\u05ea, \u05db\u05d3\u05d9 \u05dc\u05d0 \u05dc\u05e4\u05d2\u05d5\u05e2 \u05d1\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d4\u05de\u05d5\u05e7\u05e9\u05d5\u05ea."], [200.3, "\u05d5\u05d1\u05e1\u05d5\u05e3 \u05d4\u05ea\u05e4\u05e8 \u05de\u05de\u05dc\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05db\u05ea\u05e9, \u05d0\u05d7\u05e8\u05ea \u05e0\u05d5\u05e6\u05e8 \u05d1\u05d5 \u05e1\u05d3\u05e7."], [205.9, "\u05d4\u05e4\u05d2\u05dd \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d4\u05d5\u05d0 \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea, \u05de\u05dc\u05d7\u05d5\u05ea, \u05de\u05e9\u05d5\u05de\u05df \u05d5\u05de\u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05de\u05dc\u05d5\u05db\u05dc\u05db\u05ea."], [212.9, "\u05e1\u05d3\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05de\u05e8\u05db\u05d6 \u05d4\u05ea\u05e4\u05e8 \u05d5\u05d1\u05de\u05db\u05ea\u05e9, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05db\u05e9\u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05de\u05d5\u05e7\u05e9\u05d5\u05ea \u05d1\u05dc\u05d9 \u05de\u05ea\u05db\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05ea\u05d0\u05d9\u05de\u05d4."], [221.2, "\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da \u05e0\u05d2\u05e8\u05dd \u05de\u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05e9\u05dc\u05d0 \u05e4\u05d5\u05e8\u05e7\u05d4, \u05d0\u05d5 \u05de\u05d4\u05ea\u05d7\u05dc\u05d4 \u05e7\u05e8\u05d4 \u05de\u05d3\u05d9."], [226.4, "\u05d5\u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05e0\u05d2\u05e8\u05de\u05d9\u05dd \u05de\u05d4\u05d4\u05ea\u05e4\u05e9\u05d8\u05d5\u05ea \u05d4\u05d2\u05d1\u05d5\u05d4\u05d4, \u05d5\u05dc\u05db\u05df \u05de\u05e7\u05d1\u05e2\u05d9\u05dd \u05d4\u05d9\u05d8\u05d1 \u05d5\u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d0\u05ea \u05e1\u05d3\u05e8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [233.8, "\u05d5\u05db\u05e9\u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc \u05d4-HAZ \u05e7\u05e8\u05d9\u05d8\u05d9, \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d7\u05d6\u05d9\u05e8 \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05de\u05dc\u05d0 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d0\u05dd \u05d4\u05d7\u05dc\u05e7 \u05de\u05d0\u05e4\u05e9\u05e8 \u05d0\u05ea \u05d6\u05d4."], [242.3, "\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d7\u05d6\u05e7 \u05db\u05de\u05d5 \u05e4\u05dc\u05d3\u05d4, \u05e7\u05dc \u05d1\u05db\u05de\u05e2\u05d8 \u05d7\u05e6\u05d9, \u05d5\u05e2\u05de\u05d9\u05d3 \u05de\u05d0\u05d5\u05d3 \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4. \u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05de\u05e9\u05de\u05e9 \u05d1\u05ea\u05e2\u05d5\u05e4\u05d4, \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4 \u05d4\u05db\u05d9\u05de\u05d9\u05ea \u05d5\u05d1\u05e9\u05ea\u05dc\u05d9\u05dd \u05e8\u05e4\u05d5\u05d0\u05d9\u05d9\u05dd."], [253.3, "\u05d0\u05d1\u05dc \u05d1\u05d7\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4 \u05d4\u05d5\u05d0 \u05e1\u05d5\u05e4\u05d2 \u05d7\u05de\u05e6\u05df, \u05d7\u05e0\u05e7\u05df \u05d5\u05de\u05d9\u05de\u05df \u05de\u05d4\u05d0\u05d5\u05d5\u05d9\u05e8, \u05d5\u05e0\u05e2\u05e9\u05d4 \u05e9\u05d1\u05d9\u05e8."], [259.6, "\u05d4\u05d5\u05d0 \u05d2\u05dd \u05de\u05d5\u05dc\u05d9\u05da \u05d7\u05d5\u05dd \u05d2\u05e8\u05d5\u05e2, \u05d5\u05dc\u05db\u05df \u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e9\u05d0\u05e8 \u05d7\u05dd \u05d6\u05de\u05df \u05e8\u05d1, \u05d5\u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d2\u05df \u05e2\u05dc\u05d9\u05d5 \u05dc\u05d0\u05d5\u05e8\u05da \u05d6\u05de\u05df."], [266.9, "\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d2\u05df \u05e2\u05dc\u05d9\u05d5 \u05de\u05db\u05dc \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd, \u05e2\u05d3 \u05e9\u05d4\u05d5\u05d0 \u05de\u05ea\u05e7\u05e8\u05e8 \u05de\u05ea\u05d7\u05ea \u05dc\u05d1\u05e2\u05e8\u05da 400 \u05de\u05e2\u05dc\u05d5\u05ea: \u05d4\u05ea\u05e4\u05e8, \u05d4-HAZ \u05d5\u05d4\u05e9\u05d5\u05e8\u05e9."], [276.1, "\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05d2\u05df \u05d0\u05e8\u05d2\u05d5\u05df \u05e2\u05d5\u05e7\u05d1, trailing shield, \u05e9\u05de\u05d6\u05e8\u05d9\u05dd \u05d0\u05e8\u05d2\u05d5\u05df \u05e2\u05dc \u05d4\u05ea\u05e4\u05e8 \u05e9\u05de\u05d0\u05d7\u05d5\u05e8\u05d9 \u05d4\u05dc\u05e4\u05d9\u05d3, \u05d5\u05d1\u05d4\u05d6\u05e8\u05de\u05ea \u05d0\u05e8\u05d2\u05d5\u05df \u05d1\u05e6\u05d3 \u05d4\u05e9\u05d5\u05e8\u05e9."], [286.0, "\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d1\u05ea\u05d5\u05da \u05ea\u05d0 \u05e1\u05d2\u05d5\u05e8 \u05de\u05dc\u05d0 \u05d0\u05e8\u05d2\u05d5\u05df."], [290.8, "\u05d4\u05e6\u05d1\u05e2 \u05e9\u05dc \u05d4\u05ea\u05e4\u05e8 \u05de\u05e8\u05d0\u05d4 \u05d0\u05dd \u05d4\u05d4\u05d2\u05e0\u05d4 \u05d4\u05e1\u05e4\u05d9\u05e7\u05d4: \u05db\u05e1\u05d5\u05e3 \u05d0\u05d5 \u05e6\u05d4\u05d5\u05d1 \u05d1\u05d4\u05d9\u05e8 \u05d6\u05d4 \u05d8\u05d5\u05d1, \u05db\u05d7\u05d5\u05dc \u05d5\u05e1\u05d2\u05d5\u05dc \u05d6\u05d4 \u05e1\u05d9\u05de\u05df \u05d0\u05d6\u05d4\u05e8\u05d4, \u05d5\u05d0\u05e4\u05d5\u05e8 \u05d0\u05d5 \u05dc\u05d1\u05df \u05d6\u05d4 \u05e4\u05e1\u05d5\u05dc."], [302.6, "\u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1-TIG, \u05d5\u05d2\u05dd \u05d1\u05e4\u05dc\u05d6\u05de\u05d4, \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d5\u05d1\u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd."], [308.7, "\u05d4\u05e0\u05d9\u05e7\u05d9\u05d5\u05df \u05e7\u05e8\u05d9\u05d8\u05d9: \u05de\u05e0\u05e7\u05d9\u05dd \u05d1\u05d0\u05e6\u05d8\u05d5\u05df \u05d0\u05d5 \u05d1\u05d0\u05dc\u05db\u05d5\u05d4\u05d5\u05dc, \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05e2\u05dd \u05db\u05e4\u05e4\u05d5\u05ea \u05e0\u05e7\u05d9\u05d5\u05ea, \u05d5\u05dc\u05d0 \u05e0\u05d5\u05d2\u05e2\u05d9\u05dd \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d9\u05d3\u05d9\u05d9\u05dd."], [317.2, "\u05e9\u05ea\u05d9 \u05d4\u05d3\u05e8\u05d2\u05d5\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05d4\u05df \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d8\u05d4\u05d5\u05e8 \u05de\u05e1\u05d7\u05e8\u05d9\u05ea, \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05e9\u05e9 \u05d0\u05e8\u05d1\u05e2, \u05e2\u05dd \u05e9\u05d9\u05e9\u05d4 \u05d0\u05d7\u05d5\u05d6 \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05d0\u05e8\u05d1\u05e2\u05d4 \u05d0\u05d7\u05d5\u05d6 \u05d5\u05e0\u05d3\u05d9\u05d5\u05dd."], [326.4, "\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05d4\u05d9\u05d0 \u05de\u05d0\u05d5\u05ea\u05d4 \u05d3\u05e8\u05d2\u05d4 \u05db\u05de\u05d5 \u05d4\u05d7\u05dc\u05e7: \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d8\u05d4\u05d5\u05e8, \u05d0\u05d5 \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05e9\u05e9 \u05d0\u05e8\u05d1\u05e2."], [333.0, "\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05dc\u05d0 \u05de\u05ea\u05e7\u05e9\u05d4 \u05db\u05de\u05d5 \u05e4\u05dc\u05d3\u05d4, \u05d5\u05dc\u05d0 \u05e6\u05e8\u05d9\u05da \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d3\u05d9\u05dd. \u05d4-heat input \u05e0\u05de\u05d5\u05da \u05d9\u05d7\u05e1\u05d9\u05ea."], [339.6, "\u05d5\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05ea\u05da \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d4\u05ea\u05db\u05d4 \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea \u05dc\u05e4\u05dc\u05d3\u05d4 \u05d0\u05d5 \u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05db\u05d9 \u05e0\u05d5\u05e6\u05e8\u05d5\u05ea \u05ea\u05e8\u05db\u05d5\u05d1\u05d5\u05ea \u05e9\u05d1\u05d9\u05e8\u05d5\u05ea. \u05dc\u05e9\u05dd \u05db\u05da \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9 \u05de\u05e2\u05d1\u05e8 \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd."], [349.9, "\u05d0\u05ea \u05d4\u05e6\u05d1\u05e2 \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05dc\u05e4\u05e0\u05d9 \u05db\u05dc \u05e0\u05d9\u05e7\u05d5\u05d9, \u05d5\u05ea\u05e4\u05e8 \u05d1\u05e6\u05d1\u05e2 \u05d2\u05d1\u05d5\u05dc\u05d9 \u05de\u05d8\u05e4\u05dc\u05d9\u05dd \u05d1\u05d5 \u05dc\u05e4\u05d9 \u05d4\u05e0\u05d5\u05d4\u05dc."], [358.0, "\u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05e2\u05dc\u05d5\u05ea \u05d4\u05e0\u05d9\u05e7\u05d5\u05d9 \u05d5\u05d4\u05d4\u05db\u05e0\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d5-TIG \u05d1\u05d6\u05e8\u05dd \u05d7\u05d9\u05dc\u05d5\u05e4\u05d9\u05df \u05d0\u05d9\u05d8\u05d9 \u05d9\u05d7\u05e1\u05d9\u05ea."], [364.8, "\u05e6\u05e8\u05d9\u05da \u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05d6\u05e0\u05d4 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05d7\u05d5\u05d8 \u05e8\u05da, \u05d5\u05ea\u05d9\u05e7\u05d5\u05e0\u05d9 \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05dc\u05d5\u05e7\u05d7\u05d9\u05dd \u05d6\u05de\u05df."], [370.6, "\u05d1\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd, \u05d4\u05d0\u05e8\u05d2\u05d5\u05df \u05d4\u05d5\u05d0 \u05e2\u05dc\u05d5\u05ea \u05de\u05e9\u05de\u05e2\u05d5\u05ea\u05d9\u05ea: \u05de\u05d2\u05df \u05d0\u05e8\u05d2\u05d5\u05df \u05e2\u05d5\u05e7\u05d1, \u05d4\u05d2\u05e0\u05ea \u05e9\u05d5\u05e8\u05e9, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05ea\u05d0 \u05e9\u05dc\u05dd."], [378.8, "\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05d9\u05e7\u05e8\u05d4, \u05d4\u05e8\u05ea\u05da \u05e6\u05e8\u05d9\u05da \u05d4\u05db\u05e9\u05e8\u05d4 \u05de\u05d9\u05d5\u05d7\u05d3\u05ea, \u05d5\u05db\u05dc \u05ea\u05e4\u05e8 \u05e0\u05d1\u05d3\u05e7 \u05dc\u05e4\u05d9 \u05d4\u05e6\u05d1\u05e2."], [385.6, "\u05d5\u05ea\u05e4\u05e8 \u05e9\u05e0\u05e4\u05e1\u05dc \u05d1\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d9\u05e7\u05e8 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3, \u05db\u05d9 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e1\u05d9\u05e8 \u05d0\u05ea \u05db\u05dc \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05de\u05d6\u05d5\u05d4\u05dd \u05d5\u05dc\u05e8\u05ea\u05da \u05de\u05d7\u05d3\u05e9."], [393.7, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05e4\u05e8\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05d7\u05de\u05d5\u05e6\u05ea, \u05de\u05e0\u05e7\u05d9\u05dd \u05d4\u05d9\u05d8\u05d1, \u05de\u05e0\u05d4\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05d5\u05dd, \u05d5\u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05de\u05ea\u05db\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05ea\u05d0\u05d9\u05de\u05d4."], [402.6, "\u05d1\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05de\u05d2\u05e0\u05d9\u05dd \u05de\u05d4\u05d0\u05d5\u05d5\u05d9\u05e8 \u05de\u05db\u05dc \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd \u05e2\u05d3 \u05e9\u05d4\u05d5\u05d0 \u05de\u05ea\u05e7\u05e8\u05e8, \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05e6\u05d1\u05e2."], [408.6, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0, \u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05d1\u05d7\u05dc\u05e7 \u05d4\u05e8\u05d1\u05d9\u05e2\u05d9: \u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05d5\u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d5\u05d0\u05d9\u05da \u05e9\u05d5\u05dc\u05d8\u05d9\u05dd \u05d1\u05d4\u05dd."]]};
window.MH_TR["ch19"]={"t": "\u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05d5\u05de\u05d0\u05de\u05e6\u05d9\u05dd", "l": [[3.0, "\u05db\u05dc \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05ea\u05db\u05d5\u05d5\u05e5 \u05db\u05e9\u05d4\u05d5\u05d0 \u05de\u05ea\u05e7\u05e8\u05e8. \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05d4\u05d9\u05d0 \u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05e9\u05e8\u05d5\u05d0\u05d9\u05dd \u05d1\u05e2\u05d9\u05df, \u05d5\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e9\u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05d1\u05ea\u05d5\u05da \u05d4\u05d7\u05dc\u05e7 \u05d5\u05dc\u05d0 \u05e8\u05d5\u05d0\u05d9\u05dd \u05d1\u05db\u05dc\u05dc."], [12.3, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d1\u05d9\u05df \u05dc\u05de\u05d4 \u05d6\u05d4 \u05e7\u05d5\u05e8\u05d4, \u05d0\u05d9\u05dc\u05d5 \u05e1\u05d5\u05d2\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05d9\u05e9, \u05d5\u05d0\u05d9\u05da \u05e9\u05d5\u05dc\u05d8\u05d9\u05dd \u05d1\u05d4\u05dd: \u05d1\u05ea\u05db\u05df, \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8, \u05d5\u05d1\u05d9\u05d9\u05e9\u05d5\u05e8 \u05d0\u05d7\u05e8\u05d9."], [21.6, "\u05d5\u05e0\u05e1\u05d9\u05d9\u05dd \u05d1\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9\u05d9\u05dd: \u05de\u05d4 \u05d4\u05dd \u05e2\u05d5\u05e9\u05d9\u05dd \u05dc\u05d7\u05dc\u05e7, \u05d5\u05d0\u05d9\u05da \u05de\u05e9\u05d7\u05e8\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd."], [28.2, "\u05db\u05e9\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e4\u05e1 \u05e6\u05e8 \u05e9\u05dc \u05de\u05ea\u05db\u05ea, \u05d4\u05d5\u05d0 \u05e8\u05d5\u05e6\u05d4 \u05dc\u05d4\u05ea\u05e4\u05e9\u05d8."], [32.3, "\u05d0\u05d1\u05dc \u05d4\u05de\u05ea\u05db\u05ea \u05d4\u05e7\u05e8\u05d4 \u05e9\u05de\u05e1\u05d1\u05d9\u05d1 \u05de\u05d5\u05e0\u05e2\u05ea \u05de\u05de\u05e0\u05d5, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05e0\u05d3\u05d7\u05e1, \u05d5\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d2\u05dd \u05de\u05ea\u05e2\u05d5\u05d5\u05ea \u05dc\u05e6\u05de\u05d9\u05ea\u05d5\u05ea."], [40.5, "\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8, \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d6\u05d4 \u05de\u05ea\u05db\u05d5\u05d5\u05e5, \u05d5\u05e2\u05db\u05e9\u05d9\u05d5 \u05d4\u05d5\u05d0 \u05e7\u05e6\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05de\u05d4 \u05e9\u05d4\u05d9\u05d4."], [45.9, "\u05d4\u05de\u05ea\u05db\u05ea \u05e9\u05de\u05e1\u05d1\u05d9\u05d1 \u05de\u05ea\u05e0\u05d2\u05d3\u05ea \u05dc\u05d4\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea, \u05d5\u05d4\u05d0\u05d6\u05d5\u05e8 \u05e0\u05e9\u05d0\u05e8 \u05d1\u05de\u05ea\u05d9\u05d7\u05d4."], [51.1, "\u05d4\u05ea\u05e4\u05e8 \u05d5\u05d4\u05d0\u05d6\u05d5\u05e8 \u05e9\u05dc\u05d9\u05d3\u05d5 \u05e0\u05de\u05e6\u05d0\u05d9\u05dd \u05d1\u05de\u05ea\u05d9\u05d7\u05d4, \u05d5\u05de\u05e1\u05d1\u05d9\u05d1\u05dd \u05d4\u05d7\u05d5\u05de\u05e8 \u05e0\u05de\u05e6\u05d0 \u05d1\u05dc\u05d7\u05d9\u05e6\u05d4. \u05d0\u05dc\u05d4 \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9\u05d9\u05dd."], [59.6, "\u05d0\u05dd \u05d4\u05d7\u05dc\u05e7 \u05d7\u05d5\u05e4\u05e9\u05d9 \u05dc\u05d6\u05d5\u05d6, \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05de\u05e9\u05d7\u05e8\u05e8\u05d9\u05dd \u05d0\u05ea \u05e2\u05e6\u05de\u05dd \u05d1\u05e2\u05d9\u05d5\u05d5\u05ea."], [64.5, "\u05d5\u05d0\u05dd \u05d4\u05d5\u05d0 \u05de\u05e8\u05d5\u05e1\u05df \u05d7\u05d6\u05e7, \u05d4\u05d5\u05d0 \u05e0\u05e9\u05d0\u05e8 \u05d9\u05e9\u05e8, \u05d0\u05d1\u05dc \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d1\u05ea\u05d5\u05db\u05d5 \u05d2\u05d1\u05d5\u05d4\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."], [71.0, "\u05d9\u05e9 \u05db\u05de\u05d4 \u05e1\u05d5\u05d2\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd."], [73.6, "\u05d4\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea \u05e8\u05d5\u05d7\u05d1\u05d9\u05ea: \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05ea\u05e7\u05e8\u05d1\u05d9\u05dd \u05d6\u05d4 \u05dc\u05d6\u05d4, \u05e0\u05d9\u05e6\u05d1 \u05dc\u05ea\u05e4\u05e8."], [79.0, "\u05d4\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea \u05d0\u05d5\u05e8\u05db\u05d9\u05ea: \u05d4\u05ea\u05e4\u05e8 \u05de\u05ea\u05e7\u05e6\u05e8 \u05dc\u05d0\u05d5\u05e8\u05db\u05d5."], [83.0, "\u05e2\u05d9\u05d5\u05d5\u05ea \u05d6\u05d5\u05d5\u05d9\u05ea\u05d9: \u05d4\u05dc\u05d5\u05d7\u05d5\u05ea \u05de\u05ea\u05e7\u05e4\u05dc\u05d9\u05dd \u05e1\u05d1\u05d9\u05d1 \u05d4\u05ea\u05e4\u05e8, \u05db\u05d9 \u05d1\u05e6\u05d3 \u05d4\u05e2\u05dc\u05d9\u05d5\u05df \u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05de\u05ea\u05db\u05ea \u05de\u05d5\u05ea\u05db\u05ea \u05de\u05d0\u05e9\u05e8 \u05d1\u05e6\u05d3 \u05d4\u05ea\u05d7\u05ea\u05d5\u05df. \u05d6\u05d4 \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8."], [93.5, "\u05db\u05d9\u05e4\u05d5\u05e3: \u05db\u05e9\u05d4\u05ea\u05e4\u05e8 \u05dc\u05d0 \u05e0\u05de\u05e6\u05d0 \u05d1\u05de\u05e8\u05db\u05d6 \u05d4\u05d7\u05ea\u05da, \u05d4\u05d4\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea \u05d4\u05d0\u05d5\u05e8\u05db\u05d9\u05ea \u05de\u05db\u05d5\u05e4\u05e4\u05ea \u05e7\u05d5\u05e8\u05d4 \u05d0\u05d5 \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05dc\u05d0\u05d5\u05e8\u05db\u05dd."], [101.7, "\u05d2\u05dc\u05d9\u05dd: \u05d1\u05e4\u05d7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd, \u05d4\u05dc\u05d7\u05d9\u05e6\u05d4 \u05e1\u05d1\u05d9\u05d1 \u05d4\u05ea\u05e4\u05e8 \u05d2\u05d5\u05e8\u05de\u05ea \u05dc\u05e4\u05d7 \u05dc\u05d4\u05ea\u05d2\u05dc\u05d5\u05ea, buckling."], [108.9, "\u05d5\u05e2\u05d9\u05d5\u05d5\u05ea \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9: \u05d1\u05de\u05d4\u05dc\u05da \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d4\u05de\u05e8\u05d5\u05d5\u05d7 \u05d1\u05e7\u05e6\u05d4 \u05d4\u05ea\u05e4\u05e8 \u05e0\u05e1\u05d2\u05e8 \u05d0\u05d5 \u05e0\u05e4\u05ea\u05d7."], [115.7, "\u05d1\u05e4\u05d5\u05e2\u05dc, \u05db\u05de\u05d4 \u05e1\u05d5\u05d2\u05d9\u05dd \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d9\u05d7\u05d3 \u05d1\u05d0\u05d5\u05ea\u05d5 \u05d7\u05dc\u05e7, \u05d5\u05e6\u05e8\u05d9\u05da \u05dc\u05d8\u05e4\u05dc \u05d1\u05db\u05d5\u05dc\u05dd."], [121.5, "\u05d2\u05d5\u05d3\u05dc \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05ea\u05dc\u05d5\u05d9 \u05d1\u05db\u05de\u05d4 \u05d2\u05d5\u05e8\u05de\u05d9\u05dd."], [124.3, "\u05d4-heat input: \u05d9\u05d5\u05ea\u05e8 \u05d7\u05d5\u05dd, \u05d9\u05d5\u05ea\u05e8 \u05d4\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea."], [128.2, "\u05e0\u05e4\u05d7 \u05de\u05ea\u05db\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da: \u05ea\u05e4\u05e8 fillet \u05d2\u05d3\u05d5\u05dc \u05de\u05d4\u05e0\u05d3\u05e8\u05e9, \u05d0\u05d5 \u05d7\u05e8\u05d9\u05e5 \u05e8\u05d7\u05d1 \u05de\u05d3\u05d9, \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d4\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea \u05d1\u05dc\u05d9 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05d7\u05d5\u05d6\u05e7."], [137.4, "\u05de\u05e1\u05e4\u05e8 \u05d4\u05de\u05e2\u05d1\u05e8\u05d9\u05dd: \u05db\u05dc \u05de\u05e2\u05d1\u05e8 \u05de\u05d5\u05e1\u05d9\u05e3 \u05e2\u05d5\u05d3 \u05de\u05d7\u05d6\u05d5\u05e8 \u05e9\u05dc \u05d7\u05d9\u05de\u05d5\u05dd \u05d5\u05d4\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea, \u05d5\u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05d4\u05d6\u05d5\u05d5\u05d9\u05ea\u05d9."], [145.7, "\u05d4\u05d7\u05d5\u05de\u05e8: \u05d0\u05dc-\u05d7\u05dc\u05d3 \u05d5\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05ea\u05e4\u05e9\u05d8\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05d5\u05de\u05d5\u05dc\u05d9\u05db\u05d9\u05dd \u05d7\u05d5\u05dd \u05d0\u05d7\u05e8\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05ea\u05e2\u05d5\u05d5\u05ea\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df."], [154.5, "\u05d4\u05e8\u05d9\u05e1\u05d5\u05df: \u05d7\u05dc\u05e7 \u05de\u05e8\u05d5\u05e1\u05df \u05de\u05ea\u05e2\u05d5\u05d5\u05ea \u05e4\u05d7\u05d5\u05ea, \u05d0\u05d1\u05dc \u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05d1\u05d5 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d2\u05d1\u05d5\u05d4\u05d9\u05dd."], [160.6, "\u05d5\u05d4\u05e1\u05d9\u05de\u05d8\u05e8\u05d9\u05d4: \u05ea\u05e4\u05e8 \u05d1\u05e6\u05d3 \u05d0\u05d7\u05d3 \u05d1\u05dc\u05d1\u05d3 \u05de\u05d5\u05e9\u05da \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05dc\u05db\u05d9\u05d5\u05d5\u05e0\u05d5."], [166.5, "\u05d4\u05e9\u05dc\u05d9\u05d8\u05d4 \u05d4\u05d6\u05d5\u05dc\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05de\u05ea\u05d7\u05d9\u05dc\u05d4 \u05db\u05d1\u05e8 \u05d1\u05ea\u05db\u05df."], [170.1, "\u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05ea\u05e4\u05e8 \u05d1\u05d2\u05d5\u05d3\u05dc \u05d4\u05e0\u05d3\u05e8\u05e9, \u05d5\u05dc\u05d0 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8. \u05d2\u05d5\u05d3\u05dc fillet \u05db\u05e4\u05d5\u05dc \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05d1\u05e2\u05e8\u05da \u05e4\u05d9 \u05d0\u05e8\u05d1\u05e2\u05d4 \u05de\u05ea\u05db\u05ea."], [178.4, "\u05db\u05e9\u05d0\u05e4\u05e9\u05e8, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05ea\u05e4\u05e8\u05d9\u05dd \u05dc\u05e1\u05d9\u05e8\u05d5\u05d2\u05d9\u05df \u05d1\u05de\u05e7\u05d5\u05dd \u05ea\u05e4\u05e8 \u05e8\u05e6\u05d9\u05e3."], [183.0, "\u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd, \u05d7\u05e8\u05d9\u05e5 X \u05de\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd \u05d1\u05de\u05e7\u05d5\u05dd \u05d7\u05e8\u05d9\u05e5 V \u05de\u05e6\u05d3 \u05d0\u05d7\u05d3: \u05e4\u05d7\u05d5\u05ea \u05de\u05ea\u05db\u05ea, \u05d5\u05d4\u05d4\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea \u05de\u05d0\u05d5\u05d6\u05e0\u05ea."], [191.9, "\u05de\u05de\u05e7\u05de\u05d9\u05dd \u05ea\u05e4\u05e8\u05d9\u05dd \u05d1\u05d0\u05d5\u05e4\u05df \u05e1\u05d9\u05de\u05d8\u05e8\u05d9, \u05d5\u05e7\u05e8\u05d5\u05d1 \u05dc\u05e6\u05d9\u05e8 \u05d4\u05e0\u05d9\u05d8\u05e8\u05dc\u05d9 \u05e9\u05dc \u05d4\u05d7\u05ea\u05da, \u05db\u05d3\u05d9 \u05e9\u05dc\u05d0 \u05d9\u05db\u05d5\u05e4\u05e4\u05d5 \u05d0\u05d5\u05ea\u05d5."], [198.5, "\u05d5\u05de\u05e6\u05de\u05e6\u05de\u05d9\u05dd \u05d0\u05ea \u05de\u05e1\u05e4\u05e8 \u05d4\u05ea\u05e4\u05e8\u05d9\u05dd: \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05de\u05db\u05d5\u05e4\u05e3 \u05d0\u05d5 \u05de\u05e9\u05d5\u05da \u05d1\u05de\u05e7\u05d5\u05dd \u05db\u05de\u05d4 \u05dc\u05d5\u05d7\u05d5\u05ea \u05de\u05e8\u05d5\u05ea\u05db\u05d9\u05dd."], [206.0, "\u05d2\u05dd \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d9\u05e9 \u05db\u05de\u05d4 \u05db\u05dc\u05d9\u05dd."], [208.2, "\u05db\u05d9\u05d5\u05d5\u05df \u05de\u05d5\u05e7\u05d3\u05dd: \u05de\u05d8\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e8\u05d0\u05e9 \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05e4\u05d5\u05db\u05d4, \u05db\u05da \u05e9\u05d4\u05d4\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea \u05de\u05d7\u05d6\u05d9\u05e8\u05d4 \u05d0\u05d5\u05ea\u05dd \u05dc\u05de\u05e7\u05d5\u05dd."], [215.3, "\u05e7\u05d9\u05d1\u05d5\u05e2: \u05d4\u05ea\u05e7\u05e0\u05d9\u05dd \u05d5\u05de\u05d4\u05d3\u05e7\u05d9\u05dd \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05d6\u05de\u05df \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d0\u05d1\u05dc \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05d7\u05dc\u05e7 \u05d6\u05d6 \u05db\u05e9\u05de\u05e9\u05d7\u05e8\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5."], [225.0, "\u05e8\u05d9\u05ea\u05d5\u05db\u05d9 \u05d4\u05db\u05e0\u05d4: \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05e7\u05e6\u05e8\u05d5\u05ea, \u05d1\u05de\u05e8\u05d5\u05d5\u05d7\u05d9\u05dd \u05e7\u05d1\u05d5\u05e2\u05d9\u05dd \u05d5\u05d1\u05e1\u05d3\u05e8 \u05e0\u05db\u05d5\u05df, \u05db\u05d3\u05d9 \u05e9\u05d4\u05de\u05e8\u05d5\u05d5\u05d7 \u05dc\u05d0 \u05d9\u05d9\u05e1\u05d2\u05e8."], [232.4, "\u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05de\u05e8\u05d0\u05e9 \u05ea\u05d5\u05e1\u05e4\u05ea \u05d0\u05d5\u05e8\u05da, \u05e9\u05de\u05e4\u05e6\u05d4 \u05e2\u05dc \u05d4\u05d4\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea \u05d4\u05e8\u05d5\u05d7\u05d1\u05d9\u05ea."], [238.6, "\u05e1\u05d3\u05e8 \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05d0\u05d5\u05d6\u05df: \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05dc\u05e1\u05d9\u05e8\u05d5\u05d2\u05d9\u05df \u05de\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd, \u05d5\u05de\u05d4\u05de\u05e8\u05db\u05d6 \u05d4\u05d7\u05d5\u05e6\u05d4."], [244.7, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05e6\u05e2\u05d3\u05d9\u05dd \u05dc\u05d0\u05d7\u05d5\u05e8, backstep, \u05db\u05dc \u05e7\u05d8\u05e2 \u05e7\u05e6\u05e8 \u05de\u05e8\u05d5\u05ea\u05da \u05d1\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05e4\u05d5\u05da \u05dc\u05d4\u05ea\u05e7\u05d3\u05de\u05d5\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea."], [252.2, "\u05d5\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d3\u05d9\u05dc\u05d5\u05d2\u05d9\u05dd \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05e7\u05d8\u05e2\u05d9\u05dd \u05de\u05e4\u05d5\u05d6\u05e8\u05d9\u05dd, \u05db\u05d3\u05d9 \u05dc\u05e4\u05d6\u05e8 \u05d0\u05ea \u05d4\u05d7\u05d5\u05dd \u05e2\u05dc \u05db\u05dc \u05d4\u05d0\u05d5\u05e8\u05da."], [258.1, "\u05ea\u05d4\u05dc\u05d9\u05da \u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05d7\u05d5\u05dd, \u05db\u05de\u05d5 \u05e4\u05d5\u05dc\u05e1\u05d9\u05dd \u05d0\u05d5 \u05dc\u05d9\u05d9\u05d6\u05e8, \u05de\u05e7\u05d8\u05d9\u05df \u05d0\u05ea \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea."], [263.2, "\u05d5\u05e4\u05e1\u05d9 \u05e0\u05d7\u05d5\u05e9\u05ea \u05de\u05ea\u05d7\u05ea \u05d0\u05d5 \u05dc\u05d9\u05d3 \u05d4\u05ea\u05e4\u05e8 \u05e1\u05d5\u05e4\u05d2\u05d9\u05dd \u05d7\u05d5\u05dd, \u05d5\u05de\u05e7\u05d8\u05d9\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d7\u05dd."], [270.2, "\u05d0\u05dd \u05d1\u05db\u05dc \u05d6\u05d0\u05ea \u05e0\u05d5\u05e6\u05e8 \u05e2\u05d9\u05d5\u05d5\u05ea, \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d9\u05d9\u05e9\u05e8."], [273.3, "\u05d9\u05d9\u05e9\u05d5\u05e8 \u05de\u05db\u05e0\u05d9, \u05d1\u05dc\u05d7\u05e5 \u05d0\u05d5 \u05d1\u05db\u05d9\u05e4\u05d5\u05e3, \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d5\u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e4\u05e9\u05d5\u05d8\u05d9\u05dd."], [279.5, "\u05d1\u05d9\u05d9\u05e9\u05d5\u05e8 \u05d1\u05d7\u05d5\u05dd \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d0\u05d5 \u05de\u05e9\u05d5\u05dc\u05e9\u05d9\u05dd \u05d1\u05de\u05e7\u05d5\u05dd \u05de\u05d3\u05d5\u05d9\u05e7, \u05d5\u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05dc\u05d4\u05dd \u05dc\u05d4\u05ea\u05db\u05d5\u05d5\u05e5, \u05d5\u05d6\u05d4 \u05de\u05d5\u05e9\u05da \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05d7\u05d6\u05e8\u05d4."], [288.5, "\u05d4\u05d5\u05d0 \u05d3\u05d5\u05e8\u05e9 \u05e0\u05d9\u05e1\u05d9\u05d5\u05df, \u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e9\u05e2\u05d1\u05e8\u05d5 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05dc\u05d4\u05d2\u05d1\u05d9\u05dc \u05d0\u05ea \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4, \u05db\u05d3\u05d9 \u05dc\u05d0 \u05dc\u05e4\u05d2\u05d5\u05e2 \u05d1\u05ea\u05db\u05d5\u05e0\u05d5\u05ea."], [296.0, "\u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3, \u05d5\u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05dc\u05d2\u05de\u05e8 \u05e8\u05e7 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [302.5, "\u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9\u05d9\u05dd \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05d2\u05d1\u05d5\u05dc \u05d4\u05db\u05e0\u05d9\u05e2\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8."], [307.0, "\u05d4\u05dd \u05dc\u05d0 \u05e0\u05e8\u05d0\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d1\u05e9\u05d9\u05d8\u05d5\u05ea \u05de\u05d9\u05d5\u05d7\u05d3\u05d5\u05ea, \u05dc\u05de\u05e9\u05dc \u05e7\u05d9\u05d3\u05d5\u05d7 \u05d7\u05d5\u05e8 \u05e7\u05d8\u05df \u05d5\u05de\u05d3\u05d9\u05d3\u05ea \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9 \u05e1\u05d1\u05d9\u05d1\u05d5."], [314.9, "\u05d4\u05dd \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05de\u05d0\u05de\u05e6\u05d9 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4, \u05d5\u05de\u05e7\u05e6\u05e8\u05d9\u05dd \u05d0\u05ea \u05d7\u05d9\u05d9 \u05d4\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05e9\u05d5\u05dc\u05d9 \u05d4\u05ea\u05e4\u05e8."], [321.1, "\u05d4\u05dd \u05de\u05d2\u05d1\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e1\u05d3\u05e7\u05d9 \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d1\u05de\u05d0\u05de\u05e5, \u05d5\u05dc\u05e9\u05d1\u05e8 \u05e4\u05e8\u05d9\u05da \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4."], [327.7, "\u05d5\u05d1\u05d7\u05dc\u05e7 \u05e9\u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da, \u05d4\u05e1\u05e8\u05ea \u05d7\u05d5\u05de\u05e8 \u05de\u05e9\u05d7\u05e8\u05e8\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d6\u05d6 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05db\u05d1\u05e8 \u05e2\u05dc \u05d4\u05de\u05db\u05d5\u05e0\u05d4."], [336.7, "\u05dc\u05db\u05df \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05dc\u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e1\u05d5\u05e4\u05d9."], [342.9, "\u05d9\u05e9 \u05d2\u05dd \u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d1\u05d5\u05d5\u05d9\u05d1\u05e8\u05e6\u05d9\u05d4, \u05d5\u05d4\u05e7\u05e9\u05d5\u05ea \u05e4\u05d8\u05d9\u05e9 \u05e2\u05dc \u05e9\u05d5\u05dc\u05d9 \u05d4\u05ea\u05e4\u05e8, peening, \u05e9\u05de\u05e9\u05e4\u05e8\u05d5\u05ea \u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."], [352.4, "\u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05d4\u05dd \u05d0\u05d7\u05d3 \u05d4\u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05d4\u05d9\u05e7\u05e8\u05d9\u05dd \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05de\u05e8\u05d5\u05ea\u05da."], [356.3, "\u05d9\u05d9\u05e9\u05d5\u05e8 \u05dc\u05d5\u05e7\u05d7 \u05e9\u05e2\u05d5\u05ea \u05e2\u05d1\u05d5\u05d3\u05d4, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05d6\u05de\u05df \u05de\u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e2\u05e6\u05de\u05d5."], [361.1, "\u05d7\u05dc\u05e7 \u05e9\u05d6\u05d6 \u05de\u05d7\u05d5\u05e5 \u05dc\u05d8\u05d5\u05dc\u05e8\u05e0\u05e1 \u05d4\u05d5\u05dc\u05da \u05dc\u05e4\u05e1\u05d5\u05dc\u05ea, \u05d0\u05d5 \u05d3\u05d5\u05e8\u05e9 \u05ea\u05d9\u05e7\u05d5\u05df."], [365.9, "\u05ea\u05d5\u05e1\u05e4\u05d5\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3, \u05d4\u05ea\u05e7\u05e0\u05d9\u05dd, \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05dc\u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d6\u05de\u05df \u05d5\u05e2\u05dc\u05d5\u05ea."], [372.4, "\u05d5\u05dc\u05db\u05df \u05d4\u05db\u05d9 \u05d6\u05d5\u05dc \u05dc\u05d8\u05e4\u05dc \u05d1\u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05db\u05d1\u05e8 \u05d1\u05ea\u05db\u05df: \u05e4\u05d7\u05d5\u05ea \u05de\u05ea\u05db\u05ea \u05e8\u05d9\u05ea\u05d5\u05da, \u05e1\u05d9\u05de\u05d8\u05e8\u05d9\u05d4, \u05d5\u05ea\u05db\u05e0\u05d5\u05df \u05e1\u05d3\u05e8 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [381.2, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d4\u05d4\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea \u05e9\u05dc \u05d4\u05ea\u05e4\u05e8 \u05d9\u05d5\u05e6\u05e8\u05ea \u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05d5\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e9\u05d9\u05d5\u05e8\u05d9\u05d9\u05dd."], [387.1, "\u05e9\u05d5\u05dc\u05d8\u05d9\u05dd \u05d1\u05d4\u05dd \u05d1\u05ea\u05db\u05df, \u05d1\u05e1\u05d3\u05e8 \u05d5\u05d1\u05d7\u05d5\u05dd \u05d1\u05d6\u05de\u05df \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8, \u05d5\u05de\u05ea\u05e7\u05e0\u05d9\u05dd \u05d1\u05d9\u05d9\u05e9\u05d5\u05e8 \u05d0\u05d5 \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd."], [394.2, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05de\u05ea\u05d7\u05d9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d4\u05d0\u05d7\u05e8\u05d5\u05df, \u05ea\u05db\u05df \u05d5\u05d0\u05d9\u05db\u05d5\u05ea: \u05e1\u05d9\u05de\u05d5\u05e0\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."]]};
window.MH_TR["ch20"]={"t": "\u05e1\u05d9\u05de\u05d5\u05e0\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8", "l": [[3.0, "\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05e8\u05d9\u05ea\u05d5\u05da \u05dc\u05d0 \u05de\u05e1\u05d1\u05d9\u05e8\u05d9\u05dd \u05d1\u05de\u05d9\u05dc\u05d9\u05dd. \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e1\u05de\u05dc \u05e8\u05d9\u05ea\u05d5\u05da: \u05d7\u05e5, \u05e7\u05d5, \u05e1\u05de\u05dc \u05e7\u05d8\u05df, \u05d5\u05de\u05e1\u05e4\u05e8\u05d9\u05dd."], [11.9, "\u05de\u05d9 \u05e9\u05d9\u05d5\u05d3\u05e2 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05d4\u05e1\u05de\u05dc \u05d9\u05d5\u05d3\u05e2 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d0\u05d9\u05d6\u05d4 \u05ea\u05e4\u05e8 \u05dc\u05d1\u05e6\u05e2, \u05d1\u05d0\u05d9\u05d6\u05d4 \u05e6\u05d3, \u05d1\u05d0\u05d9\u05d6\u05d4 \u05d2\u05d5\u05d3\u05dc \u05d5\u05d1\u05d0\u05d9\u05d6\u05d4 \u05ea\u05d4\u05dc\u05d9\u05da."], [19.9, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05dc\u05de\u05d3 \u05d0\u05ea \u05de\u05d1\u05e0\u05d4 \u05d4\u05e1\u05de\u05dc \u05dc\u05e4\u05d9 ISO 2553, \u05d5\u05e0\u05e9\u05d5\u05d5\u05d4 \u05dc-AWS, \u05e9\u05d1\u05d4 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd \u05d4\u05e4\u05d5\u05db\u05d9\u05dd."], [29.6, "\u05dc\u05e1\u05de\u05dc \u05e8\u05d9\u05ea\u05d5\u05da \u05d9\u05e9 \u05db\u05de\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05d1\u05d5\u05e2\u05d9\u05dd."], [32.7, "\u05e7\u05d5 \u05d4\u05d7\u05e5 \u05de\u05e6\u05d1\u05d9\u05e2 \u05e2\u05dc \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05e8\u05ea\u05da."], [36.4, "\u05e7\u05d5 \u05d4\u05d9\u05d9\u05d7\u05d5\u05e1 \u05d4\u05d5\u05d0 \u05e7\u05d5 \u05d0\u05d5\u05e4\u05e7\u05d9 \u05de\u05dc\u05d0, \u05e9\u05de\u05d7\u05d5\u05d1\u05e8 \u05dc\u05d7\u05e5. \u05e2\u05dc\u05d9\u05d5 \u05de\u05e0\u05d9\u05d7\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05de\u05dc."], [42.4, "\u05d1-ISO \u05d9\u05e9 \u05d2\u05dd \u05e7\u05d5 \u05d6\u05d9\u05d4\u05d5\u05d9 \u05de\u05e7\u05d5\u05d5\u05e7\u05d5, \u05de\u05e7\u05d1\u05d9\u05dc \u05dc\u05e7\u05d5 \u05d4\u05d9\u05d9\u05d7\u05d5\u05e1, \u05de\u05e2\u05dc\u05d9\u05d5 \u05d0\u05d5 \u05de\u05ea\u05d7\u05ea\u05d9\u05d5."], [48.5, "\u05d4\u05e1\u05de\u05dc \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9 \u05de\u05e8\u05d0\u05d4 \u05d0\u05ea \u05e1\u05d5\u05d2 \u05d4\u05ea\u05e4\u05e8: fillet, \u05d7\u05e8\u05d9\u05e5 V, \u05d5\u05e2\u05d5\u05d3."], [54.3, "\u05de\u05e9\u05de\u05d0\u05dc \u05dc\u05e1\u05de\u05dc \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05d2\u05d5\u05d3\u05dc \u05d4\u05ea\u05e4\u05e8, \u05d5\u05de\u05d9\u05de\u05d9\u05df \u05d0\u05ea \u05d4\u05d0\u05d5\u05e8\u05da."], [59.2, "\u05d5\u05d1\u05e7\u05e6\u05d4 \u05d4\u05e7\u05d5 \u05d9\u05e9 \u05d6\u05e0\u05d1, \u05e2\u05dd \u05de\u05d9\u05d3\u05e2 \u05e0\u05d5\u05e1\u05e3 \u05db\u05de\u05d5 \u05de\u05e1\u05e4\u05e8 \u05d4\u05ea\u05d4\u05dc\u05d9\u05da."], [64.4, "\u05db\u05dc \u05d0\u05dc\u05d4 \u05de\u05d5\u05d2\u05d3\u05e8\u05d9\u05dd \u05d1\u05ea\u05e7\u05df, \u05db\u05da \u05e9\u05d4\u05e1\u05de\u05dc \u05e0\u05e7\u05e8\u05d0 \u05d0\u05d5\u05ea\u05d5 \u05d3\u05d1\u05e8 \u05d1\u05db\u05dc \u05de\u05e4\u05e2\u05dc \u05d5\u05d1\u05db\u05dc \u05de\u05d3\u05d9\u05e0\u05d4."], [71.1, "\u05d4\u05e9\u05d0\u05dc\u05d4 \u05d4\u05d7\u05e9\u05d5\u05d1\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8: \u05d1\u05d0\u05d9\u05d6\u05d4 \u05e6\u05d3 \u05de\u05e8\u05ea\u05db\u05d9\u05dd?"], [75.3, "\u05dc\u05db\u05dc \u05d7\u05d9\u05d1\u05d5\u05e8 \u05d9\u05e9 \u05e6\u05d3 \u05d4\u05d7\u05e5, \u05d4\u05e6\u05d3 \u05e9\u05d4\u05d7\u05e5 \u05e0\u05d5\u05d2\u05e2 \u05d1\u05d5, \u05d5\u05d4\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9."], [80.8, "\u05d1-ISO, \u05e1\u05de\u05dc \u05e2\u05dc \u05d4\u05e7\u05d5 \u05d4\u05de\u05dc\u05d0 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05e6\u05d3 \u05d4\u05d7\u05e5."], [86.2, "\u05e1\u05de\u05dc \u05e2\u05dc \u05d4\u05e7\u05d5 \u05d4\u05de\u05e7\u05d5\u05d5\u05e7\u05d5 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9, \u05dc\u05d0 \u05de\u05e9\u05e0\u05d4 \u05d0\u05dd \u05d4\u05de\u05e7\u05d5\u05d5\u05e7\u05d5 \u05de\u05e2\u05dc \u05d0\u05d5 \u05de\u05ea\u05d7\u05ea."], [93.5, "\u05d1-AWS \u05d0\u05d9\u05df \u05e7\u05d5 \u05de\u05e7\u05d5\u05d5\u05e7\u05d5: \u05e1\u05de\u05dc \u05de\u05ea\u05d7\u05ea \u05dc\u05e7\u05d5 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e6\u05d3 \u05d4\u05d7\u05e5, \u05d5\u05e1\u05de\u05dc \u05de\u05e2\u05dc \u05d4\u05e7\u05d5 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05d4\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9."], [103.1, "\u05e1\u05de\u05dc \u05de\u05e9\u05e0\u05d9 \u05e6\u05d3\u05d9 \u05d4\u05e7\u05d5 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd, \u05d5\u05d0\u05d6 \u05d0\u05d9\u05df \u05e7\u05d5 \u05de\u05e7\u05d5\u05d5\u05e7\u05d5."], [109.8, "\u05dc\u05db\u05df \u05dc\u05e4\u05e0\u05d9 \u05e9\u05e7\u05d5\u05e8\u05d0\u05d9\u05dd, \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05dc\u05e4\u05d9 \u05d0\u05d9\u05d6\u05d4 \u05ea\u05e7\u05df \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e0\u05e2\u05e9\u05d4. \u05d1\u05dc\u05d1\u05d5\u05dc \u05db\u05d0\u05df \u05de\u05d5\u05d1\u05d9\u05dc \u05dc\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05e6\u05d3 \u05d4\u05dc\u05d0 \u05e0\u05db\u05d5\u05df."], [118.6, "\u05d4\u05e1\u05de\u05dc\u05d9\u05dd \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9\u05d9\u05dd \u05de\u05ea\u05d0\u05e8\u05d9\u05dd \u05d0\u05ea \u05e6\u05d5\u05e8\u05ea \u05d4\u05ea\u05e4\u05e8."], [122.6, "\u05de\u05e9\u05d5\u05dc\u05e9 \u05d4\u05d5\u05d0 \u05ea\u05e4\u05e8 fillet."], [125.3, "\u05e9\u05e0\u05d9 \u05e7\u05d5\u05d5\u05d9\u05dd \u05de\u05e7\u05d1\u05d9\u05dc\u05d9\u05dd \u05d4\u05dd \u05ea\u05e4\u05e8 \u05e7\u05ea \u05d9\u05e9\u05e8, \u05d1\u05dc\u05d9 \u05d4\u05db\u05e0\u05ea \u05e9\u05d5\u05dc\u05d9\u05d9\u05dd."], [130.5, "V \u05d4\u05d5\u05d0 \u05d7\u05e8\u05d9\u05e5 V, \u05d5\u05d7\u05e6\u05d9 V \u05d4\u05d5\u05d0 \u05e9\u05d9\u05e4\u05d5\u05e2 \u05d1\u05e6\u05d3 \u05d0\u05d7\u05d3 \u05d1\u05dc\u05d1\u05d3."], [135.5, "\u05d1\u05d7\u05e6\u05d9 V, \u05d4\u05e7\u05d5 \u05d4\u05e0\u05d9\u05e6\u05d1 \u05ea\u05de\u05d9\u05d3 \u05d1\u05e6\u05d3 \u05e9\u05de\u05d0\u05dc, \u05d5\u05d4\u05d7\u05e5 \u05de\u05e6\u05d1\u05d9\u05e2 \u05e2\u05dc \u05d4\u05d7\u05dc\u05e7 \u05e9\u05de\u05db\u05d9\u05e0\u05d9\u05dd \u05dc\u05d5 \u05d0\u05ea \u05d4\u05e9\u05d9\u05e4\u05d5\u05e2."], [142.6, "\u05d9\u05e9 \u05d2\u05dd \u05e1\u05de\u05dc\u05d9\u05dd \u05dc\u05d7\u05e8\u05d9\u05e6\u05d9 U \u05d5-J, \u05e9\u05de\u05ea\u05d0\u05d9\u05de\u05d9\u05dd \u05dc\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd."], [147.7, "\u05e2\u05d9\u05d2\u05d5\u05dc \u05d4\u05d5\u05d0 \u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e7\u05d5\u05d3\u05ea\u05d9, \u05d5\u05e9\u05e0\u05d9 \u05e7\u05d5\u05d5\u05d9\u05dd \u05d3\u05e8\u05da \u05e2\u05d9\u05d2\u05d5\u05dc \u05d4\u05dd \u05e8\u05d9\u05ea\u05d5\u05da \u05ea\u05e4\u05e8 \u05e8\u05e6\u05d9\u05e3 \u05d1\u05d2\u05dc\u05d2\u05dc\u05d5\u05ea."], [154.5, "\u05d5\u05de\u05dc\u05d1\u05df \u05de\u05e1\u05de\u05df \u05e8\u05d9\u05ea\u05d5\u05da \u05e4\u05e7\u05e7, \u05e9\u05de\u05de\u05dc\u05d0 \u05d7\u05d5\u05e8 \u05d0\u05d5 \u05d7\u05e8\u05d9\u05e5 \u05d1\u05d0\u05d7\u05d3 \u05d4\u05dc\u05d5\u05d7\u05d5\u05ea."], [160.2, "\u05d5\u05e7\u05e9\u05ea \u05e7\u05d8\u05e0\u05d4 \u05de\u05ea\u05d7\u05ea \u05dc\u05e1\u05de\u05dc \u05de\u05e1\u05de\u05e0\u05ea \u05de\u05e2\u05d1\u05e8 \u05e9\u05d5\u05e8\u05e9 \u05de\u05d4\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9."], [166.0, "\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e9\u05dc\u05d1 \u05e1\u05de\u05dc\u05d9\u05dd \u05de\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd."], [168.7, "\u05e9\u05e0\u05d9 V \u05d2\u05d1 \u05d0\u05dc \u05d2\u05d1 \u05d4\u05dd \u05d7\u05e8\u05d9\u05e5 X, \u05d5\u05e9\u05e0\u05d9 \u05d7\u05e6\u05d0\u05d9 V \u05d4\u05dd \u05d7\u05e8\u05d9\u05e5 K."], [174.6, "\u05d5\u05de\u05e9\u05d5\u05dc\u05e9 \u05de\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd \u05d4\u05d5\u05d0 fillet \u05db\u05e4\u05d5\u05dc."], [178.1, "\u05e1\u05de\u05dc\u05d9\u05dd \u05de\u05e9\u05dc\u05d9\u05de\u05d9\u05dd \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05e6\u05d5\u05e8\u05ea \u05e4\u05e0\u05d9 \u05d4\u05ea\u05e4\u05e8: \u05e7\u05d5 \u05d9\u05e9\u05e8 \u05d4\u05d5\u05d0 \u05ea\u05e4\u05e8 \u05e9\u05d8\u05d5\u05d7, \u05e7\u05e9\u05ea \u05db\u05dc\u05e4\u05d9 \u05d7\u05d5\u05e5 \u05d4\u05d9\u05d0 \u05ea\u05e4\u05e8 \u05e7\u05de\u05d5\u05e8, \u05d5\u05e7\u05e9\u05ea \u05db\u05dc\u05e4\u05d9 \u05e4\u05e0\u05d9\u05dd \u05d4\u05d9\u05d0 \u05ea\u05e4\u05e8 \u05e7\u05e2\u05d5\u05e8."], [190.5, "\u05de\u05dc\u05d1\u05df \u05e2\u05dd \u05d4\u05d0\u05d5\u05ea M \u05de\u05e1\u05de\u05df \u05e4\u05e1 backing \u05e9\u05e0\u05e9\u05d0\u05e8, \u05d5\u05e2\u05dd MR \u05e4\u05e1 \u05e9\u05de\u05d5\u05e1\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [199.5, "\u05d9\u05e9 \u05d2\u05dd \u05e1\u05de\u05dc \u05dc\u05e9\u05d5\u05dc\u05d9 \u05ea\u05e4\u05e8 \u05e9\u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05d1\u05e6\u05d5\u05e8\u05d4 \u05d7\u05dc\u05e7\u05d4 \u05d0\u05dc \u05de\u05ea\u05db\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1, \u05d5\u05d6\u05d4 \u05d7\u05e9\u05d5\u05d1 \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e2\u05d5\u05de\u05d3\u05d9\u05dd \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."], [207.1, "\u05e2\u05d9\u05d2\u05d5\u05dc \u05d1\u05e4\u05d9\u05e0\u05d4 \u05e9\u05dc \u05e7\u05d5 \u05d4\u05d7\u05e5 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05e1\u05d1\u05d9\u05d1 \u05dc\u05db\u05dc \u05d4\u05d4\u05d9\u05e7\u05e3."], [212.2, "\u05d5\u05d3\u05d2\u05dc \u05e7\u05d8\u05df \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05e9\u05d8\u05d7, \u05d1\u05d0\u05ea\u05e8 \u05d4\u05d4\u05e8\u05db\u05d1\u05d4, \u05d5\u05dc\u05d0 \u05d1\u05de\u05e4\u05e2\u05dc."], [218.6, "\u05e2\u05db\u05e9\u05d9\u05d5 \u05dc\u05de\u05d9\u05d3\u05d5\u05ea."], [220.4, "\u05d1-fillet \u05dc\u05e4\u05d9 ISO, \u05d4\u05d0\u05d5\u05ea a \u05de\u05e6\u05d9\u05d9\u05e0\u05ea \u05d0\u05ea \u05e2\u05d5\u05d1\u05d9 \u05d4\u05e6\u05d5\u05d5\u05d0\u05e8, \u05d5\u05d4\u05d0\u05d5\u05ea z \u05de\u05e6\u05d9\u05d9\u05e0\u05ea \u05d0\u05ea \u05d0\u05d5\u05e8\u05da \u05d4\u05e8\u05d2\u05dc."], [228.5, "\u05d1\u05ea\u05e4\u05e8 \u05e9\u05d5\u05d5\u05d4 \u05e6\u05dc\u05e2\u05d5\u05ea, z \u05d2\u05d3\u05d5\u05dc \u05e4\u05d9 1.4 \u05d1\u05e2\u05e8\u05da \u05de-a. \u05db\u05dc\u05d5\u05de\u05e8 a5 \u05d5-z5 \u05d4\u05dd \u05e9\u05e0\u05d9 \u05ea\u05e4\u05e8\u05d9\u05dd \u05d1\u05d2\u05d3\u05dc\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd \u05dc\u05d2\u05de\u05e8\u05d9."], [240.1, "\u05d1-AWS \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05e8\u05e7 \u05de\u05e1\u05e4\u05e8, \u05d5\u05d4\u05d5\u05d0 \u05ea\u05de\u05d9\u05d3 \u05d0\u05d5\u05e8\u05da \u05d4\u05e8\u05d2\u05dc."], [245.2, "\u05d0\u05dd \u05d0\u05d9\u05df \u05d0\u05d5\u05e8\u05da \u05de\u05d9\u05de\u05d9\u05df \u05dc\u05e1\u05de\u05dc, \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05dc\u05db\u05dc \u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8."], [249.6, "\u05ea\u05e4\u05e8 \u05dc\u05e1\u05d9\u05e8\u05d5\u05d2\u05d9\u05df \u05dc\u05e4\u05d9 ISO \u05e0\u05db\u05ea\u05d1 \u05db\u05de\u05e1\u05e4\u05e8 \u05d4\u05e7\u05d8\u05e2\u05d9\u05dd \u05db\u05e4\u05d5\u05dc \u05d4\u05d0\u05d5\u05e8\u05da, \u05d5\u05d1\u05e1\u05d5\u05d2\u05e8\u05d9\u05d9\u05dd \u05d4\u05de\u05e8\u05d5\u05d5\u05d7. \u05dc\u05de\u05e9\u05dc, \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e7\u05d8\u05e2\u05d9\u05dd \u05e9\u05dc 50 \u05de\u05f4\u05de, \u05d1\u05de\u05e8\u05d5\u05d5\u05d7 \u05e9\u05dc 100."], [261.9, "\u05db\u05e9\u05d4\u05e7\u05d8\u05e2\u05d9\u05dd \u05de\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd \u05de\u05d5\u05d6\u05d6\u05d9\u05dd \u05d6\u05d4 \u05de\u05d5\u05dc \u05d6\u05d4, \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05e1\u05d9\u05de\u05df Z \u05e7\u05d8\u05df."], [267.2, "\u05d1-AWS \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05d5\u05e8\u05da \u05d5\u05e4\u05e1\u05d9\u05e2\u05d4, \u05dc\u05de\u05e9\u05dc 50 \u05de\u05e7\u05e3 150, \u05d5\u05d4\u05e4\u05e1\u05d9\u05e2\u05d4 \u05e0\u05de\u05d3\u05d3\u05ea \u05de\u05de\u05e8\u05db\u05d6 \u05e7\u05d8\u05e2 \u05dc\u05de\u05e8\u05db\u05d6 \u05d4\u05e7\u05d8\u05e2 \u05d4\u05d1\u05d0. \u05d2\u05dd \u05db\u05d0\u05df \u05d4\u05d4\u05d1\u05d3\u05dc \u05d1\u05d9\u05df \u05d4\u05ea\u05e7\u05e0\u05d9\u05dd \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4."], [281.6, "\u05d5\u05d1\u05ea\u05e4\u05e8 \u05e7\u05ea, \u05d4\u05d0\u05d5\u05ea s \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e1\u05de\u05dc \u05de\u05e6\u05d9\u05d9\u05e0\u05ea \u05d0\u05ea \u05e2\u05d5\u05de\u05e7 \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4 \u05d4\u05e0\u05d3\u05e8\u05e9."], [288.2, "\u05d4\u05d6\u05e0\u05d1 \u05d1\u05e1\u05d5\u05e3 \u05e7\u05d5 \u05d4\u05d9\u05d9\u05d7\u05d5\u05e1 \u05e0\u05d5\u05e9\u05d0 \u05de\u05d9\u05d3\u05e2 \u05e9\u05dc\u05d0 \u05e0\u05db\u05e0\u05e1 \u05d1\u05e1\u05de\u05dc."], [292.6, "\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05e1\u05e4\u05e8 \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05dc\u05e4\u05d9 ISO 4063, \u05db\u05de\u05d5 135 \u05dc-MAG \u05d0\u05d5 141 \u05dc-TIG."], [302.5, "\u05d0\u05e4\u05e9\u05e8 \u05dc\u05db\u05ea\u05d5\u05d1 \u05e9\u05dd \u05d2\u05dd \u05d0\u05ea \u05e8\u05de\u05ea \u05d4\u05d0\u05d9\u05db\u05d5\u05ea \u05dc\u05e4\u05d9 ISO 5817, \u05ea\u05e0\u05d5\u05d7\u05ea \u05e8\u05d9\u05ea\u05d5\u05da, \u05d0\u05d5 \u05d4\u05e4\u05e0\u05d9\u05d4 \u05dc\u05e0\u05d5\u05d4\u05dc \u05d4-WPS."], [311.7, "\u05db\u05e9\u05d0\u05d9\u05df \u05de\u05d9\u05d3\u05e2, \u05d0\u05d9\u05df \u05d6\u05e0\u05d1, \u05d5\u05d0\u05d6 \u05d7\u05dc\u05d9\u05dd \u05d4\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05d5\u05ea \u05e9\u05d1\u05d4\u05e2\u05e8\u05d5\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8."], [317.6, "\u05d5\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05ea\u05e4\u05e8\u05d9\u05dd \u05d6\u05d4\u05d9\u05dd, \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05d4\u05db\u05dc\u05dc\u05d9\u05ea \u05e4\u05e2\u05dd \u05d0\u05d7\u05ea \u05d1\u05d4\u05e2\u05e8\u05d4, \u05d5\u05d1\u05e1\u05de\u05dc\u05d9\u05dd \u05e8\u05e7 \u05d0\u05ea \u05de\u05d4 \u05e9\u05e9\u05d5\u05e0\u05d4."], [326.3, "\u05d1\u05d5\u05d0\u05d5 \u05e0\u05e7\u05e8\u05d0 \u05d3\u05d5\u05d2\u05de\u05d4."], [327.8, "\u05d4\u05d7\u05e5 \u05de\u05e6\u05d1\u05d9\u05e2 \u05e2\u05dc \u05e4\u05d9\u05e0\u05d4 \u05d1\u05d9\u05df \u05dc\u05d5\u05d7 \u05d0\u05d5\u05e4\u05e7\u05d9 \u05dc\u05dc\u05d5\u05d7 \u05d0\u05e0\u05db\u05d9."], [332.0, "\u05e2\u05dc \u05d4\u05e7\u05d5 \u05d4\u05de\u05dc\u05d0 \u05d9\u05e9 \u05de\u05e9\u05d5\u05dc\u05e9 \u05e2\u05dd a5 \u05de\u05e9\u05de\u05d0\u05dc: fillet \u05d1\u05e6\u05d3 \u05d4\u05d7\u05e5, \u05e2\u05dd \u05e6\u05d5\u05d5\u05d0\u05e8 \u05e9\u05dc 5 \u05de\u05f4\u05de."], [340.0, "\u05e2\u05dc \u05d4\u05e7\u05d5 \u05d4\u05de\u05e7\u05d5\u05d5\u05e7\u05d5 \u05d9\u05e9 \u05de\u05e9\u05d5\u05dc\u05e9 \u05e0\u05d5\u05e1\u05e3 \u05e2\u05dd a4, \u05d5\u05de\u05d9\u05de\u05d9\u05df 3 \u05db\u05e4\u05d5\u05dc 50, \u05d5\u05d1\u05e1\u05d5\u05d2\u05e8\u05d9\u05d9\u05dd 100: \u05d1\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9, fillet \u05dc\u05e1\u05d9\u05e8\u05d5\u05d2\u05d9\u05df, \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e7\u05d8\u05e2\u05d9\u05dd \u05e9\u05dc 50, \u05d1\u05de\u05e8\u05d5\u05d5\u05d7 100."], [353.7, "\u05d1\u05d6\u05e0\u05d1 \u05db\u05ea\u05d5\u05d1 135: \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d1-MAG."], [358.3, "\u05d5\u05d3\u05d2\u05dc \u05d1\u05e4\u05d9\u05e0\u05d4: \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05ea\u05d1\u05e6\u05e2 \u05d1\u05e9\u05d8\u05d7."], [362.0, "\u05e9\u05d9\u05de\u05d5 \u05dc\u05d1 \u05e9\u05d4\u05e7\u05d5 \u05d4\u05de\u05e7\u05d5\u05d5\u05e7\u05d5 \u05e0\u05de\u05e6\u05d0 \u05db\u05d0\u05df \u05de\u05ea\u05d7\u05ea \u05dc\u05e7\u05d5 \u05d4\u05de\u05dc\u05d0, \u05d5\u05d6\u05d4 \u05dc\u05d0 \u05de\u05e9\u05e0\u05d4 \u05d3\u05d1\u05e8: \u05de\u05d4 \u05e9\u05e7\u05d5\u05d1\u05e2 \u05d4\u05d5\u05d0 \u05e2\u05dc \u05d0\u05d9\u05d6\u05d4 \u05e7\u05d5 \u05d4\u05e1\u05de\u05dc \u05d9\u05d5\u05e9\u05d1."], [371.5, "\u05d1\u05e9\u05d5\u05e8\u05d4 \u05d0\u05d7\u05ea \u05e7\u05d9\u05d1\u05dc\u05e0\u05d5 \u05d0\u05ea \u05db\u05dc \u05d4\u05de\u05d9\u05d3\u05e2: \u05e6\u05d3, \u05e1\u05d5\u05d2, \u05d2\u05d5\u05d3\u05dc, \u05d0\u05d5\u05e8\u05da, \u05ea\u05d4\u05dc\u05d9\u05da \u05d5\u05de\u05e7\u05d5\u05dd."], [379.1, "\u05d9\u05e9 \u05db\u05de\u05d4 \u05d8\u05e2\u05d5\u05d9\u05d5\u05ea \u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05d1\u05e7\u05e8\u05d9\u05d0\u05d4."], [381.6, "\u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05d5\u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8: \u05e7\u05e8\u05d9\u05d0\u05ea \u05e9\u05e8\u05d8\u05d5\u05d8 AWS \u05db\u05d0\u05d9\u05dc\u05d5 \u05d4\u05d5\u05d0 ISO, \u05d5\u05dc\u05d4\u05e4\u05da, \u05d5\u05d0\u05d6 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd \u05de\u05ea\u05d4\u05e4\u05db\u05d9\u05dd."], [391.4, "\u05d4\u05e9\u05e0\u05d9\u05d9\u05d4: \u05d1\u05dc\u05d1\u05d5\u05dc \u05d1\u05d9\u05df a \u05dc-z, \u05e9\u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d2\u05d5\u05d3\u05dc \u05d4\u05ea\u05e4\u05e8 \u05d1\u05db\u05de\u05e2\u05d8 \u05e4\u05d9 1.4."], [398.5, "\u05d4\u05e9\u05dc\u05d9\u05e9\u05d9\u05ea: \u05dc\u05e4\u05e1\u05e4\u05e1 \u05d0\u05ea \u05d4\u05e1\u05de\u05dc \u05d1\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9, \u05d5\u05dc\u05e8\u05ea\u05da \u05e8\u05e7 \u05e6\u05d3 \u05d0\u05d7\u05d3."], [404.1, "\u05d4\u05e8\u05d1\u05d9\u05e2\u05d9\u05ea: \u05dc\u05e4\u05e8\u05e9 \u05dc\u05d0 \u05e0\u05db\u05d5\u05df \u05d0\u05ea \u05db\u05d9\u05d5\u05d5\u05df \u05d7\u05e6\u05d9 \u05d4-V, \u05d5\u05dc\u05d4\u05db\u05d9\u05df \u05d0\u05ea \u05d4\u05e9\u05d9\u05e4\u05d5\u05e2 \u05d1\u05d7\u05dc\u05e7 \u05d4\u05dc\u05d0 \u05e0\u05db\u05d5\u05df."], [410.9, "\u05d4\u05d7\u05de\u05d9\u05e9\u05d9\u05ea: \u05dc\u05d4\u05ea\u05e2\u05dc\u05dd \u05de\u05e1\u05de\u05dc \u05e6\u05d5\u05e8\u05ea \u05e4\u05e0\u05d9 \u05d4\u05ea\u05e4\u05e8, \u05d5\u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05ea\u05e4\u05e8 \u05e7\u05de\u05d5\u05e8 \u05db\u05e9\u05e0\u05d3\u05e8\u05e9 \u05ea\u05e4\u05e8 \u05e9\u05d8\u05d5\u05d7."], [418.9, "\u05d5\u05db\u05e9\u05de\u05e9\u05d4\u05d5 \u05dc\u05d0 \u05d1\u05e8\u05d5\u05e8, \u05dc\u05d0 \u05de\u05e0\u05d7\u05e9\u05d9\u05dd: \u05e9\u05d5\u05d0\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05ea\u05db\u05e0\u05df \u05dc\u05e4\u05e0\u05d9 \u05e9\u05de\u05e8\u05ea\u05db\u05d9\u05dd."], [425.1, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d7\u05e5, \u05e7\u05d5 \u05d9\u05d9\u05d7\u05d5\u05e1, \u05e1\u05de\u05dc, \u05de\u05d9\u05d3\u05d5\u05ea \u05d5\u05d6\u05e0\u05d1."], [430.7, "\u05d1-ISO \u05d4\u05e7\u05d5 \u05d4\u05de\u05dc\u05d0 \u05d4\u05d5\u05d0 \u05e6\u05d3 \u05d4\u05d7\u05e5, \u05d5\u05d1-AWS \u05d4\u05e6\u05d3 \u05e9\u05de\u05ea\u05d7\u05ea \u05dc\u05e7\u05d5. a \u05d4\u05d5\u05d0 \u05d4\u05e6\u05d5\u05d5\u05d0\u05e8, z \u05d4\u05d9\u05d0 \u05d4\u05e8\u05d2\u05dc."], [440.5, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05d0\u05d9\u05da \u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05d0\u05ea \u05d2\u05d5\u05d3\u05dc \u05d4\u05ea\u05e4\u05e8, \u05d5\u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc \u05d7\u05d9\u05d1\u05d5\u05e8 \u05de\u05e8\u05d5\u05ea\u05da."]]};
window.MH_TR["ch21"]={"t": "\u05d7\u05d9\u05e9\u05d5\u05d1 \u05ea\u05e4\u05e8\u05d9\u05dd \u05d5\u05d7\u05d5\u05d6\u05e7", "l": [[3.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd \u05dc\u05de\u05d3\u05e0\u05d5 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05d2\u05d5\u05d3\u05dc \u05d4\u05ea\u05e4\u05e8 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8. \u05e2\u05db\u05e9\u05d9\u05d5 \u05e0\u05dc\u05de\u05d3 \u05de\u05d0\u05d9\u05e4\u05d4 \u05d4\u05de\u05e1\u05e4\u05e8 \u05d4\u05d6\u05d4 \u05de\u05d2\u05d9\u05e2."], [10.5, "\u05ea\u05e4\u05e8 \u05e7\u05d8\u05df \u05de\u05d3\u05d9 \u05e0\u05e9\u05d1\u05e8 \u05d1\u05e2\u05d5\u05de\u05e1. \u05ea\u05e4\u05e8 \u05d2\u05d3\u05d5\u05dc \u05de\u05d3\u05d9 \u05e2\u05d5\u05dc\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05de\u05e2\u05d5\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8, \u05d5\u05dc\u05d0 \u05ea\u05de\u05d9\u05d3 \u05d7\u05d6\u05e7 \u05d9\u05d5\u05ea\u05e8."], [19.0, "\u05e0\u05dc\u05de\u05d3 \u05d0\u05d9\u05da \u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc fillet \u05d5\u05e9\u05dc \u05ea\u05e4\u05e8 \u05e7\u05ea, \u05dc\u05e4\u05d9 \u05d4\u05e2\u05e7\u05e8\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc Eurocode 3 \u05d5\u05e9\u05dc AWS, \u05d5\u05de\u05d4 \u05de\u05e9\u05ea\u05e0\u05d4 \u05db\u05e9\u05d4\u05e2\u05d5\u05de\u05e1 \u05de\u05d7\u05d6\u05d5\u05e8\u05d9."], [30.1, "\u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc fillet \u05e0\u05e7\u05d1\u05e2 \u05d1\u05e6\u05d5\u05d5\u05d0\u05e8: \u05d4\u05de\u05e8\u05d7\u05e7 \u05d4\u05e7\u05e6\u05e8 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05de\u05e9\u05d5\u05e8\u05e9 \u05d4\u05ea\u05e4\u05e8 \u05d0\u05dc \u05e4\u05e0\u05d9 \u05d4\u05ea\u05e4\u05e8."], [37.3, "\u05db\u05e9\u05ea\u05e4\u05e8 \u05db\u05d6\u05d4 \u05e0\u05db\u05e9\u05dc, \u05d4\u05e9\u05d1\u05e8 \u05e2\u05d5\u05d1\u05e8 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05de\u05d9\u05e9\u05d5\u05e8 \u05d4\u05e6\u05d5\u05d5\u05d0\u05e8, \u05db\u05d9 \u05e9\u05dd \u05d4\u05d7\u05ea\u05da \u05d4\u05e7\u05d8\u05df \u05d1\u05d9\u05d5\u05ea\u05e8."], [44.4, "\u05d1-fillet \u05e2\u05dd \u05e8\u05d2\u05dc\u05d9\u05d9\u05dd \u05e9\u05d5\u05d5\u05ea, \u05d4\u05e6\u05d5\u05d5\u05d0\u05e8 \u05e9\u05d5\u05d5\u05d4 \u05d1\u05e2\u05e8\u05da 0.7 \u05de\u05d0\u05d5\u05e8\u05da \u05d4\u05e8\u05d2\u05dc: \u05e8\u05d2\u05dc \u05e9\u05dc 7 \u05de\u05f4\u05de \u05e0\u05d5\u05ea\u05e0\u05ea \u05e6\u05d5\u05d5\u05d0\u05e8 \u05e9\u05dc \u05db-5 \u05de\u05f4\u05de."], [54.9, "\u05dc\u05db\u05df \u05d1-ISO \u05d5\u05d1-Eurocode \u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05dc\u05e4\u05d9 a, \u05d4\u05e6\u05d5\u05d5\u05d0\u05e8, \u05d5\u05d1-AWS \u05de\u05e6\u05d9\u05d9\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e8\u05d2\u05dc \u05d5\u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05de\u05de\u05e0\u05d4 \u05d0\u05ea \u05d4\u05e6\u05d5\u05d5\u05d0\u05e8."], [65.5, "\u05d4\u05e9\u05d8\u05d7 \u05e9\u05e0\u05d5\u05e9\u05d0 \u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e1 \u05d4\u05d5\u05d0 \u05d4\u05e6\u05d5\u05d5\u05d0\u05e8 \u05db\u05e4\u05d5\u05dc \u05d4\u05d0\u05d5\u05e8\u05da \u05d4\u05d0\u05e4\u05e7\u05d8\u05d9\u05d1\u05d9 \u05e9\u05dc \u05d4\u05ea\u05e4\u05e8."], [71.4, "\u05d1\u05e7\u05e6\u05d5\u05d5\u05ea \u05d4\u05ea\u05e4\u05e8 \u05d9\u05e9 \u05d4\u05ea\u05d7\u05dc\u05d4 \u05d5\u05e1\u05d9\u05d5\u05dd \u05e9\u05d0\u05d9\u05e0\u05dd \u05d1\u05d2\u05d5\u05d3\u05dc \u05de\u05dc\u05d0, \u05d5\u05dc\u05db\u05df \u05dc\u05e4\u05d9 Eurocode \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05de\u05d4\u05d0\u05d5\u05e8\u05da \u05e4\u05e2\u05de\u05d9\u05d9\u05dd a."], [80.3, "\u05d5\u05ea\u05e4\u05e8 \u05e7\u05e6\u05e8 \u05de\u05d3\u05d9 \u05dc\u05d0 \u05e0\u05d7\u05e9\u05d1 \u05d1\u05db\u05dc\u05dc: \u05d4\u05d0\u05d5\u05e8\u05da \u05d4\u05d0\u05e4\u05e7\u05d8\u05d9\u05d1\u05d9 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05dc\u05e4\u05d7\u05d5\u05ea 30 \u05de\u05f4\u05de, \u05d5\u05dc\u05e4\u05d7\u05d5\u05ea \u05e4\u05d9 6 \u05de\u05d4\u05e6\u05d5\u05d5\u05d0\u05e8."], [89.3, "\u05d5\u05d4\u05e6\u05d5\u05d5\u05d0\u05e8 \u05e2\u05e6\u05de\u05d5 \u05dc\u05d0 \u05e7\u05d8\u05df \u05de-3 \u05de\u05f4\u05de, \u05d2\u05dd \u05db\u05e9\u05d4\u05d7\u05d9\u05e9\u05d5\u05d1 \u05e0\u05d5\u05ea\u05df \u05e4\u05d7\u05d5\u05ea."], [95.1, "\u05db\u05d5\u05d7 \u05e9\u05e2\u05d5\u05d1\u05e8 \u05d3\u05e8\u05da fillet \u05d9\u05d5\u05e6\u05e8 \u05de\u05d0\u05de\u05e5 \u05d1\u05e6\u05d5\u05d5\u05d0\u05e8: \u05d4\u05db\u05d5\u05d7 \u05de\u05d7\u05d5\u05dc\u05e7 \u05d1\u05e9\u05d8\u05d7."], [100.9, "\u05db\u05e9\u05d4\u05db\u05d5\u05d7 \u05de\u05e7\u05d1\u05d9\u05dc \u05dc\u05ea\u05e4\u05e8, \u05d4\u05ea\u05e4\u05e8 \u05e2\u05d5\u05d1\u05d3 \u05d1\u05d2\u05d6\u05d9\u05e8\u05d4 \u05dc\u05d0\u05d5\u05e8\u05db\u05d5."], [105.6, "\u05db\u05e9\u05d4\u05db\u05d5\u05d7 \u05e0\u05d9\u05e6\u05d1 \u05dc\u05ea\u05e4\u05e8, \u05d4\u05e6\u05d5\u05d5\u05d0\u05e8 \u05de\u05e7\u05d1\u05dc \u05e9\u05d9\u05dc\u05d5\u05d1 \u05e9\u05dc \u05de\u05ea\u05d9\u05d7\u05d4 \u05d5\u05d2\u05d6\u05d9\u05e8\u05d4."], [111.0, "\u05d1\u05e4\u05d5\u05e2\u05dc, fillet \u05e8\u05d5\u05d7\u05d1\u05d9 \u05d7\u05d6\u05e7 \u05d9\u05d5\u05ea\u05e8 \u05de-fillet \u05d0\u05d5\u05e8\u05db\u05d9, \u05d5-AWS \u05de\u05ea\u05d9\u05e8 \u05dc\u05d4\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc\u05d5 \u05e2\u05d3 \u05e4\u05d9 1.5."], [120.3, "\u05d1-Eurocode \u05d9\u05e9 \u05e9\u05ea\u05d9 \u05d3\u05e8\u05db\u05d9\u05dd \u05dc\u05d7\u05e9\u05d1."], [123.2, "\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05de\u05e4\u05d5\u05e8\u05d8\u05ea \u05de\u05e4\u05e8\u05e7\u05ea \u05d0\u05ea \u05d4\u05de\u05d0\u05de\u05e5 \u05d1\u05e6\u05d5\u05d5\u05d0\u05e8 \u05dc\u05e9\u05dc\u05d5\u05e9\u05d4 \u05e8\u05db\u05d9\u05d1\u05d9\u05dd, \u05d5\u05de\u05e9\u05dc\u05d1\u05ea \u05d0\u05d5\u05ea\u05dd \u05d1\u05e0\u05d5\u05e1\u05d7\u05d4 \u05d0\u05d7\u05ea."], [130.3, "\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e4\u05e9\u05d5\u05d8\u05d4 \u05de\u05ea\u05e2\u05dc\u05de\u05ea \u05de\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05db\u05d5\u05d7, \u05d5\u05d1\u05d5\u05d3\u05e7\u05ea \u05e8\u05e7 \u05e9\u05d4\u05de\u05d0\u05de\u05e5 \u05d4\u05de\u05de\u05d5\u05e6\u05e2 \u05d1\u05e6\u05d5\u05d5\u05d0\u05e8 \u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8 \u05d0\u05ea \u05d7\u05d5\u05d6\u05e7 \u05d4\u05d2\u05d6\u05d9\u05e8\u05d4 \u05e9\u05dc \u05d4\u05ea\u05e4\u05e8."], [139.1, "\u05d4\u05d9\u05d0 \u05e9\u05de\u05e8\u05e0\u05d9\u05ea \u05d9\u05d5\u05ea\u05e8, \u05d5\u05dc\u05db\u05df \u05e0\u05d5\u05d7\u05d4 \u05dc\u05d1\u05d3\u05d9\u05e7\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4."], [143.4, "\u05d7\u05d5\u05d6\u05e7 \u05d4\u05ea\u05e4\u05e8 \u05e0\u05d2\u05d6\u05e8 \u05de\u05d7\u05d5\u05d6\u05e7 \u05d4\u05de\u05ea\u05d9\u05d7\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9 \u05d4\u05d7\u05dc\u05e9 \u05de\u05d1\u05d9\u05df \u05d4\u05e9\u05e0\u05d9\u05d9\u05dd."], [149.2, "\u05de\u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e9\u05d5\u05e8\u05e9 \u05e9\u05dc 3, \u05d5\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d7\u05d5\u05d6\u05e7 \u05d2\u05d6\u05d9\u05e8\u05d4. \u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05de\u05e7\u05d3\u05dd \u05de\u05ea\u05d0\u05dd \u05d5\u05d1\u05de\u05e7\u05d3\u05dd \u05d1\u05d8\u05d9\u05d7\u05d5\u05ea."], [157.8, "\u05de\u05e7\u05d3\u05dd \u05d4\u05de\u05ea\u05d0\u05dd \u05ea\u05dc\u05d5\u05d9 \u05d1\u05e4\u05dc\u05d3\u05d4: 0.8 \u05dc-S235, \u05d5-0.9 \u05dc-S355."], [168.7, "\u05d5\u05de\u05e7\u05d3\u05dd \u05d4\u05d1\u05d8\u05d9\u05d7\u05d5\u05ea \u05dc\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd \u05d4\u05d5\u05d0 1.25."], [173.3, "\u05dc-S235, \u05e2\u05dd \u05d7\u05d5\u05d6\u05e7 \u05de\u05ea\u05d9\u05d7\u05d4 \u05e9\u05dc 360 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc, \u05d9\u05d5\u05e6\u05d0 \u05d7\u05d5\u05d6\u05e7 \u05ea\u05db\u05df \u05e9\u05dc \u05db-208 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc \u05d1\u05e6\u05d5\u05d5\u05d0\u05e8."], [183.0, "\u05d5\u05dc-S355, \u05e2\u05dd 490 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc, \u05d9\u05d5\u05e6\u05d0 \u05db-251 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc."], [191.5, "\u05d1\u05d5\u05d0\u05d5 \u05e0\u05d7\u05e9\u05d1 \u05d3\u05d5\u05d2\u05de\u05d4."], [193.1, "\u05e4\u05e1 \u05de-S235 \u05e0\u05de\u05ea\u05d7 \u05d1\u05db\u05d5\u05d7 \u05e9\u05dc 150 \u05e7\u05d9\u05dc\u05d5\u05e0\u05d9\u05d5\u05d8\u05d5\u05df, \u05d5\u05de\u05d7\u05d5\u05d1\u05e8 \u05dc\u05e4\u05dc\u05d8\u05d4 \u05d1\u05e9\u05e0\u05d9 \u05ea\u05e4\u05e8\u05d9 fillet \u05d0\u05d5\u05e8\u05db\u05d9\u05d9\u05dd, \u05db\u05dc \u05d0\u05d7\u05d3 \u05d1\u05d0\u05d5\u05e8\u05da 100 \u05de\u05f4\u05de."], [204.8, "\u05e0\u05e0\u05e1\u05d4 \u05e6\u05d5\u05d5\u05d0\u05e8 \u05e9\u05dc 4 \u05de\u05f4\u05de."], [207.6, "\u05d4\u05d0\u05d5\u05e8\u05da \u05d4\u05d0\u05e4\u05e7\u05d8\u05d9\u05d1\u05d9 \u05e9\u05dc \u05db\u05dc \u05ea\u05e4\u05e8 \u05d4\u05d5\u05d0 100 \u05e4\u05d7\u05d5\u05ea \u05e4\u05e2\u05de\u05d9\u05d9\u05dd 4: \u05db\u05dc\u05d5\u05de\u05e8 92 \u05de\u05f4\u05de."], [214.8, "\u05d4\u05e9\u05d8\u05d7 \u05d4\u05db\u05d5\u05dc\u05dc: \u05e9\u05e0\u05d9 \u05ea\u05e4\u05e8\u05d9\u05dd, \u05db\u05e4\u05d5\u05dc 4, \u05db\u05e4\u05d5\u05dc 92, \u05d9\u05d5\u05e6\u05d0 736 \u05de\u05de\u05f4\u05e8."], [223.5, "\u05db\u05e4\u05d5\u05dc 208 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc, \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05db-153 \u05e7\u05d9\u05dc\u05d5\u05e0\u05d9\u05d5\u05d8\u05d5\u05df."], [229.2, "153 \u05d2\u05d3\u05d5\u05dc \u05de-150, \u05d5\u05dc\u05db\u05df \u05e6\u05d5\u05d5\u05d0\u05e8 \u05e9\u05dc 4 \u05de\u05f4\u05de \u05de\u05e1\u05e4\u05d9\u05e7."], [236.0, "\u05e2\u05dd \u05e6\u05d5\u05d5\u05d0\u05e8 \u05e9\u05dc 3 \u05de\u05f4\u05de \u05d4\u05d9\u05d9\u05e0\u05d5 \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e8\u05e7 \u05db-117 \u05e7\u05d9\u05dc\u05d5\u05e0\u05d9\u05d5\u05d8\u05d5\u05df, \u05d5\u05d6\u05d4 \u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7."], [242.9, "\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 ISO \u05e0\u05db\u05ea\u05d5\u05d1 a4. \u05d5\u05d1-AWS \u05e0\u05d3\u05e8\u05d5\u05e9 \u05e8\u05d2\u05dc \u05e9\u05dc 6 \u05de\u05f4\u05de, \u05db\u05d9 4 \u05db\u05e4\u05d5\u05dc 1.41 \u05d9\u05d5\u05e6\u05d0 \u05db-5.7."], [255.6, "\u05d1\u05ea\u05e4\u05e8 \u05e7\u05ea \u05e2\u05dd \u05d7\u05d3\u05d9\u05e8\u05d4 \u05de\u05dc\u05d0\u05d4, \u05d4\u05d7\u05d9\u05e9\u05d5\u05d1 \u05e4\u05e9\u05d5\u05d8 \u05d9\u05d5\u05ea\u05e8."], [259.7, "\u05d0\u05dd \u05d7\u05d5\u05de\u05e8 \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05d7\u05d6\u05e7 \u05dc\u05e4\u05d7\u05d5\u05ea \u05db\u05de\u05d5 \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9, \u05d4\u05ea\u05e4\u05e8 \u05d7\u05d6\u05e7 \u05db\u05de\u05d5 \u05d4\u05dc\u05d5\u05d7, \u05d5\u05dc\u05d0 \u05e6\u05e8\u05d9\u05da \u05dc\u05d7\u05e9\u05d1 \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e0\u05e4\u05e8\u05d3."], [267.6, "\u05de\u05e6\u05d1 \u05db\u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 matching, \u05d5-overmatching \u05db\u05e9\u05d7\u05d5\u05de\u05e8 \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05d7\u05d6\u05e7 \u05d9\u05d5\u05ea\u05e8."], [273.5, "\u05d1\u05ea\u05e4\u05e8 \u05e7\u05ea \u05e2\u05dd \u05d7\u05d3\u05d9\u05e8\u05d4 \u05d7\u05dc\u05e7\u05d9\u05ea, \u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05db\u05de\u05d5 fillet \u05e2\u05de\u05d5\u05e7: \u05d4\u05e6\u05d5\u05d5\u05d0\u05e8 \u05d4\u05d5\u05d0 \u05e2\u05d5\u05de\u05e7 \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4 \u05d4\u05de\u05d5\u05d1\u05d8\u05d7, \u05dc\u05d0 \u05e2\u05d5\u05d1\u05d9 \u05d4\u05dc\u05d5\u05d7."], [282.6, "\u05d1-AWS, \u05d1\u05d7\u05dc\u05e7 \u05de\u05d4\u05d6\u05d5\u05d5\u05d9\u05d5\u05ea \u05d5\u05de\u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd 3 \u05de\u05f4\u05de \u05de\u05e2\u05d5\u05de\u05e7 \u05d4\u05d4\u05db\u05e0\u05d4, \u05db\u05d9 \u05d4\u05e9\u05d5\u05e8\u05e9 \u05dc\u05d0 \u05ea\u05de\u05d9\u05d3 \u05e0\u05d7\u05d3\u05e8 \u05e2\u05d3 \u05d4\u05e1\u05d5\u05e3."], [291.6, "\u05dc\u05db\u05df \u05d7\u05d3\u05d9\u05e8\u05d4 \u05d7\u05dc\u05e7\u05d9\u05ea \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05dc\u05d7\u05d9\u05e6\u05d4 \u05d0\u05d5 \u05dc\u05e2\u05d5\u05de\u05e1 \u05e7\u05d8\u05df, \u05d5\u05dc\u05d0 \u05dc\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e9\u05e6\u05e8\u05d9\u05da \u05d0\u05ea \u05db\u05dc \u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc \u05d4\u05dc\u05d5\u05d7."], [299.7, "\u05dc\u05d0 \u05ea\u05de\u05d9\u05d3 \u05d4\u05db\u05d5\u05d7 \u05e2\u05d5\u05d1\u05e8 \u05d1\u05de\u05e8\u05db\u05d6 \u05d4\u05ea\u05e4\u05e8."], [302.8, "\u05db\u05e9\u05d6\u05e8\u05d5\u05e2 \u05de\u05e8\u05d5\u05ea\u05db\u05ea \u05dc\u05e2\u05de\u05d5\u05d3 \u05d5\u05d4\u05e2\u05d5\u05de\u05e1 \u05e8\u05d7\u05d5\u05e7 \u05de\u05de\u05e0\u05d5, \u05e0\u05d5\u05e6\u05e8 \u05de\u05d5\u05de\u05e0\u05d8, \u05d5\u05d4\u05ea\u05e4\u05e8 \u05de\u05e7\u05d1\u05dc \u05d2\u05dd \u05d2\u05d6\u05d9\u05e8\u05d4 \u05d5\u05d2\u05dd \u05db\u05e4\u05d9\u05e4\u05d4."], [311.2, "\u05de\u05ea\u05d9\u05d9\u05d7\u05e1\u05d9\u05dd \u05dc\u05ea\u05e4\u05e8\u05d9\u05dd \u05db\u05d0\u05dc \u05e7\u05d5\u05d5\u05d9\u05dd, \u05d5\u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05dc\u05d4\u05dd \u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d7\u05ea\u05da, \u05db\u05de\u05d5 \u05dc\u05e7\u05d5\u05e8\u05d4."], [316.9, "\u05d4\u05de\u05d0\u05de\u05e5 \u05d4\u05d2\u05d1\u05d5\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e0\u05de\u05e6\u05d0 \u05d1\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d4\u05e8\u05d7\u05d5\u05e7\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05de\u05de\u05e8\u05db\u05d6 \u05e7\u05d1\u05d5\u05e6\u05ea \u05d4\u05ea\u05e4\u05e8\u05d9\u05dd."], [322.7, "\u05d1\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d4\u05d6\u05d5 \u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05d0\u05de\u05e5 \u05de\u05d4\u05d2\u05d6\u05d9\u05e8\u05d4 \u05e2\u05dd \u05d4\u05de\u05d0\u05de\u05e5 \u05de\u05d4\u05db\u05e4\u05d9\u05e4\u05d4, \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05de\u05d5\u05dc \u05d7\u05d5\u05d6\u05e7 \u05d4\u05ea\u05e4\u05e8."], [330.1, "\u05d5\u05dc\u05db\u05df \u05d1\u05db\u05e4\u05d9\u05e4\u05d4, \u05ea\u05e4\u05e8 \u05d0\u05e8\u05d5\u05da \u05d9\u05d5\u05ea\u05e8 \u05e2\u05d5\u05d6\u05e8 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05ea\u05e4\u05e8 \u05e2\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8: \u05d4\u05d0\u05d5\u05e8\u05da \u05e4\u05d5\u05e2\u05dc \u05d1\u05e8\u05d9\u05d1\u05d5\u05e2."], [338.8, "\u05db\u05dc \u05de\u05d4 \u05e9\u05d7\u05d9\u05e9\u05d1\u05e0\u05d5 \u05e2\u05d3 \u05e2\u05db\u05e9\u05d9\u05d5 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05e2\u05d5\u05de\u05e1 \u05e1\u05d8\u05d8\u05d9."], [342.3, "\u05db\u05e9\u05d4\u05e2\u05d5\u05de\u05e1 \u05de\u05e9\u05ea\u05e0\u05d4 \u05e9\u05d5\u05d1 \u05d5\u05e9\u05d5\u05d1, \u05db\u05de\u05d5 \u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea, \u05d1\u05d2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d1\u05e2\u05d2\u05d5\u05e8\u05e0\u05d9\u05dd, \u05d4\u05db\u05e9\u05dc \u05de\u05d2\u05d9\u05e2 \u05de\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."], [350.2, "\u05e1\u05d3\u05e7 \u05d4\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05de\u05ea\u05d7\u05d9\u05dc \u05db\u05de\u05e2\u05d8 \u05ea\u05de\u05d9\u05d3 \u05d1\u05e9\u05d5\u05dc\u05d9 \u05d4\u05ea\u05e4\u05e8, \u05d1\u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05d4\u05d2\u05d9\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05de\u05e9\u05ea\u05e0\u05d4 \u05d1\u05d7\u05d3\u05d5\u05ea."], [357.2, "\u05d4\u05ea\u05e7\u05e0\u05d9\u05dd \u05de\u05e1\u05d5\u05d5\u05d2\u05d9\u05dd \u05db\u05dc \u05e4\u05e8\u05d8 \u05de\u05e8\u05d5\u05ea\u05da \u05dc\u05e4\u05d9 \u05d3\u05e8\u05d2\u05ea FAT: \u05d8\u05d5\u05d5\u05d7 \u05d4\u05de\u05d0\u05de\u05e5 \u05e9\u05d4\u05d5\u05d0 \u05e2\u05d5\u05de\u05d3 \u05d1\u05d5 \u05d1\u05de\u05e9\u05da \u05e9\u05e0\u05d9 \u05de\u05d9\u05dc\u05d9\u05d5\u05df \u05de\u05d7\u05d6\u05d5\u05e8\u05d9\u05dd."], [365.9, "\u05dc\u05d5\u05d7 \u05de\u05d2\u05d5\u05dc\u05d2\u05dc \u05d1\u05dc\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05e7\u05d1\u05dc FAT 160. \u05d0\u05d5\u05ea\u05d5 \u05dc\u05d5\u05d7 \u05e2\u05dd fillet \u05e8\u05d5\u05d7\u05d1\u05d9 \u05d9\u05d5\u05e8\u05d3 \u05dc\u05db-80, \u05db\u05dc\u05d5\u05de\u05e8 \u05dc\u05d7\u05e6\u05d9."], [375.4, "\u05d5\u05e2\u05d5\u05d3 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d7\u05e9\u05d5\u05d1\u05d4: \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea, \u05e4\u05dc\u05d3\u05d4 \u05d7\u05d6\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05e2\u05d5\u05d6\u05e8\u05ea, \u05db\u05d9 \u05d7\u05d5\u05d6\u05e7 \u05d4\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05e9\u05dc \u05e4\u05e8\u05d8 \u05de\u05e8\u05d5\u05ea\u05da \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05ea\u05dc\u05d5\u05d9 \u05d1\u05d3\u05e8\u05d2\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4."], [385.4, "\u05de\u05d4 \u05e9\u05e2\u05d5\u05d6\u05e8 \u05d4\u05d5\u05d0 \u05d2\u05d9\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4: \u05d4\u05e9\u05d7\u05d6\u05d4 \u05e9\u05dc \u05e9\u05d5\u05dc\u05d9 \u05d4\u05ea\u05e4\u05e8, peening, \u05d0\u05d5 \u05d4\u05d6\u05d6\u05ea \u05d4\u05ea\u05e4\u05e8 \u05dc\u05d0\u05d6\u05d5\u05e8 \u05e2\u05dd \u05de\u05d0\u05de\u05e5 \u05e0\u05de\u05d5\u05da."], [394.8, "\u05d9\u05e9 \u05d2\u05dd \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05e9\u05dc\u05d0 \u05ea\u05dc\u05d5\u05d9\u05d9\u05dd \u05d1\u05e2\u05d5\u05de\u05e1."], [397.5, "\u05e2\u05dc \u05dc\u05d5\u05d7 \u05e2\u05d1\u05d4, \u05ea\u05e4\u05e8 \u05e7\u05d8\u05df \u05de\u05ea\u05e7\u05e8\u05e8 \u05de\u05d4\u05e8 \u05de\u05d3\u05d9 \u05d5\u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7, \u05d5\u05dc\u05db\u05df \u05d9\u05e9 \u05d2\u05d5\u05d3\u05dc \u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9 \u05dc\u05e4\u05d9 \u05e2\u05d5\u05d1\u05d9 \u05d4\u05dc\u05d5\u05d7."], [406.0, "\u05dc\u05e4\u05d9 AWS: \u05e8\u05d2\u05dc \u05e9\u05dc 3 \u05de\u05f4\u05de \u05dc\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d3 6 \u05de\u05f4\u05de, 5 \u05de\u05f4\u05de \u05e2\u05d3 12, 6 \u05de\u05f4\u05de \u05e2\u05d3 20, \u05d5-8 \u05de\u05f4\u05de \u05de\u05e2\u05dc 20."], [418.8, "\u05d5\u05d1\u05e9\u05e4\u05ea \u05dc\u05d5\u05d7 \u05d1\u05e2\u05d5\u05d1\u05d9 6 \u05de\u05f4\u05de \u05d5\u05de\u05e2\u05dc\u05d4, \u05d4\u05e8\u05d2\u05dc \u05e7\u05d8\u05e0\u05d4 \u05d1-2 \u05de\u05f4\u05de \u05de\u05e2\u05d5\u05d1\u05d9 \u05d4\u05dc\u05d5\u05d7, \u05db\u05d3\u05d9 \u05e9\u05d4\u05e4\u05d9\u05e0\u05d4 \u05dc\u05d0 \u05ea\u05d9\u05de\u05e1 \u05d5\u05d0\u05e4\u05e9\u05e8 \u05d9\u05d4\u05d9\u05d4 \u05dc\u05de\u05d3\u05d5\u05d3 \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8."], [429.6, "\u05d5\u05e2\u05db\u05e9\u05d9\u05d5, \u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8."], [432.0, "\u05e9\u05d8\u05d7 \u05d4\u05d7\u05ea\u05da \u05e9\u05dc fillet \u05d2\u05d3\u05dc \u05d1\u05e8\u05d9\u05d1\u05d5\u05e2 \u05e9\u05dc \u05d4\u05e6\u05d5\u05d5\u05d0\u05e8: \u05e6\u05d5\u05d5\u05d0\u05e8 6 \u05d1\u05de\u05e7\u05d5\u05dd 4 \u05d3\u05d5\u05e8\u05e9 \u05e4\u05d9 2.25 \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9, \u05d5\u05e0\u05d5\u05ea\u05df \u05e8\u05e7 \u05e4\u05d9 1.5 \u05d7\u05d5\u05d6\u05e7."], [443.0, "\u05ea\u05e4\u05e8 \u05d2\u05d3\u05d5\u05dc \u05d3\u05d5\u05e8\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e2\u05d1\u05e8\u05d9\u05dd, \u05d9\u05d5\u05ea\u05e8 \u05d6\u05de\u05df, \u05d9\u05d5\u05ea\u05e8 \u05d7\u05d5\u05dd, \u05d5\u05d9\u05d5\u05ea\u05e8 \u05e2\u05d9\u05d5\u05d5\u05ea \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05ea\u05e7\u05df \u05d0\u05d7\u05e8 \u05db\u05da."], [450.4, "\u05d2\u05dd \u05d4\u05d2\u05d3\u05dc\u05d4 \u05dc\u05d9\u05ea\u05e8 \u05d1\u05d9\u05d8\u05d7\u05d5\u05df \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d0\u05d5 \u05de\u05e2\u05d1\u05e8 \u05e0\u05d5\u05e1\u05e3 \u05e9\u05d4\u05e8\u05ea\u05da \u05de\u05d5\u05e1\u05d9\u05e3 \u05e2\u05dc \u05d3\u05e2\u05ea \u05e2\u05e6\u05de\u05d5, \u05de\u05d9\u05d9\u05e7\u05e8\u05d9\u05dd \u05d1\u05dc\u05d9 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05d1\u05d8\u05d9\u05d7\u05d5\u05ea."], [459.9, "\u05d5\u05ea\u05e4\u05e8 \u05de\u05d7\u05d5\u05e9\u05d1 \u05e0\u05db\u05d5\u05df, \u05e2\u05dd \u05d0\u05d5\u05e8\u05da \u05de\u05e1\u05e4\u05d9\u05e7 \u05d1\u05de\u05e7\u05d5\u05dd \u05e6\u05d5\u05d5\u05d0\u05e8 \u05e2\u05d1\u05d4, \u05d7\u05d5\u05e1\u05da \u05d7\u05d5\u05de\u05e8 \u05d5\u05d6\u05de\u05df \u05d5\u05de\u05e7\u05d8\u05d9\u05df \u05e2\u05d9\u05d5\u05d5\u05ea."], [467.9, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc fillet \u05e0\u05e7\u05d1\u05e2 \u05d1\u05e6\u05d5\u05d5\u05d0\u05e8, \u05db\u05e4\u05d5\u05dc \u05d4\u05d0\u05d5\u05e8\u05da \u05d4\u05d0\u05e4\u05e7\u05d8\u05d9\u05d1\u05d9."], [473.5, "\u05d7\u05d5\u05d6\u05e7 \u05d4\u05ea\u05e4\u05e8 \u05e0\u05d2\u05d6\u05e8 \u05de\u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9, \u05e2\u05dd \u05de\u05e7\u05d3\u05dd \u05de\u05ea\u05d0\u05dd \u05d5\u05de\u05e7\u05d3\u05dd \u05d1\u05d8\u05d9\u05d7\u05d5\u05ea."], [479.5, "\u05ea\u05e4\u05e8 \u05e7\u05ea \u05e2\u05dd \u05d7\u05d3\u05d9\u05e8\u05d4 \u05de\u05dc\u05d0\u05d4 \u05d5\u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9 \u05ea\u05d5\u05d0\u05dd \u05d7\u05d6\u05e7 \u05db\u05de\u05d5 \u05d4\u05dc\u05d5\u05d7. \u05d5\u05d1\u05e2\u05d5\u05de\u05e1 \u05de\u05d7\u05d6\u05d5\u05e8\u05d9 \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea, \u05d5\u05e9\u05dd \u05d4\u05d2\u05d9\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05e7\u05d5\u05d1\u05e2\u05ea."], [490.2, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e4\u05d2\u05de\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da, \u05d0\u05d9\u05da \u05d4\u05dd \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd, \u05d5\u05d0\u05d9\u05da \u05de\u05d6\u05d4\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd."]]};
window.MH_TR["ch22"]={"t": "\u05e4\u05d2\u05de\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da", "l": [[3.0, "\u05d0\u05d9\u05df \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05d5\u05e9\u05dc\u05dd. \u05d1\u05db\u05dc \u05ea\u05e4\u05e8 \u05d9\u05e9 \u05e1\u05d8\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea \u05de\u05d4\u05e6\u05d5\u05e8\u05d4 \u05d5\u05de\u05d4\u05de\u05d1\u05e0\u05d4 \u05d4\u05d0\u05d9\u05d3\u05d9\u05d0\u05dc\u05d9\u05d9\u05dd."], [9.3, "\u05d4\u05e9\u05d0\u05dc\u05d4 \u05d4\u05d9\u05d0 \u05dc\u05d0 \u05d0\u05dd \u05d9\u05e9 \u05e4\u05d2\u05de\u05d9\u05dd, \u05d0\u05dc\u05d0 \u05d0\u05d9\u05d6\u05d4, \u05db\u05de\u05d4 \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd, \u05d5\u05d0\u05dd \u05d4\u05dd \u05de\u05e1\u05d5\u05db\u05e0\u05d9\u05dd."], [15.8, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05dc\u05de\u05d3 \u05d0\u05ea \u05e1\u05d5\u05d2\u05d9 \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd, \u05d0\u05d9\u05da \u05db\u05dc \u05d0\u05d7\u05d3 \u05e0\u05d5\u05e6\u05e8, \u05d5\u05d0\u05d9\u05da \u05de\u05d6\u05d4\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5."], [22.4, "\u05d4\u05ea\u05e7\u05e0\u05d9\u05dd \u05de\u05d1\u05d3\u05d9\u05dc\u05d9\u05dd \u05d1\u05d9\u05df \u05d0\u05d9 \u05e8\u05e6\u05d9\u05e4\u05d5\u05ea \u05dc\u05d1\u05d9\u05df \u05e4\u05d2\u05dd."], [26.0, "\u05d0\u05d9 \u05e8\u05e6\u05d9\u05e4\u05d5\u05ea \u05d4\u05d9\u05d0 \u05db\u05dc \u05e1\u05d8\u05d9\u05d9\u05d4 \u05d1\u05ea\u05e4\u05e8. \u05d4\u05d9\u05d0 \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05e4\u05d2\u05dd \u05e8\u05e7 \u05db\u05e9\u05d4\u05d9\u05d0 \u05e2\u05d5\u05d1\u05e8\u05ea \u05d0\u05ea \u05d2\u05d1\u05d5\u05dc \u05d4\u05e7\u05d1\u05dc\u05d4."], [32.7, "\u05d4\u05ea\u05e7\u05df ISO 6520 \u05de\u05d7\u05dc\u05e7 \u05d0\u05ea \u05d0\u05d9 \u05d4\u05e8\u05e6\u05d9\u05e4\u05d5\u05d9\u05d5\u05ea \u05dc\u05e9\u05e9 \u05e7\u05d1\u05d5\u05e6\u05d5\u05ea: \u05e1\u05d3\u05e7\u05d9\u05dd, \u05d7\u05dc\u05dc\u05d9\u05dd, \u05d7\u05d5\u05de\u05e8 \u05d6\u05e8 \u05db\u05dc\u05d5\u05d0, \u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da \u05d5\u05d7\u05d3\u05d9\u05e8\u05d4, \u05e6\u05d5\u05e8\u05d4 \u05dc\u05d0 \u05ea\u05e7\u05d9\u05e0\u05d4, \u05d5\u05e9\u05d5\u05e0\u05d5\u05ea."], [45.4, "\u05d4\u05ea\u05e7\u05df ISO 5817 \u05e7\u05d5\u05d1\u05e2 \u05dc\u05db\u05dc \u05e1\u05d5\u05d2 \u05d2\u05d1\u05d5\u05dc \u05e7\u05d1\u05dc\u05d4, \u05d1\u05e9\u05dc\u05d5\u05e9 \u05e8\u05de\u05d5\u05ea \u05d0\u05d9\u05db\u05d5\u05ea: B, C \u05d5-D."], [54.3, "\u05e8\u05de\u05d4 B \u05d4\u05d9\u05d0 \u05d4\u05de\u05d7\u05de\u05d9\u05e8\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d5\u05e8\u05de\u05d4 D \u05d4\u05d9\u05d0 \u05d4\u05de\u05e7\u05dc\u05d4."], [59.1, "\u05d4\u05de\u05ea\u05db\u05e0\u05df \u05d1\u05d5\u05d7\u05e8 \u05d0\u05ea \u05d4\u05e8\u05de\u05d4 \u05dc\u05e4\u05d9 \u05d4\u05e2\u05d5\u05de\u05e1 \u05d5\u05d4\u05e1\u05d9\u05db\u05d5\u05df, \u05d5\u05dc\u05d0 \u05ea\u05de\u05d9\u05d3 \u05e6\u05e8\u05d9\u05da \u05d0\u05ea \u05d4\u05e8\u05de\u05d4 \u05d4\u05d2\u05d1\u05d5\u05d4\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8."], [66.0, "\u05d4\u05e1\u05d3\u05e7\u05d9\u05dd \u05d4\u05dd \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d4\u05de\u05e1\u05d5\u05db\u05e0\u05d9\u05dd \u05d1\u05d9\u05d5\u05ea\u05e8."], [69.3, "\u05e1\u05d3\u05e7 \u05d4\u05d5\u05d0 \u05d7\u05d3, \u05d5\u05d1\u05e7\u05e6\u05d4 \u05e9\u05dc\u05d5 \u05d4\u05de\u05d0\u05de\u05e5 \u05d2\u05d1\u05d5\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05d9\u05db\u05d5\u05dc \u05dc\u05d2\u05d3\u05d5\u05dc \u05ea\u05d7\u05ea \u05e2\u05d5\u05de\u05e1 \u05e2\u05d3 \u05e9\u05d1\u05e8."], [77.0, "\u05e1\u05d3\u05e7\u05d9 \u05de\u05d9\u05de\u05df \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d4\u05ea\u05e4\u05e8 \u05db\u05d1\u05e8 \u05d4\u05ea\u05e7\u05e8\u05e8, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1-HAZ, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05ea\u05d7\u05ea \u05dc\u05ea\u05e4\u05e8, \u05d5\u05dc\u05d0 \u05e8\u05d5\u05d0\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05de\u05d1\u05d7\u05d5\u05e5."], [86.8, "\u05d4\u05dd \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d5\u05e4\u05d9\u05e2 \u05d2\u05dd \u05e9\u05e2\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05dc\u05db\u05df \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e8\u05d2\u05d9\u05e9\u05d5\u05ea \u05de\u05d7\u05db\u05d9\u05dd \u05e2\u05d3 \u05d9\u05d5\u05de\u05d9\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea."], [94.6, "\u05e1\u05d3\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05d1\u05d6\u05de\u05df \u05d4\u05d4\u05ea\u05de\u05e6\u05e7\u05d5\u05ea, \u05dc\u05d0\u05d5\u05e8\u05da \u05de\u05e8\u05db\u05d6 \u05d4\u05ea\u05e4\u05e8, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05db\u05e9\u05d4\u05ea\u05e4\u05e8 \u05e6\u05e8 \u05d5\u05e2\u05de\u05d5\u05e7 \u05de\u05d3\u05d9."], [102.3, "\u05e1\u05d3\u05e7\u05d9 \u05de\u05db\u05ea\u05e9 \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05e1\u05d5\u05e3 \u05d4\u05ea\u05e4\u05e8, \u05db\u05e9\u05de\u05e4\u05e1\u05d9\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e9\u05ea \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea \u05d5\u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05e9\u05e7\u05e2."], [108.9, "\u05de\u05d5\u05e0\u05e2\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d1\u05de\u05d9\u05dc\u05d5\u05d9 \u05d4\u05de\u05db\u05ea\u05e9 \u05dc\u05e4\u05e0\u05d9 \u05e1\u05d9\u05d5\u05dd, \u05d0\u05d5 \u05d1\u05d4\u05d5\u05e8\u05d3\u05d4 \u05d4\u05d3\u05e8\u05d2\u05ea\u05d9\u05ea \u05e9\u05dc \u05d4\u05d6\u05e8\u05dd."], [114.3, "\u05d5\u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd \u05de\u05d5\u05e4\u05d9\u05e2 lamellar tearing: \u05e1\u05d3\u05e7 \u05de\u05d3\u05d5\u05e8\u05d2 \u05d1\u05ea\u05d5\u05da \u05d4\u05dc\u05d5\u05d7, \u05de\u05ea\u05d7\u05ea \u05dc\u05ea\u05e4\u05e8, \u05db\u05e9\u05d4\u05dc\u05d5\u05d7 \u05e0\u05de\u05e9\u05da \u05d1\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05e2\u05d5\u05d1\u05d9 \u05e9\u05dc\u05d5."], [124.6, "\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05d4\u05df \u05d7\u05dc\u05dc\u05d9\u05dd \u05e9\u05dc \u05d2\u05d6 \u05e9\u05e0\u05dc\u05db\u05d3 \u05d1\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d5\u05ea\u05db\u05ea \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05e1\u05e4\u05d9\u05e7 \u05dc\u05e6\u05d0\u05ea."], [130.7, "\u05d4\u05e1\u05d9\u05d1\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05d2\u05e0\u05ea \u05d2\u05d6 \u05dc\u05e7\u05d5\u05d9\u05d4: \u05e8\u05d5\u05d7, \u05e1\u05e4\u05d9\u05e7\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05de\u05d3\u05d9, \u05d0\u05d5 \u05e1\u05e4\u05d9\u05e7\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d3\u05d9 \u05e9\u05d9\u05d5\u05e6\u05e8\u05ea \u05de\u05e2\u05e8\u05d1\u05d5\u05dc\u05ea \u05d5\u05e9\u05d5\u05d0\u05d1\u05ea \u05d0\u05d5\u05d5\u05d9\u05e8."], [140.5, "\u05d2\u05dd \u05e4\u05d9\u05d9\u05d4 \u05e1\u05ea\u05d5\u05de\u05d4 \u05d1-spatter, \u05d0\u05d5 \u05e6\u05d9\u05e0\u05d5\u05e8 \u05d2\u05d6 \u05d3\u05d5\u05dc\u05e3, \u05e4\u05d5\u05d2\u05e2\u05d9\u05dd \u05d1\u05d4\u05d2\u05e0\u05d4."], [145.9, "\u05e1\u05d9\u05d1\u05d4 \u05e9\u05e0\u05d9\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05dc\u05db\u05dc\u05d5\u05da: \u05dc\u05d7\u05d5\u05ea, \u05e9\u05de\u05df, \u05e6\u05d1\u05e2, \u05d7\u05dc\u05d5\u05d3\u05d4 \u05d0\u05d5 \u05e6\u05d9\u05e4\u05d5\u05d9 \u05d0\u05d1\u05e5 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05d7\u05dc\u05e7."], [154.0, "\u05d5\u05e1\u05d9\u05d1\u05d4 \u05e9\u05dc\u05d9\u05e9\u05d9\u05ea \u05d4\u05d9\u05d0 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05d0\u05d5 \u05d0\u05d1\u05e7\u05d4 \u05e9\u05e1\u05e4\u05d2\u05d5 \u05dc\u05d7\u05d5\u05ea."], [158.8, "\u05d4\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05d9\u05db\u05d5\u05dc\u05d5\u05ea \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05d5\u05d3\u05d3\u05d5\u05ea, \u05de\u05e4\u05d5\u05d6\u05e8\u05d5\u05ea, \u05d1\u05e7\u05d1\u05d5\u05e6\u05d5\u05ea, \u05d0\u05d5 \u05de\u05d5\u05d0\u05e8\u05db\u05d5\u05ea \u05db\u05de\u05d5 \u05e6\u05d9\u05e0\u05d5\u05e8\u05d5\u05ea."], [165.6, "\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05ea\u05e4\u05e8 \u05e8\u05d5\u05d0\u05d9\u05dd \u05d1\u05e2\u05d9\u05df. \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05e4\u05e0\u05d9\u05de\u05d9\u05d5\u05ea \u05de\u05d2\u05dc\u05d9\u05dd \u05e8\u05e7 \u05d1\u05d1\u05d3\u05d9\u05e7\u05d4, \u05dc\u05de\u05e9\u05dc \u05d1\u05e6\u05d9\u05dc\u05d5\u05dd \u05e8\u05e0\u05d8\u05d2\u05df."], [174.4, "\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e0\u05dc\u05db\u05d3 \u05d1\u05ea\u05d5\u05da \u05d4\u05ea\u05e4\u05e8 \u05d7\u05d5\u05de\u05e8 \u05d6\u05e8."], [178.0, "\u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d5\u05d0 \u05e9\u05d0\u05e8\u05d9\u05d5\u05ea slag \u05e9\u05dc\u05d0 \u05e0\u05d5\u05e7\u05d5 \u05d1\u05d9\u05df \u05d4\u05de\u05e2\u05d1\u05e8\u05d9\u05dd, \u05d5\u05e0\u05dc\u05db\u05d3\u05d5 \u05de\u05ea\u05d7\u05ea \u05dc\u05de\u05e2\u05d1\u05e8 \u05d4\u05d1\u05d0."], [185.8, "\u05d4\u05df \u05de\u05d5\u05e4\u05d9\u05e2\u05d5\u05ea \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1-SMAW, FCAW \u05d5-SAW, \u05d5\u05dc\u05d9\u05d3 \u05d3\u05e4\u05e0\u05d5\u05ea \u05d4\u05d7\u05e8\u05d9\u05e5, \u05e9\u05dd \u05e7\u05e9\u05d4 \u05dc\u05e0\u05e7\u05d5\u05ea."], [195.2, "\u05d1-TIG \u05e0\u05dc\u05db\u05d3\u05d5\u05ea \u05e9\u05d0\u05e8\u05d9\u05d5\u05ea \u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df, \u05db\u05e9\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05e0\u05d5\u05d2\u05e2\u05ea \u05d1\u05d0\u05de\u05d1\u05d8 \u05d0\u05d5 \u05db\u05e9\u05d4\u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05d1\u05e9\u05d1\u05d9\u05dc\u05d4."], [202.6, "\u05d1\u05e6\u05d9\u05dc\u05d5\u05dd \u05e8\u05e0\u05d8\u05d2\u05df, slag \u05e0\u05e8\u05d0\u05d4 \u05db\u05d4\u05d4, \u05d5\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df, \u05e9\u05d4\u05d5\u05d0 \u05e6\u05e4\u05d5\u05e3 \u05de\u05d0\u05d5\u05d3, \u05e0\u05e8\u05d0\u05d4 \u05d1\u05d4\u05d9\u05e8."], [209.8, "\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da \u05d4\u05d5\u05d0 \u05de\u05e6\u05d1 \u05e9\u05d1\u05d5 \u05de\u05ea\u05db\u05ea \u05d4\u05ea\u05e4\u05e8 \u05dc\u05d0 \u05d4\u05ea\u05de\u05d6\u05d2\u05d4 \u05e2\u05dd \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9, \u05d0\u05d5 \u05e2\u05dd \u05d4\u05de\u05e2\u05d1\u05e8 \u05d4\u05e7\u05d5\u05d3\u05dd."], [217.6, "\u05d4\u05d5\u05d0 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05d3\u05d5\u05e4\u05df \u05d4\u05d7\u05e8\u05d9\u05e5, \u05d1\u05d9\u05df \u05de\u05e2\u05d1\u05e8\u05d9\u05dd, \u05d0\u05d5 \u05d1\u05e9\u05d5\u05e8\u05e9."], [222.4, "\u05d7\u05d5\u05e1\u05e8 \u05d7\u05d3\u05d9\u05e8\u05d4 \u05d4\u05d5\u05d0 \u05de\u05e6\u05d1 \u05e9\u05d1\u05d5 \u05d4\u05ea\u05e4\u05e8 \u05dc\u05d0 \u05d4\u05d2\u05d9\u05e2 \u05e2\u05d3 \u05d4\u05e9\u05d5\u05e8\u05e9, \u05d5\u05d4\u05d7\u05e8\u05d9\u05e5 \u05e0\u05e9\u05d0\u05e8 \u05e4\u05ea\u05d5\u05d7 \u05de\u05dc\u05de\u05d8\u05d4."], [229.4, "\u05d4\u05e1\u05d9\u05d1\u05d5\u05ea: \u05d6\u05e8\u05dd \u05e0\u05de\u05d5\u05da \u05de\u05d3\u05d9, \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d3\u05d9, \u05d6\u05d5\u05d5\u05d9\u05ea \u05dc\u05d0 \u05e0\u05db\u05d5\u05e0\u05d4, \u05d7\u05e8\u05d9\u05e5 \u05e6\u05e8 \u05de\u05d3\u05d9, \u05d0\u05d5 \u05e4\u05e2\u05e8 \u05e9\u05d5\u05e8\u05e9 \u05e7\u05d8\u05df \u05de\u05d3\u05d9."], [239.4, "\u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05de\u05e1\u05d5\u05db\u05e0\u05d9\u05dd \u05db\u05de\u05e2\u05d8 \u05db\u05de\u05d5 \u05e1\u05d3\u05e7\u05d9\u05dd, \u05db\u05d9 \u05d4\u05dd \u05e9\u05d8\u05d5\u05d7\u05d9\u05dd \u05d5\u05d7\u05d3\u05d9\u05dd."], [244.2, "\u05d5\u05dc\u05e8\u05d5\u05d1 \u05dc\u05d0 \u05e8\u05d5\u05d0\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05de\u05d1\u05d7\u05d5\u05e5: \u05d4\u05ea\u05e4\u05e8 \u05e0\u05e8\u05d0\u05d4 \u05d9\u05e4\u05d4, \u05d0\u05d1\u05dc \u05d1\u05e4\u05e0\u05d9\u05dd \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05de\u05d7\u05d5\u05d1\u05e8."], [251.3, "\u05d4\u05e7\u05d1\u05d5\u05e6\u05d4 \u05d4\u05d1\u05d0\u05d4 \u05d4\u05d9\u05d0 \u05e4\u05d2\u05de\u05d9 \u05e6\u05d5\u05e8\u05d4, \u05e9\u05e8\u05d5\u05d1\u05dd \u05e0\u05e8\u05d0\u05d9\u05dd \u05d1\u05e2\u05d9\u05df."], [256.0, "undercut \u05d4\u05d5\u05d0 \u05d7\u05e8\u05d9\u05e5 \u05dc\u05d0\u05d5\u05e8\u05da \u05e9\u05d5\u05dc\u05d9 \u05d4\u05ea\u05e4\u05e8, \u05d1\u05d7\u05d5\u05de\u05e8 \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9, \u05e9\u05e0\u05d5\u05e6\u05e8 \u05de\u05d6\u05e8\u05dd \u05d2\u05d1\u05d5\u05d4, \u05e7\u05e9\u05ea \u05d0\u05e8\u05d5\u05db\u05d4 \u05d0\u05d5 \u05d6\u05d5\u05d5\u05d9\u05ea \u05dc\u05d0 \u05e0\u05db\u05d5\u05e0\u05d4."], [265.2, "overlap \u05d4\u05d5\u05d0 \u05de\u05ea\u05db\u05ea \u05e9\u05d2\u05dc\u05e9\u05d4 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9 \u05d1\u05e9\u05d5\u05dc\u05d9 \u05d4\u05ea\u05e4\u05e8 \u05d1\u05dc\u05d9 \u05dc\u05d4\u05ea\u05de\u05d6\u05d2 \u05d0\u05d9\u05ea\u05d5."], [271.5, "\u05ea\u05e4\u05e8 \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05d0\u05d5 \u05e7\u05de\u05d5\u05e8 \u05de\u05d3\u05d9 \u05de\u05d1\u05d6\u05d1\u05d6 \u05d7\u05d5\u05de\u05e8, \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e9\u05d9\u05e0\u05d5\u05d9 \u05d7\u05d3 \u05d1\u05e9\u05d5\u05dc\u05d9 \u05d4\u05ea\u05e4\u05e8, \u05e9\u05de\u05e7\u05d8\u05d9\u05df \u05d0\u05ea \u05d7\u05d5\u05d6\u05e7 \u05d4\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."], [280.3, "\u05ea\u05e4\u05e8 \u05e9\u05dc\u05d0 \u05de\u05d5\u05dc\u05d0 \u05e2\u05d3 \u05d4\u05e1\u05d5\u05e3 \u05de\u05e9\u05d0\u05d9\u05e8 \u05d7\u05ea\u05da \u05e7\u05d8\u05df \u05de\u05d4\u05e0\u05d3\u05e8\u05e9."], [285.2, "\u05d1\u05e6\u05d3 \u05d4\u05e9\u05d5\u05e8\u05e9 \u05d9\u05e9 \u05d7\u05d3\u05d9\u05e8\u05ea \u05d9\u05ea\u05e8, \u05e9\u05d1\u05d5\u05dc\u05d8\u05ea \u05de\u05ea\u05d7\u05ea, \u05d0\u05d5 \u05e9\u05d5\u05e8\u05e9 \u05e9\u05e7\u05d5\u05e2. \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05e7\u05e9\u05ea \u05e9\u05d5\u05e8\u05e4\u05ea \u05d7\u05d5\u05e8 \u05d1\u05dc\u05d5\u05d7."], [294.2, "\u05d0\u05d9 \u05d9\u05d9\u05e9\u05d5\u05e8 \u05d1\u05d9\u05df \u05d4\u05dc\u05d5\u05d7\u05d5\u05ea \u05d1\u05ea\u05e4\u05e8 \u05e7\u05ea \u05d9\u05d5\u05e6\u05e8 \u05de\u05d0\u05de\u05e6\u05d9 \u05db\u05e4\u05d9\u05e4\u05d4 \u05e0\u05d5\u05e1\u05e4\u05d9\u05dd \u05d1\u05d7\u05d9\u05d1\u05d5\u05e8."], [300.1, "\u05d5\u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05d1\u05d4 \u05d4\u05e7\u05e9\u05ea \u05e0\u05d2\u05e2\u05d4 \u05d1\u05d7\u05dc\u05e7 \u05de\u05d7\u05d5\u05e5 \u05dc\u05ea\u05e4\u05e8, arc strike, \u05d9\u05d5\u05e6\u05e8\u05ea \u05d0\u05d6\u05d5\u05e8 \u05e7\u05e9\u05d4 \u05e7\u05d8\u05df \u05e9\u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7."], [309.2, "\u05d0\u05d9\u05da \u05de\u05d6\u05d4\u05d9\u05dd? \u05e7\u05d5\u05d3\u05dd \u05db\u05dc, \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05d9\u05e4\u05d4 \u05d4\u05e4\u05d2\u05dd \u05e0\u05de\u05e6\u05d0."], [313.6, "\u05e4\u05d2\u05de\u05d9 \u05e6\u05d5\u05e8\u05d4, \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05e2\u05dc \u05d4\u05e4\u05e0\u05d9\u05dd, \u05e1\u05d3\u05e7\u05d9 \u05de\u05db\u05ea\u05e9 \u05d5-spatter \u05e8\u05d5\u05d0\u05d9\u05dd \u05d1\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d7\u05d6\u05d5\u05ea\u05d9\u05ea."], [320.8, "\u05e1\u05d3\u05e7\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd, \u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da, \u05e9\u05d0\u05e8\u05d9\u05d5\u05ea slag \u05d5\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05e4\u05e0\u05d9\u05de\u05d9\u05d5\u05ea \u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05dc\u05d0 \u05d4\u05d5\u05e8\u05e1\u05d5\u05ea."], [329.0, "\u05d5\u05d1\u05e7\u05d1\u05d9\u05e2\u05ea \u05d4\u05d7\u05d5\u05de\u05e8\u05d4 \u05de\u05d1\u05d3\u05d9\u05dc\u05d9\u05dd \u05d1\u05d9\u05df \u05e4\u05d2\u05de\u05d9\u05dd \u05de\u05d9\u05e9\u05d5\u05e8\u05d9\u05d9\u05dd \u05dc\u05e4\u05d2\u05de\u05d9\u05dd \u05e0\u05e4\u05d7\u05d9\u05d9\u05dd."], [334.1, "\u05e1\u05d3\u05e7\u05d9\u05dd \u05d5\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da \u05d4\u05dd \u05de\u05d9\u05e9\u05d5\u05e8\u05d9\u05d9\u05dd \u05d5\u05d7\u05d3\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05de\u05e1\u05d5\u05db\u05e0\u05d9\u05dd. \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05d5\u05e9\u05d0\u05e8\u05d9\u05d5\u05ea slag \u05d4\u05df \u05e0\u05e4\u05d7\u05d9\u05d5\u05ea \u05d5\u05de\u05e2\u05d5\u05d2\u05dc\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05e4\u05d7\u05d5\u05ea \u05de\u05e1\u05d5\u05db\u05e0\u05d5\u05ea."], [346.2, "\u05dc\u05db\u05df \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05e7\u05d1\u05dc\u05d4 \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd \u05d4\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d0\u05e4\u05e1, \u05d5\u05dc\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05de\u05d5\u05ea\u05e8\u05ea \u05db\u05de\u05d5\u05ea \u05de\u05e1\u05d5\u05d9\u05de\u05ea."], [353.8, "\u05d5\u05e2\u05db\u05e9\u05d9\u05d5, \u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8."], [356.2, "\u05ea\u05d9\u05e7\u05d5\u05df \u05e9\u05dc \u05e4\u05d2\u05dd \u05e2\u05d5\u05dc\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05de\u05e7\u05d5\u05e8\u05d9."], [360.2, "\u05e6\u05e8\u05d9\u05da \u05dc\u05de\u05e6\u05d5\u05d0 \u05d0\u05ea \u05d4\u05e4\u05d2\u05dd, \u05dc\u05d7\u05e6\u05d5\u05d1 \u05d0\u05d5 \u05dc\u05d4\u05e9\u05d7\u05d9\u05d6 \u05e2\u05d3 \u05e9\u05d4\u05d5\u05d0 \u05e0\u05e2\u05dc\u05dd, \u05dc\u05e8\u05ea\u05da \u05de\u05d7\u05d3\u05e9, \u05d5\u05dc\u05d1\u05d3\u05d5\u05e7 \u05e9\u05d5\u05d1."], [367.9, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e8\u05d2\u05d9\u05e9\u05d5\u05ea \u05e6\u05e8\u05d9\u05da \u05dc\u05d7\u05de\u05dd \u05de\u05e8\u05d0\u05e9 \u05e9\u05d5\u05d1, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05dc\u05d1\u05e6\u05e2 \u05e9\u05d5\u05d1 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [374.6, "\u05db\u05dc \u05ea\u05d9\u05e7\u05d5\u05df \u05de\u05d7\u05de\u05dd \u05e9\u05d5\u05d1 \u05d0\u05ea \u05d4-HAZ, \u05d5\u05d1\u05d4\u05e8\u05d1\u05d4 \u05e0\u05d4\u05dc\u05d9\u05dd \u05de\u05d5\u05d2\u05d1\u05dc \u05de\u05e1\u05e4\u05e8 \u05d4\u05ea\u05d9\u05e7\u05d5\u05e0\u05d9\u05dd \u05d1\u05d0\u05d5\u05ea\u05d5 \u05de\u05e7\u05d5\u05dd."], [381.2, "\u05d2\u05dd \u05d3\u05e8\u05d9\u05e9\u05ea \u05d0\u05d9\u05db\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d4\u05e0\u05d3\u05e8\u05e9 \u05de\u05d9\u05d9\u05e7\u05e8\u05ea: \u05e8\u05de\u05d4 B \u05d1\u05de\u05e7\u05d5\u05dd C \u05e4\u05d9\u05e8\u05d5\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea, \u05d9\u05d5\u05ea\u05e8 \u05ea\u05d9\u05e7\u05d5\u05e0\u05d9\u05dd \u05d5\u05e8\u05ea\u05db\u05d9\u05dd \u05de\u05d5\u05e1\u05de\u05db\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."], [391.1, "\u05d5\u05d4\u05d3\u05e8\u05da \u05d4\u05d6\u05d5\u05dc\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d9\u05d0 \u05de\u05e0\u05d9\u05e2\u05d4: \u05e0\u05d9\u05e7\u05d9\u05d5\u05df, \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d9\u05d1\u05e9\u05d9\u05dd, \u05d4\u05d2\u05e0\u05ea \u05d2\u05d6 \u05ea\u05e7\u05d9\u05e0\u05d4 \u05d5\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05e0\u05db\u05d5\u05e0\u05d9\u05dd."], [399.6, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d0\u05d9 \u05e8\u05e6\u05d9\u05e4\u05d5\u05ea \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05e4\u05d2\u05dd \u05e8\u05e7 \u05db\u05e9\u05d4\u05d9\u05d0 \u05e2\u05d5\u05d1\u05e8\u05ea \u05d0\u05ea \u05d2\u05d1\u05d5\u05dc \u05d4\u05e7\u05d1\u05dc\u05d4 \u05e9\u05dc \u05e8\u05de\u05ea \u05d4\u05d0\u05d9\u05db\u05d5\u05ea."], [406.5, "\u05e1\u05d3\u05e7\u05d9\u05dd \u05d5\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da \u05d4\u05dd \u05d4\u05de\u05e1\u05d5\u05db\u05e0\u05d9\u05dd \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d5\u05dc\u05e8\u05d5\u05d1 \u05dc\u05d0 \u05e0\u05e8\u05d0\u05d9\u05dd \u05de\u05d1\u05d7\u05d5\u05e5. \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05d5\u05e9\u05d0\u05e8\u05d9\u05d5\u05ea slag \u05e0\u05d5\u05e6\u05e8\u05d5\u05ea \u05de\u05d2\u05d6, \u05de\u05dc\u05db\u05dc\u05d5\u05da \u05d5\u05de\u05e0\u05d9\u05e7\u05d5\u05d9 \u05dc\u05e7\u05d5\u05d9."], [418.7, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e9\u05d9\u05d8\u05d5\u05ea \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4, \u05de\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d7\u05d6\u05d5\u05ea\u05d9\u05ea \u05d5\u05e2\u05d3 \u05d0\u05d5\u05dc\u05d8\u05e8\u05e1\u05d0\u05d5\u05e0\u05d3 \u05d5\u05e8\u05e0\u05d8\u05d2\u05df."]]};
window.MH_TR["ch23"]={"t": "\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e8\u05d9\u05ea\u05d5\u05da", "l": [[3.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd \u05e8\u05d0\u05d9\u05e0\u05d5 \u05e9\u05e8\u05d5\u05d1 \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d4\u05de\u05e1\u05d5\u05db\u05e0\u05d9\u05dd \u05dc\u05d0 \u05e0\u05e8\u05d0\u05d9\u05dd \u05de\u05d1\u05d7\u05d5\u05e5."], [8.1, "\u05dc\u05db\u05df \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e8\u05d9\u05ea\u05d5\u05db\u05d9\u05dd \u05d1\u05e9\u05d9\u05d8\u05d5\u05ea \u05e9\u05de\u05d2\u05dc\u05d5\u05ea \u05de\u05d4 \u05e9\u05d4\u05e2\u05d9\u05df \u05dc\u05d0 \u05e8\u05d5\u05d0\u05d4, \u05d1\u05dc\u05d9 \u05dc\u05e4\u05d2\u05d5\u05e2 \u05d1\u05d7\u05dc\u05e7."], [14.2, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d7\u05de\u05e9 \u05d4\u05e9\u05d9\u05d8\u05d5\u05ea \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea: \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d7\u05d6\u05d5\u05ea\u05d9\u05ea, \u05e0\u05d5\u05d6\u05dc \u05d7\u05d5\u05d3\u05e8, \u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05de\u05d2\u05e0\u05d8\u05d9\u05d9\u05dd, \u05d0\u05d5\u05dc\u05d8\u05e8\u05e1\u05d0\u05d5\u05e0\u05d3 \u05d5\u05e8\u05e0\u05d8\u05d2\u05df."], [24.0, "\u05d1\u05d3\u05d9\u05e7\u05d4 \u05dc\u05d0 \u05de\u05ea\u05d7\u05d9\u05dc\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da. \u05d4\u05d9\u05d0 \u05de\u05ea\u05d7\u05d9\u05dc\u05d4 \u05dc\u05e4\u05e0\u05d9\u05d5."], [28.1, "\u05dc\u05e4\u05e0\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05d4\u05db\u05e0\u05d4: \u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05d7\u05e8\u05d9\u05e5, \u05e4\u05e2\u05e8 \u05d4\u05e9\u05d5\u05e8\u05e9, \u05e0\u05d9\u05e7\u05d9\u05d5\u05df \u05d5\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e0\u05db\u05d5\u05e0\u05d9\u05dd."], [35.6, "\u05d1\u05d6\u05de\u05df \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05d5\u05e7\u05d3\u05dd, \u05d5\u05e0\u05d9\u05e7\u05d5\u05d9 \u05d1\u05d9\u05df \u05de\u05e2\u05d1\u05e8\u05d9\u05dd."], [42.0, "\u05d5\u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8 \u05e2\u05e6\u05de\u05d5."], [45.2, "\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05dc\u05d0 \u05d4\u05d5\u05e8\u05e1\u05d5\u05ea, NDT, \u05de\u05e9\u05d0\u05d9\u05e8\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05e9\u05dc\u05dd. \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d4\u05d5\u05e8\u05e1\u05d5\u05ea \u05d7\u05d5\u05ea\u05db\u05d5\u05ea \u05d3\u05d5\u05d2\u05de\u05d4, \u05d5\u05e0\u05dc\u05de\u05d3 \u05d0\u05d5\u05ea\u05df \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0."], [54.7, "\u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4, \u05d5\u05d4\u05d6\u05d5\u05dc\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d4\u05d9\u05d0 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d7\u05d6\u05d5\u05ea\u05d9\u05ea."], [59.2, "\u05d4\u05d9\u05d0 \u05de\u05d2\u05dc\u05d4 \u05d0\u05ea \u05e8\u05d5\u05d1 \u05e4\u05d2\u05de\u05d9 \u05d4\u05e6\u05d5\u05e8\u05d4: undercut, overlap, \u05ea\u05e4\u05e8 \u05dc\u05d0 \u05de\u05dc\u05d0, \u05d0\u05d9 \u05d9\u05d9\u05e9\u05d5\u05e8, \u05e1\u05d3\u05e7\u05d9\u05dd \u05e2\u05dc \u05d4\u05e4\u05e0\u05d9\u05dd \u05d5\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05e2\u05dc \u05d4\u05e4\u05e0\u05d9\u05dd."], [69.1, "\u05e6\u05e8\u05d9\u05da \u05ea\u05d0\u05d5\u05e8\u05d4 \u05d8\u05d5\u05d1\u05d4, \u05e9\u05dc \u05dc\u05e4\u05d7\u05d5\u05ea 350 \u05dc\u05d5\u05e7\u05e1, \u05d5\u05dc\u05d4\u05e1\u05ea\u05db\u05dc \u05de\u05e7\u05e8\u05d5\u05d1 \u05d5\u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e0\u05db\u05d5\u05e0\u05d4."], [75.9, "\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05ea \u05d2\u05d5\u05d3\u05dc \u05d4\u05ea\u05e4\u05e8 \u05d1\u05de\u05d3\u05d9 \u05ea\u05e4\u05e8, \u05e9\u05de\u05e8\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e8\u05d2\u05dc, \u05d4\u05e6\u05d5\u05d5\u05d0\u05e8 \u05d5\u05d4\u05d2\u05d5\u05d1\u05d4."], [81.7, "\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d2\u05dd \u05e9\u05d4\u05ea\u05e4\u05e8 \u05d1\u05d0\u05d5\u05e8\u05da \u05d4\u05e0\u05db\u05d5\u05df \u05d5\u05d1\u05de\u05e7\u05d5\u05dd \u05d4\u05e0\u05db\u05d5\u05df \u05dc\u05e4\u05d9 \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8."], [86.9, "\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d7\u05d6\u05d5\u05ea\u05d9\u05ea \u05d8\u05d5\u05d1\u05d4 \u05d7\u05d5\u05e1\u05db\u05ea \u05d4\u05e8\u05d1\u05d4 \u05db\u05e1\u05e3, \u05db\u05d9 \u05d4\u05d9\u05d0 \u05ea\u05d5\u05e4\u05e1\u05ea \u05d1\u05e2\u05d9\u05d5\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d4\u05d9\u05e7\u05e8\u05d5\u05ea."], [93.1, "\u05d0\u05d1\u05dc \u05d4\u05d9\u05d0 \u05dc\u05d0 \u05e8\u05d5\u05d0\u05d4 \u05de\u05d4 \u05e9\u05de\u05ea\u05d7\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [96.7, "\u05d1\u05d3\u05d9\u05e7\u05ea \u05e0\u05d5\u05d6\u05dc \u05d7\u05d5\u05d3\u05e8, PT, \u05de\u05d2\u05dc\u05d4 \u05e1\u05d3\u05e7\u05d9\u05dd \u05d5\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05e9\u05e4\u05ea\u05d5\u05d7\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d2\u05dd \u05db\u05e9\u05d4\u05dd \u05d3\u05e7\u05d9\u05dd \u05de\u05d0\u05d5\u05d3."], [104.6, "\u05e7\u05d5\u05d3\u05dd \u05de\u05e0\u05e7\u05d9\u05dd \u05d4\u05d9\u05d8\u05d1 \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8, \u05db\u05d9 \u05dc\u05db\u05dc\u05d5\u05da \u05e1\u05d5\u05d2\u05e8 \u05d0\u05ea \u05d4\u05e1\u05d3\u05e7\u05d9\u05dd."], [109.5, "\u05de\u05e8\u05e1\u05e1\u05d9\u05dd \u05e0\u05d5\u05d6\u05dc \u05e6\u05d1\u05e2\u05d5\u05e0\u05d9, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d0\u05d3\u05d5\u05dd \u05d0\u05d5 \u05e4\u05dc\u05d5\u05d0\u05d5\u05e8\u05e1\u05e6\u05e0\u05d8\u05d9, \u05d5\u05de\u05d7\u05db\u05d9\u05dd \u05e9\u05d9\u05d7\u05d3\u05d5\u05e8 \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05df \u05d7\u05de\u05e9 \u05dc\u05e9\u05d9\u05e9\u05d9\u05dd \u05d3\u05e7\u05d5\u05ea."], [119.0, "\u05de\u05e0\u05d2\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05e2\u05d5\u05d3\u05e3 \u05de\u05d4\u05e4\u05e0\u05d9\u05dd, \u05d5\u05de\u05e8\u05e1\u05e1\u05d9\u05dd \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05d5\u05dc\u05d1\u05e0\u05d4 \u05e9\u05dc developer."], [124.4, "\u05d4-developer \u05de\u05d5\u05e9\u05da \u05d0\u05ea \u05d4\u05e0\u05d5\u05d6\u05dc \u05de\u05ea\u05d5\u05da \u05d4\u05e1\u05d3\u05e7, \u05d5\u05e1\u05d9\u05de\u05df \u05d0\u05d3\u05d5\u05dd \u05de\u05d5\u05e4\u05d9\u05e2 \u05e2\u05dc \u05d4\u05e8\u05e7\u05e2 \u05d4\u05dc\u05d1\u05df."], [130.4, "\u05d4\u05e9\u05d9\u05d8\u05d4 \u05e4\u05e9\u05d5\u05d8\u05d4 \u05d5\u05d6\u05d5\u05dc\u05d4, \u05d5\u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05db\u05de\u05e2\u05d8 \u05dc\u05db\u05dc \u05de\u05ea\u05db\u05ea, \u05db\u05d5\u05dc\u05dc \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05d0\u05dc \u05d7\u05dc\u05d3."], [136.5, "\u05d0\u05d1\u05dc \u05d4\u05d9\u05d0 \u05de\u05d2\u05dc\u05d4 \u05e8\u05e7 \u05e4\u05d2\u05de\u05d9\u05dd \u05e9\u05e4\u05ea\u05d5\u05d7\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [140.6, "\u05d1\u05d3\u05d9\u05e7\u05ea \u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05de\u05d2\u05e0\u05d8\u05d9\u05d9\u05dd, MT, \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05e8\u05d9\u05d8\u05d9\u05d5\u05ea \u05d1\u05dc\u05d1\u05d3, \u05db\u05d9 \u05e6\u05e8\u05d9\u05da \u05d7\u05d5\u05de\u05e8 \u05e9\u05e0\u05de\u05e9\u05da \u05dc\u05de\u05d2\u05e0\u05d8."], [148.5, "\u05de\u05de\u05d2\u05e0\u05d8\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05de\u05d2\u05e0\u05d8 \u05d1\u05e6\u05d5\u05e8\u05ea U."], [152.9, "\u05e1\u05d3\u05e7 \u05d1\u05d3\u05e8\u05da \u05e9\u05dc \u05d4\u05e9\u05d3\u05d4 \u05d4\u05de\u05d2\u05e0\u05d8\u05d9 \u05d2\u05d5\u05e8\u05dd \u05dc\u05e9\u05d3\u05d4 \u05dc\u05d1\u05e8\u05d5\u05d7 \u05d4\u05d7\u05d5\u05e6\u05d4, \u05d5\u05e9\u05dd \u05e0\u05d0\u05e1\u05e4\u05d9\u05dd \u05d7\u05dc\u05e7\u05d9\u05e7\u05d9 \u05d1\u05e8\u05d6\u05dc \u05d3\u05e7\u05d9\u05dd."], [160.5, "\u05db\u05da \u05e8\u05d5\u05d0\u05d9\u05dd \u05e7\u05d5 \u05d1\u05e8\u05d5\u05e8 \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05e1\u05d3\u05e7, \u05d2\u05dd \u05db\u05e9\u05d4\u05d5\u05d0 \u05e7\u05e6\u05ea \u05de\u05ea\u05d7\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [165.8, "\u05e1\u05d3\u05e7 \u05e9\u05de\u05e7\u05d1\u05d9\u05dc \u05dc\u05e9\u05d3\u05d4 \u05dc\u05d0 \u05e0\u05e8\u05d0\u05d4, \u05d5\u05dc\u05db\u05df \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e4\u05e2\u05de\u05d9\u05d9\u05dd, \u05d1\u05e9\u05e0\u05d9 \u05db\u05d9\u05d5\u05d5\u05e0\u05d9\u05dd \u05e0\u05d9\u05e6\u05d1\u05d9\u05dd."], [172.0, "\u05d4\u05e9\u05d9\u05d8\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4 \u05d5\u05e8\u05d2\u05d9\u05e9\u05d4, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05e2\u05d5\u05d1\u05d3\u05ea \u05e2\u05dc \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05e2\u05dc \u05d0\u05dc \u05d7\u05dc\u05d3 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9."], [178.5, "\u05d1\u05d3\u05d9\u05e7\u05ea \u05d0\u05d5\u05dc\u05d8\u05e8\u05e1\u05d0\u05d5\u05e0\u05d3, UT, \u05e9\u05d5\u05dc\u05d7\u05ea \u05d2\u05dc\u05d9 \u05e7\u05d5\u05dc \u05d1\u05ea\u05d3\u05e8 \u05d2\u05d1\u05d5\u05d4 \u05dc\u05ea\u05d5\u05da \u05d4\u05de\u05ea\u05db\u05ea."], [184.6, "\u05d1\u05ea\u05e4\u05e8\u05d9\u05dd \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e8\u05d0\u05e9 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d6\u05d5\u05d5\u05d9\u05ea\u05d9, \u05e9\u05de\u05db\u05e0\u05d9\u05e1 \u05d0\u05ea \u05d4\u05e7\u05d5\u05dc \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05d5\u05de\u05d2\u05d9\u05e2 \u05dc\u05db\u05dc \u05d7\u05ea\u05da \u05d4\u05ea\u05e4\u05e8."], [191.5, "\u05d1\u05d9\u05df \u05e8\u05d0\u05e9 \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05dc\u05d7\u05dc\u05e7 \u05de\u05d5\u05e8\u05d7\u05d9\u05dd \u05d2'\u05dc, \u05db\u05d9 \u05d4\u05e7\u05d5\u05dc \u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8 \u05d3\u05e8\u05da \u05d0\u05d5\u05d5\u05d9\u05e8."], [196.8, "\u05db\u05e9\u05d4\u05e7\u05d5\u05dc \u05e4\u05d5\u05d2\u05e2 \u05d1\u05e4\u05d2\u05dd, \u05d4\u05d5\u05d0 \u05d7\u05d5\u05d6\u05e8 \u05dc\u05e8\u05d0\u05e9 \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4, \u05d5\u05dc\u05e4\u05d9 \u05d4\u05d6\u05de\u05df \u05d5\u05d4\u05d6\u05d5\u05d5\u05d9\u05ea \u05d9\u05d5\u05d3\u05e2\u05d9\u05dd \u05d0\u05d9\u05e4\u05d4 \u05d4\u05e4\u05d2\u05dd \u05d5\u05d1\u05d0\u05d9\u05d6\u05d4 \u05e2\u05d5\u05de\u05e7."], [204.7, "UT \u05de\u05e6\u05d5\u05d9\u05df \u05dc\u05d2\u05d9\u05dc\u05d5\u05d9 \u05e1\u05d3\u05e7\u05d9\u05dd \u05d5\u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da, \u05db\u05dc\u05d5\u05de\u05e8 \u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05d4\u05de\u05d9\u05e9\u05d5\u05e8\u05d9\u05d9\u05dd \u05d4\u05de\u05e1\u05d5\u05db\u05e0\u05d9\u05dd."], [211.1, "\u05d4\u05d5\u05d0 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd, \u05d0\u05d1\u05dc \u05d3\u05d5\u05e8\u05e9 \u05d1\u05d5\u05d3\u05e7 \u05de\u05d9\u05d5\u05de\u05df, \u05d5\u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05d3\u05e7\u05d9\u05dd \u05d4\u05d5\u05d0 \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8."], [217.3, "\u05d1\u05e9\u05d9\u05d8\u05d4 \u05d4\u05de\u05ea\u05e7\u05d3\u05de\u05ea, phased array, \u05d0\u05d5 PAUT, \u05d9\u05e9 \u05d1\u05e8\u05d0\u05e9 \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd, \u05e9\u05de\u05e1\u05d9\u05d8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05d5\u05dc \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05ea."], [226.3, "\u05db\u05da \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05ea\u05de\u05d5\u05e0\u05d4 \u05e9\u05dc \u05d4\u05d7\u05ea\u05da, \u05d5\u05d0\u05ea \u05d4\u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e9\u05de\u05d5\u05e8 \u05d5\u05dc\u05d1\u05d3\u05d5\u05e7 \u05e9\u05d5\u05d1."], [232.2, "\u05d1\u05d3\u05d9\u05e7\u05d4 \u05e8\u05d3\u05d9\u05d5\u05d2\u05e8\u05e4\u05d9\u05ea, RT, \u05de\u05e2\u05d1\u05d9\u05e8\u05d4 \u05e7\u05e8\u05d9\u05e0\u05d4 \u05d3\u05e8\u05da \u05d4\u05ea\u05e4\u05e8, \u05e7\u05e8\u05e0\u05d9 \u05e8\u05e0\u05d8\u05d2\u05df \u05d0\u05d5 \u05e7\u05e8\u05e0\u05d9 \u05d2\u05de\u05d0."], [239.4, "\u05de\u05d0\u05d7\u05d5\u05e8\u05d9 \u05d4\u05ea\u05e4\u05e8 \u05d9\u05e9 \u05e1\u05e8\u05d8 \u05d0\u05d5 \u05d2\u05dc\u05d0\u05d9 \u05d3\u05d9\u05d2\u05d9\u05d8\u05dc\u05d9. \u05d0\u05d9\u05e4\u05d4 \u05e9\u05d9\u05e9 \u05e4\u05d7\u05d5\u05ea \u05d7\u05d5\u05de\u05e8, \u05e2\u05d5\u05d1\u05e8\u05ea \u05d9\u05d5\u05ea\u05e8 \u05e7\u05e8\u05d9\u05e0\u05d4."], [246.6, "\u05dc\u05db\u05df \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05d5\u05e9\u05d0\u05e8\u05d9\u05d5\u05ea slag \u05e0\u05e8\u05d0\u05d5\u05ea \u05db\u05d4\u05d5\u05ea, \u05d5\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05e0\u05e8\u05d0\u05d4 \u05d1\u05d4\u05d9\u05e8."], [253.4, "RT \u05de\u05e6\u05d5\u05d9\u05df \u05dc\u05e4\u05d2\u05de\u05d9\u05dd \u05e0\u05e4\u05d7\u05d9\u05d9\u05dd, \u05d5\u05e0\u05d5\u05ea\u05df \u05ea\u05d9\u05e2\u05d5\u05d3 \u05e7\u05d1\u05d5\u05e2 \u05e9\u05dc \u05d4\u05ea\u05e4\u05e8."], [258.6, "\u05d0\u05d1\u05dc \u05e1\u05d3\u05e7 \u05d0\u05d5 \u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da \u05e0\u05e8\u05d0\u05d9\u05dd \u05e8\u05e7 \u05d0\u05dd \u05d4\u05dd \u05de\u05e7\u05d1\u05d9\u05dc\u05d9\u05dd \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05e7\u05e8\u05d9\u05e0\u05d4."], [264.3, "\u05d5\u05d4\u05e7\u05e8\u05d9\u05e0\u05d4 \u05de\u05e1\u05d5\u05db\u05e0\u05ea: \u05e6\u05e8\u05d9\u05da \u05dc\u05e4\u05e0\u05d5\u05ea \u05d0\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8, \u05d5\u05dc\u05db\u05df \u05e6\u05d9\u05dc\u05d5\u05de\u05d9\u05dd \u05e0\u05e2\u05e9\u05d9\u05dd \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d1\u05dc\u05d9\u05dc\u05d4 \u05d0\u05d5 \u05d1\u05ea\u05d0 \u05e1\u05d2\u05d5\u05e8."], [272.5, "\u05d6\u05d5 \u05d2\u05dd \u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05d9\u05e7\u05e8\u05d4 \u05d5\u05d4\u05d0\u05d9\u05d8\u05d9\u05ea \u05de\u05d1\u05d9\u05df \u05d4\u05d7\u05de\u05e9."], [276.8, "\u05d0\u05d9\u05da \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05e9\u05d9\u05d8\u05d4? \u05dc\u05e4\u05d9 \u05e1\u05d5\u05d2 \u05d4\u05d7\u05d5\u05de\u05e8, \u05e2\u05d5\u05d1\u05d9, \u05e1\u05d5\u05d2 \u05d4\u05e4\u05d2\u05dd \u05d4\u05e6\u05e4\u05d5\u05d9, \u05d5\u05e0\u05d2\u05d9\u05e9\u05d5\u05ea."], [283.2, "PT \u05d5-MT \u05de\u05db\u05e1\u05d9\u05dd \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7. UT \u05d5-RT \u05de\u05db\u05e1\u05d9\u05dd \u05d0\u05ea \u05d4\u05e0\u05e4\u05d7."], [289.6, "\u05d5\u05dc\u05e8\u05d5\u05d1 \u05de\u05e9\u05dc\u05d1\u05d9\u05dd: \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d7\u05d6\u05d5\u05ea\u05d9\u05ea \u05dc\u05db\u05dc \u05d4\u05ea\u05e4\u05e8\u05d9\u05dd, \u05d5\u05e9\u05d9\u05d8\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea \u05dc\u05d7\u05dc\u05e7 \u05de\u05d4\u05dd."], [295.7, "\u05d4\u05d9\u05e7\u05e3 \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05e0\u05e7\u05d1\u05e2 \u05d1\u05ea\u05db\u05e0\u05d5\u05df: \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d0\u05d7\u05d5\u05d6 \u05de\u05d4\u05ea\u05e4\u05e8\u05d9\u05dd, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05db\u05d5\u05dc\u05dd."], [301.7, "\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05e0\u05d1\u05d3\u05e7\u05ea \u05de\u05d5\u05dc \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05e7\u05d1\u05dc\u05d4 \u05e9\u05dc \u05e8\u05de\u05ea \u05d4\u05d0\u05d9\u05db\u05d5\u05ea, \u05dc\u05de\u05e9\u05dc \u05dc\u05e4\u05d9 ISO 5817."], [309.1, "\u05d5\u05d4\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e2\u05e6\u05de\u05dd \u05de\u05d5\u05e1\u05de\u05db\u05d9\u05dd \u05dc\u05e4\u05d9 ISO 9712, \u05d1\u05e9\u05dc\u05d5\u05e9 \u05e8\u05de\u05d5\u05ea."], [314.9, "\u05e8\u05de\u05d4 1 \u05de\u05d1\u05e6\u05e2\u05ea \u05dc\u05e4\u05d9 \u05d4\u05d5\u05e8\u05d0\u05d5\u05ea, \u05e8\u05de\u05d4 2 \u05de\u05db\u05d9\u05d9\u05dc\u05ea, \u05d1\u05d5\u05d3\u05e7\u05ea \u05d5\u05de\u05d7\u05dc\u05d9\u05d8\u05d4 \u05dc\u05e4\u05d9 \u05d4\u05ea\u05e7\u05df, \u05d5\u05e8\u05de\u05d4 3 \u05db\u05d5\u05ea\u05d1\u05ea \u05d0\u05ea \u05d4\u05e0\u05d4\u05dc\u05d9\u05dd."], [325.7, "\u05d5\u05e2\u05db\u05e9\u05d9\u05d5, \u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8."], [328.1, "\u05db\u05dc \u05e9\u05d9\u05d8\u05d4 \u05e2\u05d5\u05dc\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05e7\u05d5\u05d3\u05de\u05ea: \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d7\u05d6\u05d5\u05ea\u05d9\u05ea \u05d4\u05d9\u05d0 \u05d4\u05d6\u05d5\u05dc\u05d4, \u05d5-RT \u05d4\u05d9\u05d0 \u05d4\u05d9\u05e7\u05e8\u05d4."], [335.0, "\u05d4\u05d9\u05e7\u05e3 \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05de\u05db\u05e4\u05d9\u05dc \u05d0\u05ea \u05d4\u05de\u05d7\u05d9\u05e8: \u05d1\u05d3\u05d9\u05e7\u05d4 \u05e9\u05dc \u05db\u05dc \u05d4\u05ea\u05e4\u05e8\u05d9\u05dd \u05e2\u05d5\u05dc\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d1\u05d3\u05d9\u05e7\u05d4 \u05de\u05d3\u05d2\u05de\u05d9\u05ea."], [341.7, "RT \u05e2\u05d5\u05e6\u05e8 \u05d0\u05ea \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05d0\u05d6\u05d5\u05e8, \u05d5\u05d3\u05d5\u05e8\u05e9 \u05ea\u05d9\u05d0\u05d5\u05dd \u05d5\u05d1\u05d8\u05d9\u05d7\u05d5\u05ea \u05e7\u05e8\u05d9\u05e0\u05d4."], [346.3, "\u05ea\u05e4\u05e8 \u05e9\u05e0\u05db\u05e9\u05dc \u05e6\u05e8\u05d9\u05da \u05ea\u05d9\u05e7\u05d5\u05df \u05d5\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d7\u05d5\u05d6\u05e8\u05ea, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05d2\u05d3\u05d9\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05d9\u05e7\u05e3 \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05dc\u05ea\u05e4\u05e8\u05d9\u05dd \u05e0\u05d5\u05e1\u05e4\u05d9\u05dd."], [353.5, "\u05d5\u05d4\u05d7\u05d9\u05e1\u05db\u05d5\u05df \u05d4\u05d2\u05d3\u05d5\u05dc: \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d7\u05d6\u05d5\u05ea\u05d9\u05ea \u05e7\u05e4\u05d3\u05e0\u05d9\u05ea \u05dc\u05e4\u05e0\u05d9, \u05d1\u05d6\u05de\u05df \u05d5\u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05e9\u05de\u05d5\u05e0\u05e2\u05ea \u05e4\u05d2\u05de\u05d9\u05dd \u05d1\u05de\u05e7\u05d5\u05dd \u05dc\u05de\u05e6\u05d5\u05d0 \u05d0\u05d5\u05ea\u05dd."], [363.0, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d7\u05d6\u05d5\u05ea\u05d9\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05db\u05dc. PT \u05d5-MT \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, UT \u05d5-RT \u05dc\u05ea\u05d5\u05da \u05d4\u05ea\u05e4\u05e8."], [371.9, "UT \u05d7\u05d6\u05e7 \u05d1\u05e4\u05d2\u05de\u05d9\u05dd \u05de\u05d9\u05e9\u05d5\u05e8\u05d9\u05d9\u05dd, \u05d5-RT \u05d7\u05d6\u05e7 \u05d1\u05e4\u05d2\u05de\u05d9\u05dd \u05e0\u05e4\u05d7\u05d9\u05d9\u05dd. \u05d5\u05d4\u05d1\u05d5\u05d3\u05e7 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d5\u05e1\u05de\u05da."], [379.8, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e0\u05d4\u05dc\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da \u05d5\u05d4\u05e1\u05de\u05db\u05d5\u05ea, WPS, PQR, \u05d5\u05d4\u05e1\u05de\u05db\u05ea \u05e8\u05ea\u05db\u05d9\u05dd."]]};
window.MH_TR["ch24"]={"t": "\u05e0\u05d4\u05dc\u05d9\u05dd \u05d5\u05d4\u05e1\u05de\u05db\u05d5\u05ea", "l": [[3.0, "\u05e9\u05e0\u05d9 \u05e8\u05ea\u05db\u05d9\u05dd \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d0\u05ea \u05d0\u05d5\u05ea\u05d5 \u05d7\u05d9\u05d1\u05d5\u05e8, \u05d5\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea. \u05d0\u05d9\u05da \u05de\u05d1\u05d8\u05d9\u05d7\u05d9\u05dd \u05e9\u05db\u05dc \u05ea\u05e4\u05e8 \u05d9\u05d9\u05e6\u05d0 \u05db\u05de\u05d5 \u05e9\u05ea\u05d5\u05db\u05e0\u05df?"], [11.0, "\u05d4\u05ea\u05e9\u05d5\u05d1\u05d4 \u05d4\u05d9\u05d0 \u05e0\u05d4\u05dc\u05d9\u05dd \u05db\u05ea\u05d5\u05d1\u05d9\u05dd, \u05e9\u05e0\u05d1\u05d3\u05e7\u05d5 \u05de\u05e8\u05d0\u05e9, \u05d5\u05e8\u05ea\u05db\u05d9\u05dd \u05e9\u05d4\u05d5\u05e1\u05de\u05db\u05d5 \u05dc\u05d1\u05e6\u05e2 \u05d0\u05d5\u05ea\u05dd."], [17.5, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05dc\u05de\u05d3 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05de\u05e1\u05de\u05db\u05d9\u05dd: WPS, PQR, \u05d5\u05d4\u05e1\u05de\u05db\u05ea \u05d4\u05e8\u05ea\u05da."], [25.3, "WPS \u05d4\u05d5\u05d0 \u05e0\u05d5\u05d4\u05dc \u05e8\u05d9\u05ea\u05d5\u05da: \u05d4\u05de\u05ea\u05db\u05d5\u05df \u05e9\u05d4\u05e8\u05ea\u05da \u05e2\u05d5\u05d1\u05d3 \u05dc\u05e4\u05d9\u05d5 \u05d1\u05e2\u05de\u05d3\u05d4."], [31.2, "\u05d4\u05d5\u05d0 \u05de\u05d2\u05d3\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9, \u05d7\u05d5\u05de\u05e8 \u05d4\u05de\u05d9\u05dc\u05d5\u05d9, \u05d4\u05ea\u05d4\u05dc\u05d9\u05da, \u05d5\u05e6\u05d5\u05e8\u05ea \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8."], [37.1, "\u05d4\u05d5\u05d0 \u05de\u05d2\u05d3\u05d9\u05e8 \u05d0\u05ea \u05ea\u05e0\u05d5\u05d7\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d4\u05d6\u05e8\u05dd, \u05d4\u05de\u05ea\u05d7, \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05de\u05db\u05d0\u05df \u05d0\u05ea \u05d4-heat input."], [44.4, "\u05d5\u05d2\u05dd \u05d0\u05ea \u05d4\u05d2\u05d6 \u05d5\u05d4\u05e1\u05e4\u05d9\u05e7\u05d4, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d9\u05de\u05d5\u05dd \u05d4\u05de\u05d5\u05e7\u05d3\u05dd, \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d1\u05d9\u05df \u05d4\u05de\u05e2\u05d1\u05e8\u05d9\u05dd, \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."], [53.8, "\u05dc\u05db\u05dc \u05e4\u05e8\u05de\u05d8\u05e8 \u05d9\u05e9 \u05ea\u05d7\u05d5\u05dd \u05de\u05d5\u05ea\u05e8, \u05d5\u05dc\u05d0 \u05e2\u05e8\u05da \u05d9\u05d7\u05d9\u05d3."], [57.8, "\u05d4-WPS \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05d6\u05de\u05d9\u05df \u05dc\u05d9\u05d3 \u05d4\u05e2\u05de\u05d3\u05d4, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05d1\u05ea\u05d9\u05e7 \u05d1\u05de\u05e9\u05e8\u05d3."], [62.9, "WPS \u05d8\u05d5\u05d1 \u05db\u05ea\u05d5\u05d1 \u05db\u05da \u05e9\u05d4\u05e8\u05ea\u05da \u05d9\u05db\u05d5\u05dc \u05dc\u05e2\u05d1\u05d5\u05d3 \u05dc\u05e4\u05d9\u05d5 \u05d1\u05dc\u05d9 \u05dc\u05e0\u05d7\u05e9."], [69.5, "\u05d0\u05d1\u05dc \u05d0\u05d9\u05da \u05d9\u05d5\u05d3\u05e2\u05d9\u05dd \u05e9\u05d4-WPS \u05d1\u05d0\u05de\u05ea \u05e0\u05d5\u05ea\u05df \u05ea\u05e4\u05e8 \u05d8\u05d5\u05d1? \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5."], [75.0, "\u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05d1\u05d8\u05d9\u05d5\u05d8\u05d4, pWPS, \u05e0\u05d5\u05d4\u05dc \u05de\u05d5\u05e6\u05e2 \u05e9\u05e2\u05d5\u05d3 \u05dc\u05d0 \u05e0\u05d1\u05d3\u05e7."], [80.6, "\u05dc\u05e4\u05d9\u05d4 \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d3\u05d5\u05d2\u05de\u05ea \u05d1\u05d3\u05d9\u05e7\u05d4, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e0\u05d5\u05db\u05d7\u05d5\u05ea \u05d1\u05d5\u05d3\u05e7 \u05de\u05d5\u05e1\u05de\u05da."], [85.8, "\u05d1\u05d6\u05de\u05df \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e8\u05d5\u05e9\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05e2\u05e8\u05db\u05d9\u05dd \u05d1\u05e4\u05d5\u05e2\u05dc: \u05d6\u05e8\u05dd, \u05de\u05ea\u05d7, \u05de\u05d4\u05d9\u05e8\u05d5\u05ea, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea."], [93.2, "\u05d0\u05d7\u05e8 \u05db\u05da \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05d3\u05d5\u05d2\u05de\u05d4 \u05d1\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05dc\u05d0 \u05d4\u05d5\u05e8\u05e1\u05d5\u05ea, \u05d5\u05d0\u05d6 \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05dc\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d4\u05d5\u05e8\u05e1\u05d5\u05ea."], [99.5, "\u05d0\u05dd \u05db\u05dc \u05d4\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e2\u05d5\u05d1\u05e8\u05d5\u05ea, \u05d4\u05e8\u05e9\u05d5\u05de\u05d4 \u05d4\u05d6\u05d5 \u05d4\u05d9\u05d0 \u05d4-PQR: \u05d4\u05ea\u05d9\u05e2\u05d5\u05d3 \u05e9\u05de\u05d5\u05db\u05d9\u05d7 \u05e9\u05d4\u05e0\u05d5\u05d4\u05dc \u05e2\u05d5\u05d1\u05d3."], [106.7, "\u05d5\u05e2\u05dc \u05d1\u05e1\u05d9\u05e1 \u05d4-PQR \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4-WPS \u05d4\u05e1\u05d5\u05e4\u05d9, \u05e9\u05d9\u05d5\u05e6\u05d0 \u05dc\u05e8\u05e6\u05e4\u05ea \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8."], [113.5, "\u05d0\u05dc\u05d4 \u05d4\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d4\u05d4\u05d5\u05e8\u05e1\u05d5\u05ea \u05e9\u05d4\u05d1\u05d8\u05d7\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd."], [117.1, "\u05d1\u05d1\u05d3\u05d9\u05e7\u05ea \u05de\u05ea\u05d9\u05d7\u05d4 \u05de\u05d5\u05e9\u05db\u05d9\u05dd \u05e4\u05e1 \u05e9\u05d7\u05d5\u05e6\u05d4 \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8 \u05e2\u05d3 \u05e9\u05d4\u05d5\u05d0 \u05e0\u05e9\u05d1\u05e8, \u05d5\u05d7\u05d5\u05d6\u05e7 \u05d4\u05de\u05ea\u05d9\u05d7\u05d4 \u05e6\u05e8\u05d9\u05da \u05dc\u05e2\u05d1\u05d5\u05e8 \u05d0\u05ea \u05d4\u05de\u05d9\u05e0\u05d9\u05de\u05d5\u05dd \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9."], [126.2, "\u05d1\u05d1\u05d3\u05d9\u05e7\u05ea \u05db\u05e4\u05d9\u05e4\u05d4 \u05de\u05db\u05d5\u05e4\u05e4\u05d9\u05dd \u05e4\u05e1 \u05e2\u05d3 \u05de\u05d0\u05d4 \u05d5\u05e9\u05de\u05d5\u05e0\u05d9\u05dd \u05de\u05e2\u05dc\u05d5\u05ea \u05e1\u05d1\u05d9\u05d1 \u05d2\u05dc\u05d9\u05dc, \u05de\u05e6\u05d3 \u05d4\u05e4\u05e0\u05d9\u05dd, \u05de\u05e6\u05d3 \u05d4\u05e9\u05d5\u05e8\u05e9, \u05d0\u05d5 \u05de\u05d4\u05e6\u05d3."], [135.0, "\u05d4\u05ea\u05e4\u05e8 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05ea\u05db\u05d5\u05e4\u05e3 \u05d1\u05dc\u05d9 \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7, \u05d5\u05db\u05da \u05de\u05ea\u05d2\u05dc\u05d9\u05dd \u05d7\u05d5\u05e1\u05e8 \u05d4\u05d9\u05ea\u05d5\u05da \u05d5\u05e4\u05d2\u05de\u05d9\u05dd \u05d7\u05d1\u05d5\u05d9\u05d9\u05dd."], [141.4, "\u05d1\u05d1\u05d3\u05d9\u05e7\u05ea \u05de\u05d0\u05e7\u05e8\u05d5 \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8, \u05de\u05dc\u05d8\u05e9\u05d9\u05dd \u05d5\u05e6\u05d5\u05e8\u05d1\u05d9\u05dd \u05d1\u05d7\u05d5\u05de\u05e6\u05d4, \u05d5\u05e8\u05d5\u05d0\u05d9\u05dd \u05d1\u05e2\u05d9\u05df \u05d0\u05ea \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4, \u05d4\u05d4\u05d9\u05ea\u05d5\u05da \u05d5\u05d4-HAZ."], [150.7, "\u05d1\u05d1\u05d3\u05d9\u05e7\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05ea\u05e4\u05e8 \u05d5\u05d4-HAZ, \u05db\u05d3\u05d9 \u05dc\u05d5\u05d5\u05d3\u05d0 \u05e9\u05d0\u05d9\u05df \u05d0\u05d6\u05d5\u05e8 \u05e7\u05e9\u05d4 \u05d5\u05e4\u05e8\u05d9\u05da \u05de\u05d3\u05d9."], [158.1, "\u05d5\u05db\u05e9\u05e0\u05d3\u05e8\u05e9\u05ea \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05e2\u05d5\u05e9\u05d9\u05dd \u05d1\u05d3\u05d9\u05e7\u05ea \u05d4\u05dc\u05dd, Charpy, \u05d1\u05ea\u05e4\u05e8 \u05d5\u05d1-HAZ."], [167.0, "PQR \u05d0\u05d7\u05d3 \u05dc\u05d0 \u05de\u05db\u05e1\u05d4 \u05e8\u05e7 \u05d0\u05ea \u05de\u05d4 \u05e9\u05e0\u05d1\u05d3\u05e7 \u05d1\u05d3\u05d9\u05d5\u05e7. \u05d4\u05d5\u05d0 \u05de\u05e1\u05de\u05d9\u05da \u05ea\u05d7\u05d5\u05dd."], [173.4, "\u05dc\u05de\u05e9\u05dc \u05d1\u05e2\u05d5\u05d1\u05d9: \u05d3\u05d5\u05d2\u05de\u05d4 \u05e2\u05d1\u05d4 \u05de\u05e1\u05de\u05d9\u05db\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05d5\u05d1\u05d9\u05d9\u05dd \u05de\u05d7\u05e6\u05d9 \u05d5\u05e2\u05d3 \u05e4\u05d9 \u05e9\u05e0\u05d9\u05d9\u05dd \u05de\u05d4\u05e2\u05d5\u05d1\u05d9 \u05e9\u05dc\u05d4."], [180.6, "\u05d4\u05ea\u05e7\u05df \u05de\u05d2\u05d3\u05d9\u05e8 \u05de\u05e9\u05ea\u05e0\u05d9\u05dd \u05d7\u05d9\u05d5\u05e0\u05d9\u05d9\u05dd: \u05d7\u05d5\u05de\u05e8 \u05d1\u05e1\u05d9\u05e1\u05d9, \u05ea\u05d4\u05dc\u05d9\u05da, \u05e1\u05d5\u05d2 \u05d7\u05d5\u05de\u05e8 \u05d4\u05de\u05d9\u05dc\u05d5\u05d9, \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d2\u05dd \u05ea\u05e0\u05d5\u05d7\u05d4 \u05d5-heat input."], [191.5, "\u05dc\u05de\u05e9\u05dc, PQR \u05e2\u05dc \u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05dc\u05d0 \u05de\u05e1\u05de\u05d9\u05da \u05e8\u05d9\u05ea\u05d5\u05da \u05e9\u05dc \u05d0\u05dc \u05d7\u05dc\u05d3, \u05d5\u05e0\u05d5\u05d4\u05dc \u05e9\u05dc MAG \u05dc\u05d0 \u05de\u05e1\u05de\u05d9\u05da TIG."], [200.3, "\u05e9\u05d9\u05e0\u05d5\u05d9 \u05d1\u05de\u05e9\u05ea\u05e0\u05d4 \u05d7\u05d9\u05d5\u05e0\u05d9 \u05de\u05d7\u05d5\u05e5 \u05dc\u05ea\u05d7\u05d5\u05dd \u05d3\u05d5\u05e8\u05e9 PQR \u05d7\u05d3\u05e9."], [205.5, "\u05e9\u05d9\u05e0\u05d5\u05d9 \u05d1\u05de\u05e9\u05ea\u05e0\u05d4 \u05dc\u05d0 \u05d7\u05d9\u05d5\u05e0\u05d9 \u05de\u05d5\u05ea\u05e8, \u05d1\u05ea\u05e0\u05d0\u05d9 \u05e9\u05de\u05e2\u05d3\u05db\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4-WPS."], [211.1, "\u05dc\u05db\u05df \u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d0\u05ea \u05d3\u05d5\u05d2\u05de\u05ea \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d1\u05d7\u05d5\u05db\u05de\u05d4, \u05db\u05da \u05e9\u05ea\u05db\u05e1\u05d4 \u05db\u05de\u05d4 \u05e9\u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d4\u05e6\u05e4\u05d5\u05d9\u05d4."], [218.0, "\u05e0\u05d5\u05d4\u05dc \u05d8\u05d5\u05d1 \u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7. \u05e6\u05e8\u05d9\u05da \u05d2\u05dd \u05e8\u05ea\u05da \u05e9\u05d9\u05d5\u05d3\u05e2 \u05dc\u05d1\u05e6\u05e2 \u05d0\u05d5\u05ea\u05d5."], [223.0, "\u05d1\u05d4\u05e1\u05de\u05db\u05ea \u05e8\u05ea\u05da \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05d3\u05dd, \u05dc\u05d0 \u05d0\u05ea \u05d4\u05e0\u05d5\u05d4\u05dc."], [227.0, "\u05d4\u05e8\u05ea\u05da \u05de\u05e8\u05ea\u05da \u05d3\u05d5\u05d2\u05de\u05d4 \u05dc\u05e4\u05d9 WPS \u05de\u05d0\u05d5\u05e9\u05e8, \u05d5\u05d4\u05d3\u05d5\u05d2\u05de\u05d4 \u05e0\u05d1\u05d3\u05e7\u05ea \u05d1\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d7\u05d6\u05d5\u05ea\u05d9\u05ea, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05d1\u05e6\u05d9\u05dc\u05d5\u05dd, \u05d1\u05db\u05e4\u05d9\u05e4\u05d4 \u05d0\u05d5 \u05d1\u05e9\u05d1\u05d9\u05e8\u05d4."], [236.9, "\u05d4\u05d4\u05e1\u05de\u05db\u05d4 \u05de\u05d5\u05d2\u05d1\u05dc\u05ea \u05dc\u05ea\u05d4\u05dc\u05d9\u05da, \u05dc\u05e7\u05d1\u05d5\u05e6\u05ea \u05d4\u05d7\u05d5\u05de\u05e8, \u05dc\u05ea\u05d7\u05d5\u05dd \u05e2\u05d5\u05d1\u05d9 \u05d5\u05e7\u05d5\u05d8\u05e8, \u05dc\u05e1\u05d5\u05d2 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8, \u05d5\u05dc\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea."], [244.6, "\u05e8\u05ea\u05da \u05e9\u05d4\u05d5\u05e1\u05de\u05da \u05d1\u05ea\u05e0\u05d5\u05d7\u05d4 \u05e7\u05e9\u05d4, \u05db\u05de\u05d5 \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05e2\u05dc \u05d4\u05e8\u05d0\u05e9, \u05de\u05d5\u05e1\u05de\u05da \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d2\u05dd \u05dc\u05ea\u05e0\u05d5\u05d7\u05d5\u05ea \u05e7\u05dc\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8."], [252.0, "\u05d5\u05de\u05e4\u05e2\u05d9\u05dc \u05e9\u05dc \u05de\u05db\u05d5\u05e0\u05ea \u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05d5 \u05e9\u05dc \u05e8\u05d5\u05d1\u05d5\u05d8 \u05de\u05d5\u05e1\u05de\u05da \u05d1\u05e0\u05e4\u05e8\u05d3, \u05db\u05de\u05e4\u05e2\u05d9\u05dc, \u05d5\u05dc\u05d0 \u05db\u05e8\u05ea\u05da \u05d9\u05d3\u05e0\u05d9."], [258.5, "\u05d4\u05d4\u05e1\u05de\u05db\u05d4 \u05dc\u05d0 \u05e0\u05e6\u05d7\u05d9\u05ea: \u05dc\u05e4\u05d9 ISO \u05d4\u05de\u05e2\u05e1\u05d9\u05e7 \u05de\u05d0\u05e9\u05e8 \u05db\u05dc \u05d7\u05e6\u05d9 \u05e9\u05e0\u05d4 \u05e9\u05d4\u05e8\u05ea\u05da \u05d4\u05de\u05e9\u05d9\u05da \u05dc\u05e8\u05ea\u05da, \u05d5\u05de\u05d7\u05d3\u05e9\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05db\u05dc \u05db\u05de\u05d4 \u05e9\u05e0\u05d9\u05dd."], [268.4, "\u05d5\u05d1-ASME, \u05e8\u05ea\u05da \u05e9\u05dc\u05d0 \u05e8\u05d9\u05ea\u05da \u05d1\u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05e1\u05d5\u05d9\u05dd \u05d7\u05e6\u05d9 \u05e9\u05e0\u05d4, \u05de\u05d0\u05d1\u05d3 \u05d0\u05ea \u05d4\u05d4\u05e1\u05de\u05db\u05d4 \u05dc\u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05d6\u05d4."], [276.6, "\u05d9\u05e9 \u05db\u05de\u05d4 \u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05ea\u05e7\u05e0\u05d9\u05dd, \u05d5\u05d4\u05df \u05dc\u05d0 \u05de\u05d7\u05dc\u05d9\u05e4\u05d5\u05ea \u05d6\u05d5 \u05d0\u05ea \u05d6\u05d5."], [280.4, "\u05d1\u05d0\u05d9\u05e8\u05d5\u05e4\u05d4 \u05d5\u05d1\u05d9\u05e9\u05e8\u05d0\u05dc \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05e4\u05d9 ISO: \u05e0\u05d5\u05d4\u05dc \u05dc\u05e4\u05d9 ISO 15614, \u05d5\u05e8\u05ea\u05db\u05d9\u05dd \u05dc\u05e4\u05d9 ISO 9606."], [292.3, "\u05d1\u05db\u05dc\u05d9 \u05dc\u05d7\u05e5 \u05d5\u05d1\u05e6\u05e0\u05e8\u05ea \u05dc\u05e4\u05d9 \u05d4\u05e7\u05d5\u05d3 \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9, \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05dc\u05e4\u05d9 ASME, \u05d7\u05dc\u05e7 \u05ea\u05e9\u05e2."], [299.6, "\u05d5\u05d1\u05de\u05d1\u05e0\u05d9 \u05e4\u05dc\u05d3\u05d4 \u05d1\u05d0\u05e8\u05e6\u05d5\u05ea \u05d4\u05d1\u05e8\u05d9\u05ea \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05dc\u05e4\u05d9 AWS D1.1."], [305.7, "\u05dc-AWS \u05d9\u05e9 \u05d9\u05ea\u05e8\u05d5\u05df: \u05e0\u05d4\u05dc\u05d9\u05dd \u05e9\u05e2\u05d5\u05de\u05d3\u05d9\u05dd \u05d1\u05ea\u05e0\u05d0\u05d9\u05dd \u05de\u05d5\u05d2\u05d3\u05e8\u05d9\u05dd \u05e0\u05d7\u05e9\u05d1\u05d9\u05dd \u05de\u05d5\u05e1\u05de\u05db\u05d9\u05dd \u05de\u05e8\u05d0\u05e9, prequalified, \u05d5\u05dc\u05d0 \u05e6\u05e8\u05d9\u05da PQR."], [315.2, "\u05d4\u05e1\u05de\u05db\u05d4 \u05dc\u05e4\u05d9 \u05ea\u05e7\u05df \u05d0\u05d7\u05d3 \u05dc\u05d0 \u05ea\u05de\u05d9\u05d3 \u05de\u05ea\u05e7\u05d1\u05dc\u05ea \u05d1\u05ea\u05e7\u05df \u05d0\u05d7\u05e8, \u05d5\u05dc\u05db\u05df \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05de\u05e8\u05d0\u05e9 \u05de\u05d4 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05d3\u05d5\u05e8\u05e9."], [323.1, "\u05db\u05dc \u05d6\u05d4 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05ea\u05d5\u05e2\u05d3."], [325.4, "\u05dc\u05db\u05dc \u05ea\u05e4\u05e8 \u05d7\u05e9\u05d5\u05d1 \u05d9\u05d5\u05d3\u05e2\u05d9\u05dd \u05dc\u05e4\u05d9 \u05d0\u05d9\u05d6\u05d4 WPS \u05d4\u05d5\u05d0 \u05e8\u05d5\u05ea\u05da, \u05d5\u05de\u05d9 \u05d4\u05e8\u05ea\u05da \u05e9\u05d1\u05d9\u05e6\u05e2 \u05d0\u05d5\u05ea\u05d5."], [332.3, "\u05de\u05e4\u05ea \u05e8\u05d9\u05ea\u05d5\u05da \u05e2\u05dc \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e1\u05de\u05e0\u05ea \u05dc\u05db\u05dc \u05ea\u05e4\u05e8 \u05de\u05e1\u05e4\u05e8, \u05d5\u05dc\u05d9\u05d3\u05d5 \u05d4\u05e0\u05d5\u05d4\u05dc, \u05d4\u05e8\u05ea\u05da \u05d5\u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05d4\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea."], [340.1, "\u05e9\u05d5\u05de\u05e8\u05d9\u05dd \u05d2\u05dd \u05d0\u05ea \u05ea\u05e2\u05d5\u05d3\u05d5\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05d5\u05d7\u05d5\u05de\u05e8\u05d9 \u05d4\u05de\u05d9\u05dc\u05d5\u05d9, \u05db\u05d3\u05d9 \u05e9\u05d0\u05e4\u05e9\u05e8 \u05d9\u05d4\u05d9\u05d4 \u05dc\u05e2\u05e7\u05d5\u05d1 \u05d0\u05d7\u05e8\u05d9 \u05db\u05dc \u05ea\u05e4\u05e8 \u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e9\u05e0\u05d9\u05dd."], [347.4, "\u05d5\u05d1\u05d5\u05d3\u05e7 \u05de\u05d1\u05d7\u05d5\u05e5 \u05de\u05ea\u05d7\u05d9\u05dc \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05de\u05e1\u05de\u05db\u05d9\u05dd, \u05d5\u05e8\u05e7 \u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05e1\u05ea\u05db\u05dc \u05e2\u05dc \u05d4\u05ea\u05e4\u05e8\u05d9\u05dd."], [354.3, "\u05d5\u05e2\u05db\u05e9\u05d9\u05d5, \u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8."], [356.6, "PQR \u05e2\u05d5\u05dc\u05d4 \u05d4\u05e8\u05d1\u05d4: \u05d7\u05d5\u05de\u05e8, \u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d3\u05d5\u05d2\u05de\u05d4, \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d1\u05de\u05e2\u05d1\u05d3\u05d4, \u05d5\u05e0\u05d5\u05db\u05d7\u05d5\u05ea \u05d1\u05d5\u05d3\u05e7 \u05de\u05d5\u05e1\u05de\u05da."], [364.9, "\u05dc\u05db\u05df \u05db\u05d3\u05d0\u05d9 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05d0\u05ea \u05d3\u05d5\u05d2\u05de\u05ea \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05db\u05da \u05e9\u05ea\u05db\u05e1\u05d4 \u05ea\u05d7\u05d5\u05dd \u05e8\u05d7\u05d1, \u05d5\u05dc\u05d0 \u05dc\u05d1\u05e6\u05e2 PQR \u05e0\u05e4\u05e8\u05d3 \u05dc\u05db\u05dc \u05e2\u05d1\u05d5\u05d3\u05d4."], [372.6, "\u05d2\u05dd \u05d4\u05e1\u05de\u05db\u05ea \u05e8\u05ea\u05db\u05d9\u05dd \u05e2\u05d5\u05dc\u05d4 \u05db\u05e1\u05e3 \u05d5\u05d6\u05de\u05df, \u05d5\u05db\u05dc \u05e8\u05ea\u05da \u05e9\u05dc\u05d0 \u05de\u05d5\u05e1\u05de\u05da \u05dc\u05ea\u05e0\u05d5\u05d7\u05d4 \u05d0\u05d5 \u05dc\u05d7\u05d5\u05de\u05e8 \u05d4\u05e0\u05d3\u05e8\u05e9 \u05d9\u05d5\u05e6\u05e8 \u05e6\u05d5\u05d5\u05d0\u05e8 \u05d1\u05e7\u05d1\u05d5\u05e7."], [381.3, "\u05d4\u05e1\u05de\u05db\u05d4 \u05e9\u05e4\u05d2\u05d4 \u05d1\u05dc\u05d9 \u05e9\u05de\u05d9\u05e9\u05d4\u05d5 \u05e9\u05dd \u05dc\u05d1 \u05e2\u05dc\u05d5\u05dc\u05d4 \u05dc\u05e4\u05e1\u05d5\u05dc \u05e2\u05d1\u05d5\u05d3\u05d4 \u05e9\u05db\u05d1\u05e8 \u05d1\u05d5\u05e6\u05e2\u05d4."], [386.6, "\u05d5\u05e2\u05d1\u05d5\u05d3\u05d4 \u05e9\u05dc\u05d0 \u05dc\u05e4\u05d9 \u05d4-WPS, \u05d0\u05d5 \u05d1\u05dc\u05d9 \u05ea\u05d9\u05e2\u05d5\u05d3, \u05e2\u05dc\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d9\u05e4\u05e1\u05dc \u05d2\u05dd \u05d0\u05dd \u05d4\u05ea\u05e4\u05e8 \u05e2\u05e6\u05de\u05d5 \u05d8\u05d5\u05d1."], [393.7, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: WPS \u05d4\u05d5\u05d0 \u05d4\u05de\u05ea\u05db\u05d5\u05df, PQR \u05d4\u05d5\u05d0 \u05d4\u05d4\u05d5\u05db\u05d7\u05d4 \u05e9\u05d4\u05de\u05ea\u05db\u05d5\u05df \u05e2\u05d5\u05d1\u05d3, \u05d5\u05d4\u05e1\u05de\u05db\u05ea \u05d4\u05e8\u05ea\u05da \u05de\u05d5\u05db\u05d9\u05d7\u05d4 \u05e9\u05d4\u05e8\u05ea\u05da \u05d9\u05d5\u05d3\u05e2 \u05dc\u05d1\u05e6\u05e2 \u05d0\u05d5\u05ea\u05d5."], [404.8, "\u05db\u05dc \u05d0\u05d7\u05d3 \u05de\u05d4\u05dd \u05de\u05e1\u05de\u05d9\u05da \u05ea\u05d7\u05d5\u05dd, \u05d5\u05e9\u05d9\u05e0\u05d5\u05d9 \u05de\u05d7\u05d5\u05e5 \u05dc\u05ea\u05d7\u05d5\u05dd \u05d3\u05d5\u05e8\u05e9 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d7\u05d3\u05e9\u05d4."], [410.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0, \u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05d1\u05e7\u05d5\u05e8\u05e1: \u05e2\u05dc\u05d5\u05d9\u05d5\u05ea \u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05d0\u05d9\u05da \u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05db\u05de\u05d4 \u05ea\u05e4\u05e8 \u05d1\u05d0\u05de\u05ea \u05e2\u05d5\u05dc\u05d4."]]};
window.MH_TR["ch25"]={"t": "\u05e2\u05dc\u05d5\u05d9\u05d5\u05ea \u05e8\u05d9\u05ea\u05d5\u05da", "l": [[3.0, "\u05d4\u05d2\u05e2\u05e0\u05d5 \u05dc\u05e4\u05e8\u05e7 \u05d4\u05d0\u05d7\u05e8\u05d5\u05df: \u05db\u05de\u05d4 \u05e2\u05d5\u05dc\u05d4 \u05ea\u05e4\u05e8."], [6.8, "\u05d4\u05de\u05d7\u05d9\u05e8 \u05e9\u05dc \u05e8\u05d9\u05ea\u05d5\u05da \u05dc\u05d0 \u05e0\u05e7\u05d1\u05e2 \u05e8\u05e7 \u05dc\u05e4\u05d9 \u05d7\u05d5\u05de\u05e8 \u05d4\u05de\u05d9\u05dc\u05d5\u05d9. \u05d1\u05e8\u05d5\u05d1 \u05d4\u05de\u05e7\u05e8\u05d9\u05dd, \u05d4\u05d7\u05dc\u05e7 \u05d4\u05d2\u05d3\u05d5\u05dc \u05d4\u05d5\u05d0 \u05d4\u05d6\u05de\u05df."], [13.9, "\u05d1\u05e4\u05e8\u05e7 \u05e0\u05dc\u05de\u05d3 \u05dc\u05d7\u05e9\u05d1 \u05e2\u05dc\u05d5\u05ea \u05dc\u05de\u05d8\u05e8 \u05ea\u05e4\u05e8, \u05d5\u05e0\u05e8\u05d0\u05d4 \u05de\u05d4 \u05d1\u05d0\u05de\u05ea \u05de\u05d5\u05e8\u05d9\u05d3 \u05d0\u05d5\u05ea\u05d4."], [20.1, "\u05e2\u05dc\u05d5\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05d5\u05e8\u05db\u05d1\u05ea \u05de\u05db\u05de\u05d4 \u05e8\u05db\u05d9\u05d1\u05d9\u05dd."], [23.2, "\u05e2\u05d1\u05d5\u05d3\u05d4: \u05e9\u05db\u05e8 \u05d4\u05e8\u05ea\u05da, \u05db\u05d5\u05dc\u05dc \u05ea\u05e7\u05d5\u05e8\u05d4, \u05dc\u05db\u05dc \u05d4\u05d6\u05de\u05df \u05e9\u05d4\u05d5\u05d0 \u05d1\u05e2\u05de\u05d3\u05d4."], [28.6, "\u05d7\u05d5\u05de\u05e8\u05d9\u05dd: \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05dc\u05d5\u05d9, \u05d2\u05d6, \u05d5\u05d0\u05d1\u05e7\u05d4 \u05d0\u05d5 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea."], [33.8, "\u05d7\u05e9\u05de\u05dc \u05d5\u05e6\u05d9\u05d5\u05d3: \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d7\u05dc\u05e7 \u05e7\u05d8\u05df \u05de\u05d4\u05e2\u05dc\u05d5\u05ea."], [38.4, "\u05d5\u05dc\u05e4\u05e0\u05d9 \u05d5\u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da: \u05d7\u05d9\u05ea\u05d5\u05da, \u05d4\u05db\u05e0\u05ea \u05e9\u05d5\u05dc\u05d9\u05d9\u05dd, \u05d4\u05e8\u05db\u05d1\u05d4, \u05d4\u05e9\u05d7\u05d6\u05d4, \u05d9\u05d9\u05e9\u05d5\u05e8, \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea."], [48.2, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d9\u05d3\u05e0\u05d9, \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d4\u05d9\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05df \u05e9\u05d1\u05e2\u05d9\u05dd \u05dc\u05ea\u05e9\u05e2\u05d9\u05dd \u05d0\u05d7\u05d5\u05d6 \u05de\u05e2\u05dc\u05d5\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e2\u05e6\u05de\u05d5."], [55.1, "\u05d4\u05d7\u05d9\u05e9\u05d5\u05d1 \u05de\u05ea\u05d7\u05d9\u05dc \u05d1\u05db\u05de\u05d5\u05ea \u05de\u05ea\u05db\u05ea \u05d4\u05ea\u05e4\u05e8."], [58.2, "\u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05d0\u05ea \u05e9\u05d8\u05d7 \u05d4\u05d7\u05ea\u05da \u05e9\u05dc \u05d4\u05ea\u05e4\u05e8, \u05d5\u05de\u05db\u05e4\u05d9\u05dc\u05d9\u05dd \u05d1\u05d0\u05d5\u05e8\u05da."], [62.6, "\u05d1-fillet \u05e2\u05dd \u05e8\u05d2\u05dc\u05d9\u05d9\u05dd \u05e9\u05d5\u05d5\u05ea, \u05e9\u05d8\u05d7 \u05d4\u05d7\u05ea\u05da \u05e9\u05d5\u05d5\u05d4 \u05dc\u05e6\u05d5\u05d5\u05d0\u05e8 \u05d1\u05e8\u05d9\u05d1\u05d5\u05e2."], [67.6, "\u05dc\u05de\u05e9\u05dc, \u05e6\u05d5\u05d5\u05d0\u05e8 \u05e9\u05dc 5 \u05de\u05f4\u05de \u05e0\u05d5\u05ea\u05df \u05e9\u05d8\u05d7 \u05e9\u05dc 25 \u05de\u05de\u05f4\u05e8."], [73.7, "\u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d1\u05e2\u05e8\u05da \u05e2\u05e9\u05e8\u05d4 \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd \u05e2\u05dc \u05d4\u05e7\u05de\u05d9\u05e8\u05d5\u05ea, \u05d5\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05db-27.5 \u05de\u05de\u05f4\u05e8."], [80.2, "\u05d1\u05de\u05d8\u05e8 \u05ea\u05e4\u05e8 \u05d6\u05d4 27.5 \u05e1\u05de\u05f4\u05e7, \u05d5\u05d1\u05e4\u05dc\u05d3\u05d4, \u05e9\u05de\u05e9\u05e7\u05dc\u05d4 7.85 \u05d2\u05e8\u05dd \u05dc\u05e1\u05de\u05f4\u05e7, \u05d9\u05d5\u05e6\u05d0 \u05db-216 \u05d2\u05e8\u05dd."], [92.2, "\u05d1\u05d7\u05e8\u05d9\u05e6\u05d9\u05dd \u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05d0\u05ea \u05e9\u05d8\u05d7 \u05d4\u05d7\u05e8\u05d9\u05e5 \u05dc\u05e4\u05d9 \u05d4\u05d6\u05d5\u05d5\u05d9\u05ea, \u05d4\u05e2\u05d5\u05d1\u05d9, \u05e4\u05e2\u05e8 \u05d4\u05e9\u05d5\u05e8\u05e9 \u05d5\u05d4\u05e9\u05d5\u05dc\u05d9\u05d9\u05dd."], [99.5, "\u05dc\u05d0 \u05db\u05dc \u05d7\u05d5\u05de\u05e8 \u05d4\u05de\u05d9\u05dc\u05d5\u05d9 \u05e9\u05e7\u05d5\u05e0\u05d9\u05dd \u05e0\u05db\u05e0\u05e1 \u05dc\u05ea\u05e4\u05e8."], [102.8, "\u05d1\u05d7\u05d5\u05d8 \u05de\u05dc\u05d0, \u05d1\u05e2\u05e8\u05da \u05ea\u05e9\u05e2\u05d9\u05dd \u05d5\u05d7\u05de\u05d9\u05e9\u05d4 \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd \u05e0\u05db\u05e0\u05e1\u05d9\u05dd \u05dc\u05ea\u05e4\u05e8, \u05d5\u05d4\u05e9\u05d0\u05e8 \u05d4\u05d5\u05dc\u05da \u05dc-spatter."], [109.4, "\u05d1\u05d7\u05d5\u05d8 \u05e2\u05dd \u05dc\u05d9\u05d1\u05d4, \u05db\u05e9\u05de\u05d5\u05e0\u05d9\u05dd \u05d5\u05d7\u05de\u05d9\u05e9\u05d4 \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd. \u05d5\u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4 \u05e8\u05e7 \u05db\u05e9\u05d9\u05e9\u05d9\u05dd \u05d0\u05d7\u05d5\u05d6, \u05d1\u05d2\u05dc\u05dc \u05d4\u05e7\u05e6\u05d4 \u05e9\u05e0\u05d6\u05e8\u05e7, \u05d4-slag \u05d5\u05d4-spatter."], [119.3, "\u05d1\u05d3\u05d5\u05d2\u05de\u05d4 \u05e9\u05dc\u05e0\u05d5, \u05e2\u05dd \u05d7\u05d5\u05d8 \u05de\u05dc\u05d0, \u05e6\u05e8\u05d9\u05da \u05db-227 \u05d2\u05e8\u05dd \u05d7\u05d5\u05d8 \u05dc\u05de\u05d8\u05e8."], [125.8, "\u05e2\u05db\u05e9\u05d9\u05d5 \u05d4\u05d6\u05de\u05df, \u05e9\u05d4\u05d5\u05d0 \u05d4\u05e8\u05db\u05d9\u05d1 \u05d4\u05d7\u05e9\u05d5\u05d1 \u05d1\u05d9\u05d5\u05ea\u05e8."], [130.5, "\u05db\u05dc \u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05ea\u05d9\u05da \u05d7\u05d5\u05de\u05e8 \u05d1\u05e7\u05e6\u05d1 \u05d0\u05d7\u05e8, \u05d1\u05e7\u05d9\u05dc\u05d5\u05d2\u05e8\u05de\u05d9\u05dd \u05dc\u05e9\u05e2\u05d4 \u05e9\u05dc \u05e7\u05e9\u05ea."], [135.8, "\u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4, \u05d1\u05e2\u05e8\u05da \u05e7\u05d9\u05dc\u05d5 \u05e2\u05d3 \u05e9\u05e0\u05d9\u05d9\u05dd \u05dc\u05e9\u05e2\u05d4. \u05d1-MIG MAG, \u05e9\u05e0\u05d9\u05d9\u05dd \u05e2\u05d3 \u05d7\u05de\u05d9\u05e9\u05d4. \u05d5\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05e7\u05e9\u05ea \u05e9\u05e7\u05d5\u05e2\u05d4, \u05d7\u05de\u05d9\u05e9\u05d4 \u05e2\u05d3 \u05d7\u05de\u05d9\u05e9\u05d4 \u05e2\u05e9\u05e8 \u05d5\u05d9\u05d5\u05ea\u05e8."], [147.0, "\u05d6\u05de\u05df \u05d4\u05e7\u05e9\u05ea \u05e9\u05d5\u05d5\u05d4 \u05dc\u05de\u05e9\u05e7\u05dc \u05de\u05ea\u05db\u05ea \u05d4\u05ea\u05e4\u05e8, \u05d7\u05dc\u05e7\u05d9 \u05e7\u05e6\u05d1 \u05d4\u05d4\u05ea\u05db\u05d4."], [152.3, "\u05d0\u05d1\u05dc \u05d4\u05e8\u05ea\u05da \u05dc\u05d0 \u05de\u05e8\u05ea\u05da \u05db\u05dc \u05d4\u05d6\u05de\u05df: \u05d4\u05d5\u05d0 \u05de\u05d7\u05dc\u05d9\u05e3 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4, \u05de\u05e0\u05e7\u05d4, \u05de\u05de\u05e7\u05dd, \u05de\u05d6\u05d9\u05d6 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d5\u05d1\u05d5\u05d3\u05e7."], [160.4, "\u05d4\u05d7\u05dc\u05e7 \u05de\u05d4\u05d6\u05de\u05df \u05e9\u05d1\u05d5 \u05d4\u05e7\u05e9\u05ea \u05d3\u05d5\u05dc\u05e7\u05ea \u05e0\u05e7\u05e8\u05d0 \u05de\u05e7\u05d3\u05dd \u05d4\u05e4\u05e2\u05dc\u05d4."], [165.1, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d9\u05d3\u05e0\u05d9 \u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d4\u05d5\u05d0 \u05d1\u05e2\u05e8\u05da \u05e2\u05e9\u05e8\u05d9\u05dd \u05e2\u05d3 \u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05d0\u05d7\u05d5\u05d6, \u05d1-MIG MAG \u05d7\u05e6\u05d9 \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9 \u05db\u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05e2\u05d3 \u05d7\u05de\u05d9\u05e9\u05d9\u05dd, \u05d5\u05d1\u05ea\u05d0 \u05e8\u05d5\u05d1\u05d5\u05d8\u05d9 \u05e9\u05d9\u05e9\u05d9\u05dd \u05e2\u05d3 \u05e9\u05de\u05d5\u05e0\u05d9\u05dd."], [176.4, "\u05e0\u05d7\u05e9\u05d1 \u05d0\u05ea \u05d4\u05d3\u05d5\u05d2\u05de\u05d4 \u05e2\u05d3 \u05d4\u05e1\u05d5\u05e3. \u05d4\u05de\u05d7\u05d9\u05e8\u05d9\u05dd \u05db\u05d0\u05df \u05d4\u05dd \u05d4\u05e0\u05d7\u05d5\u05ea \u05dc\u05d3\u05d5\u05d2\u05de\u05d4 \u05d1\u05dc\u05d1\u05d3."], [181.7, "\u05de\u05ea\u05db\u05ea \u05ea\u05e4\u05e8: 216 \u05d2\u05e8\u05dd \u05dc\u05de\u05d8\u05e8. \u05e7\u05e6\u05d1 \u05d4\u05ea\u05db\u05d4 \u05d1-MAG: \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e7\u05d9\u05dc\u05d5 \u05dc\u05e9\u05e2\u05d4."], [189.2, "\u05d6\u05de\u05df \u05d4\u05e7\u05e9\u05ea: \u05db-4.3 \u05d3\u05e7\u05d5\u05ea \u05dc\u05de\u05d8\u05e8."], [193.4, "\u05e2\u05dd \u05de\u05e7\u05d3\u05dd \u05d4\u05e4\u05e2\u05dc\u05d4 \u05e9\u05dc \u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05d5\u05d7\u05de\u05d9\u05e9\u05d4 \u05d0\u05d7\u05d5\u05d6, \u05d4\u05d6\u05de\u05df \u05d4\u05db\u05d5\u05dc\u05dc \u05d4\u05d5\u05d0 \u05db-12.3 \u05d3\u05e7\u05d5\u05ea \u05dc\u05de\u05d8\u05e8."], [200.2, "\u05e0\u05e0\u05d9\u05d7 \u05e2\u05dc\u05d5\u05ea \u05e2\u05d1\u05d5\u05d3\u05d4 \u05e9\u05dc 200 \u05e9\u05e7\u05dc \u05dc\u05e9\u05e2\u05d4, \u05db\u05d5\u05dc\u05dc \u05ea\u05e7\u05d5\u05e8\u05d4: \u05d9\u05d5\u05e6\u05d0 \u05db-41 \u05e9\u05e7\u05dc \u05dc\u05de\u05d8\u05e8."], [207.3, "\u05d7\u05d5\u05d8: 227 \u05d2\u05e8\u05dd, \u05d1\u05d7\u05de\u05d9\u05e9\u05d4 \u05e2\u05e9\u05e8 \u05e9\u05e7\u05dc \u05dc\u05e7\u05d9\u05dc\u05d5, \u05db-3.4 \u05e9\u05e7\u05dc."], [214.7, "\u05d2\u05d6: \u05d7\u05de\u05d9\u05e9\u05d4 \u05e2\u05e9\u05e8 \u05dc\u05d9\u05d8\u05e8 \u05dc\u05d3\u05e7\u05d4, \u05dc\u05d0\u05d5\u05e8\u05da \u05d6\u05de\u05df \u05d4\u05e7\u05e9\u05ea, \u05db-65 \u05dc\u05d9\u05d8\u05e8, \u05d1\u05e2\u05e8\u05da \u05e9\u05e0\u05d9 \u05e9\u05e7\u05dc\u05d9\u05dd."], [222.7, "\u05e1\u05da \u05d4\u05db\u05dc \u05db-46 \u05e9\u05e7\u05dc \u05dc\u05de\u05d8\u05e8, \u05d5\u05de\u05ea\u05d5\u05db\u05dd \u05db\u05e9\u05de\u05d5\u05e0\u05d9\u05dd \u05d5\u05e9\u05de\u05d5\u05e0\u05d4 \u05d0\u05d7\u05d5\u05d6 \u05d4\u05dd \u05e2\u05d1\u05d5\u05d3\u05d4."], [229.0, "\u05db\u05dc\u05d5\u05de\u05e8, \u05d7\u05d9\u05e1\u05db\u05d5\u05df \u05e9\u05dc \u05e2\u05e9\u05e8\u05d4 \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd \u05d1\u05d6\u05de\u05df \u05e9\u05d5\u05d5\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d7\u05d9\u05e1\u05db\u05d5\u05df \u05e9\u05dc \u05e2\u05e9\u05e8\u05d4 \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd \u05d1\u05d7\u05d5\u05d8."], [236.3, "\u05de\u05d4 \u05de\u05d5\u05e8\u05d9\u05d3 \u05d0\u05ea \u05d4\u05e2\u05dc\u05d5\u05ea? \u05e7\u05d5\u05d3\u05dd \u05db\u05dc, \u05d2\u05d5\u05d3\u05dc \u05d4\u05ea\u05e4\u05e8."], [240.7, "\u05e9\u05d8\u05d7 \u05d4-fillet \u05d2\u05d3\u05dc \u05d1\u05e8\u05d9\u05d1\u05d5\u05e2 \u05e9\u05dc \u05d4\u05e6\u05d5\u05d5\u05d0\u05e8: \u05e6\u05d5\u05d5\u05d0\u05e8 6 \u05d1\u05de\u05e7\u05d5\u05dd 5 \u05de\u05d5\u05e1\u05d9\u05e3 \u05db-44 \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd \u05dc\u05d6\u05de\u05df \u05d5\u05dc\u05d7\u05d5\u05de\u05e8."], [249.8, "\u05dc\u05db\u05df \u05ea\u05e4\u05e8 \u05de\u05d7\u05d5\u05e9\u05d1 \u05e0\u05db\u05d5\u05df, \u05db\u05de\u05d5 \u05e9\u05dc\u05de\u05d3\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 21, \u05d4\u05d5\u05d0 \u05d4\u05d7\u05d9\u05e1\u05db\u05d5\u05df \u05d4\u05e8\u05d0\u05e9\u05d5\u05df."], [256.3, "\u05e9\u05e0\u05d9\u05ea, \u05ea\u05db\u05e0\u05d5\u05df \u05d4\u05d7\u05e8\u05d9\u05e5: \u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd, \u05d7\u05e8\u05d9\u05e5 X \u05d1\u05de\u05e7\u05d5\u05dd \u05d7\u05e8\u05d9\u05e5 V \u05d7\u05d5\u05e1\u05da \u05db\u05d7\u05e6\u05d9 \u05de\u05d4\u05e0\u05e4\u05d7."], [264.1, "\u05d5\u05d4\u05e7\u05d8\u05e0\u05ea \u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05d7\u05e8\u05d9\u05e5 \u05de\u05e9\u05d9\u05e9\u05d9\u05dd \u05dc\u05d0\u05e8\u05d1\u05e2\u05d9\u05dd \u05d5\u05d7\u05de\u05e9 \u05de\u05e2\u05dc\u05d5\u05ea \u05d7\u05d5\u05e1\u05db\u05ea \u05db\u05e8\u05d1\u05e2 \u05de\u05d4\u05e0\u05e4\u05d7, \u05d0\u05dd \u05e2\u05d3\u05d9\u05d9\u05df \u05d9\u05e9 \u05d2\u05d9\u05e9\u05d4 \u05d8\u05d5\u05d1\u05d4 \u05dc\u05e9\u05d5\u05e8\u05e9."], [272.5, "\u05e9\u05dc\u05d9\u05e9\u05d9\u05ea, \u05d4\u05d4\u05e8\u05db\u05d1\u05d4: \u05de\u05e8\u05d5\u05d5\u05d7 \u05d2\u05d3\u05d5\u05dc \u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05e0\u05e4\u05d7, \u05d5\u05d1\u05d7\u05e8\u05d9\u05e6\u05d9\u05dd \u05e6\u05e8\u05d9\u05da \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e2\u05d5\u05d3 \u05de\u05e2\u05d1\u05e8 \u05e9\u05dc\u05dd."], [281.8, "\u05d4\u05e8\u05db\u05d1\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea, \u05e2\u05dd \u05d4\u05ea\u05e7\u05e0\u05d9\u05dd \u05d8\u05d5\u05d1\u05d9\u05dd, \u05d7\u05d5\u05e1\u05db\u05ea \u05d6\u05de\u05df \u05e8\u05d9\u05ea\u05d5\u05da."], [287.0, "\u05d2\u05dd \u05d1\u05d7\u05d9\u05e8\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05e9\u05e4\u05d9\u05e2\u05d4: \u05ea\u05d4\u05dc\u05d9\u05da \u05e2\u05dd \u05e7\u05e6\u05d1 \u05d4\u05ea\u05db\u05d4 \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e7\u05e6\u05e8 \u05d0\u05ea \u05d6\u05de\u05df \u05d4\u05e7\u05e9\u05ea."], [293.8, "\u05d4\u05ea\u05e0\u05d5\u05d7\u05d4 \u05de\u05e9\u05e4\u05d9\u05e2\u05d4 \u05de\u05d0\u05d5\u05d3: \u05e8\u05d9\u05ea\u05d5\u05da \u05e9\u05d8\u05d5\u05d7 \u05de\u05d4\u05d9\u05e8 \u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05e0\u05db\u05d9 \u05d0\u05d5 \u05de\u05e2\u05dc \u05d4\u05e8\u05d0\u05e9."], [300.6, "\u05e9\u05d5\u05dc\u05d7\u05df \u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05e9\u05de\u05d1\u05d9\u05d0 \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8 \u05dc\u05ea\u05e0\u05d5\u05d7\u05d4 \u05e9\u05d8\u05d5\u05d7\u05d4 \u05de\u05d7\u05d6\u05d9\u05e8 \u05d0\u05ea \u05e2\u05e6\u05de\u05d5 \u05de\u05d4\u05e8."], [306.1, "\u05de\u05d9\u05db\u05d5\u05df \u05d5\u05e8\u05d5\u05d1\u05d5\u05d8\u05d9\u05dd \u05de\u05e2\u05dc\u05d9\u05dd \u05d0\u05ea \u05de\u05e7\u05d3\u05dd \u05d4\u05d4\u05e4\u05e2\u05dc\u05d4, \u05d0\u05d1\u05dc \u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05d4\u05e8\u05db\u05d1\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d5\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea."], [312.6, "\u05d0\u05dc \u05ea\u05e9\u05db\u05d7\u05d5 \u05d0\u05ea \u05de\u05d4 \u05e9\u05e7\u05d5\u05e8\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05d5\u05d0\u05d7\u05e8\u05d9: \u05d4\u05e9\u05d7\u05d6\u05d4, \u05e0\u05d9\u05e7\u05d5\u05d9 spatter, \u05d9\u05d9\u05e9\u05d5\u05e8 \u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea."], [320.2, "\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05d6\u05de\u05df \u05e9\u05dc\u05d4\u05dd \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8 \u05de\u05d6\u05de\u05df \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e2\u05e6\u05de\u05d5."], [324.2, "\u05d5\u05ea\u05d9\u05e7\u05d5\u05df \u05e9\u05dc \u05e4\u05d2\u05dd \u05e2\u05d5\u05dc\u05d4 \u05db\u05de\u05d4 \u05e4\u05e2\u05de\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05ea\u05e4\u05e8 \u05d4\u05de\u05e7\u05d5\u05e8\u05d9, \u05d5\u05dc\u05db\u05df \u05d0\u05d9\u05db\u05d5\u05ea \u05d8\u05d5\u05d1\u05d4 \u05de\u05d4\u05d4\u05ea\u05d7\u05dc\u05d4 \u05d4\u05d9\u05d0 \u05d2\u05dd \u05d7\u05d9\u05e1\u05db\u05d5\u05df."], [332.9, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd \u05d4\u05e9\u05d9\u05d8\u05d4: \u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05e9\u05d8\u05d7 \u05d7\u05ea\u05da, \u05de\u05de\u05e0\u05d5 \u05de\u05e9\u05e7\u05dc \u05de\u05ea\u05db\u05ea \u05d4\u05ea\u05e4\u05e8 \u05dc\u05de\u05d8\u05e8."], [339.5, "\u05de\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05e0\u05e6\u05d9\u05dc\u05d5\u05ea, \u05d5\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d0\u05ea \u05db\u05de\u05d5\u05ea \u05d7\u05d5\u05de\u05e8 \u05d4\u05de\u05d9\u05dc\u05d5\u05d9."], [343.2, "\u05de\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05e7\u05e6\u05d1 \u05d4\u05d4\u05ea\u05db\u05d4 \u05d5\u05d1\u05de\u05e7\u05d3\u05dd \u05d4\u05d4\u05e4\u05e2\u05dc\u05d4, \u05d5\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05d6\u05de\u05df."], [348.2, "\u05de\u05db\u05e4\u05d9\u05dc\u05d9\u05dd \u05d6\u05de\u05df \u05d1\u05ea\u05e2\u05e8\u05d9\u05e3, \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d1\u05de\u05d7\u05d9\u05e8, \u05d5\u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d4\u05db\u05e0\u05d4, \u05d2\u05d9\u05de\u05d5\u05e8 \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea."], [354.5, "\u05d5\u05db\u05da \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e9\u05d5\u05d5\u05ea \u05d1\u05d9\u05df \u05d7\u05dc\u05d5\u05e4\u05d5\u05ea: \u05ea\u05d4\u05dc\u05d9\u05da, \u05d7\u05e8\u05d9\u05e5, \u05ea\u05e0\u05d5\u05d7\u05d4, \u05d0\u05d5 \u05d2\u05d5\u05d3\u05dc \u05ea\u05e4\u05e8."], [363.0, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da, \u05d4\u05d6\u05de\u05df \u05d4\u05d5\u05d0 \u05d4\u05db\u05e1\u05e3: \u05d1\u05e8\u05d5\u05d1 \u05d4\u05de\u05e7\u05e8\u05d9\u05dd \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d4\u05d9\u05d0 \u05e8\u05d5\u05d1 \u05d4\u05e2\u05dc\u05d5\u05ea."], [369.2, "\u05ea\u05e4\u05e8 \u05d1\u05d2\u05d5\u05d3\u05dc \u05d4\u05e0\u05db\u05d5\u05df, \u05d7\u05e8\u05d9\u05e5 \u05d7\u05db\u05dd, \u05ea\u05e0\u05d5\u05d7\u05d4 \u05e0\u05d5\u05d7\u05d4 \u05d5\u05d4\u05e8\u05db\u05d1\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d7\u05d5\u05e1\u05db\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05db\u05dc \u05d4\u05e0\u05d7\u05d4 \u05e2\u05dc \u05d7\u05d5\u05d8."], [377.1, "\u05d5\u05db\u05d0\u05df \u05de\u05e1\u05ea\u05d9\u05d9\u05dd \u05e7\u05d5\u05e8\u05e1 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da. \u05de\u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd, \u05d3\u05e8\u05da \u05d4\u05de\u05d8\u05dc\u05d5\u05e8\u05d2\u05d9\u05d4 \u05d5\u05d4\u05ea\u05db\u05e0\u05d5\u05df, \u05d5\u05e2\u05d3 \u05d4\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea, \u05d4\u05d4\u05e1\u05de\u05db\u05d5\u05ea \u05d5\u05d4\u05e2\u05dc\u05d5\u05d9\u05d5\u05ea."], [386.3, "\u05ea\u05d5\u05d3\u05d4 \u05e9\u05e6\u05e4\u05d9\u05ea\u05dd, \u05d5\u05d1\u05d4\u05e6\u05dc\u05d7\u05d4 \u05d1\u05e2\u05d1\u05d5\u05d3\u05d4."]]};
